INSERT INTO time_periods (id, name, start_year, end_year, color, sort_order, description) VALUES
(1, 'Creation & Primeval History', -4004, -1996, '#a16844', 1, 'Adam through the Tower of Babel'),
(2, 'Patriarchs', -1996, -1706, '#c3a03a', 2, 'Abraham, Isaac, Jacob, Joseph'),
(3, 'Egypt & Exodus', -1706, -1451, '#bc634d', 3, 'Israel in Egypt, the Exodus and the wilderness years'),
(4, 'Conquest & Judges', -1451, -1095, '#7fae64', 4, 'Joshua''s conquest through the period of the Judges'),
(5, 'United Kingdom', -1095, -975, '#567cd3', 5, 'Saul, David, Solomon'),
(6, 'Divided Kingdom', -975, -588, '#e1707c', 6, 'Israel and Judah as separate kingdoms: Israel until the fall of Samaria in 721, Judah until the fall of Jerusalem in 588 (Ussher)'),
(7, 'Exile', -588, -536, '#5c7794', 7, 'Babylonian captivity'),
(8, 'Return & Restoration', -536, -400, '#55b486', 8, 'Zerubbabel, Ezra, Nehemiah'),
(9, 'Intertestamental Period', -400, -5, '#917bab', 9, 'Between the Testaments'),
(10, 'Life of Christ', -5, 33, '#d8bd51', 10, 'Birth through Ascension of Jesus'),
(11, 'Apostolic Age', 33, 100, '#7f79d1', 11, 'Early church through death of John'),
(12, 'Early Church & Persecution', 100, 313, '#e38879', 12, 'Persecution under Rome; Church Fathers; canon formation'),
(13, 'Imperial Christianity', 313, 476, '#a264b0', 13, 'Edict of Milan through fall of the Western Roman Empire'),
(14, 'Early Medieval', 476, 1054, '#63aea9', 14, 'Rise of monasticism; spread of Christianity; East-West tensions'),
(15, 'High Medieval & Crusades', 1054, 1400, '#667ab9', 15, 'Great Schism; Crusades; Scholasticism; early reform movements'),
(16, 'Reformation', 1400, 1648, '#67b36a', 16, 'Gutenberg Bible; Protestant Reformation; Catholic Counter-Reformation'),
(17, 'Enlightenment & Missions', 1648, 1900, '#4188b6', 17, 'Great Awakenings; modern missions movement; Bible societies'),
(18, 'Modern Era', 1900, 2026, '#90b1bc', 18, 'Global Christianity; ecumenical movement; digital age');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(1, 'Adam', NULL, -4004, -3074, 0, 0, 'traditional', 'patriarch', 'major', NULL, NULL, NULL, 'First man, formed from the dust and given life by the breath of God. Placed in Eden to tend and keep the garden, his disobedience brought sin and death into the human story, and Paul later presents him as the counterpart to Christ, the last Adam who brings life.', 'Ussher chronology (Annales, 1650): created 4004 BC, died 3074 BC (930 years, Gen 5:5). Mainstream scholarship does not date the first humans from the Genesis genealogies.'),
(2, 'Eve', 'Havah', -4004, -3074, 0, 1, 'possible', 'matriarch', 'major', NULL, NULL, NULL, 'First woman, fashioned from Adam''s side as his companion and counterpart, her name meaning mother of all living. Deceived by the serpent, she shared the forbidden fruit, yet received the first promise of an offspring who would one day crush the deceiver.', 'Ussher: created 4004 BC with Adam (Gen 1:27; 2:22). Scripture does not record her death; 3074 BC is an estimate that simply takes Adam''s death year.'),
(3, 'Noah', NULL, -2948, -1998, 0, 0, 'traditional', 'patriarch', 'major', NULL, 52, NULL, 'Righteous man who walked with God in a corrupt generation, building the ark that carried his family and the animals through the flood. Recipient of the first covenant, sealed by the rainbow; flood traditions across ancient Mesopotamia, including the Gilgamesh epic, echo the memory of a great deluge.', 'Ussher: born 2948 BC (AM 1056), died 1998 BC (950 years, Gen 9:29).'),
(49, 'Seth', NULL, -3874, -2962, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 1, 2, 'Third son of Adam and Eve; ancestor of Noah.', 'Ussher: born 3874 BC (AM 130), died 2962 BC (912 years, Gen 5:8).'),
(50, 'Enoch', NULL, -3382, -3017, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 151, NULL, 'Walked with God and was taken up; did not see death.', 'Ussher: born 3382 BC (AM 622), translated 3017 BC (365 years, Gen 5:24; Heb 11:5).'),
(51, 'Methuselah', NULL, -3317, -2349, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 50, NULL, 'Longest-lived person in the Bible at 969 years.', 'Ussher: born 3317 BC (AM 687, Annals sec. 19) and died aged 969 (Gen 5:27) in 2349 BC (AM 1656, Annals sec. 33), the year the Flood began; Ussher remarks that he lived longest of all men. Strictly subtracting 969 years from 3317 BC would give 2348 BC; the Annals date his death to 2349 BC, which is the figure used here.'),
(52, 'Lamech', NULL, -3130, -2353, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 51, NULL, 'Father of Noah; expressed hope for relief from the curse.', 'Ussher: born 3130 BC (AM 874), died 2353 BC (777 years, Gen 5:31).'),
(53, 'Shem', NULL, -2446, -1846, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 3, NULL, 'Son of Noah; ancestor of the Semitic peoples and of Abraham.', 'Ussher: born 2446 BC (AM 1558, Noah aged 502), the year Shem was 100 two years after the Flood (Gen 11:10); died 1846 BC (600 years, Gen 11:10-11). Japheth, listed as the elder (Gen 10:21), is placed at 2448 BC when Noah was 500 (Gen 5:32).'),
(54, 'Ham', NULL, -2445, -1945, 1, 1, 'possible', 'patriarch', 'minor', NULL, 3, NULL, 'Son of Noah; ancestor of the Canaanites, Egyptians, and others.', 'Estimate. Noah fathered Shem, Ham and Japheth after he was 500 (Gen 5:32), and Ham is the younger son (Gen 9:24), so he is placed just after Shem (born 2446 BC). No lifespan is given; about 500 years is an estimate on the post-Flood pattern.'),
(55, 'Japheth', NULL, -2448, -1948, 1, 1, 'possible', 'patriarch', 'minor', NULL, 3, NULL, 'Son of Noah; ancestor of many European and Asian peoples.', 'Estimate. Gen 5:32 (Noah aged 500); Gen 10:21 can be read as calling Japheth the elder brother of Shem, so he takes the earliest year, 2448 BC. No lifespan is given; about 500 years is an estimate on the post-Flood pattern.'),
(148, 'Enosh', 'Enos', -3769, -2864, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 49, NULL, 'Son of Seth; in his time people began to call on the name of the LORD.', 'Ussher: born 3769 BC (AM 235), died 2864 BC (905 years, Gen 5:6-11).'),
(149, 'Kenan', 'Cainan', -3679, -2769, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 148, NULL, 'Son of Enosh; fourth generation from Adam.', 'Ussher: born 3679 BC (AM 325), died 2769 BC (910 years, Gen 5:9-14).'),
(150, 'Mahalalel', NULL, -3609, -2714, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 149, NULL, 'Son of Kenan; fifth generation from Adam.', 'Ussher: born 3609 BC (AM 395), died 2714 BC (895 years, Gen 5:12-17).'),
(151, 'Jared', NULL, -3544, -2582, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 150, NULL, 'Son of Mahalalel; father of Enoch. Lived 962 years, second-longest lifespan.', 'Ussher: born 3544 BC (AM 460), died 2582 BC (962 years, Gen 5:15-20).'),
(152, 'Arphaxad', 'Arpachshad', -2346, -1908, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 53, NULL, 'Son of Shem; born two years after the Flood. Ancestor of Abraham.', 'Ussher: born 2346 BC (AM 1658), died 1908 BC (438 years, Gen 11:10-13). Luke 3:36 and the Septuagint of Gen 11:12-13 place a Cainan between Arphaxad and Salah; the Hebrew text followed here does not.'),
(153, 'Salah', 'Shelah', -2311, -1878, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 152, NULL, 'Son of Arphaxad; father of Eber (Gen 11:12-15).', 'Ussher: born 2311 BC (AM 1693), died 1878 BC (433 years, Gen 11:12-15).'),
(154, 'Eber', 'Heber', -2281, -1817, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 153, NULL, 'Son of Salah; ancestor of the Hebrews (the name "Hebrew" derives from Eber).', 'Ussher: born 2281 BC (AM 1723), died 1817 BC (464 years, Gen 11:14-17).'),
(155, 'Peleg', NULL, -2247, -2008, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 154, NULL, 'Son of Eber; in his days the earth was divided (Tower of Babel).', 'Ussher: born 2247 BC (AM 1757), died 2008 BC (239 years, Gen 11:16-19). Gen 10:25.'),
(156, 'Reu', 'Ragau', -2217, -1978, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 155, NULL, 'Son of Peleg; continued the post-Flood patriarchal line.', 'Ussher: born 2217 BC (AM 1787), died 1978 BC (239 years, Gen 11:18-21).'),
(157, 'Serug', 'Saruch', -2185, -1955, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 156, NULL, 'Son of Reu; grandfather of Terah.', 'Ussher: born 2185 BC (AM 1819), died 1955 BC (230 years, Gen 11:20-23).'),
(158, 'Nahor', 'Nahor son of Serug', -2155, -2007, 0, 0, 'traditional', 'patriarch', 'minor', NULL, 157, NULL, 'Son of Serug; grandfather of Abraham. Not to be confused with Abraham''s brother Nahor.', 'Ussher: born 2155 BC (AM 1849), died 2007 BC (148 years, Gen 11:22-25).'),
(159, 'Terah', NULL, -2126, -1921, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 158, NULL, 'Son of Nahor; father of Abraham, Nahor, and Haran. Died in Haran.', 'Ussher: born 2126 BC (AM 1878), died 1921 BC (205 years, Gen 11:24-32). Abraham departed after Terah''s death (Acts 7:4).'),
(160, 'Cain', NULL, -3950, -3000, 1, 1, 'possible', 'other', 'moderate', NULL, 1, 2, 'Firstborn of Adam and Eve, a tiller of the soil whose rejected offering festered into the murder of his brother Abel. Marked yet protected by God, he became the Bible''s first city builder and an enduring warning that sin crouches at the door yet can be mastered.', 'Estimate. Scripture gives no dates for Cain: he was born after the Fall (Gen 4:1), before Seth, who was born when Adam was 130 (Gen 5:3), and his death is not recorded. The years are placeholders for display, not a figure we can attribute to Ussher.'),
(161, 'Abel', NULL, -3948, -3880, 1, 1, 'possible', 'other', 'moderate', NULL, 1, 2, 'Second son of Adam and Eve, a keeper of flocks whose offering God accepted, provoking his brother''s lethal envy. The first innocent to die in Scripture, he is honored in Hebrews as a man of faith whose blood still speaks, and Jesus names him first among the righteous slain.', 'Estimate. Scripture: killed before Seth was born, when Adam was 130 (Gen 4:8, 25; 5:3). Ussher, Annals sec. 13 (130 AM, 3874 BC): the murder came shortly before Seth''s birth. Exact year not fixed; the birth year is a placeholder and 3880 BC is an estimate for his death.'),
(510, 'Haran, brother of Abraham', 'Haran son of Terah', -2056, NULL, 0, 1, 'traditional', 'ancestor', 'minor', 'Shem', 159, NULL, 'Son of Terah and brother of Abraham and Nahor. He was the father of Lot, Milcah and Iscah, and he died in Ur before his father Terah left for Canaan.', 'Ussher, Annals sec. 58: born 2056 BC, when Terah was 70 (Gen 11:26); Abram was born 60 years later (1996 BC, sec. 63). Haran died in Ur before Terah set out (Gen 11:28); Scripture and Ussher give no year for his death.'),
(511, 'Nahor, brother of Abraham', 'Nahor II', -2000, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Shem', 159, NULL, 'Brother of Abraham who married his niece Milcah. His son Bethuel was the father of Rebekah and Laban, and his family stayed in Mesopotamia.', 'Estimate from his place as Terah''s son and brother of Abraham (born 1996 BC). Not to be confused with Nahor, Terah''s father. Scripture gives no dates for him.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(4, 'Abraham', 'Abram', -1996, -1821, 0, 0, 'traditional', 'patriarch', 'major', NULL, 159, NULL, 'Patriarch called from Ur of the Chaldees to a land God would show him, receiving the covenant promise that all nations would be blessed through his offspring. His faith, tested in the offering of Isaac, made him the father of the faithful for Jews, Christians, and Muslims alike.', 'Ussher: born 1996 BC (AM 2008), died 1821 BC (175 years, Gen 25:7). Ussher reads Terah as 130 at Abraham''s birth (Gen 11:32 with 12:4 and Acts 7:4); a plain reading of Gen 11:26 (Terah 70 when he fathered Abram) would give about 2056 BC, and Abram is probably listed first for rank rather than birth order. Mainstream scholarship, where it dates the patriarchs at all, places them roughly 2000 to 1700 BC.'),
(5, 'Sarah', 'Sarai', -1986, -1859, 0, 0, 'traditional', 'matriarch', 'moderate', NULL, 159, NULL, 'Wife of Abraham, mother of Isaac.', 'Ussher: born 1986 BC (10 years younger than Abraham, Gen 17:17), died 1859 BC (127 years, Gen 23:1).'),
(6, 'Isaac', NULL, -1896, -1716, 0, 0, 'traditional', 'patriarch', 'major', NULL, 4, 5, 'Son of promise, born to Abraham and Sarah in their old age and spared on Mount Moriah when God provided a ram in his place. He reopened his father''s wells in the Negev and passed the covenant blessing to Jacob, the quiet link between Abraham and the tribes of Israel.', 'Ussher: born 1896 BC (Abraham aged 100, Gen 21:5), died 1716 BC (180 years, Gen 35:28).'),
(7, 'Rebekah', NULL, -1876, -1739, 1, 1, 'possible', 'matriarch', 'moderate', NULL, 513, NULL, 'Wife of Isaac, mother of Jacob and Esau.', 'Estimate. She was a ''damsel'' when she married Isaac, aged 40, in 1856 BC (Gen 24:16; 25:20), so she is placed about 20 years old then. Her death is not recorded; she was buried at Machpelah (Gen 49:31). The year of death is an estimate.'),
(8, 'Jacob', 'Israel', -1836, -1689, 0, 0, 'traditional', 'patriarch', 'major', NULL, 6, 7, 'Younger twin who obtained birthright and blessing, wrestled with God at Peniel, and received the new name Israel. Father of twelve sons who became Israel''s tribes, his long journey from schemer to patriarch traces the transforming grip of covenant grace.', 'Ussher: born 1836 BC (Isaac aged 60, Annals sec. 98; Gen 25:26), died 1689 BC (147 years, sec. 145; Gen 47:28). Fled to Haran 1760 BC (sec. 111, aged 77), married after seven years of service c. 1753 BC (sec. 114), Joseph born 1745 BC (aged 91, sec. 121; Gen 41:46; 45:6; 47:9), returned to Canaan 1739 BC after 20 years with Laban (sec. 123; Gen 31:38, 41).'),
(9, 'Joseph', NULL, -1745, -1635, 0, 0, 'traditional', 'patriarch', 'major', NULL, 8, 62, 'Favored son of Jacob, sold into Egypt by jealous brothers, who rose from prison to become Pharaoh''s vizier through the interpretation of dreams. His grain policy saved Egypt and his own family from famine, and his forgiveness of his brothers remains Scripture''s great portrait of providence over evil intent.', 'Scripture: born when Jacob was 91 (Gen 41:46; 45:6; 47:9: Joseph 30 at Pharaoh, nine years before Jacob at 130), at the end of Jacob''s 14 years of service (Gen 30:25; 31:41); died aged 110 (Gen 50:26). Jacob''s birth in 1836 BC is Ussher''s, giving born 1745 BC and died 1635 BC (Annals sections 121, 148).'),
(56, 'Lot', NULL, -1960, -1870, 1, 1, 'possible', 'other', 'moderate', NULL, 510, NULL, 'Abraham''s nephew; escaped the destruction of Sodom.', 'Estimate. Scripture gives no age for Lot; he is Abraham''s nephew and travelled with him (Gen 11:27-31; 12:4), and his death is not recorded. Sodom fell c. 1897 BC (Gen 19). The years are estimates, not a figure we can attribute to Ussher.'),
(57, 'Ishmael', NULL, -1910, -1773, 0, 0, 'traditional', 'patriarch', 'moderate', NULL, 4, 58, 'Son of Abraham by Hagar; father of twelve princes.', 'Ussher: born 1910 BC (Abraham aged 86, Gen 16:16), died 1773 BC (137 years, Gen 25:17).'),
(58, 'Hagar', NULL, -1930, -1850, 1, 1, 'possible', 'matriarch', 'moderate', NULL, NULL, NULL, 'Sarah''s Egyptian servant; mother of Ishmael.', 'Estimate. Scripture gives no age for Hagar, and her death is not recorded. Jewish tradition (Pirke de-Rabbi Eliezer 30) identifies her as Pharaoh''s daughter; Islamic tradition (Ibn Kathir) places her near Beer-lahai-roi. The years are estimates.'),
(59, 'Esau', 'Edom', -1836, -1689, 0, 1, 'possible', 'patriarch', 'moderate', NULL, 6, 7, 'Jacob''s twin brother; sold his birthright; ancestor of the Edomites.', 'Ussher: born 1836 BC (twin of Jacob, Gen 25:26). Death is not recorded in Scripture; 1689 BC is an estimate taking the year of Jacob''s death.'),
(60, 'Laban', NULL, -1880, -1735, 1, 1, 'possible', 'other', 'moderate', NULL, 513, NULL, 'Rebekah''s brother; father of Leah and Rachel. Tricked Jacob.', 'Estimate. Brother of Rebekah (Gen 24:29) and father of Leah and Rachel, and still active when Jacob left Paddan-aram in 1739 BC (Gen 31), so he lived past that year. Birth and death years are estimates.'),
(61, 'Leah', NULL, -1777, -1710, 1, 1, 'possible', 'matriarch', 'moderate', NULL, 60, NULL, 'Jacob''s first wife; mother of six sons and Dinah.', 'Estimate. Elder daughter of Laban (Gen 29:16), given to Jacob after his seven years of service, in 1753 BC (Gen 29:20-25); placed about 24 at marriage. Her death is not recorded; she was buried at Machpelah (Gen 49:31).'),
(62, 'Rachel', NULL, -1774, -1730, 1, 1, 'possible', 'matriarch', 'moderate', NULL, 60, NULL, 'Jacob''s beloved wife; mother of Joseph and Benjamin.', 'Estimate. Laban''s younger daughter, a shepherdess when Jacob arrived in 1760 BC (Gen 29:9-18), married to him a week after Leah in 1753 BC (29:27-28); placed about 21 at marriage. She bore Joseph in 1745 BC (30:22-25) and died giving birth to Benjamin near Ephrath (35:16-20), placed c. 1730 BC.'),
(63, 'Judah', NULL, -1749, -1619, 1, 1, 'traditional', 'patriarch', 'moderate', 'Judah', 8, 61, 'Fourth son of Jacob and Leah whose offer of himself in place of Benjamin marked one of Genesis''s great moments of transformation. Jacob''s blessing promised the scepter to his line, and through him came the royal tribe of David and, in Christian reading, the Messiah himself.', 'Estimate from Scripture: Leah''s fourth son (Gen 29:35), after the marriage of 1753 BC; placed in 1749 BC (Ussher, Annals 120, has 1755 BC on his earlier marriage date). Entered Egypt in 1706 BC (Gen 46:12). Ussher does not date Gen 38 (Er, Onan, Tamar and Perez). Death is not recorded; about 130 years is assumed.'),
(64, 'Benjamin', NULL, -1730, -1600, 1, 1, 'possible', 'patriarch', 'moderate', 'Benjamin', 8, 62, 'Youngest son of Jacob and Rachel; born near Bethlehem.', 'Estimate. Born near Ephrath after Jacob''s return in 1739 BC, when Rachel died (Gen 35:16-20), placed c. 1730 BC. At that date he would be about 24 when Jacob entered Egypt in 1706 BC, yet Gen 46:21 lists ten sons for him, a known difficulty (the list may include later descendants). Death is not recorded; about 130 years is an estimate.'),
(65, 'Reuben', NULL, -1752, -1622, 1, 1, 'traditional', 'patriarch', 'moderate', 'Reuben', 8, 61, 'Jacob''s firstborn; lost his birthright. Tried to save Joseph.', 'Estimate from Scripture: Leah''s first son (Gen 29:32), born soon after the marriage of 1753 BC (Gen 29:20-28); placed in 1752 BC. Ussher (Annals 117) has 1758 BC on his earlier dating of the marriage. Entered Egypt in 1706 BC (Gen 46:8-9). Death is not recorded; about 130 years is assumed.'),
(162, 'Dinah', NULL, -1745, -1677, 1, 1, 'possible', 'other', 'minor', NULL, 8, 61, 'Daughter of Jacob and Leah; incident at Shechem.', 'Estimate. Daughter of Jacob and Leah, born after Zebulun (Gen 30:21); entered Egypt with Jacob (Gen 46:15). Midrash (Genesis Rabbah 80:11) identifies her as Job''s wife. The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. Death is not recorded; about 68 years is an estimate.'),
(163, 'Simeon', NULL, -1751, -1621, 1, 1, 'traditional', 'patriarch', 'minor', 'Simeon', 8, 61, 'Second son of Jacob and Leah; ancestor of the tribe of Simeon.', 'Estimate from Scripture: Leah''s second son (Gen 29:33), after the marriage of 1753 BC; placed in 1751 BC (Ussher, Annals 118: 1758-1757 BC on his earlier marriage date). Held in prison by Joseph in 1707-1706 BC (Gen 42:24; 43:23). Death is not recorded; about 130 years is assumed.'),
(164, 'Levi', NULL, -1750, -1613, 1, 1, 'traditional', 'patriarch', 'moderate', 'Levi', 8, 61, 'Third son of Jacob and Leah; ancestor of the priestly tribe. Lived 137 years.', 'Estimate from Scripture: Leah''s third son (Gen 29:34), after the marriage of 1753 BC; placed in 1750 BC (Ussher, Annals 119, has 1756 BC on his earlier marriage date). Lived 137 years (Exod 6:16), so died about 1613 BC in Egypt. He fathered Kohath in Canaan and Jochebed in Egypt (Num 26:59).'),
(165, 'Dan', NULL, -1748, -1618, 1, 1, 'possible', 'patriarch', 'minor', 'Dan', 8, 516, 'Fifth son of Jacob; ancestor of the tribe of Dan.', 'Estimate. Fifth son of Jacob, born to Rachel''s servant Bilhah (Gen 30:6); entered Egypt (Gen 46:23). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. Death is not recorded; about 130 years is assumed.'),
(166, 'Naphtali', NULL, -1747, -1614, 1, 1, 'possible', 'patriarch', 'minor', 'Naphtali', 8, 516, 'Sixth son of Jacob; ancestor of the tribe of Naphtali.', 'Estimate. Sixth son of Jacob, born to Bilhah (Gen 30:8); entered Egypt (Gen 46:24). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. The non-canonical Testament of Naphtali records 133 years, which gives 1614 BC.'),
(167, 'Gad', NULL, -1747, -1620, 1, 1, 'possible', 'patriarch', 'minor', 'Gad', 8, 517, 'Seventh son of Jacob; ancestor of the tribe of Gad.', 'Estimate. Seventh son of Jacob, born to Leah''s servant Zilpah (Gen 30:11); entered Egypt (Gen 46:16). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. The non-canonical Testament of Gad records 127 years, which gives 1620 BC.'),
(168, 'Asher', NULL, -1746, -1619, 1, 1, 'possible', 'patriarch', 'minor', 'Asher', 8, 517, 'Eighth son of Jacob; ancestor of the tribe of Asher.', 'Estimate. Eighth son of Jacob, born to Zilpah (Gen 30:13); entered Egypt (Gen 46:17). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. The non-canonical Testament of Asher records 127 years, which gives 1619 BC.'),
(169, 'Issachar', NULL, -1746, -1624, 1, 1, 'possible', 'patriarch', 'minor', 'Issachar', 8, 61, 'Ninth son of Jacob; ancestor of the tribe of Issachar.', 'Estimate. Ninth son of Jacob and Leah (Gen 30:18); entered Egypt (Gen 46:13). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. The non-canonical Testament of Issachar records 122 years, which gives 1624 BC.'),
(170, 'Zebulun', NULL, -1745, -1631, 1, 1, 'possible', 'patriarch', 'minor', 'Zebulun', 8, 61, 'Tenth son of Jacob; ancestor of the tribe of Zebulun.', 'Estimate. Tenth son of Jacob and Leah (Gen 30:20); entered Egypt (Gen 46:14). The sons and Dinah are laid out in the order of Gen 29:31-30:24 and 35:16-18 within Ussher''s frame (Jacob to Haran and marriage 1760 BC, Leah''s first four sons 1758-1755 BC, Joseph born 1745 BC, return 1739 BC: Ussher, Annals sections 112-121, 123); the years are approximate. The non-canonical Testament of Zebulun records 114 years, which gives 1631 BC.'),
(171, 'Manasseh, son of Joseph', 'Manasseh son of Joseph, Manasseh', -1714, -1600, 1, 1, 'possible', 'patriarch', 'moderate', 'Manasseh', 9, 178, 'Firstborn son of Joseph; adopted by Jacob. Half-tribe of Israel.', 'Estimate. Born in Egypt before the famine, after Joseph became ruler in 1715 BC (Gen 41:50-51); adopted by Jacob (Gen 48). Death is not recorded; the year is an estimate.'),
(172, 'Ephraim', NULL, -1712, -1600, 1, 1, 'possible', 'patriarch', 'moderate', 'Ephraim', 9, 178, 'Second son of Joseph; adopted by Jacob and given the firstborn blessing.', 'Estimate. Born in Egypt before the famine, after Manasseh (Gen 41:52); given the firstborn blessing by Jacob (Gen 48:14-20). Death is not recorded; the year is an estimate.'),
(173, 'Tamar', 'Tamar daughter-in-law of Judah', -1742, -1670, 1, 1, 'possible', 'matriarch', 'moderate', NULL, NULL, NULL, 'Daughter-in-law of Judah; mother of Perez and Zerah. In the lineage of David and Jesus.', 'Estimate. Scripture gives no dates for Tamar. She became Judah''s daughter-in-law and the mother of Perez and Zerah (Gen 38). The years are estimates, and Gen 38 does not fit neatly into the chronology of Judah''s sons (see Perez).'),
(174, 'Perez', 'Pharez', -1708, -1610, 1, 1, 'possible', 'patriarch', 'minor', 'Judah', 63, 173, 'Son of Judah and Tamar; ancestor of David and Jesus.', 'Estimate. Judah was born in 1755 BC (Ussher, Annals section 120) and Genesis 38 (Er, Onan and Shelah growing up before Tamar bears Perez) cannot fall much earlier than this. Genesis 46:12 lists Perez and his sons among those who went down to Egypt in 1706 BC, perhaps counted by anticipation.'),
(175, 'Keturah', NULL, -1900, -1800, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Abraham''s wife after Sarah''s death; mother of six sons including Midian.', 'Estimate. Gen 25:1-4 tells of Abraham''s marriage to Keturah and her six sons, after the account of Sarah''s death (1859 BC) though the text does not state the order in time; some Jewish tradition identifies her with Hagar. Born about 40 years before that marriage so that she could bear six sons; death not recorded.'),
(177, 'Potiphar', NULL, -1770, -1710, 1, 1, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'Egyptian officer who bought Joseph as a slave; captain of Pharaoh''s guard.', 'Gen 39:1-20. Captain of Pharaoh''s guard. Disappears from narrative after Joseph''s imprisonment. Est. death c. 1710 BC.'),
(178, 'Asenath', NULL, -1735, -1640, 1, 1, 'possible', 'matriarch', 'minor', NULL, NULL, NULL, 'Egyptian wife of Joseph; daughter of Potiphera priest of On. Mother of Manasseh and Ephraim.', 'Gen 41:45, 50-52. Daughter of Potiphera, priest of On. Jewish apocryphal tradition (Joseph and Asenath) describes her conversion. Est. death c. 1640 BC.'),
(497, 'Kohath', NULL, -1720, -1587, 1, 1, 'possible', 'ancestor', 'minor', 'Levi', 164, NULL, 'Second son of Levi and grandfather of Moses, Aaron and Miriam. His descendants, the Kohathites, carried the ark and the holy things of the tabernacle.', 'Estimate. Ussher, Annals section 151: Levi begot Kohath in Canaan, so he was born before the descent into Egypt in 1706 BC (Gen 46:11); he lived 133 years (Exod 6:18). Scripture and Ussher give no year of birth.'),
(512, 'Milcah', NULL, -1975, NULL, 1, 1, 'possible', 'matriarch', 'minor', 'Shem', 510, NULL, 'Daughter of Haran and wife of her uncle Nahor. She bore Nahor eight sons, among them Bethuel, the father of Rebekah.', 'Estimate. Milcah was born after her father Haran and before her son Bethuel; Scripture gives no dates.'),
(513, 'Bethuel', NULL, -1950, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Shem', 511, 512, 'Son of Nahor and Milcah, father of Rebekah and Laban. Scripture mentions him by name but records few of his own words or deeds.', 'Estimate. Born to Nahor and Milcah in the generation after Abraham''s brother, and before his children Laban and Rebekah (born 1876 BC). Scripture gives no dates for him.'),
(514, 'Moab, son of Lot', 'Moab', -1896, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 56, NULL, 'Son of Lot by his elder daughter, born after the destruction of Sodom. Scripture calls him the father of the Moabites, the people from whom Ruth came.', 'Estimate. Born within a year or so of the destruction of Sodom (1897 BC; Gen 19:30-38). Scripture gives no further dates.'),
(515, 'Ben-ammi', NULL, -1896, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 56, NULL, 'Son of Lot by his younger daughter. Scripture calls him the father of the Ammonites. His name means "son of my people."', 'Estimate. Born within a year or so of the destruction of Sodom (1897 BC; Gen 19:30-38). Scripture gives no further dates.'),
(516, 'Bilhah', NULL, -1790, NULL, 1, 1, 'possible', 'matriarch', 'minor', NULL, NULL, NULL, 'Rachel''s maid, given to Jacob as a wife so that Rachel might have children through her. She bore Dan and Naphtali.', 'Estimate. A young woman in Laban''s household when Jacob married (1760 BC, Ussher, Annals section 115), mother of Dan (born about 1748 BC). Scripture gives no dates for her.'),
(517, 'Zilpah', NULL, -1790, NULL, 1, 1, 'possible', 'matriarch', 'minor', NULL, NULL, NULL, 'Leah''s maid, given to Jacob as a wife when Leah had stopped bearing. She bore Gad and Asher.', 'Estimate. A young woman in Laban''s household when Jacob married (1760 BC, Ussher, Annals section 115), mother of Gad and Asher (born about 1747 BC). Scripture gives no dates for her.'),
(900, 'Hamor', NULL, -1790, -1733, 1, 1, 'possible', 'ruler', 'minor', 'Hivite', NULL, NULL, 'Hivite prince of the country around Shechem and father of Shechem. He asked Jacob to give Dinah to his son in marriage and offered the two families a place among his people. He and his son were killed by Simeon and Levi.', 'Estimate. Jacob bought land from the sons of Hamor on his return to Canaan (Gen 33:19; Ussher, 1739 BC); the episode of Dinah follows (Gen 34), placed about 1733 BC. Birth is a rough estimate for the father of a young man.'),
(901, 'Shechem, son of Hamor', NULL, -1755, -1733, 1, 1, 'possible', 'other', 'minor', 'Hivite', 900, NULL, 'Hivite prince, son of Hamor. He seized Dinah, then asked to marry her, and he and his father persuaded the men of the city to be circumcised. Simeon and Levi killed the men of the city while they were sore. He is a different person from the city of Shechem.', 'Estimate. Described as the most honoured of his father''s house (Gen 34:19), so a young man at the episode of Gen 34, placed about 1733 BC, when he was killed (Gen 34:26).'),
(903, 'Gershon', NULL, -1725, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Levi', 164, NULL, 'Eldest son of Levi and brother of Kohath and Merari. His descendants, the Gershonites, cared for the curtains and coverings of the tabernacle.', 'Estimate. Listed first among the sons of Levi (Gen 46:11; Exod 6:16) and born in Canaan before the descent into Egypt in 1706 BC. Levi married in 1753 BC; Scripture gives no year of birth and does not record his death.'),
(904, 'Merari', NULL, -1714, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Levi', 164, NULL, 'Youngest of Levi''s three sons, brother of Gershon and Kohath. His descendants, the Merarites, carried the frames and pillars of the tabernacle.', 'Estimate. Listed third among the sons of Levi (Gen 46:11; Exod 6:16) and born in Canaan before 1706 BC. Scripture gives no year of birth and does not record his death.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(10, 'Moses', NULL, -1571, -1451, 0, 0, 'traditional', 'prophet', 'major', 'Levi', 498, 499, 'Deliverer drawn from the Nile who confronted Pharaoh, led Israel out of Egypt through the sea, and received the law at Sinai. Prophet, lawgiver, and mediator of the covenant, he shepherded Israel through forty wilderness years and viewed the promised land from Nebo; the Torah bears his name.', 'Ussher: born 1571 BC, died 1451 BC (120 years, Deut 34:7). Exodus 1491 BC.'),
(11, 'Aaron', NULL, -1574, -1452, 0, 0, 'traditional', 'priest', 'major', 'Levi', 498, 499, 'Elder brother of Moses, his spokesman before Pharaoh, and Israel''s first high priest, ancestor of the priestly line. Though he faltered at the golden calf, his benediction endures; the priestly blessing of Numbers 6 appears on the Ketef Hinnom silver amulets, the oldest known copies of biblical text.', 'Scripture: 83 when he and Moses spoke to Pharaoh (Exod 7:7), three years older than Moses (80), and 123 when he died on Mount Hor on the first day of the fifth month of the 40th year (Num 33:38-39). Ussher, Annals sections 160 and 268: born 1574 BC, died 1452 BC; the 122-year difference of the year headings is the 123 years of Scripture counted inclusively (he was born late in the year and died in the summer of the 40th year), a few months before Moses.'),
(12, 'Miriam', NULL, -1582, -1452, 1, 0, 'traditional', 'prophet', 'moderate', 'Levi', 498, 499, 'Sister of Moses and Aaron; prophetess.', 'Ussher: born c. 1582 BC, reckoning that she lived 130 years (Scripture gives no age); died at Kadesh in the first month of the 40th year (Num 20:1), 1452 BC, four months before Aaron. Daughter of Amram and Jochebed (Num 26:59).'),
(13, 'Joshua son of Nun', 'Joshua, Yehoshua, Hoshea, Oshea', -1553, -1443, 1, 1, 'traditional', 'warrior', 'major', 'Ephraim', 518, NULL, 'Successor of Moses and one of the two faithful spies, he led Israel across the Jordan, took Jericho, and apportioned the land among the tribes. His farewell charge to choose whom you will serve sealed the covenant at Shechem, and a fierce burn layer at Hazor recalls the conquest narrative.', 'Scripture: died aged 110 (Josh 24:29); the text gives no year. Ussher, Annals 340: died AM 2561, 1443 BC, after living at Timnath-serah many years after the land had rest (c. 1445 BC); birth follows from the age at death (about 62 at the Exodus; Exod 33:11 calls him a young man, using a word that can mean attendant). An earlier c. 1426 BC followed Josephus (Antiquities 5.117).'),
(66, 'Pharaoh of the Exodus', NULL, -1545, -1491, 1, 1, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'The unnamed Egyptian king who enslaved Israel and defied Moses'' demand for release through ten devastating plagues. His army''s destruction in the sea sealed Israel''s deliverance; Scripture withholds his name, and scholars still debate which historical pharaoh he was.', 'Ussher: Exodus 1491 BC. Perished at the Red Sea (Exod 14:28; Ps 136:15). Identity debated.'),
(67, 'Caleb', 'Caleb son of Jephunneh', -1530, -1420, 0, 1, 'traditional', 'warrior', 'moderate', 'Judah', 519, NULL, 'One of two faithful spies (with Joshua) who urged Israel to enter Canaan.', 'Born 1530 BC: aged 40 when sent as a spy from Kadesh-barnea (1490 BC) and 85 when he claimed Hebron 45 years later, c. 1445 BC (Josh 14:7-10). Death unrecorded; c. 1420 BC is an estimate.'),
(68, 'Phinehas', 'Phinehas son of Eleazar', -1480, -1400, 1, 1, 'possible', 'priest', 'moderate', 'Levi', 184, NULL, 'Zealous priest who stopped a plague by his decisive action.', 'Life dates estimated. A grown man when he killed Zimri at Baal-peor in 1452 BC (Num 25:7-13); still ministering before the ark in the Benjamite war (Judg 20:28), which Ussher places after the death of Joshua''s elders, before c. 1413 BC.'),
(69, 'Jethro', 'Reuel', -1590, -1480, 1, 1, 'possible', 'priest', 'moderate', NULL, NULL, NULL, 'Moses'' father-in-law; priest of Midian who advised Moses on delegation.', 'Life dates estimated (no age or year is given). Moses married his daughter c. 1531 BC (Exod 2:21), and he visited Moses at Sinai c. 1491-1490 BC (Exod 18; Num 10:29).'),
(70, 'Zipporah', NULL, -1555, -1460, 1, 1, 'possible', 'other', 'minor', NULL, 69, NULL, 'Wife of Moses; daughter of Jethro.', 'Life dates estimated. Married Moses in Midian c. 1531 BC (Exod 2:21); rejoined him at Sinai (Exod 18:2-5). Death unrecorded.'),
(71, 'Othniel', NULL, -1470, -1390, 1, 1, 'traditional', 'judge', 'minor', 'Judah', 520, NULL, 'First judge of Israel: Othniel son of Kenaz, "Caleb''s younger brother" (Judg 3:9), of Judah, who took Kirjath-sepher and married Caleb''s daughter Achsah. The Spirit of the LORD came upon him and he delivered Israel from Cushan-rishathaim king of Mesopotamia (Judg 3:8-11).', 'Took Kirjath-sepher (Debir) in Joshua''s lifetime, which Ussher dates 1446 BC (Annals §328; Josh 15:16-17; Judg 1:11-13), so born by about 1470 BC. Delivered Israel 1405 BC (Annals §342; the eight years of Cushan began 1413, §341) after eight years of oppression by Cushan-rishathaim (Judg 3:8-10). Ussher measures each period of rest (Judg 3:11, 3:30, 5:31, 8:28) from the previous deliverance, so the figure includes the oppression that he ended. Birth and death are estimates; Judg 3:11 records his death without a year. The texts call Othniel the son of Kenaz and Caleb''s (younger) brother; since Caleb is the son of Jephunneh (Num 13:6), the wording is ambiguous and no sibling link is recorded.'),
(121, 'Job', NULL, -1685, -1495, 1, 1, 'possible', 'sage', 'moderate', NULL, NULL, NULL, 'A blameless man of Uz whose catastrophic losses became Scripture''s deepest exploration of innocent suffering. Refusing his friends'' easy explanations, he carried his anguish directly to God, who answered from the whirlwind, and his endurance became proverbial in both testaments.', 'Ussher, Annals (AM 2369, 1635 BC): Job lived at this time and suffered his trials; Scripture fixes no year. Job 42:16: he lived 140 years after his trials, so death about 1495 BC (1635 less 140). Birth 1685 BC is an estimate (he had ten grown children at the time of the trials, Job 1:2, 4). The book names no king or event. Many scholars place Job in the patriarchal age, about 2000 to 1800 BC, or leave it undated.'),
(179, 'Korah', NULL, -1540, -1490, 1, 1, 'traditional', 'other', 'moderate', 'Levi', 526, NULL, 'Levite who led a rebellion against Moses and Aaron; swallowed by the earth.', 'Num 16:1-35. Ussher: c. 1490 BC.'),
(180, 'Balaam', NULL, -1530, -1452, 1, 1, 'traditional', 'prophet', 'moderate', NULL, 529, NULL, 'Pagan prophet hired by Balak to curse Israel; his donkey spoke. Killed by Israel.', 'Num 22-24; 31:8. Killed in the war against Midian in the 40th year, 1452 BC (Ussher). Birth estimated.'),
(181, 'Balak', NULL, -1510, -1450, 1, 1, 'possible', 'king', 'moderate', NULL, 531, NULL, 'King of Moab who hired Balaam to curse Israel.', 'Num 22-24. King of Moab who hired Balaam to curse Israel, shortly before the death of Moses (1451 BC). His death is not recorded; c. 1450 BC is an estimate.'),
(182, 'Rahab', NULL, -1475, -1400, 1, 1, 'possible', 'matriarch', 'moderate', NULL, NULL, NULL, 'A woman of Jericho who hid Israel''s spies and confessed their God as Lord of heaven and earth, securing her family''s rescue by a scarlet cord. Grafted into Israel, she appears in Matthew''s genealogy of Jesus and is praised for her faith in both Hebrews and James.', 'Josh 2; 6:22-25; Matt 1:5; Heb 11:31. Life dates estimated; an adult at the fall of Jericho in 1451 BC.'),
(183, 'Achan', NULL, -1490, -1451, 1, 0, 'traditional', 'other', 'moderate', 'Judah', 528, NULL, 'Israelite who took forbidden plunder from Jericho; caused defeat at Ai.', 'Josh 7:1-26. Ussher, Annals §313: 1451 BC (AM 2553c).'),
(184, 'Eleazar son of Aaron', 'Eleazar', -1530, -1415, 1, 1, 'possible', 'priest', 'moderate', 'Levi', 11, 522, 'Son of Aaron; succeeded him as high priest. Served during the conquest.', 'Exod 6:23; Num 20:28; Josh 24:33. Life dates estimated; he succeeded Aaron in 1452 BC and outlived Joshua (Josh 24:33).'),
(185, 'Hur', NULL, -1590, -1480, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Held up Moses'' arms during the battle with Amalek alongside Aaron.', 'Exod 17:10-12; 24:14. Life dates estimated: grandfather of Bezalel (Exod 31:2; 1 Chr 2:19-20) and a leader at Sinai in 1491 BC; last mentioned at Exod 24:14.'),
(186, 'Bezalel', NULL, -1520, -1440, 1, 1, 'possible', 'sage', 'moderate', 'Judah', 527, NULL, 'Master craftsman filled with the Spirit of God; built the Tabernacle.', 'Exod 31:1-11; 35:30-35. Filled with the Spirit for Tabernacle construction. Death unrecorded; est. c. 1440 BC (active during wilderness period).'),
(187, 'Dathan', NULL, -1530, -1490, 1, 1, 'traditional', 'other', 'minor', 'Reuben', 530, NULL, 'Reubenite who joined Korah''s rebellion against Moses; swallowed by the earth.', 'Num 16:1-35.'),
(188, 'Abiram', NULL, -1530, -1490, 1, 1, 'traditional', 'other', 'minor', 'Reuben', 530, NULL, 'Reubenite who joined Korah''s rebellion against Moses; swallowed by the earth.', 'Num 16:1-35.'),
(260, 'Hezron', NULL, -1682, -1590, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 174, NULL, 'Son of Perez; grandson of Judah. Went down to Egypt with Jacob. Ancestor of David and Jesus.', 'Gen 46:12; Ruth 4:18; 1 Chr 2:5. Life dates estimated. Gen 46:12 counts him among those who came into Egypt with Jacob (1706 BC), which leaves very little time after the birth of his father Perez; some interpreters take Hezron and Hamul as born in Egypt but reckoned with Jacob''s household.'),
(261, 'Ram', NULL, -1652, -1550, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 260, NULL, 'Son of Hezron; ancestor of David. Mentioned in Ruth''s genealogy and Matthew''s genealogy of Jesus.', 'Ruth 4:19; 1 Chr 2:9-10; Matt 1:3-4. Life dates estimated.'),
(262, 'Amminadab', NULL, -1615, -1500, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 261, NULL, 'Son of Ram; father of Nahshon. His daughter Elisheba married Aaron. Ancestor of David and Jesus.', 'Ruth 4:19-20; Exod 6:23; 1 Chr 2:10; Matt 1:4. Life dates estimated.'),
(263, 'Nahshon', NULL, -1550, -1452, 1, 1, 'possible', 'ruler', 'minor', 'Judah', 262, NULL, 'Son of Amminadab; leader of the tribe of Judah during the Exodus. Brother-in-law of Aaron. Ancestor of David.', 'Num 1:7; 2:3; 7:12-17; Ruth 4:20; Matt 1:4. Life dates estimated: prince of Judah at the census of 1490 BC and brother of Aaron''s wife Elisheba (Exod 6:23); he died in the wilderness before the second census (Num 26:64-65).'),
(264, 'Salmon', 'Sala', -1490, -1400, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 263, NULL, 'Son of Nahshon; husband of Rahab according to Matthew. Father of Boaz. Ancestor of David and Jesus.', 'Ruth 4:20-21; Matt 1:4-5; 1 Chr 2:11. Life dates estimated; Matthew makes him the husband of Rahab of Jericho (1451 BC). The line Salmon, Boaz, Obed, Jesse, David spans roughly 1450 to 1085 BC, too long for four generations, so the genealogy is generally taken to be abbreviated, as Hebrew genealogies often are.'),
(498, 'Amram', NULL, -1630, -1493, 1, 1, 'possible', 'ancestor', 'minor', 'Levi', 497, NULL, 'Levite, son of Kohath, husband of Jochebed and father of Miriam, Aaron and Moses.', 'Estimate. He lived 137 years (Exod 6:20) and, Ussher says (Annals section 151), died shortly before the Israelites left Egypt (1491 BC), which puts his birth about 1630 BC. He was father of Miriam (born c. 1582 BC), Aaron (born 1574 BC) and Moses (born 1571 BC). Exodus 6 may compress the generations between Levi and Moses, as biblical genealogies sometimes do; this timeline follows the text as written.'),
(499, 'Jochebed', NULL, -1620, NULL, 1, 1, 'possible', 'matriarch', 'minor', 'Levi', 164, NULL, 'Mother of Miriam, Aaron and Moses, who hid her infant son from Pharaoh''s decree and was then paid to nurse him for Pharaoh''s daughter.', 'Estimate. Called a daughter of Levi born in Egypt (Num 26:59) and Amram''s father''s sister (Exod 6:20), so born after 1706 BC and before Levi''s death (c. 1613 BC); placed at about 1620 BC. Her death is not recorded.'),
(500, 'Gershom', NULL, -1530, NULL, 1, 1, 'possible', 'other', 'minor', 'Levi', 10, 70, 'Elder son of Moses and Zipporah, born in Midian. His name recalls Moses''s words, "I have been a stranger in a strange land."', 'Estimate. Born in Midian after Moses married Zipporah, about 1531 BC (Exod 2:21-22). His death is not recorded.'),
(501, 'Eliezer, son of Moses', NULL, -1525, NULL, 1, 1, 'possible', 'other', 'minor', 'Levi', 10, 70, 'Younger son of Moses and Zipporah. His name means "my God is help," for God had delivered Moses from Pharaoh''s sword.', 'Estimate. Born in Midian, after Gershom and before Moses returned to Egypt in 1491 BC (Exod 4:20; 18:3-4). His death is not recorded.'),
(518, 'Nun', 'Non', -1570, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Ephraim', NULL, NULL, 'Father of Joshua, Moses'' successor. He is named only as "the father of Joshua" and in the genealogy of Ephraim.', 'Estimate. Born about thirty-four years before Joshua (born 1536 BC). Scripture gives no dates for him.'),
(519, 'Jephunneh', NULL, -1565, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', NULL, NULL, 'Father of Caleb, one of the two faithful spies. He is called a Kenezite, a name linking his family to the clan of Kenaz.', 'Estimate. Born about thirty-five years before Caleb (born 1530 BC). Scripture gives no dates for him.'),
(520, 'Kenaz, father of Othniel', NULL, -1515, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', NULL, NULL, 'Father of Othniel, the first judge of Israel. The texts call Othniel "the son of Kenaz, Caleb''s younger brother," and the Hebrew does not make clear whether the "younger brother" is Othniel or Kenaz.', 'Estimate. Born about forty-five years before Othniel (born 1470 BC). Caleb is the son of Jephunneh (Num 13:6), so the relationship of Kenaz to Caleb is uncertain: the phrase may mean that Kenaz was Caleb''s brother, or that Othniel was a kinsman counted as his brother. No sibling link is recorded here for that reason.'),
(521, 'Achsah', NULL, -1472, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 67, NULL, 'Daughter of Caleb, offered in marriage to whoever would take Kirjath-sepher. Othniel took the city and married her, and she then asked her father for springs of water to go with her southern land.', 'Estimate. Married when Caleb was about eighty-five (Josh 14:10; 15:16-19), so born in the 1470s BC. Scripture gives no dates for her.'),
(522, 'Elisheba', NULL, -1570, NULL, 1, 1, 'possible', 'matriarch', 'minor', 'Judah', 262, NULL, 'Wife of Aaron, daughter of Amminadab and sister of Nahshon, the prince of Judah. She was the mother of Nadab, Abihu, Eleazar and Ithamar, and so of Israel''s priestly families.', 'Estimate. Born about the same time as Aaron (born 1574 BC) as sister of Nahshon (born about 1550 BC). Scripture gives no dates for her.'),
(523, 'Nadab, son of Aaron', 'Nadab', -1534, -1490, 1, 1, 'possible', 'priest', 'minor', 'Levi', 11, 522, 'Eldest son of Aaron. With his brother Abihu he offered "strange fire" before the LORD and both died at once, soon after the tabernacle was set up.', 'Estimate. Aaron''s eldest son (Exod 6:23), born about forty years before the Exodus. He died on the day the priesthood began its service, about 1490 BC (Lev 10:1-2; Num 3:4). Not the same as Nadab, king of Israel.'),
(524, 'Abihu', NULL, -1532, -1490, 1, 1, 'possible', 'priest', 'minor', 'Levi', 11, 522, 'Second son of Aaron. He and his brother Nadab went up with Moses and the elders to see God on Sinai, but died for offering unauthorised fire at the altar.', 'Estimate. Born just after Nadab. He died with Nadab about 1490 BC, leaving no sons (Lev 10:1-2; Num 3:4).'),
(525, 'Ithamar', NULL, -1526, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', 11, 522, 'Youngest son of Aaron. After the deaths of Nadab and Abihu he served as priest with Eleazar and oversaw the work of the Gershonites and Merarites. The line of Eli later traced back to him.', 'Estimate. Born after Eleazar, before the Exodus (1491 BC). His death is not recorded. Eli is usually taken to be of Ithamar''s line (compare 1 Kings 2:27 and 1 Chronicles 24:3), though 1 Samuel does not say so.'),
(526, 'Izhar', NULL, -1626, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Levi', 497, NULL, 'Son of Kohath, brother of Amram and uncle of Moses and Aaron. He was the father of Korah, who led the rebellion in the wilderness.', 'Estimate. Born a few years after his brother Amram, as a son of Kohath (born before 1706 BC). Scripture gives no dates for him.'),
(527, 'Uri', NULL, -1555, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 185, NULL, 'Son of Hur and father of Bezalel, the craftsman of the tabernacle. He is named only in the genealogy of Bezalel.', 'Estimate. Born between Hur (born 1590 BC) and Bezalel (born 1520 BC). Exodus 31:2 calls Hur his father without further description; identifying this Hur with the Hur who held up Moses'' arms (Exod 17:12) is the usual reading but is not stated in the text.'),
(528, 'Carmi, father of Achan', NULL, -1525, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', NULL, NULL, 'Judahite, father of Achan, whose theft of the devoted spoil of Jericho brought defeat at Ai. Joshua''s account lists his line back through Zabdi to Zerah.', 'Estimate. Born about thirty-five years before Achan (born 1490 BC). Scripture gives no dates for him. Joshua 7:1 gives the line as Achan, Carmi, Zabdi, Zerah; the names between Carmi and Zerah are not added here.'),
(529, 'Beor', 'Bosor', -1565, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Balaam the seer, who was summoned by the king of Moab to curse Israel. Scripture gives no details of Beor himself.', 'Estimate. Born about thirty-five years before Balaam (born 1530 BC). In 2 Peter 2:15 the name appears as Bosor.'),
(530, 'Eliab, father of Dathan and Abiram', NULL, -1560, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Reuben', NULL, NULL, 'Reubenite, son of Pallu and father of Dathan and Abiram, who joined Korah''s rebellion against Moses and Aaron.', 'Estimate. Born about thirty years before Dathan and Abiram (born about 1530 BC). Scripture gives no dates for him. Numbers 26:8-9 also names a son Nemuel, not added here.'),
(531, 'Zippor', NULL, -1545, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Balak, king of Moab, who hired Balaam to curse Israel. He is named only as Balak''s father.', 'Estimate. Born about thirty-five years before Balak (born 1510 BC). Scripture gives no dates for him.'),
(905, 'Machir, son of Manasseh', NULL, -1690, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Manasseh', 171, NULL, 'Son of Manasseh and grandfather of Gilead. His children were brought up on Joseph''s knees. His family went to Gilead, drove out the Amorites and received the land from Moses.', 'Estimate. His children were on Joseph''s knees (Gen 50:23), so he was born well before Joseph''s death about 1635 BC. The conquest of Gilead in Num 32:39-40 (about 1452 BC) is by his descendants, the clan of Machir; the person himself cannot have lived so long. Death not recorded.'),
(906, 'Zelophehad', NULL, -1530, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Manasseh', NULL, NULL, 'Descendant of Manasseh through Machir, Gilead and Hepher. He died in the wilderness leaving five daughters and no sons, which led to the law that daughters inherit when there is no son.', 'Estimate. He died in the wilderness (Num 27:3), between the Exodus in 1491 BC and the census of about 1452 BC, leaving five unmarried daughters. Hepher and Gilead, named in Num 27:1, are not separate rows here. Machir is three generations earlier, so the text compresses the generations.'),
(907, 'Mahlah, daughter of Zelophehad', NULL, -1500, NULL, 1, 1, 'possible', 'other', 'minor', 'Manasseh', 906, NULL, 'Eldest of the five daughters of Zelophehad, who asked Moses for their father''s inheritance. She married a son of her father''s brother.', 'Estimate. Unmarried at the petition of about 1452 BC (Num 27:1-7) and later married to a cousin (Num 36:11). Order of birth follows the list in Num 26:33.'),
(908, 'Noah, daughter of Zelophehad', NULL, -1498, NULL, 1, 1, 'possible', 'other', 'minor', 'Manasseh', 906, NULL, 'One of the five daughters of Zelophehad who petitioned for their father''s inheritance. Not the same person as the flood patriarch Noah.', 'Estimate. Unmarried at the petition of about 1452 BC (Num 27:1-7) and later married to a cousin (Num 36:11). Order of birth follows Num 26:33.'),
(909, 'Hoglah, daughter of Zelophehad', NULL, -1496, NULL, 1, 1, 'possible', 'other', 'minor', 'Manasseh', 906, NULL, 'One of the five daughters of Zelophehad who petitioned Moses, and later Joshua, for an inheritance among their father''s brothers.', 'Estimate. Unmarried at the petition of about 1452 BC (Num 27:1-7) and later married to a cousin (Num 36:11). Order of birth follows Num 26:33.'),
(910, 'Milcah, daughter of Zelophehad', NULL, -1494, NULL, 1, 1, 'possible', 'other', 'minor', 'Manasseh', 906, NULL, 'One of the five daughters of Zelophehad who received land among the tribe of Manasseh. Not the same person as Milcah, wife of Nahor.', 'Estimate. Unmarried at the petition of about 1452 BC (Num 27:1-7) and later married to a cousin (Num 36:11). Order of birth follows Num 26:33.'),
(911, 'Tirzah, daughter of Zelophehad', NULL, -1492, NULL, 1, 1, 'possible', 'other', 'minor', 'Manasseh', 906, NULL, 'Youngest named daughter of Zelophehad, who asked for her father''s inheritance with her sisters. Not the same person as the city of Tirzah.', 'Estimate. Unmarried at the petition of about 1452 BC (Num 27:1-7) and later married to a cousin (Num 36:11). Order of birth follows Num 26:33.'),
(922, 'Eliphaz the Temanite', NULL, -1690, NULL, 1, 1, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'The first and eldest of Job''s three friends, from Teman. He came to comfort Job, argued that suffering follows sin, and was rebuked by God at the end; Job prayed for him.', 'Estimate. Dated with Job, whom Ussher places at 1635 BC. The friends were "very aged" (Job 15:10; 32:6), so born near or before Job''s own birth about 1685 BC. Many scholars date the book much earlier or leave it undated. Death not recorded.'),
(923, 'Bildad the Shuhite', NULL, -1685, NULL, 1, 1, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'One of Job''s three friends, from the land of Shuah. He urged Job to seek God and appealed to the wisdom of earlier generations. God rebuked him with his companions.', 'Estimate. Dated with Job (Ussher, 1635 BC); an aged man at the time of the trials (Job 32:6). Death not recorded.'),
(924, 'Zophar the Naamathite', NULL, -1685, NULL, 1, 1, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'One of Job''s three friends, from Naamah. He spoke sharply to Job, saying God was exacting less than his guilt deserved. God rebuked him with Eliphaz and Bildad.', 'Estimate. Dated with Job (Ussher, 1635 BC); an aged man at the time of the trials (Job 32:6). Death not recorded.'),
(925, 'Elihu, son of Barachel', NULL, -1660, NULL, 1, 1, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'Young man of the family of Ram, from Buz, who waited while the older men spoke and then answered both Job and his three friends, saying God is just and uses suffering to teach. God does not rebuke him.', 'Estimate. Dated with Job (Ussher, 1635 BC). He was much younger than the others (Job 32:6), so born later than Job and his friends. Death not recorded.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(14, 'Deborah', NULL, -1330, -1255, 1, 1, 'traditional', 'judge', 'major', NULL, NULL, NULL, 'Prophet and judge who held court beneath a palm in the hill country of Ephraim, she summoned Barak and led Israel to victory over Sisera''s Canaanite forces. The Song of Deborah in Judges 5 is widely regarded as one of the oldest poems preserved in the Hebrew Bible.', 'Jabin of Hazor oppressed Israel twenty years (Judg 4:3), c. 1305-1285 BC; Deborah and Barak defeated Sisera c. 1285 BC (Ussher), who counts the forty years of rest (Judg 5:31) from Ehud''s deliverance. "A mother in Israel" (Judg 5:7) at the victory; birth and death are estimates.'),
(15, 'Gideon', 'Jerubbaal', -1300, -1236, 1, 0, 'traditional', 'judge', 'moderate', 'Manasseh', 534, NULL, 'Judge called from threshing wheat in a winepress to deliver Israel from Midian, he routed a vast host with only three hundred men so the glory would be God''s alone. Also named Jerubbaal; a jar inscription bearing that rare name was unearthed at Khirbet al-Rai in the Judean foothills.', 'Midian oppressed Israel seven years (Judg 6:1), c. 1252-1245 BC; Gideon''s victory c. 1245 BC (Ussher). Ussher counts the forty years of quiet "in the days of Gideon" (Judg 8:28) from Deborah''s victory, so Gideon died c. 1236 BC, when Abimelech seized power. His age is not given: his firstborn Jether was still a youth at the victory (Judg 8:20), and he died "in a good old age" (Judg 8:32). Birth is an estimate. Annals §356-357.'),
(16, 'Samson', NULL, -1155, -1117, 0, 0, 'traditional', 'judge', 'major', 'Dan', 192, NULL, 'Nazirite judge endowed with extraordinary strength, he battled the Philistines single-handedly until Delilah''s betrayal cost him his hair, his eyes, and his freedom. In death he toppled Dagon''s temple, and his story mirrors Israel''s own struggle with compromised devotion.', 'Ussher: born c. 1155 BC, soon after the Philistines'' forty years of domination began (Judg 13:1); judged Israel twenty years "in the days of the Philistines" (Judg 15:20; 16:31), c. 1137-1117 BC, and died at Gaza in 1117 BC, the year before Eli. Annals §380, §382, §384.'),
(17, 'Ruth', NULL, -1195, -1130, 1, 1, 'possible', 'matriarch', 'moderate', NULL, NULL, NULL, 'Moabite great-grandmother of David.', 'Life dates estimated. The story is set "in the days when the judges ruled" (Ruth 1:1); placing Obed''s birth c. 1170 BC leaves a natural three generations to David (b. 1085 BC). Boaz praised her for not following young men (Ruth 3:10).'),
(18, 'Samuel', NULL, -1150, -1060, 1, 1, 'possible', 'prophet', 'major', 'Levi', 544, 75, 'Last of the judges and first of the great prophets, dedicated at the Shiloh sanctuary in answer to Hannah''s prayer. He anointed both Saul and David, guiding Israel''s passage from tribal confederation to monarchy while insisting that obedience outweighs sacrifice.', 'Life dates estimated (Ussher gives no year). Serving Eli at Shiloh as a child (1 Sam 1-3), he judged Israel after Eli''s death in 1116 BC, routed the Philistines at Mizpah c. 1096 BC (1 Sam 7), anointed Saul in 1095 BC and David c. 1063 BC, and died c. 1060 BC, before David''s second flight to Gath (1 Sam 25:1; 27:1-2).'),
(19, 'Saul', NULL, -1135, -1055, 1, 0, 'traditional', 'king', 'major', 'Benjamin', 548, NULL, 'Israel''s first king, a tall Benjaminite anointed by Samuel, who won early victories over Ammon and the Philistines. His impatience and disobedience cost his house the throne, and his tragic decline beside David''s rise ended on Mount Gilboa, where he fell in battle.', 'Ussher: reigned forty years (Acts 13:21), 1095-1055 BC, and fell at Gilboa. His age at accession is not given (the Hebrew of 1 Sam 13:1 is defective); the birth year is an estimate allowing for a son, Jonathan, who commanded a thousand men in Saul''s second year (1 Sam 13:2). Mainstream scholarship dates his reign c. 1050-1010 BC.'),
(72, 'Ehud', NULL, -1365, -1306, 1, 1, 'traditional', 'judge', 'minor', 'Benjamin', 536, NULL, 'Left-handed Benjamite judge, son of Gera, who killed Eglon king of Moab with a hidden dagger and then led Israel to subdue Moab (Judg 3:15-30).', 'Moab oppressed Israel eighteen years (Judg 3:14), c. 1343-1325 BC; Ehud killed Eglon c. 1325 BC (Ussher), who counts the eighty years of rest (Judg 3:30) from Othniel''s deliverance. Israel sinned again "when Ehud was dead" (Judg 4:1), before Jabin''s oppression began c. 1305 BC. Birth and death are estimates.'),
(73, 'Jephthah', NULL, -1225, -1182, 1, 1, 'traditional', 'judge', 'minor', NULL, 535, NULL, 'Gileadite warrior, driven out by his half-brothers, who was recalled to lead Gilead against the Ammonites and defeated them. His rash vow cost him his only daughter, and he afterwards fought the men of Ephraim (Judg 11:1-12:7).', 'Judged Israel six years (Judg 12:7), c. 1188-1182 BC (Ussher), after defeating the Ammonites. His "three hundred years" since Israel took Heshbon (Judg 11:26; Heshbon taken 1452 BC) are about 264 on this reckoning, so a round figure; reconstructions that run the Ammonite and Philistine oppressions together (Judg 10:7) date him several decades later. Birth estimated; he had a grown daughter at the victory.'),
(74, 'Eli', NULL, -1214, -1116, 0, 0, 'traditional', 'priest', 'moderate', 'Levi', NULL, NULL, 'High priest at Shiloh who judged Israel forty years and brought up the boy Samuel. His failure to restrain his sons Hophni and Phinehas brought judgment on his house, and he died at 98 when news came that the ark had been taken (1 Sam 1-4).', 'Ussher: born 1214 BC; judged Israel forty years (1 Sam 4:18), c. 1157-1116 BC, following Abdon, and died aged 98 on hearing that the ark was taken (1 Sam 4:15-18), 1116 BC. Annals §365, §378, §386.'),
(75, 'Hannah', NULL, -1175, -1100, 1, 1, 'possible', 'matriarch', 'moderate', NULL, NULL, NULL, 'Mother of Samuel; prayed fervently for a child and dedicated him to God.', 'Life dates estimated (1 Sam 1-2); mother of Samuel (born c. 1150 BC).'),
(76, 'Boaz', NULL, -1235, -1160, 1, 1, 'possible', 'patriarch', 'moderate', 'Judah', 264, 182, 'Kinsman-redeemer who married Ruth; ancestor of David.', 'Life dates estimated: a kinsman of Elimelech, much older than Ruth (Ruth 2:1; 3:10), father of Obed c. 1170 BC. Matthew names Rahab of Jericho (1451 BC) as his mother (Matt 1:5); as that is nearly three centuries before Ruth''s story, the link Salmon-Boaz is generally taken to be abbreviated, "begat" meaning "was ancestor of".'),
(77, 'Naomi', NULL, -1225, -1165, 1, 1, 'possible', 'other', 'moderate', NULL, NULL, NULL, 'Ruth''s mother-in-law who returned from Moab to Bethlehem.', 'Life dates estimated. Of Bethlehem; returned from Moab a widow, too old to remarry (Ruth 1:12), and nursed her grandson Obed (Ruth 4:16), c. 1170 BC on these estimates. The book is set "when the judges ruled" (Ruth 1:1) without saying which judge.'),
(78, 'Abimelech', NULL, -1265, -1233, 1, 0, 'traditional', 'king', 'minor', 'Manasseh', 15, NULL, 'Son of Gideon who made himself king; killed at Thebez.', 'Son of Gideon''s concubine in Shechem (Judg 8:31). Made king at Shechem after Gideon''s death, c. 1236 BC; reigned three years (Judg 9:22) and was killed at Thebez c. 1233 BC (Ussher). Birth estimated. Annals §358-360.'),
(83, 'Jonathan', NULL, -1115, -1055, 1, 0, 'traditional', 'warrior', 'moderate', 'Benjamin', 19, NULL, 'Saul''s son and David''s closest friend; died at Gilboa.', 'Birth estimated: he commanded a thousand men in Saul''s second year (1 Sam 13:2-3), c. 1093 BC, and had a five-year-old son when he died (2 Sam 4:4). Died with Saul at Gilboa, 1055 BC (Ussher; 1 Sam 31:2).'),
(189, 'Barak', NULL, -1320, -1255, 1, 1, 'possible', 'warrior', 'moderate', 'Naphtali', 532, NULL, 'Military commander who fought alongside Deborah against Sisera.', 'Judg 4-5; Heb 11:32. Life dates estimated around the victory over Sisera, c. 1285 BC (Ussher).'),
(190, 'Jael', NULL, -1315, -1250, 1, 1, 'possible', 'warrior', 'moderate', NULL, NULL, NULL, 'Kenite woman who killed Sisera by driving a tent peg through his temple.', 'Judg 4:17-22; 5:24-27. Killed Sisera with a tent peg, c. 1285 BC (Ussher). Life dates estimated.'),
(191, 'Sisera', NULL, -1320, -1285, 1, 1, 'traditional', 'warrior', 'minor', NULL, NULL, NULL, 'Canaanite general defeated by Deborah and Barak; killed by Jael.', 'Judg 4-5. Killed by Jael on the day of his defeat, c. 1285 BC (Ussher). Birth estimated.'),
(192, 'Manoah', NULL, -1200, -1130, 1, 1, 'possible', 'other', 'minor', 'Dan', NULL, NULL, 'Father of Samson; visited by the Angel of the LORD.', 'Judg 13-14; 16:31. Life dates estimated: Samson was born c. 1155 BC, Manoah went with him to Timnah (Judg 14:5), and Samson was buried in Manoah''s tomb (Judg 16:31).'),
(193, 'Delilah', NULL, -1145, -1100, 1, 1, 'possible', 'other', 'moderate', NULL, NULL, NULL, 'A woman of the valley of Sorek whom Samson loved. Bribed by the Philistine lords, she drew out the secret of his strength and betrayed him (Judg 16:4-21); Scripture does not say whether she was a Philistine or an Israelite.', 'Judg 16:4-21. Betrayed Samson c. 1117 BC (Ussher). Life dates are estimates.'),
(194, 'Tola', NULL, -1280, -1210, 1, 0, 'traditional', 'judge', 'minor', 'Issachar', NULL, NULL, 'A man of Issachar, son of Puah, who lived at Shamir in Mount Ephraim and judged Israel twenty-three years after Abimelech (Judg 10:1-2).', 'Judged Israel 23 years (Judg 10:1-2), c. 1233-1210 BC (Ussher), and died. Birth estimated. Annals §360, §366.'),
(195, 'Jair', 'Jair the Gileadite', -1255, -1188, 1, 0, 'traditional', 'judge', 'minor', 'Manasseh', NULL, NULL, 'Judge of Israel for 22 years; had 30 sons who rode 30 donkeys.', 'Judged Israel 22 years (Judg 10:3-5), c. 1210-1188 BC (Ussher). Ussher begins the eighteen-year oppression by the Ammonites and Philistines (Judg 10:7-8) c. 1206 BC, in Jair''s time, although the narrative tells it after his burial, and ends it with Jephthah''s victory in 1188 BC, the year Jair died. Birth estimated. Annals §366-370.'),
(196, 'Ibzan', NULL, -1235, -1175, 1, 1, 'traditional', 'judge', 'minor', NULL, NULL, NULL, 'Judge of Israel from Bethlehem for 7 years; had 30 sons and 30 daughters.', 'Judged Israel seven years after Jephthah (Judg 12:8-10), c. 1182-1175 BC (Ussher). Birth estimated; he had married off thirty sons and thirty daughters.'),
(197, 'Elon', NULL, -1225, -1165, 1, 0, 'traditional', 'judge', 'minor', 'Zebulun', NULL, NULL, 'A Zebulonite who judged Israel ten years and was buried at Aijalon in Zebulun (Judg 12:11-12).', 'Judged Israel ten years (Judg 12:11-12), c. 1175-1165 BC (Ussher). Birth estimated. Annals §374, §377.'),
(198, 'Abdon', NULL, -1235, -1157, 1, 0, 'traditional', 'judge', 'minor', 'Ephraim', NULL, NULL, 'Son of Hillel the Pirathonite, of Ephraim, who judged Israel eight years; he had forty sons and thirty grandsons who rode on seventy ass colts (Judg 12:13-15).', 'Judged Israel eight years (Judg 12:13-15), c. 1165-1157 BC (Ussher). Birth estimated; he had grandsons of riding age. Annals §377-378.'),
(200, 'Abner', NULL, -1130, -1048, 1, 0, 'traditional', 'warrior', 'moderate', 'Benjamin', 549, NULL, 'Commander of Saul''s army; supported Ish-bosheth then defected to David. Killed by Joab.', 'Birth estimated: son of Ner, Saul''s uncle (1 Sam 14:50-51), and already captain of Saul''s army early in the reign. Killed by Joab at Hebron in 1048 BC (Ussher; 2 Sam 3:27). Annals §415.'),
(207, 'Ahithophel', NULL, -1110, -1023, 1, 0, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'David''s counselor who defected to Absalom; hanged himself when his advice was rejected.', '2 Sam 15:12, 31; 16:20-17:23. Hanged himself during Absalom''s revolt, 1023 BC. If Bathsheba''s father Eliam (2 Sam 11:3) is the Eliam son of Ahithophel among David''s mighty men (2 Sam 23:34), he was her grandfather; the birth year is an estimate allowing for that. Ussher, Annals §442-444.'),
(221, 'Nabal', NULL, -1100, -1060, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Wealthy but foolish man married to Abigail; refused to help David. Died after the LORD struck him.', '1 Sam 25:2-42. Died about ten days after his feast (1 Sam 25:38), soon after Samuel''s death and before David fled to Gath, c. 1060 BC. Birth estimated.'),
(265, 'Obed', NULL, -1170, -1100, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 76, 17, 'Son of Boaz and Ruth; father of Jesse, grandfather of David. Central link in the Messianic lineage.', 'Ruth 4:13-17, 21-22; 1 Chr 2:12; Matt 1:5. Life dates estimated.'),
(266, 'Jesse', 'Yishai', -1140, -1060, 1, 1, 'possible', 'patriarch', 'moderate', 'Judah', 265, NULL, 'A Bethlehemite of the tribe of Judah, grandson of Ruth and Boaz, and father of eight sons, the youngest of whom Samuel anointed as king. Isaiah''s promise of a shoot from the stump of Jesse made his name shorthand for the messianic hope Christians see fulfilled in Jesus.', '1 Sam 16:1-13; 17:12-14; Ruth 4:22; Isa 11:1, 10; Matt 1:5-6. Life dates estimated: "an old man in the days of Saul" (1 Sam 17:12), father of David (b. 1085 BC) in his old age.'),
(420, 'Shamgar', 'Shamgar son of Anath', -1340, -1290, 1, 1, 'possible', 'judge', 'minor', NULL, NULL, NULL, 'Son of Anath, named after Ehud as one who "also delivered Israel", killing six hundred Philistines with an ox goad (Judg 3:31). The Song of Deborah recalls "the days of Shamgar" as a time when the highways were deserted (Judg 5:6).', 'No years are given. Ussher places him after Ehud (c. 1325 BC), and Judg 5:6 makes him an older contemporary of Deborah and Jael (c. 1285 BC). Life dates are estimates.'),
(532, 'Abinoam', NULL, -1355, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Naphtali', NULL, NULL, 'Father of Barak, who led Israel''s army with Deborah against Sisera. He was from Kedesh in Naphtali.', 'Estimate. Born about thirty-five years before Barak (born 1320 BC). Scripture gives no dates for him.'),
(533, 'Heber the Kenite', NULL, -1320, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Kenite, of the family of Hobab, Moses'' father-in-law. He had separated from the other Kenites and pitched his tent near Kedesh, at peace with Jabin of Hazor; his wife Jael killed Sisera.', 'Estimate. Husband of Jael (born about 1315 BC). Scripture gives no dates for him, and the Kenite clan is described as living at peace with Jabins Canaanite kingdom at the time of Sisera''s defeat (about 1285 BC).'),
(534, 'Joash, father of Gideon', 'Joash the Abiezrite', -1335, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Manasseh', NULL, NULL, 'Abiezrite of Ophrah, father of Gideon. He kept an altar to Baal that Gideon tore down, and defended his son when the townsmen demanded his death.', 'Estimate. Born about thirty-five years before Gideon (born 1300 BC). Not the same as Joash, king of Judah. Scripture gives no dates for him.'),
(535, 'Gilead, father of Jephthah', NULL, -1255, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Manasseh', NULL, NULL, 'Father of Jephthah the Gileadite. The text names him as the father, while also noting that Jephthah''s mother was a prostitute; his other sons drove Jephthah out.', 'Estimate. Born about thirty years before Jephthah (born 1225 BC). Scripture gives no dates for him. The name is also that of a region east of the Jordan.'),
(536, 'Gera, father of Ehud', NULL, -1400, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', NULL, NULL, 'Benjamite, father of Ehud, the left-handed judge who killed Eglon, king of Moab.', 'Estimate. Born about thirty-five years before Ehud (born 1365 BC). Scripture gives no dates for him. Other men of the same name appear in Benjamin''s genealogies.'),
(537, 'Hophni', NULL, -1175, -1116, 1, 0, 'possible', 'priest', 'minor', 'Levi', 74, NULL, 'Elder son of Eli, priest at Shiloh with his brother Phinehas. The two abused the sacrifices and were condemned by a prophet; both died on the day the Philistines took the ark.', 'Estimate. Born while Eli (born 1214 BC) was in his thirties. His death in the battle in which the ark was captured (1116 BC) is dated by that event (1 Sam 4:11).'),
(538, 'Phinehas, son of Eli', NULL, -1172, -1116, 1, 0, 'possible', 'priest', 'minor', 'Levi', 74, NULL, 'Younger son of Eli, priest at Shiloh with Hophni. He died in the battle in which the ark was taken, and his wife died giving birth to Ichabod on hearing the news.', 'Estimate. Born shortly after Hophni. His death in the battle in which the ark was captured (1116 BC) is dated by that event (1 Sam 4:11). Not the same as Phinehas, son of Eleazar.'),
(539, 'Ichabod', NULL, -1116, NULL, 0, 1, 'probable', 'other', 'minor', 'Levi', 538, NULL, 'Son of Phinehas and grandson of Eli, born as his mother died after hearing that the ark was lost. She named him Ichabod, "the glory has departed." His brother Ahitub appears in 1 Samuel 14:3.', 'Born at the time the ark was captured (1116 BC; 1 Sam 4:19-21). The text does not record his death. Ussher, Annals §386.'),
(540, 'Elimelech', NULL, -1235, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Man of Bethlehem who took his wife Naomi and sons Mahlon and Chilion to Moab in a famine and died there. Boaz later redeemed his land.', 'Estimate. Born about ten years before Naomi (born 1225 BC); he died in Moab, within the period of the judges, before his sons (Ruth 1:1-5). Scripture gives no dates for him.'),
(541, 'Mahlon', NULL, -1200, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 540, 77, 'Elder son of Elimelech and Naomi, who married Ruth the Moabite and died childless in Moab. Boaz married Ruth to raise up his name.', 'Estimate. Born about twenty-five years after his parents'' birth; he married about ten years before dying in Moab (Ruth 1:4-5). His death is not dated.'),
(542, 'Chilion', NULL, -1198, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 540, 77, 'Younger son of Elimelech and Naomi, husband of Orpah. He died in Moab without children.', 'Estimate. Born just after Mahlon; he died in Moab about ten years after the marriages (Ruth 1:4-5). His death is not dated.'),
(543, 'Orpah', NULL, -1197, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Moabite woman, wife of Chilion. After his death she kissed Naomi goodbye and stayed in Moab while her sister-in-law Ruth went on to Bethlehem.', 'Estimate; she married about the time Ruth did (Ruth 1:4). Scripture gives no dates for her.'),
(544, 'Elkanah, father of Samuel', NULL, -1190, NULL, 1, 1, 'possible', 'other', 'minor', 'Levi', NULL, NULL, 'Man of Ramathaim in the hills of Ephraim who went up yearly to Shiloh with his wives Hannah and Peninnah. He was the father of Samuel.', 'Estimate. Born about forty years before Samuel (born 1150 BC). Scripture gives no dates for him. 1 Samuel 1:1 calls him an Ephrathite, while 1 Chronicles 6:27-28 lists a Levite Elkanah as father of Samuel; the sources differ on his tribe.'),
(545, 'Joel, son of Samuel', NULL, -1125, NULL, 1, 1, 'possible', 'judge', 'minor', 'Levi', 18, NULL, 'Eldest son of Samuel. With his brother Abiah he judged at Beer-sheba, but they took bribes and perverted justice, and the elders used their conduct to ask for a king.', 'Estimate. Born while Samuel (born 1150 BC) was in his twenties; Samuel made his sons judges when he was old (1 Sam 8:1-2), shortly before Saul''s anointing in 1095 BC. 1 Chronicles 6:28 gives the firstborn''s name as Vashni; the two names are commonly reconciled but the text does not say so.'),
(546, 'Abiah, son of Samuel', 'Abijah', -1122, NULL, 1, 1, 'possible', 'judge', 'minor', 'Levi', 18, NULL, 'Second son of Samuel, judge at Beer-sheba with his brother Joel. Their corruption led Israel''s elders to ask Samuel for a king.', 'Estimate. Born shortly after Joel; Samuel made his sons judges when he was old (1 Sam 8:1-2). His death is not recorded.'),
(547, 'Abiel', NULL, -1205, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', NULL, NULL, 'Benjamite, grandfather of King Saul and of Abner. His sons Kish and Ner were brothers, so Saul and Abner were cousins.', 'Estimate. Born about thirty-five years before his sons Kish and Ner. 1 Samuel 9:1 and 14:51 call both of them sons of Abiel; 1 Chronicles 8:33 and 9:39 give a different arrangement (Ner begat Kish; 9:36 lists them as brothers), and the genealogies are hard to reconcile. This timeline follows 1 Samuel.'),
(548, 'Kish', NULL, -1170, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', 547, NULL, 'Benjamite, "a mighty man of power," father of King Saul. Saul was sent out to look for his father''s lost donkeys on the day Samuel met him.', 'Estimate. Born about thirty-five years before Saul (born 1135 BC). Scripture gives no dates for him.'),
(549, 'Ner', NULL, -1168, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', 547, NULL, 'Benjamite, brother of Kish and uncle of King Saul. His son Abner commanded Saul''s army.', 'Estimate. Born near his brother Kish, about forty years before Abner (born 1130 BC). The KJV of 1 Samuel 14:50 calls Abner "Saul''s uncle," but verse 51 shows Ner to be the uncle and Abner the cousin. 1 Chronicles 8:33 places Ner as Kish''s father; this timeline follows 1 Samuel.'),
(550, 'Ahinoam, wife of Saul', NULL, -1130, NULL, 1, 1, 'possible', 'queen', 'minor', 'Benjamin', NULL, NULL, 'Wife of King Saul, daughter of Ahimaaz. The text names her as his wife but does not say which of his children were hers. She is a different woman from David''s wife Ahinoam of Jezreel.', 'Estimate. Roughly the age of Saul (born 1135 BC), who had grown sons by the time he became king. Scripture gives no dates for her.'),
(551, 'Merab', NULL, -1110, NULL, 1, 1, 'possible', 'other', 'minor', 'Benjamin', 19, NULL, 'Saul''s elder daughter, offered to David as a reward for fighting the Philistines but given instead to Adriel the Meholathite.', 'Estimate. Born before her younger sister Michal (born 1085 BC) and after Jonathan (born 1115 BC). Scripture gives no dates for her.'),
(552, 'Eliab, son of Jesse', NULL, -1120, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Judah', 266, NULL, 'Eldest son of Jesse. Samuel took him for the Lord''s anointed because of his height, but God had chosen another; later he rebuked David for coming to the battle line against Goliath.', 'Estimate. Born about thirty-five years before David (born 1085 BC), as the eldest of Jesse''s eight sons. Scripture gives no dates for him.'),
(553, 'Abinadab, son of Jesse', NULL, -1117, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Judah', 266, NULL, 'Second son of Jesse. He was passed over by Samuel and followed Saul to the battle against the Philistines.', 'Estimate. Born between Eliab and Shammah (about 1120 to 1114 BC). Scripture gives no dates for him.'),
(554, 'Shammah, son of Jesse', 'Shimma, Shimeah, Shammah', -1114, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Judah', 266, NULL, 'Third son of Jesse, passed over by Samuel and a soldier in Saul''s army. The Chronicles list him as Shimma; his son Jonadab, a wily man, advised Amnon.', 'Estimate. Born about thirty years before David (born 1085 BC). The identification of Shammah (1 Sam 16:9; 17:13) with Shimma (1 Chron 2:13) and Shimeah (2 Sam 13:3) is the usual reading; the text gives the names separately.'),
(555, 'Zeruiah', NULL, -1108, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Sister of David and mother of the three brothers Joab, Abishai and Asahel, who served in his army. The text calls her David''s sister but does not name her husband or say which parent she shared with David.', 'Estimate, born before her son Joab (born 1085 BC). 1 Chronicles 2:16 calls Zeruiah and Abigail "sisters" of Jesse''s sons. 2 Samuel 17:25 calls Abigail the daughter of Nahash and sister of Zeruiah, so Zeruiah and Abigail may have had a different father or mother from David; no parent is recorded for her here.'),
(556, 'Abigail, sister of David', NULL, -1106, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Sister of David and of Zeruiah, mother of Amasa, whom Absalom made commander of his army. She is a different woman from Abigail the wife of Nabal and David.', 'Estimate, born before her son Amasa. 1 Chronicles 2:16 calls her a sister of Jesse''s sons; 2 Samuel 17:25 calls her the daughter of Nahash. The text does not reconcile the two, and no parent is recorded for her here.'),
(559, 'Jether, father of Amasa', 'Ithra', -1110, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Husband of Abigail, David''s sister, and father of Amasa. 1 Chronicles calls him an Ishmaelite; 2 Samuel calls him Ithra an Israelite.', 'Estimate; born slightly before his wife Abigail (born about 1106 BC). The two names and descriptions (Jether the Ishmaelite, 1 Chron 2:17; Ithra the Israelite, 2 Sam 17:25) are usually taken to be one man, with a difference in the manuscripts.'),
(569, 'Ahitub, father of Zadok', NULL, -1135, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'Priest, father of Zadok, who served David and anointed Solomon. He is not the Ahitub who was the grandson of Eli.', 'Estimate. Born about forty-five years before Zadok (born 1090 BC). Scripture gives no dates for him. 1 Chronicles 6:8 places Zadok in the line of Eleazar, whereas Eli''s Ahitub was of the line of Ithamar.'),
(920, 'Gaal, son of Ebed', NULL, -1275, NULL, 1, 1, 'possible', 'warrior', 'minor', NULL, NULL, NULL, 'Man who came to Shechem with his brothers and stirred its men against Abimelech. He was defeated by Zebul and Abimelech and driven out of the city.', 'Estimate. Active during Abimelech''s three-year reign, about 1236-1233 BC (Judg 9:22-41; Ussher), placed as an adult of about forty. His birth and death are not recorded. Nothing is said of his tribe.'),
(921, 'Peninnah', NULL, -1185, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Second wife of Elkanah, with sons and daughters, who provoked Hannah each year because Hannah had no children.', 'Estimate. She was Elkanah''s wife with several children before Samuel''s birth in 1150 BC (1 Sam 1:2-7), placed a few years after him. Death not recorded.'),
(932, 'Ahimelech the priest of Nob', NULL, -1115, -1060, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'Priest at Nob, son of Ahitub, who gave the fleeing David the holy bread and the sword of Goliath. Saul had him and the priests of Nob killed, which Doeg the Edomite carried out. His son Abiathar escaped. Of the house of Eli, in the priestly line of Ithamar.', 'Estimate. He was an established priest when David came to Nob, around 1060 BC (the tour dates that visit), and Saul killed him soon after (1 Sam 22:18). Birth is a guess around that. Ahitub and Ahimelech belong to Eli''s house through Phinehas (1 Sam 14:3; 22:9); 1 Chr 24:3 places an Ahimelech among the sons of Ithamar, though that may be Abiathar''s son.'),
(935, 'Nahash king of Ammon', NULL, -1135, -1039, 1, 1, 'possible', 'king', 'minor', NULL, NULL, NULL, 'King of the Ammonites who besieged Jabesh-gilead and offered terms of putting out every right eye, until Saul rescued the city. Later he showed David kindness, so that David tried to comfort his son Hanun when Nahash died.', 'Estimate. He was reigning when Saul was made king (1095 BC on this timeline, 1 Sam 11) and died some years before David''s embassy, which Ussher dates to 1038 BC (2 Sam 10:1-2). That spans nearly sixty years, so either his reign was very long or the two events are only loosely tied to the dates given.'),
(938, 'Barzillai the Gileadite', NULL, -1103, NULL, 0, 1, 'probable', 'other', 'minor', NULL, NULL, NULL, 'Aged and wealthy man of Rogelim in Gilead who fed David and his people at Mahanaim during Absalom''s revolt. He escorted the king over the Jordan but declined to live at court, asking that his servant Chimham go in his place.', 'He was eighty years old when David returned after Absalom''s revolt (2 Sam 19:32, 35), 1023 BC on this timeline, so born 1103 BC. His death is not recorded.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(20, 'David', NULL, -1085, -1015, 0, 0, 'traditional', 'king', 'major', 'Judah', 266, NULL, 'Shepherd of Bethlehem who felled Goliath and rose to the throne after Saul, uniting the tribes and taking Jerusalem as his capital. Psalmist and covenant king promised an everlasting dynasty, his house is named on the Tel Dan stele, the earliest extrabiblical witness to his royal line.', 'Ussher: born 1085 BC; anointed by Samuel at Bethlehem c. 1063 BC; king at Hebron aged 30 in 1055 BC and over all Israel from 1048 BC; reigned forty years, seven and a half at Hebron and thirty-three at Jerusalem (2 Sam 5:4-5), and died 1015 BC. Mainstream scholarship dates his reign c. 1010-970 BC.'),
(21, 'Solomon', NULL, -1034, -975, 0, 0, 'traditional', 'king', 'major', 'Judah', 20, 80, 'Son of David famed for God-given wisdom, he built the first temple in Jerusalem and presided over a golden age of trade, building, and proverbs. Monumental gates at Hazor, Megiddo, and Gezer have long been associated with his projects, yet his foreign marriages sowed the kingdom''s division.', 'Scripture: reigned forty years (1 Kgs 11:42); began the Temple in his 4th year, the 480th year from the Exodus (1 Kgs 6:1), and finished it in seven years (6:38), then built his own house thirteen years (7:1). Ussher, Annals 435, 459, 465: born 1034 BC to Bathsheba after the death of her first child by David (2 Sam 12:24), so about 19 at his accession; reign 1015-975 BC; Temple begun 1012 BC and finished 1005 BC; palace 1005-992 BC. Rehoboam was 41 when Solomon died (1 Kgs 14:21), so born the year before Solomon took the throne (Annals 455). Mainstream scholarship dates his reign c. 970-931 BC.'),
(22, 'Nathan the prophet', 'Nathan', -1085, -1005, 1, 1, 'possible', 'prophet', 'moderate', NULL, NULL, NULL, 'Prophet during David and Solomon''s reigns.', 'Life dates estimated. Active from the Davidic covenant (c. 1044 BC, 2 Sam 7) to Solomon''s anointing (1015 BC, 1 Kgs 1).'),
(31, 'Jeroboam', 'Jeroboam I', -1010, -954, 1, 0, 'traditional', 'king', 'moderate', 'Ephraim', NULL, NULL, 'First king of the northern kingdom of Israel.', 'Ussher: reigned 975-954 BC (22 years counted inclusively, 1 Kgs 14:20); Nadab succeeded in Asa''s second year (1 Kgs 15:25). Thiele: 931-910 BC. Birth estimated.'),
(79, 'Abigail', NULL, -1090, -1010, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Wise woman who became David''s wife after the death of Nabal.', 'Life dates estimated. Married David after Nabal''s death, c. 1060 BC (1 Sam 25); with him at Ziklag and Hebron (1 Sam 30:5; 2 Sam 2:2) and mother of his second son (2 Sam 3:3). Death unrecorded.'),
(80, 'Bathsheba', NULL, -1065, -1000, 1, 1, 'possible', 'queen', 'moderate', NULL, 568, NULL, 'Wife of David; mother of Solomon.', 'Life dates estimated. Taken by David c. 1035 BC (Ussher; 2 Sam 11); mother of Solomon (b. 1034 BC); alive early in Solomon''s reign (1 Kgs 2:19). Death unrecorded.'),
(81, 'Joab', NULL, -1085, -1014, 1, 0, 'traditional', 'warrior', 'moderate', NULL, NULL, 555, 'Commander of David''s army; politically shrewd and ruthless.', 'Birth estimated; son of David''s sister Zeruiah (1 Chr 2:16). Executed by Benaiah at Solomon''s command early in his reign, 1014 BC (Ussher; 1 Kgs 2:28-34).'),
(82, 'Absalom', NULL, -1053, -1023, 1, 0, 'traditional', 'other', 'moderate', 'Judah', 20, 562, 'David''s rebellious son who temporarily seized the throne.', 'Born at Hebron to Maacah (2 Sam 3:2-3), so before David took Jerusalem in 1048 BC; Ussher (Annals 410) puts the marriage to Maacah in 1055 BC; exact birth year estimated. Scripture''s sequence: Amnon''s crime, two full years to the sheepshearing (2 Sam 13:23), three years in Geshur (13:38), two full years in Jerusalem before seeing the king (14:28), then revolt "after forty years" (15:7; the Septuagint, Syriac and Josephus read four). Ussher counts the forty from David''s anointing (1063 BC) and dates Amnon''s murder 1030 BC and the revolt and death 1023 BC (Annals 437-445).'),
(84, 'Michal', NULL, -1085, -1030, 1, 1, 'possible', 'queen', 'minor', 'Benjamin', 19, NULL, 'Saul''s daughter; David''s first wife who helped him escape.', 'Life dates estimated. Saul''s younger daughter (1 Sam 14:49), married to David after his victory over Goliath (c. 1063-1062 BC), given to Phaltiel, and returned to David in 1048 BC (2 Sam 3:14-16). Childless (2 Sam 6:23). Death unrecorded.'),
(85, 'Rehoboam', NULL, -1016, -958, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 21, 567, 'Solomon''s son; his harshness caused the kingdom to divide.', 'Ussher: reigned 975-958 BC (17 years, 1 Kgs 14:21); 41 at accession, so born 1016 BC. Thiele: 931-913 BC.'),
(98, 'Nadab', NULL, -990, -953, 1, 0, 'traditional', 'king', 'minor', 'Ephraim', 31, NULL, 'Son and successor of Jeroboam I; killed by Baasha after two years.', 'Ussher: reigned 954-953 BC (2 years counted inclusively, 1 Kgs 15:25-28), killed by Baasha in Asa''s third year. Thiele: 910-909 BC. Birth estimated.'),
(99, 'Baasha', NULL, -980, -930, 1, 0, 'traditional', 'king', 'minor', 'Issachar', 613, NULL, 'King of Israel who destroyed the house of Jeroboam.', 'Ussher: reigned 953-930 BC (24 years counted inclusively, 1 Kgs 15:33); Elah succeeded in Asa''s 26th year (16:8). Thiele: 909-886 BC. Birth estimated.'),
(199, 'Ish-bosheth', 'Esh-Baal', -1095, -1048, 0, 0, 'traditional', 'king', 'minor', 'Benjamin', 19, NULL, 'Saul''s surviving son; made king over Israel by Abner while David reigned in Judah.', 'Scripture: forty when he began to reign, and reigned two years (2 Sam 2:10). Ussher, Annals 409: he was made king at Mahanaim in 1055 BC, the year of Saul''s death, so born 1095 BC, the year Saul became king; the two years are the two years of peace with David, followed by a long war (2 Sam 3:1; Annals 411), and he was murdered in 1048 BC (Annals 416), just before the tribes made David king (2 Sam 4-5). Others place his two years at the end of David''s seven and a half years at Hebron, making him born c. 1090 BC.'),
(201, 'Mephibosheth', 'Merib-Baal', -1060, -1000, 0, 1, 'traditional', 'other', 'minor', 'Benjamin', 83, NULL, 'Son of Jonathan; lame in both feet. David showed him kindness for Jonathan''s sake.', 'Born 1060 BC: five years old when news came of the deaths of Saul and Jonathan in 1055 BC (2 Sam 4:4; Ussher). 2 Sam 9:1-13; 16:1-4; 19:24-30. Death unrecorded; c. 1000 BC is an estimate.'),
(202, 'Uriah', 'Uriah the Hittite', -1060, -1035, 1, 0, 'traditional', 'warrior', 'minor', NULL, NULL, NULL, 'Loyal soldier; husband of Bathsheba. Killed by David''s order to cover his sin.', '2 Sam 11:1-27; Matt 1:6. Ussher, Annals 433: killed at the siege of Rabbah in 1035 BC. Birth estimated.'),
(203, 'Hiram', 'Hiram of Tyre', -1070, -985, 1, 1, 'possible', 'king', 'moderate', NULL, NULL, NULL, 'King of Tyre; ally of David and Solomon. Supplied materials for the Temple.', 'On Ussher''s dates Hiram sent builders to David c. 1046 BC (2 Sam 5:11) and still dealt with Solomon c. 992 BC (1 Kgs 9:10-14). Josephus (Against Apion 1.18, from Menander of Ephesus) gives him a reign of 34 years and a life of 53, which mainstream chronology places c. 980-947 BC; on that reckoning 2 Sam 5:11 is told out of sequence. Life dates are estimates.'),
(204, 'Adonijah', NULL, -1051, -1014, 1, 0, 'traditional', 'other', 'minor', 'Judah', 20, 563, 'David''s fourth son who tried to seize the throne; executed by Solomon.', 'Fourth son of David, born at Hebron after Absalom (2 Sam 3:4); birth estimated. Claimed the throne as David lay dying in 1015 BC and was executed by Solomon early in his reign, 1014 BC (Ussher; 1 Kgs 1-2).'),
(205, 'Shimei', 'Shimei son of Gera', -1070, -1011, 1, 0, 'traditional', 'other', 'minor', 'Benjamin', NULL, NULL, 'Cursed David during Absalom''s rebellion; later executed by Solomon.', '2 Sam 16:5-13; 19:16-23; 1 Kgs 2:36-46. Executed three years after Solomon confined him to Jerusalem, 1011 BC (Ussher). Birth estimated.'),
(206, 'Hushai', 'Hushai the Archite', -1070, -1010, 1, 1, 'possible', 'sage', 'minor', NULL, NULL, NULL, 'David''s friend who pretended to join Absalom and thwarted Ahithophel''s counsel.', '2 Sam 15:32-37; 16:16-17:16. Active in Absalom''s revolt, 1023 BC (Ussher, Annals 442-445). Life dates estimated; Scripture gives no ages.'),
(208, 'Zadok the priest', 'Zadok', -1075, -1000, 1, 1, 'possible', 'priest', 'moderate', 'Levi', 569, NULL, 'Faithful priest who supported David and anointed Solomon. His line continued as high priests.', '2 Sam 15:24-29; 1 Kgs 1:32-45; Ezek 44:15. Life dates estimated; "a young man mighty of valour" when he came with the tribes to David at Hebron (1 Chr 12:27-28), 1048 BC (Ussher, Annals 413), so born about 1075 BC. Anointed Solomon with Nathan in 1015 BC (1 Kgs 1:39; Annals 457).'),
(270, 'Abijah', 'Abijam', -995, -955, 1, 0, 'traditional', 'king', 'minor', 'Judah', 85, 570, 'King of Judah, son of Rehoboam. Reigned 3 years. Ancestor of Jesus in Matthew 1:7.', 'Ussher: reigned 958-955 BC (3 years, 1 Kgs 15:1-2), from the 18th year of Jeroboam. Birth estimated: the text gives no age, but he had fourteen wives and 38 children (2 Chr 13:21). Thiele: 913-911 BC. Not to be confused with Abijah the priest.'),
(281, 'Nathan son of David', 'Nathan', -1030, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 20, 80, 'Son of David and Bathsheba. Ancestor of Jesus in Luke 3:31. Not the prophet Nathan.', '2 Sam 5:14; 1 Chr 3:5; Luke 3:31. Born in Jerusalem to Bathsheba. 1 Chr 3:5 lists him before Solomon, but Solomon was evidently her first son after the death of the child of 2 Sam 12 (c. 1034 BC), so a birth c. 1030 BC is estimated. Not to be confused with Nathan the prophet (2 Sam 7).'),
(557, 'Abishai', NULL, -1083, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Judah', NULL, 555, 'Son of Zeruiah, nephew of David, and one of his best-known commanders. He went with David into Saul''s camp by night and later saved David''s life in battle.', 'Estimate. Born between his brothers Joab (born 1085 BC) and Asahel. His death is not recorded in Scripture.'),
(558, 'Asahel', NULL, -1080, -1055, 1, 1, 'possible', 'warrior', 'minor', 'Judah', NULL, 555, 'Youngest son of Zeruiah and a nephew of David, "light of foot as a wild roe." He pursued Abner after the battle at Gibeon and was killed by him, which later led Joab to kill Abner.', 'Estimate. Born after Joab (1085 BC) and Abishai. He was killed in the first years of David''s reign at Hebron, about 1055 BC (2 Sam 2:18-23).'),
(560, 'Amasa', NULL, -1078, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Judah', 559, 556, 'Nephew of David and cousin of Joab. Absalom made him commander of his army; after Absalom''s death David offered him Joab''s place, and Joab killed him.', 'Estimate. Born after his mother Abigail (born about 1106 BC); an adult commander by Absalom''s revolt (1023 BC). His death is not dated in this table.'),
(561, 'Ahinoam of Jezreel', NULL, -1085, NULL, 1, 1, 'possible', 'queen', 'minor', 'Judah', NULL, NULL, 'One of David''s wives, taken during his years as a fugitive from Saul. She bore his first son, Amnon.', 'Estimate, a contemporary of David (born 1085 BC). Scripture gives no dates for her.'),
(562, 'Maacah, daughter of Talmai', NULL, -1075, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Princess of Geshur, a wife of David and the mother of Absalom and Tamar. Her father Talmai gave Absalom refuge after he killed Amnon.', 'Estimate. Born before Absalom (born 1053 BC). Scripture gives no dates for her. Not the same as Maacah, daughter of Absalom, Rehoboam''s wife.'),
(563, 'Haggith', NULL, -1070, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Wife of David and mother of Adonijah, who tried to take the throne before Solomon was crowned.', 'Estimate. Born before Adonijah (born 1051 BC). Scripture gives no dates for her.'),
(564, 'Amnon', NULL, -1055, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 20, 561, 'David''s firstborn, born at Hebron. He raped his half-sister Tamar and was killed two years later on Absalom''s orders.', 'Estimate. Born at Hebron in the first year of David''s reign there (David anointed there 1055 BC; 2 Sam 3:2). His death at Absalom''s sheep-shearing is not dated in the text.'),
(565, 'Chileab', 'Daniel, Kileab', -1054, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 20, 79, 'David''s second son, born at Hebron to Abigail, widow of Nabal. He is mentioned once in Samuel; Chronicles calls him Daniel.', 'Estimate. Born at Hebron the year after Amnon (2 Sam 3:3). 1 Chronicles 3:1 gives the name Daniel; the two are usually taken to be the same son. His death is not recorded.'),
(566, 'Tamar, daughter of David', NULL, -1048, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 20, 562, 'Beautiful daughter of David and full sister of Absalom, assaulted by her half-brother Amnon. Absalom took her into his house and later killed Amnon.', 'Estimate. Born in the years after Absalom (born 1053 BC), before the rape described in 2 Samuel 13. Not the same as Tamar, Judah''s daughter-in-law.'),
(567, 'Naamah the Ammonitess', 'Naamah', -1036, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Wife of Solomon and mother of King Rehoboam. She was from Ammon, one of the foreign peoples whose women are named among Solomon''s wives.', 'Estimate. Born before Rehoboam (born 1016 BC). Scripture gives no dates for her.'),
(568, 'Eliam, father of Bathsheba', 'Ammiel', -1095, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Father of Bathsheba, wife of Uriah and later of David. 2 Samuel 23:34 names an Eliam son of Ahithophel among David''s mighty men; the text does not say that the two are the same man.', 'Estimate. Born about thirty years before Bathsheba (born 1065 BC). 1 Chronicles 3:5 gives her father as Ammiel, a reversal of the same name. Scripture gives no dates for him.'),
(933, 'Abiathar', NULL, -1085, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', 932, NULL, 'Son of Ahimelech and the one priest of Nob to escape Saul''s massacre. He fled to David, served as his priest and, with Zadok, held the priesthood. He backed Adonijah and Solomon removed him to Anathoth, ending the line of Eli''s house in the priesthood as God had said at Shiloh.', 'Estimate. Already grown when he escaped from Nob (about 1060 BC) and still serving when he joined Adonijah in 1015 BC (1 Kgs 1:7), when Ussher dates his removal to 1014 BC. His death is not recorded. Ussher counts him of Ithamar''s line, so the priesthood passed back to Eleazar''s line in Zadok.'),
(936, 'Hanun king of Ammon', NULL, -1075, NULL, 1, 1, 'possible', 'king', 'minor', NULL, 935, NULL, 'Son and successor of Nahash. He listened to his princes, who said David''s messengers were spies, and shamed them by shaving half their beards and cutting their robes. The insult brought on David''s war against Ammon and the Syrians.', 'Estimate. Reigned from about 1038 BC, when his father died (Ussher; 2 Sam 10:1-4). Birth is a guess around that; his death is not recorded.'),
(937, 'Benaiah, son of Jehoiada', NULL, -1070, NULL, 1, 1, 'possible', 'warrior', 'minor', NULL, NULL, NULL, 'Warrior from Kabzeel whom David set over his guard, the Cherethites and Pelethites. He took part in anointing Solomon, executed Joab and Shimei''s sentence at Solomon''s command, and succeeded Joab as head of the army. Not the later priest Jehoiada of Athaliah''s day.', 'Estimate. He was a famous mighty man by the later years of David and was captain of the guard in 1015 BC (1 Kgs 1:32-38). Ussher places Joab''s death and Benaiah''s promotion in 1014 BC. His death is not recorded.'),
(939, 'Rizpah, concubine of Saul', NULL, -1090, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Daughter of Aiah and concubine of Saul. Abner''s taking of her sparked his break with Ish-bosheth. Years later she kept watch over the bodies of her two sons and five of Saul''s grandsons through a whole season, driving off birds and beasts, until David had the bones buried.', 'Estimate. She was Saul''s concubine before 1055 BC and her sons were grown men when the Gibeonites executed them, about 1018 BC (2 Sam 21:8-10, Ussher). Death not recorded. Her son Mephibosheth is a different person from Jonathan''s son of the same name.'),
(941, 'Obed-edom the Gittite', NULL, -1080, NULL, 1, 1, 'possible', 'other', 'minor', 'Levi', NULL, NULL, 'Man of Gath in whose house the ark rested three months after Uzzah''s death. God blessed his household, which encouraged David to bring the ark on to Jerusalem. Chronicles later lists an Obed-edom among the Levite gatekeepers and singers, and many readers take them to be the same man; others distinguish him from Obed-edom son of Jeduthun.', 'Estimate. A grown man with a household in 1045 BC; still serving as a gatekeeper when the ark was settled (1 Chr 15:24; 16:38). Called a Gittite from Gath or Gath-rimmon, a Levite city, which is why Chronicles can list him as a Levite. Death not recorded.'),
(942, 'Asaph', NULL, -1085, NULL, 1, 1, 'possible', 'prophet', 'minor', 'Levi', NULL, NULL, 'Levite of the Gershonite family, son of Berechiah, whom David appointed chief of the singers before the ark. His sons formed one of the three guilds of Temple musicians, and Psalm 50 and Psalms 73-83 carry his name.', 'Estimate. Already a leading Levite in 1045 BC, when David set the singers in order (1 Chr 15:17-19), so born about 1085 BC. His death is not recorded; the sons of Asaph are still singing in Solomon''s day (2 Chr 5:12) and later reigns.'),
(943, 'Heman the singer', NULL, -1085, NULL, 1, 1, 'possible', 'prophet', 'minor', 'Levi', NULL, NULL, 'Kohathite Levite, called the king''s seer, who led one of the three guilds of Temple singers and had fourteen sons and three daughters. He is named as a son of Joel and, in a traditional reading, grandson of the prophet Samuel. Psalm 88 is attributed to Heman the Ezrahite, whom some identify with him.', 'Estimate. A leading singer in 1045 BC (1 Chr 15:17), so born about 1085 BC. Chronicles calls his father Joel, son of Shemuel (1 Chr 6:33), usually read as Samuel (born 1150 BC), but his father is not in the table. Death not recorded.'),
(944, 'Jeduthun', 'Ethan', -1080, NULL, 1, 1, 'possible', 'prophet', 'minor', 'Levi', NULL, NULL, 'Merarite Levite who led the third guild of Temple musicians, prophesying with the harp, and is called the king''s seer. Psalms 39, 62 and 77 carry his name. Chronicles lists Ethan the Merarite where Jeduthun appears elsewhere, and the two are commonly identified.', 'Estimate. Serving as a musician when David arranged the Levites (1 Chr 15-16, about 1045 BC), so born about 1080 BC. The Ethan identification is the common reading, not stated outright. Death not recorded.'),
(948, 'Jonadab son of Shimeah', NULL, -1060, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', 554, NULL, 'Nephew of David and a friend of his cousin Amnon, whom he advised to feign illness to get Tamar alone. After Amnon''s murder he calmed David by saying only Amnon was dead. In Chronicles his father is called Shimea; a Jonathan son of Shimeah later killed a giant of Gath.', 'Estimate. A grown friend of Amnon (born about 1055 BC) by 1035 BC, when Absalom killed Amnon (1030 BC on this timeline). Death not recorded. His father is Shammah, son of Jesse (Shimeah is a spelling of the name).'),
(951, 'Ahijah the Shilonite', NULL, -1050, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet of Shiloh who tore his new cloak into twelve pieces and gave Jeroboam ten, as a sign that God would take ten tribes from Solomon''s son. Years later, old and blind, he told Jeroboam''s disguised wife that her son would die and that Jeroboam''s house would be cut off. Chronicles says he wrote about Solomon.', 'Estimate. Grown enough to be a prophet by 985 BC (1 Kgs 11:29), and old and blind when Jeroboam was king (1 Kgs 14:4), after 975 BC. Death not recorded. He is not Ahijah, father of Baasha.'),
(960, 'Iddo the seer', NULL, -1005, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet and seer in the days of Solomon, Rehoboam and Abijah of Judah. His visions against Jeroboam and his writings on Rehoboam''s genealogies and the acts of Abijah are cited by the Chronicler as sources. His book is lost. He is a different Iddo from the grandfather of the prophet Zechariah.', 'Estimate. He wrote of Solomon (reign ended 975 BC) and of Abijah (reign 958-955 BC) (2 Chr 9:29; 13:22), so was active across roughly 990-955 BC. Scripture does not give his birth or death.'),
(962, 'Azariah son of Oded', NULL, -985, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet on whom the Spirit of God came as King Asa returned from victory over the Ethiopians. He urged Asa and Judah to seek the LORD, and his words spurred Asa''s reform and covenant renewal.', 'Estimate. He prophesied in Asa''s fifteenth year (2 Chr 15:10), about 941 BC by this timeline''s date for Asa''s reform. Scripture does not give his birth or death.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(23, 'Elijah', NULL, -930, NULL, 1, 1, 'traditional', 'prophet', 'major', NULL, NULL, NULL, 'Prophet of Gilead who confronted Ahab and the prophets of Baal on Mount Carmel, where fire from heaven vindicated the Lord. Fed by ravens and met by a still small voice at Horeb, he was taken up in a whirlwind, and Malachi promises his return before the great day of the Lord.', 'Ussher: active during Ahab''s reign (918-897 BC). Translated c. 896 BC (2 Kgs 2:11), early in Joram of Israel''s reign. 2 Chr 21:12-15 records a writing from Elijah to Jehoram of Judah (reigned from 892 BC): either it was written before his translation or the dating is uncertain. Born c. 930 BC (estimated).'),
(24, 'Elisha', NULL, -920, -839, 1, 1, 'traditional', 'prophet', 'major', NULL, 583, NULL, 'Farmer called from the plow to succeed Elijah, receiving a double portion of his spirit. Serving Israel through the reigns of four kings, he healed Naaman''s leprosy, multiplied bread and oil, and raised the dead, extending God''s mercy to Israelite and foreigner alike.', 'Called by Elijah in Ahab''s reign (1 Kgs 19:19-21), before Ahab died in 897 BC; succeeded Elijah c. 896 BC (2 Kgs 2). Died early in the reign of Jehoash of Israel (2 Kgs 13:14-20), c. 839 BC (Ussher). Born c. 920 BC (estimated).'),
(25, 'Isaiah', 'Yeshayahu', -783, -695, 1, 1, 'traditional', 'prophet', 'major', NULL, 584, NULL, 'Jerusalem prophet who saw the Lord enthroned in the temple and counseled kings Ahaz and Hezekiah through the Assyrian crisis. His visions of Immanuel and the suffering servant shaped messianic hope, and the great Isaiah scroll from Qumran is the best preserved of the Dead Sea Scrolls.', 'Ussher, Annals §583-584: called in 759 BC, the year Uzziah died (Isa 6:1); the Annals (§553) also place him in Judah under Uzziah, earlier. Tradition: martyred by Manasseh c. 695 BC (cf. Heb 11:37; Annals §682). Isa 37:38 reports Sennacherib''s death, which Assyrian records date to 681 BC, so either Isaiah outlived 695 or the notice was added later. Born c. 783 BC (estimated; Ussher gives no birth year).'),
(26, 'Jeremiah', 'Yirmeyahu', -650, -570, 1, 1, 'probable', 'prophet', 'major', 'Levi', 588, NULL, 'The weeping prophet who warned Judah for decades of coming Babylonian judgment, endured imprisonment and a muddy cistern, and promised a new covenant written on the heart. Clay bullae from the City of David bear names of royal officials, such as Jehucal son of Shelemiah, who appear in his book.', 'Called in the 13th year of Josiah (Jer 1:2), 629 BC on Ussher''s chain (Annals §737; 627 in modern reckoning), while still a youth (1:6); active to the fall of Jerusalem and afterwards in Egypt (Jer 43-44). Birth and death estimated; tradition says he was stoned in Egypt.'),
(27, 'Ezekiel', 'Yechezkel', -625, -570, 1, 1, 'probable', 'prophet', 'major', 'Levi', 589, NULL, 'Priest deported to Babylon who received his prophetic call amid visions of the divine chariot beside the Chebar canal. Through stark symbolic acts he interpreted Jerusalem''s fall and foresaw dry bones living and a new temple; cuneiform records of Judean exile settlements corroborate his community''s setting.', 'Taken to Babylon with Jehoiachin (2 Kgs 24:14-16), 599 BC on Ussher''s chain (597 modern; Annals §796). Called on 24 July 595 BC, in the fifth year of that captivity (Ezek 1:2; Annals §821). Ussher reads the thirtieth year of 1:1 as thirty years from Josiah''s reform of 624 BC; others read it as Ezekiel''s age. Last dated oracle in the 27th year (29:17), c. 573 BC. Birth and death estimated.'),
(28, 'Daniel', 'Belteshazzar', -620, -534, 1, 1, 'probable', 'prophet', 'major', 'Judah', NULL, NULL, 'A Judean noble exiled to Babylon who rose to high office under Babylonian and Persian rulers while refusing to compromise his devotion to God. His deliverance from the lions'' den and his sweeping visions of successive empires shaped Jewish and Christian hope in God''s coming kingdom.', 'Deported as a youth in the 4th year of Jehoiakim by Ussher''s count (Dan 1:1-6), 607 BC (Annals §776; 605 modern). His last dated vision is in the third year of Cyrus (Dan 10:1), 535 BC counting from the edict of 537 (Annals §956; 536 BC in modern reckoning); Ussher puts his death shortly after, which is left unrecorded here. Birth and death estimated.'),
(29, 'Hezekiah', NULL, -752, -698, 0, 0, 'traditional', 'king', 'major', 'Judah', 90, 576, 'A reforming king of Judah who purged idolatry and trusted God when Sennacherib''s Assyrian army besieged Jerusalem. His water tunnel from the Gihon spring survives, and the Siloam inscription found in it in 1880 records his workmen''s feat, corroborating the biblical account.', 'Ussher, Annals §586: born 752 BC to Ahaz and Abi, daughter of Zachariah; 25 at accession (2 Kgs 18:2). §617, §620: made viceroy in Ahaz''s last year (727) and reigned alone from 726; 29 years, to 698 BC (§682). Samaria fell in his sixth year (721 BC, §633) and Sennacherib came in his fourteenth (713 BC, §642, §645), after which fifteen years were added to his life (2 Kgs 20:6). By these figures Ahaz was about 10 at Hezekiah''s birth (§579). Thiele and most modern scholars: 715-686 BC, with Sennacherib''s invasion in 701 BC.'),
(30, 'Josiah', NULL, -649, -610, 0, 0, 'traditional', 'king', 'major', 'Judah', 268, 579, 'Judah''s young king whose temple repairs uncovered the book of the law, igniting the kingdom''s most sweeping religious reform. He centralized worship in Jerusalem, renewed the covenant, and kept a Passover unmatched since the judges; scholars link his lawbook to Deuteronomy.', 'Ussher: reigned 641-610 BC (31 years, 2 Kgs 22:1). Age 8 at accession: born 649 BC, when Amon was about 16; the text''s figures also make Josiah about 14 at the birth of Jehoiakim (25 in 610, 2 Kgs 23:36). Killed at Megiddo by Pharaoh Necho (2 Kgs 23:29). Thiele and modern scholarship: 640-609 BC.'),
(32, 'Ahab', NULL, -945, -897, 1, 0, 'traditional', 'king', 'moderate', NULL, 100, NULL, 'Wicked king of Israel; husband of Jezebel.', 'Ussher: reigned 918-897 BC (22 years counted inclusively, 1 Kgs 16:29), from Asa''s 38th year; killed at Ramoth-gilead (1 Kgs 22:34-37). Thiele: 874-853 BC; Shalmaneser III''s Kurkh Monolith names him at Qarqar in 853 BC. Birth estimated.'),
(48, 'Naaman', NULL, -930, -870, 1, 1, 'possible', 'warrior', 'moderate', NULL, NULL, NULL, 'Syrian army commander healed of leprosy by Elisha.', 'Healed during the reign of Jehoram of Israel, c. 890 BC on Ussher''s chain (2 Kgs 5-6). Birth estimated; death unrecorded, estimate only.'),
(86, 'Asa', NULL, -975, -914, 1, 0, 'traditional', 'king', 'moderate', 'Judah', 270, NULL, 'Good king of Judah who removed idols and sought the Lord.', 'Ussher: reigned 955-914 BC (41 years, 1 Kgs 15:9-10), from the 20th year of Jeroboam. Birth estimated: his son Jehoshaphat was 35 when Asa died (1 Kgs 22:42) and Asa was diseased in his feet in his old age (1 Kgs 15:23). Thiele: 911-870 BC. 1 Kings 15:9-24; 2 Chronicles 14-16. Scripture gives Asa''s accession in the 20th year of Jeroboam (1 Kgs 15:9), while Jeroboam''s 22 years (14:20) and Nadab''s accession in Asa''s 2nd year (15:25) make Asa''s first year Jeroboam''s 21st; Ussher''s harmonising choice (Abijah''s 3 years run 958-955) puts Asa''s first year at 955 BC, in Jeroboam''s 20th year as it ended. The 36th year of 2 Chr 16:1 is counted from the division of the kingdom, i.e. Asa''s 16th (940 BC, Annals Sec. 496), since Baasha died in Asa''s 26th year (1 Kgs 16:6-8).'),
(87, 'Jehoshaphat', NULL, -949, -889, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 86, 571, 'Good king of Judah who strengthened the nation and sent teachers through the land.', 'Ussher: reigned 914-889 BC (25 years, 1 Kgs 22:42), from the 4th year of Ahab. Age 35 at accession: born 949 BC. Thiele: 872-848 BC (including a coregency).'),
(88, 'Jehoram of Judah', 'Joram', -924, -885, 0, 0, 'traditional', 'king', 'minor', 'Judah', 87, NULL, 'Wicked king of Judah who married Ahab''s daughter and led Judah astray.', 'Ussher chain: reigned 892-885 BC (8 years, 2 Kgs 8:16-17), from the fifth year of Joram of Israel while Jehoshaphat was still living; 2 Kgs 1:17 implies an earlier association with his father. Age 32 at accession: born 924 BC; died at about 40 (2 Chr 21:20). Thiele: 848-841 BC, coregent from 853.'),
(89, 'Uzziah', 'Azariah', -826, -759, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 96, 574, 'Good king of Judah who became proud and was struck with leprosy.', 'Ussher, Annals §547: born 826 BC, 16 at accession (2 Kgs 15:2). §552: reigned 810-759 BC (52 years), succeeding Amaziah in the 27th year of Jeroboam II reckoned from a coregency. §584: died in 759 BC, the year of Isaiah''s vision (Isa 6:1); Jotham succeeded him. §564: struck with leprosy when an old man, soon after Menahem took the throne of Israel (about 771 BC); Jotham judged the people meanwhile. Thiele: 792-740 BC (coregent from 792).'),
(90, 'Ahaz', NULL, -762, -726, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 97, NULL, 'Wicked king of Judah who practiced child sacrifice and shut the Temple doors.', 'Ussher, Annals §597: reigned 742-726 BC (16 years, 2 Kgs 16:1-2), from the 17th year of Pekah. §579: born 762 BC (age 20 at accession). Taken as written, the figures make Ahaz about 10 at the birth of Hezekiah (born 752 BC, §586; Ussher himself counts 11 and cites Tremellius, who read the 20 years as Jotham''s accession rather than Ahaz''s); the text is kept and the difficulty is unresolved. Thiele: 732-715 BC. Isaiah 7.'),
(91, 'Manasseh', NULL, -710, -643, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 29, 577, 'Most wicked king of Judah who later repented in exile.', 'Ussher: reigned 698-643 BC (55 years, 2 Kgs 21:1). Age 12 at accession: born 710 BC, within the fifteen years added to Hezekiah''s life. Thiele: 697-642 BC (coregent from 697).'),
(92, 'Jehoiakim', 'Eliakim', -635, -599, 0, 0, 'traditional', 'king', 'minor', 'Judah', 30, 581, 'King of Judah who burned Jeremiah''s scroll and rebelled against Babylon.', 'Ussher: reigned 610-599 BC (11 years, 2 Kgs 23:36). Age 25 at accession: born 635 BC. Thiele and modern scholarship: 609-598 BC.'),
(93, 'Zedekiah', 'Mattaniah', -620, -588, 0, 1, 'traditional', 'king', 'minor', 'Judah', 30, 580, 'Last king of Judah; blinded and taken captive to Babylon.', 'Ussher: reigned 599-588 BC (11 years, 2 Kgs 24:18). Age 21 at accession: born 620 BC. Blinded and taken to Babylon when Jerusalem fell in 588 BC; he died in prison there at an unrecorded date (Jer 52:11), so the death year is approximate. Modern scholarship: 597-587/586 BC.'),
(94, 'Athaliah', NULL, -927, -878, 1, 0, 'traditional', 'queen', 'moderate', NULL, 32, NULL, 'Wicked queen of Judah who usurped the throne and killed royal heirs.', 'Ussher: reigned 884-878 BC (six years, 2 Kgs 11:3), after Ahaziah''s death in 884; killed in the seventh year when Joash was crowned (2 Kgs 11:4-16; Annals §535-536). Birth 927 BC from Annals §502 (as it seems, 42 years before her son Ahaziah began to reign in 885). Thiele: 841-835 BC. Called daughter of Ahab (2 Kgs 8:18) and of Omri (8:26), i.e. Ahab''s daughter and Omri''s granddaughter.'),
(95, 'Joash of Judah', 'Jehoash', -885, -839, 0, 0, 'traditional', 'king', 'moderate', 'Judah', 267, 572, 'Boy king hidden in the Temple; restored proper worship under Jehoiada''s guidance.', 'Ussher: reigned 878-839 BC (40 years counted inclusively, 2 Kgs 12:1), from the 7th year of Jehu; slain by his servants (2 Kgs 12:20-21). Age 7 at accession (2 Kgs 11:21): born 885 BC. Thiele: 835-796 BC.'),
(96, 'Amaziah', NULL, -864, -810, 0, 0, 'traditional', 'king', 'minor', 'Judah', 95, 573, 'King of Judah who followed the Lord at first but later turned to idols.', 'Ussher: reigned 839-810 BC (29 years, 2 Kgs 14:2), from the second year of Jehoash of Israel; he outlived Jehoash by 15 years (14:17) and Jeroboam II began in his 15th year (14:23). Age 25 at accession: born 864 BC. Thiele: 796-767 BC.'),
(97, 'Jotham', NULL, -783, -742, 0, 0, 'traditional', 'king', 'minor', 'Judah', 89, 575, 'Good king of Judah who built the upper gate of the Temple.', 'Ussher, Annals §584: succeeded Uzziah in 759 BC and reigned 16 years (2 Kgs 15:33); §597: Ahaz succeeded him in 742 BC. §564: born 783 BC; age 25 at accession in the Annals'' reckoning of 2 Kgs 15:33 (783 to 759 is 24 years counted inclusively). Thiele: 750-732 BC (coregent with Uzziah from 750).'),
(100, 'Omri', NULL, -970, -918, 1, 0, 'traditional', 'king', 'moderate', NULL, NULL, NULL, 'King of Israel who founded Samaria; politically powerful but godless.', 'Ussher: reigned 929-918 BC (12 years, 1 Kgs 16:23), at first contested by Tibni; his sole rule began in Asa''s 31st year. Named on the Moabite Stone. Thiele: 885-874 BC. Birth estimated. Scripture: Omri began in Asa''s 31st year and reigned 12 years (1 Kgs 16:23), yet Ahab began in Asa''s 38th (16:29), only seven years later. Ussher''s choice (Annals Sec. 500-503): the 12 years are counted from 929 BC, Asa''s 27th year, when the army made him king; Tibni''s rival party held half the people for about four years until Omri prevailed in the 31st.'),
(101, 'Ahaziah of Israel', NULL, -922, -896, 1, 0, 'traditional', 'king', 'minor', NULL, 32, 107, 'Son of Ahab; wicked king who sought Baal-zebub instead of God.', 'Ussher: began in Jehoshaphat''s 17th year as viceroy to his father Ahab (898 BC, 1 Kgs 22:51; Annals Sec. 516), sole king after Ahab''s death in 897 and dead in 896 BC; his two years (22:51) were partly with his father, partly alone (Annals Sec. 521). Thiele: 853-852 BC. Birth estimated.'),
(102, 'Jehoram of Israel', 'Joram of Israel', -920, -884, 1, 0, 'traditional', 'king', 'minor', NULL, 32, 107, 'Son of Ahab; last king of the Omride dynasty; killed by Jehu.', 'Ussher: reigned 896-884 BC (12 years, 2 Kgs 3:1), from Jehoshaphat''s 18th year; killed by Jehu (2 Kgs 9:24). Brother of Ahaziah, who had no son (2 Kgs 1:17); the text does not say which was older. Synchronisms: 18th year of Jehoshaphat (2 Kgs 3:1) and 2nd year of Jehoram of Judah (1:17), the latter reconciled by Ussher through Jehoram''s earlier viceroyalty (Annals Sec. 515). Thiele: 852-841 BC. Birth estimated.'),
(103, 'Jehu', NULL, -920, -856, 1, 0, 'traditional', 'king', 'moderate', NULL, 614, NULL, 'Anointed by Elisha''s servant; destroyed the house of Ahab and Baal worship.', 'Ussher: reigned 884-856 BC (28 years, 2 Kgs 10:36). Thiele: 841-814 BC; Shalmaneser III''s Black Obelisk shows him paying tribute in 841 BC. Birth estimated.'),
(104, 'Jeroboam II', NULL, -856, -784, 1, 0, 'traditional', 'king', 'moderate', 'Ephraim', 441, NULL, 'Powerful king of Israel who expanded borders but tolerated idolatry.', 'Ussher: sole reign 825-784 BC (41 years, 2 Kgs 14:23), from Amaziah''s 15th year. Ussher also makes him viceroy to his father Jehoash from 836 BC (Annals Sec. 546), counting from which Uzziah''s accession in 810 BC falls in Jeroboam''s 27th year (2 Kgs 15:1; Sec. 552). Jonah, Amos and Hosea were active in his reign (2 Kgs 14:25; Amos 1:1; Hos 1:1). Thiele: 793-753 BC (coregent from 793). Birth estimated.'),
(105, 'Hoshea', 'Hosea (king)', -765, -721, 1, 1, 'traditional', 'king', 'minor', NULL, 619, NULL, 'Last king of Israel; kingdom fell to Assyria during his reign.', 'Ussher: killed Pekah in the 20th year of Jotham, 739 BC (2 Kgs 15:30; Annals §610), then reigned 9 years from the 12th year of Ahaz, 730 BC (2 Kgs 17:1; §614), after nine years of anarchy; Hezekiah began in his 3rd year (2 Kgs 18:1) and Samaria fell in his 9th, 721 BC, Hezekiah''s 6th (2 Kgs 18:10; §633). Imprisoned by the king of Assyria (17:4); his death is unrecorded, so the death year is approximate. Thiele: 732-723 BC. Birth estimated.'),
(106, 'Zimri', NULL, -960, -929, 1, 0, 'traditional', 'king', 'minor', NULL, NULL, NULL, 'King of Israel for only seven days; died by suicide during Omri''s siege.', 'Ussher: reigned seven days in 929 BC, the 27th year of Asa (1 Kgs 16:15-18). Thiele: 885 BC. Birth estimated.'),
(107, 'Jezebel', NULL, -943, -884, 1, 0, 'traditional', 'queen', 'moderate', NULL, 622, NULL, 'Phoenician wife of Ahab; promoted Baal worship and persecuted prophets.', 'Her marriage to Ahab is reported at his accession in 918 BC (1 Kgs 16:31) and may have been earlier. Killed by Jehu in 884 BC (2 Kgs 9:30-37). Birth estimated.'),
(108, 'Hosea', 'Hosea (prophet)', -805, -720, 1, 1, 'possible', 'prophet', 'moderate', NULL, 591, NULL, 'Prophet who married Gomer to illustrate God''s love for unfaithful Israel.', 'Prophesied in the days of Uzziah, Jotham, Ahaz and Hezekiah of Judah and of Jeroboam II of Israel (Hos 1:1): on Ussher''s chain from before 784 BC into Hezekiah''s reign (from 726 BC). Birth and death estimated.'),
(109, 'Joel', NULL, -865, -796, 1, 1, 'possible', 'prophet', 'minor', NULL, 597, NULL, 'Prophet who described a locust plague and the Day of the Lord.', 'Ussher, Annals §553: prophesied in Judah under Uzziah (810-758 BC) and Jeroboam II, around the 13th Jubilee (808 BC), before Amos. The book names no king and modern dates range from the 9th to the 4th century BC. Birth and death estimated.'),
(110, 'Amos', NULL, -820, -740, 1, 1, 'possible', 'prophet', 'moderate', NULL, NULL, NULL, 'Shepherd-prophet from Tekoa who denounced social injustice in Israel.', 'Prophesied in the days of Uzziah (810-758) and Jeroboam II (825-784), two years before the earthquake (Amos 1:1): between 810 and 784 BC on Ussher''s chain, c. 760 BC in modern reckoning. Birth and death estimated (death c. 740 BC).'),
(111, 'Obadiah', NULL, -620, -550, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet who pronounced judgment on Edom for betraying Judah.', 'Usually dated soon after the fall of Jerusalem (Obad 11-14), 588 BC on Ussher''s chain (587/586 in modern reckoning); some date the book to Edom''s revolt under Jehoram of Judah (2 Kgs 8:20-22). Birth and death estimated.'),
(112, 'Jonah', NULL, -830, -750, 1, 1, 'possible', 'prophet', 'moderate', NULL, 590, NULL, 'Prophet sent to Nineveh; swallowed by a great fish after fleeing.', 'Foretold the restoration of Israel''s borders achieved by Jeroboam II (2 Kgs 14:25), who reigned 825-784 BC on Ussher''s chain; the mission to Nineveh is undated. Birth and death estimated (death c. 750 BC).'),
(113, 'Micah', NULL, -775, -700, 1, 1, 'possible', 'prophet', 'moderate', NULL, NULL, NULL, 'Prophet who foretold Bethlehem as the Messiah''s birthplace.', 'Prophesied in the days of Jotham, Ahaz and Hezekiah (Mic 1:1; Jer 26:18), 759-698 BC on Ussher''s chain (Annals §585, §653). Micah 1:1; 5:2. Birth and death estimated.'),
(114, 'Nahum', NULL, -690, -615, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet who foretold the fall of Nineveh.', 'Prophesied after the fall of No-amon (Nah 3:8) and before the fall of Nineveh. Ussher, Annals §657: No fell to Sennacherib in 712 BC; §739: Nineveh was taken in 626 BC. The year is an estimate between them (c. 660 BC here; Josephus, §585, has Nahum under Ahaz). Mainstream: Thebes fell to Ashurbanipal in 663 BC and Nineveh in 612. Birth and death estimated.'),
(115, 'Habakkuk', NULL, -650, -580, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet who questioned God about evil and received answers about faith.', 'The book foresees the rise of the Chaldeans (Hab 1:6) and is usually dated c. 610-600 BC, late in Josiah''s reign or under Jehoiakim; it names no king. Contemporary of Jeremiah. Birth and death estimated.'),
(116, 'Zephaniah', NULL, -660, -600, 1, 1, 'possible', 'prophet', 'minor', 'Judah', 601, NULL, 'Prophet during Josiah''s reign who warned of the Day of the Lord. His line is given in Zephaniah 1:1 back to Hizkiah, who may be King Hezekiah; that is likely to some readers but not certain, and this table does not link the two.', 'Prophesied in the days of Josiah (Zeph 1:1), 641-610 BC on Ussher''s chain; Ussher places his warnings with Jeremiah''s call in 629 BC (Annals §737), before the reform of 624 BC (§742). Birth and death estimated.'),
(209, 'Widow of Zarephath', NULL, -935, -870, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Poor widow who fed Elijah during the famine; her son was raised from death.', '1 Kgs 17:8-24; Luke 4:25-26. Cared for Elijah during Ahab''s reign c. 910 BC per Ussher. Son raised from death. Est. death c. 870 BC.'),
(210, 'Gehazi', NULL, -910, -840, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Servant of Elisha who was struck with leprosy for greed after Naaman''s healing.', '2 Kgs 4:12-37; 5:20-27; 8:4-5. Struck with leprosy for greed during Elisha''s ministry (c. 896-839 BC per Ussher, Annals §523, §545). Still alive when telling the king of Israel, probably Jehoram (896-884 BC), about Elisha (2 Kgs 8:4-5). Birth and death estimated (death c. 840 BC).'),
(211, 'Shunammite Woman', NULL, -915, -840, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Wealthy woman who provided for Elisha; her son was raised from death by Elisha.', '2 Kgs 4:8-37; 8:1-6. Son raised by Elisha early in his ministry (from c. 896 BC per Ussher). Returned from Philistia after a seven-year absence and appealed to the king, probably Jehoram (896-884 BC). Birth and death estimated (death c. 840 BC).'),
(212, 'Hazael', NULL, -920, -838, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'King of Aram (Syria) whose accession Elisha foretold in Damascus; he smothered Ben-hadad and reigned in his place, and oppressed Israel through the reigns of Jehu and Jehoahaz.', 'Ussher: king of Aram by 884 BC, when he had recently succeeded Ben-hadad as Elisha foretold (2 Kgs 8:7-15, 28-29; Annals Sec. 533); the accession year (c. 885) is an estimate. He oppressed Israel through the reign of Jehoahaz (856-840 BC; 2 Kgs 10:32; 13:3, 22) and sent a force against Jerusalem in Joash of Judah''s last year, 839 BC (2 Kgs 12:17-18; Sec. 544). He was dead when Jehoash of Israel recovered cities from his son Ben-hadad (2 Kgs 13:24-25; Sec. 546), so death is placed c. 838 BC (estimate; was 840). Inscriptions of Shalmaneser III name him king of Damascus by 841 BC; modern dates c. 842-800 BC. Birth and death estimated.'),
(213, 'Sennacherib', NULL, -745, -681, 1, 0, 'certain', 'ruler', 'moderate', NULL, 627, NULL, 'Assyrian king who besieged Jerusalem under Hezekiah; his army destroyed by the angel of the LORD.', '2 Kgs 18:13-19:37; Isa 36-37. Reigned 705-681 BC. His annals (Sennacherib''s Prism) date the campaign against Hezekiah to 701 BC; Ussher''s chain places it in Hezekiah''s 14th year, 713 BC. Assassinated by his sons in 681 BC (2 Kgs 19:37). Birth estimated.'),
(214, 'Nebuchadnezzar', 'Nebuchadrezzar', -634, -562, 1, 0, 'probable', 'ruler', 'major', NULL, 624, NULL, 'The Babylonian king who besieged Jerusalem, destroyed Solomon''s temple, and carried Judah into exile, yet appears in Daniel as a ruler humbled to confess the Most High. The Babylonian Chronicle preserves his own court''s terse record of the first capture of the city.', 'Scripture ties his reign to the kings of Judah: his 1st year is Jehoiakim''s 4th (Jer 25:1; Dan 1:1), the 18th is Zedekiah''s 10th (Jer 32:1), Jehoiachin was taken in his 8th (2 Kgs 24:12) and Jerusalem burned in his 19th (2 Kgs 25:8). Ussher, Annals §768-782, 890: viceroy from 607 BC (20 months), sole king from 605 on his father''s death, died 562 BC after 43 years alone. Mainstream: reigned 605-562 BC (Babylonian Chronicle), with the fall of Jerusalem in 587/586. Birth estimated (c. 634-630 BC).'),
(216, 'Cyrus', 'Cyrus the Great', -600, -530, 1, 0, 'certain', 'ruler', 'major', NULL, 629, NULL, 'Founder of the Persian Empire who took Babylon and permitted Judah''s exiles to return and rebuild the temple. Isaiah strikingly names this Gentile king the Lord''s anointed, and the Cyrus Cylinder documents his wider policy of restoring displaced peoples and their sanctuaries.', 'Isa 44:28; 45:1; 2 Chr 36:22-23; Ezra 1:1-4. Took Babylon in October 539 BC and died in 530 BC. Ussher dates his decree (Ezra 1:1) to 537 BC (Annals §948-949), counting his first year after Darius the Mede; modern scholarship gives 538 BC. Birth estimated.'),
(217, 'Darius the Mede', 'Darius,Darius the Median', -601, NULL, 0, 1, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'Ruler called Darius the Median who received the kingdom of Babylon at about 62 after Belshazzar''s death (Dan 5:31). Pressed by his officials, he had Daniel thrown to the lions and then honored Daniel''s God when he was delivered (Dan 6). He is not named outside Daniel and his identity is debated.', 'Dan 5:31; 6:1-28; 9:1; 11:1. Ussher, Annals §792, 939, 948: Cyaxares, son of Astyages (Ahasuerus of Dan 9:1), born 601 BC and 62 years old when he took the kingdom on Babylon''s fall in 538 BC; he reigned two years, and Cyrus''s first year followed in 537 BC. Death unrecorded. Mainstream: Babylon fell in 539 BC, and he is variously identified with Gubaru/Ugbaru, Cyaxares II or Cyrus himself; distinct from Darius I (522-486 BC).'),
(218, 'Shadrach', 'Hananiah', -620, -550, 1, 1, 'possible', 'sage', 'minor', 'Judah', NULL, NULL, 'One of Daniel''s three companions who survived the fiery furnace.', 'Dan 1:6-7; 3:1-30. Deported with Daniel in 607 BC on Ussher''s reckoning (Annals §776). Birth and death estimated.'),
(219, 'Meshach', 'Mishael', -620, -550, 1, 1, 'possible', 'sage', 'minor', 'Judah', NULL, NULL, 'One of Daniel''s three companions who survived the fiery furnace.', 'Dan 1:6-7; 3:1-30. Deported with Daniel in 607 BC on Ussher''s reckoning (Annals §776). Birth and death estimated.'),
(220, 'Abednego', 'Azariah', -620, -550, 1, 1, 'possible', 'sage', 'minor', 'Judah', NULL, NULL, 'One of Daniel''s three companions who survived the fiery furnace.', 'Dan 1:6-7; 3:1-30. Deported with Daniel in 607 BC on Ussher''s reckoning (Annals §776). Birth and death estimated.'),
(222, 'Huldah', NULL, -660, -600, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophetess in Jerusalem consulted by King Josiah about the Book of the Law found in the Temple.', '2 Kgs 22:14-20; 2 Chr 34:22-28. Consulted in the 18th year of Josiah, 624 BC on Ussher''s chain (Annals §742). Birth and death estimated.'),
(223, 'Hilkiah', NULL, -670, -610, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'High priest who found the Book of the Law in the Temple during Josiah''s reforms.', '2 Kgs 22:8-14; 2 Chr 34:14-21. Found the book of the law in the 18th year of Josiah (2 Kgs 22:3), 624 BC on Ussher''s chain (Annals §742). Birth and death estimated.'),
(267, 'Ahaziah of Judah', 'Jehoahaz', -907, -884, 0, 0, 'traditional', 'king', 'minor', 'Judah', 88, 94, 'Son of Jehoram and Athaliah; king of Judah for one year. Killed by Jehu.', 'Ussher: reigned 885-884 BC (1 year, 2 Kgs 8:25-26), from the 12th year of Joram of Israel. Age 22 at accession: born 907 BC; 2 Chr 22:2 reads 42, which would make him older than his father and is usually taken as a copyist''s error. Killed by Jehu (2 Kgs 9:27-28). Thiele: 841 BC.'),
(268, 'Amon', NULL, -665, -641, 0, 0, 'traditional', 'king', 'minor', 'Judah', 91, 578, 'Son of Manasseh; evil king of Judah for 2 years. Assassinated by his servants.', 'Ussher: reigned 643-641 BC (2 years, 2 Kgs 21:19). Age 22 at accession: born 665 BC. Killed by his servants (21:23). Thiele: 642-640 BC.'),
(269, 'Jehoiachin', 'Jeconiah,Coniah', -617, -560, 0, 1, 'traditional', 'king', 'minor', 'Judah', 92, 582, 'Son of Jehoiakim; king of Judah for 3 months. Deported to Babylon; later released by Evil-Merodach. In the lineage of Jesus.', '2 Kgs 24:8-16; 25:27-30; Jer 22:24-30; Matt 1:11-12. Ussher: reigned three months in 599 BC, then deported (Annals §794-796); released by Evil-merodach in the 37th year of his captivity (2 Kgs 25:27), 562 BC (§891). Age 18 at accession (2 Kgs 24:8): born 617 BC; 2 Chr 36:9 reads 8. The Babylonian Chronicle dates his surrender to March 597 BC. Ussher thinks he died about 560 BC, when Evil-merodach did (§899); the year is an estimate.'),
(271, 'Shealtiel', 'Salathiel', -595, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 269, NULL, 'Son of Jehoiachin (Jeconiah) in Matthew 1:12 and 1 Chronicles 3:17, and father of Zerubbabel in Matthew, Luke and Ezra 3:2 (1 Chronicles 3:19 lists Pedaiah as Zerubbabel''s father). Luke 3:27 calls him the son of Neri, so the genealogies differ here. Two classic explanations are offered. One holds that Shealtiel was Jehoiachin''s son by birth and Neri''s heir by levirate or adoptive succession, Jehoiachin being recorded as childless in Jer 22:30. The other holds that Luke follows Mary''s line, in which Neri is her ancestor. This table follows Matthew for his father and shows Neri as a parent relationship. He lived in the exile in Babylon.', 'Exilic period. Born in Babylon after Jeconiah''s deportation, 599 BC on Ussher''s chain (597 BC by the Babylonian Chronicle; 1 Chr 3:17). Birth estimated.'),
(300, 'Neri', NULL, -620, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 299, NULL, 'Named in Luke 3:27 as the son of Melchi and father of Shealtiel, the point where Luke''s line through Nathan touches the royal line of Matthew. Matthew 1:12 and 1 Chronicles 3:17 make Shealtiel a son of Jehoiachin (Jeconiah), so the lists disagree. Two classic explanations are offered. One treats it as a levirate or adoptive link, Shealtiel becoming heir to Neri''s line when Jehoiachin was recorded as childless (Jer 22:30). The other holds that Luke traces Mary''s ancestry, in which Neri is her forebear and the name Shealtiel belongs to a separate line or a shared name. This table keeps Matthew''s father for Shealtiel and shows Neri as a parent relationship.', 'Known only from Luke''s genealogy. Luke identifies Shealtiel as son of Neri rather than Jeconiah (Matt 1:12).'),
(440, 'Jehoahaz of Israel', NULL, -895, -840, 1, 0, 'traditional', 'king', 'minor', NULL, 103, NULL, 'King of Israel, son of Jehu, who reigned seventeen years. Hazael of Aram and his son Ben-hadad oppressed Israel throughout his reign until he besought the Lord, who gave Israel a deliverer (2 Kgs 13:1-9).', 'Ussher: reigned 856-840 BC (17 years counted inclusively, 2 Kgs 13:1), from the 23rd year of Joash of Judah. Thiele: 814-798 BC. Birth estimated. Not Jehoahaz (Shallum) of Judah.'),
(441, 'Jehoash of Israel', 'Joash,Joash of Israel', -876, -825, 1, 0, 'traditional', 'king', 'minor', NULL, 440, NULL, 'King of Israel, son of Jehoahaz. He wept over the dying Elisha, struck the ground only three times with the arrows, and so defeated Ben-hadad three times (2 Kgs 13:14-25). He also defeated Amaziah of Judah at Beth-shemesh and broke down part of Jerusalem''s wall (2 Kgs 14:8-14).', 'Ussher: reigned 16 years (2 Kgs 13:10), 840-825 BC counted from his father Jehoahaz''s death; made viceroy in the latter end of the 37th year of Joash of Judah (842 BC, 2 Kgs 13:10; Annals Sec. 542), which accounts for the 37th-year synchronism although Jehoahaz''s 17 years from Joash''s 23rd end in 840. Amaziah began in Jehoash''s 2nd year (14:1) = 839 BC, and Amaziah outlived him by 15 years (14:17). Thiele: 798-782 BC. Birth estimated. Not Joash (Jehoash) of Judah.'),
(442, 'Elah', NULL, -955, -929, 1, 0, 'traditional', 'king', 'minor', NULL, 99, NULL, 'King of Israel, son of Baasha, who reigned two years. While he was drinking himself drunk in his steward''s house at Tirzah, Zimri, captain of half his chariots, killed him and destroyed the house of Baasha, as the prophet Jehu son of Hanani had foretold (1 Kgs 16:1-14).', 'Ussher: reigned 930-929 BC (2 years counted inclusively, 1 Kgs 16:8), from the 26th year of Asa; killed in Asa''s 27th year (16:10). Thiele: 886-885 BC. Birth estimated.'),
(443, 'Zechariah of Israel', 'Zachariah', -820, -772, 1, 0, 'traditional', 'king', 'minor', NULL, 104, NULL, 'King of Israel, son of Jeroboam II and the last of Jehu''s dynasty, who reigned six months before Shallum son of Jabesh killed him before the people. His fall fulfilled the word that Jehu''s sons would sit on the throne to the fourth generation (2 Kgs 15:8-12; 10:30).', 'Ussher: reigned six months in 773-772 BC, from the 38th year of Azariah (2 Kgs 15:8), after an interregnum following Jeroboam II''s death. Thiele: 753 BC. Birth estimated. Not the prophet Zechariah.'),
(444, 'Shallum of Israel', 'Shallum son of Jabesh', -810, -772, 1, 0, 'traditional', 'king', 'minor', NULL, 616, NULL, 'Usurper who killed Zechariah son of Jeroboam II and reigned over Israel a full month in Samaria, until Menahem son of Gadi came up from Tirzah and killed him (2 Kgs 15:10-15).', 'Ussher: one month in 772 BC, in the 39th year of Uzziah (2 Kgs 15:13). Thiele: 752 BC. Birth estimated. Not Shallum (Jehoahaz) of Judah.'),
(445, 'Menahem', NULL, -810, -761, 1, 0, 'traditional', 'king', 'minor', NULL, 617, NULL, 'King of Israel for ten years who seized the throne by killing Shallum and brutally sacked Tiphsah (2 Kgs 15:14-16). He paid Pul king of Assyria a thousand talents of silver, raised from Israel''s wealthy men, to secure his kingdom (2 Kgs 15:19-20).', 'Ussher: reigned 772-761 BC (ten years from the 39th year of Azariah, 2 Kgs 15:17; Pekahiah succeeded in Azariah''s 50th, 15:23). Thiele: 752-742 BC; Assyrian records list Menahem of Samaria among Tiglath-pileser III''s tributaries c. 738 BC. Birth estimated.'),
(446, 'Pekahiah', NULL, -785, -759, 1, 0, 'traditional', 'king', 'minor', NULL, 445, NULL, 'King of Israel, son of Menahem, who reigned two years before Pekah son of Remaliah, one of his captains, killed him in the palace at Samaria (2 Kgs 15:23-26).', 'Ussher: reigned 761-759 BC, from the 50th year of Azariah (2 Kgs 15:23). Thiele: 742-740 BC. Birth estimated.'),
(447, 'Pekah', 'Pekah son of Remaliah', -780, -739, 1, 0, 'traditional', 'king', 'minor', NULL, 618, NULL, 'King of Israel, son of Remaliah, who killed Pekahiah and allied with Rezin of Aram against Ahaz of Judah (2 Kgs 16:5; Isa 7:1-9). In his days Tiglath-pileser took Galilee and Gilead and carried their people captive, and Hoshea son of Elah conspired against him and killed him (2 Kgs 15:29-30).', 'Ussher: reigned 759-739 BC (20 years from the 52nd year of Azariah, 2 Kgs 15:27, 15:32); Ahaz began at the end of his 17th year (2 Kgs 16:1; Annals §597). He was killed by Hoshea in the 20th year of Jotham (2 Kgs 15:30), counted from Jotham''s first year in 759, which is 739 BC and the 4th year of Ahaz (§610). Hoshea''s peaceful reign counts from the 12th year of Ahaz (730 BC, 2 Kgs 17:1), after nine years of anarchy. Thiele: 752-732 BC (partly overlapping); Assyrian records place his fall c. 732 BC. Birth estimated.'),
(448, 'Jehoahaz of Judah', 'Shallum', -633, NULL, 0, 1, 'traditional', 'king', 'minor', 'Judah', 30, 580, 'Son of Josiah, made king by the people of the land at 23 after his father fell at Megiddo. He reigned three months before Pharaoh Necho bound him at Riblah and took him to Egypt, where he died (2 Kgs 23:30-34; Jer 22:10-12).', 'Ussher: reigned three months in 610 BC (2 Kgs 23:31); age 23 at accession, so born 633 BC. Modern scholarship: 609 BC. Called Shallum in Jer 22:11 and 1 Chr 3:15. Died in Egypt at an unrecorded date. Not Jehoahaz of Israel; Ahaziah of Judah is also called Jehoahaz (2 Chr 21:17).'),
(449, 'Tiglath-Pileser III', 'Pul,Tiglath-pileser,Tilgath-pilneser', -780, -728, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Assyrian king who seized Galilee and Gilead from Pekah (2 Kgs 15:29) and answered Ahaz''s plea by capturing Damascus (2 Kgs 16:7-9). He began the Assyrian deportations of Israel (2 Kgs 15:29; 1 Chr 5:26, which names Pul and Tilgath-pilneser).', 'Ussher, Annals §596: began to reign in 747 BC as "Ninus the younger" (19 years, Castor); §604, §607: took Damascus and Galilee in 740 BC, the 3rd year of Ahaz; §615: died in 728 BC and was succeeded by Shalmaneser. Ussher keeps Pul apart from him: Pul took Menahem''s tribute in 771 BC (2 Kgs 15:19-20; §574-576), and 1 Chr 5:26 names the two kings separately. Birth unknown (estimate). Mainstream: Pul and Tiglath-pileser are one king, reigned 745-727 BC.'),
(585, 'Shear-jashub', NULL, -750, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 25, NULL, 'Son of the prophet Isaiah. His name means "a remnant shall return," and Isaiah brought him to meet King Ahaz as a sign.', 'Estimate. He was old enough to walk with his father when Isaiah met Ahaz during the attack of Syria and Israel (Isa 7:1-3), so born around 750 BC. His death is not recorded.'),
(586, 'Maher-shalal-hash-baz', NULL, -742, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 25, 587, 'Son of Isaiah and the prophetess. His name, "swift is the plunder, speedy is the spoil," was a sign that Damascus and Samaria would fall to Assyria before the child could say "my father."', 'Estimate. Born at the time of the sign given to Ahaz, when Syria and Israel threatened Judah (Isa 8:1-4; Ussher, Annals §598-599, under 742 BC), about 742 BC. His death is not recorded.'),
(594, 'Jezreel, son of Hosea', NULL, -776, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 108, 592, 'First child of Hosea and Gomer. The Lord told Hosea to give him the name Jezreel, a sign that the blood shed at Jezreel would be avenged on the house of Jehu.', 'Estimate. Born in the time of Jeroboam II, shortly before the fall of Jehu''s dynasty in 772 BC (Hos 1:4), so about 776 BC. His death is not recorded.'),
(595, 'Lo-ruhamah', NULL, -774, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 108, 592, 'Daughter of Gomer and Hosea''s second child. Her name means "not pitied." Hosea 1:6 says Gomer "bare a daughter" without the words "to him," as it says of the first child, but the children are given their names as signs to Hosea and are counted as his.', 'Estimate. Born after Jezreel, about 774 BC (Hos 1:6). Her death is not recorded.'),
(596, 'Lo-ammi', NULL, -771, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 108, 592, 'Son of Gomer and the third child. His name means "not my people." As with Lo-ruhamah, the text says Gomer "bare a son" and the children are counted as Hosea''s.', 'Estimate. Born after Lo-ruhamah was weaned (Hos 1:8), about 771 BC. His death is not recorded.'),
(961, 'Micaiah son of Imlah', NULL, -950, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet of the LORD in the northern kingdom whom King Ahab hated because he never prophesied good about him. Alone against four hundred court prophets, he told Ahab and Jehoshaphat that the battle at Ramoth-gilead would fail, and was put in prison for it.', 'Estimate. He is a grown prophet at the battle of Ramoth-gilead in 897 BC (1 Kgs 22). Scripture does not give his birth or death.'),
(963, 'Oded the prophet', NULL, -775, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet of the LORD in Samaria in the days of Ahaz of Judah. He met the army of Israel returning with Judean captives and rebuked them, and the leaders of Ephraim then clothed, fed and sent the captives home to Jericho. He is a different Oded from the father of Azariah.', 'Estimate. He appears after Pekah''s attack on Judah in the days of Ahaz (2 Chr 28:5-15), placed here in the Syro-Ephraimite war of about 742 BC. Scripture does not give his birth or death.'),
(964, 'Jehonadab son of Rechab', 'Jonadab', -930, NULL, 1, 1, 'possible', 'other', 'minor', 'Kenite', NULL, NULL, 'Zealous ally of Jehu who rode with him in his chariot and helped him destroy the worshippers of Baal in Samaria. He is also the ancestor-figure of the Rechabites, who kept his command never to drink wine, build houses or plant vineyards; Jeremiah later held them up as a model of obedience.', 'Estimate. He met Jehu in 884 BC (2 Kgs 10:15), so was an adult then. Scripture does not give his birth or death. The Rechabites in 1 Chronicles 2:55 are linked to the Kenites.'),
(965, 'Rezin', NULL, -790, -740, 1, 1, 'possible', 'king', 'moderate', 'Aram', NULL, NULL, 'King of Syria (Aram) from Damascus who, with Pekah of Israel, marched against Ahaz of Judah. Isaiah told Ahaz not to fear these two "smoking firebrands." Rezin recovered Elath for Syria; Tiglath-pileser of Assyria then took Damascus and killed him.', 'Estimate. He fought Ahaz in the Syro-Ephraimite war (about 742 BC) and was killed when Tiglath-pileser took Damascus (2 Kgs 16:9), dated here to 740 BC. Birth is an estimate.'),
(966, 'The Rab-shakeh', NULL, -750, NULL, 1, 1, 'possible', 'other', 'minor', 'Assyria', NULL, NULL, 'Rab-shakeh is an Assyrian title (chief cupbearer or field commander), not a personal name. Sennacherib sent him from Lachish to Jerusalem, where he mocked Hezekiah''s trust in the LORD, spoke in Hebrew to the men on the wall, and demanded surrender.', 'Title only; his name is not given. Estimate: an adult officer when Sennacherib came against Jerusalem (713 BC in this timeline). His death is not recorded.'),
(967, 'Shaphan the scribe', NULL, -680, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Secretary of state to King Josiah, son of Azaliah. He took the book of the law that Hilkiah found in the temple, read it to the king, and was sent with others to ask the prophetess Huldah. He was the father of Ahikam, who protected Jeremiah, and grandfather of Gedaliah.', 'Estimate. He was an established royal scribe in Josiah''s eighteenth year (2 Kgs 22:3), about 624 BC, and father of Ahikam. His death is not recorded.'),
(968, 'Ahikam son of Shaphan', NULL, -655, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 967, NULL, 'Court official, son of Shaphan, sent by Josiah to Huldah the prophetess about the book of the law. Years later his influence kept Jeremiah from being handed over to the mob that wanted him put to death. He was the father of Gedaliah.', 'Estimate. Named among Josiah''s officials in 624 BC (2 Kgs 22:12) and still influential under Jehoiakim (Jer 26:24). His death is not recorded.'),
(969, 'Gedaliah, governor of Judah', NULL, -630, -588, 1, 1, 'possible', 'ruler', 'minor', NULL, 968, NULL, 'Son of Ahikam and grandson of Shaphan. After Jerusalem fell, Nebuchadnezzar made him governor over the people left in the land, at Mizpah. Jeremiah lived under his protection. He ignored warnings of a plot and was murdered by Ishmael son of Nethaniah, after which the remnant fled to Egypt.', 'Estimate. Appointed after the fall of Jerusalem and killed in the seventh month (2 Kgs 25:22-25); Ussher dates both in 588 BC, the same year. Birth is an estimate from his father''s career.'),
(970, 'Ishmael son of Nethaniah', NULL, -625, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Of the royal family of Judah, son of Nethaniah, son of Elishama. Encouraged by Baalis king of Ammon, he came to Mizpah, ate with Gedaliah and then murdered him, along with those who were with him. Johanan son of Kareah drove him off and he escaped to the Ammonites.', 'Estimate. Active in 588 BC (Jer 40-41; 2 Kgs 25:25). His death is not recorded.'),
(971, 'Johanan son of Kareah', NULL, -630, NULL, 1, 1, 'possible', 'warrior', 'minor', NULL, NULL, NULL, 'Commander of Judah''s forces in the fields who warned Gedaliah of the plot against him, then pursued Ishmael after the murder. Despite Jeremiah''s warning from the LORD, he led the remnant to Egypt and took Jeremiah and Baruch with them.', 'Estimate. Active in 588 BC and shortly after (Jer 40-43). His death is not recorded.'),
(972, 'Pashur son of Immer', NULL, -650, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'Priest and chief officer of the temple who had Jeremiah beaten and put in the stocks at the Benjamin gate for his prophecy of disaster. Jeremiah renamed him "Magor-missabib" (terror on every side) and foretold his captivity in Babylon.', 'Estimate. He was chief governor of the temple during Jeremiah''s ministry (Jer 20:1-6), which this timeline starts in 629 BC. The year of the incident is not given and his death is not recorded.'),
(973, 'Hananiah son of Azur', NULL, -640, -597, 1, 1, 'possible', 'prophet', 'minor', 'Benjamin', NULL, NULL, 'False prophet from Gibeon who told the people in the temple that Babylon''s yoke would be broken within two years. He broke the wooden yoke Jeremiah wore. Jeremiah answered that the LORD had not sent him, and he died that same year.', 'He spoke in the fourth year of Zedekiah and died the same year, in the seventh month (Jer 28:1, 17); Ussher dates this to 597 BC. Birth is an estimate. Not the Hananiah who is Shadrach.'),
(974, 'Baruch son of Neriah', NULL, -640, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Jeremiah''s scribe and companion. He wrote down Jeremiah''s prophecies from dictation, read them publicly in the temple, witnessed the purchase of the field at Anathoth, and was taken with Jeremiah to Egypt. The LORD gave him a personal word in Jeremiah 45.', 'Estimate. He was a grown man writing for Jeremiah in the fourth year of Jehoiakim (Jer 36:1-4) and still with him in Egypt after 588 BC (Jer 43:6). His death is not recorded; later traditions about it are not in Scripture.'),
(975, 'Ebed-melech the Ethiopian', NULL, -630, NULL, 1, 1, 'possible', 'other', 'minor', 'Cush', NULL, NULL, 'Ethiopian (Cushite) eunuch in King Zedekiah''s household who pleaded with the king for Jeremiah''s life, then lowered ropes and old rags to pull him out of the cistern. The LORD promised through Jeremiah to rescue him when the city fell, because he trusted in God.', 'Estimate. Active when Jeremiah was in the cistern, 589 BC in this timeline (Jer 38:7-13). His death is not recorded.'),
(976, 'Nebuzar-adan', NULL, -640, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Babylon', NULL, NULL, 'Captain of Nebuchadnezzar''s guard. He burned the temple, the palace and Jerusalem''s houses, broke down the walls, and carried the people into exile. On the king''s orders he released Jeremiah and left the poor of the land under Gedaliah.', 'Estimate. He acted on the seventh day of the fifth month of Nebuchadnezzar''s nineteenth year, 588 BC (2 Kgs 25:8). His death is not recorded.'),
(977, 'Ashpenaz', NULL, -650, NULL, 1, 1, 'possible', 'other', 'minor', 'Babylon', NULL, NULL, 'Chief of Nebuchadnezzar''s eunuchs, ordered to bring young Israelites of the royal family and nobility to be trained in Babylonian language and learning. He gave Daniel and his three friends their Babylonian names and showed them favour when Daniel asked to avoid the king''s food.', 'Estimate. Active when Daniel was taken to Babylon in 607 BC (Dan 1:3). His death is not recorded.'),
(978, 'Arioch', NULL, -650, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Babylon', NULL, NULL, 'Captain of Nebuchadnezzar''s guard, sent to execute the wise men of Babylon when none could tell the king''s dream. Daniel spoke to him and asked for time, and Arioch brought Daniel before the king.', 'Estimate. Active at the time of Nebuchadnezzar''s dream of the statue, 604 BC (Dan 2:14-25). His death is not recorded.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(33, 'Ezra', NULL, -500, -440, 1, 1, 'possible', 'priest', 'major', 'Levi', NULL, NULL, 'A priest and scribe skilled in the law of Moses who led a company of exiles from Babylon back to Jerusalem under Persian sanction. By publicly reading and teaching the Torah, he re-centered the restored community on Scripture, a legacy foundational to Jewish identity ever after. Ezra 7:1-5 traces his line through Seraiah and Zadok back to Aaron the chief priest, in an abridged list.', 'Came to Jerusalem in the seventh year of Artaxerxes I (Ezra 7:7-8), 458 BC (457 on autumn-to-autumn reckoning), and read the law in Nehemiah''s time (Neh 8; 444 BC). Called son of Seraiah (Ezra 7:1), the high priest killed in 588 BC, meaning descendant. Birth and death estimated.'),
(34, 'Nehemiah', NULL, -470, -400, 1, 1, 'possible', 'ruler', 'major', NULL, 605, NULL, 'Cupbearer to the Persian king Artaxerxes who returned as governor of Judah and rebuilt Jerusalem''s shattered walls in fifty-two days despite fierce opposition. His memoirs join practical leadership to constant prayer, and with Ezra he anchored the restored community in covenant obedience. His brother Hanani brought him news of Jerusalem (Neh 1:2).', 'Came to Jerusalem in the 20th year of Artaxerxes I (Neh 2:1), 445/444 BC; returned to the king in his 32nd year, 433/432 BC, and later came back (Neh 13:6-7). Birth and death estimated.'),
(36, 'Esther', 'Hadassah', -500, -420, 1, 1, 'possible', 'queen', 'major', 'Benjamin', 607, NULL, 'A Jewish orphan named Hadassah who became queen of Persia in the citadel of Susa and risked her life to expose Haman''s plot to annihilate her people. Her courage is celebrated yearly at Purim; the Ahasuerus of her story is commonly identified with Xerxes I of Persian history. She was Mordecai''s cousin, the daughter of his uncle Abihail (Esth 2:7, 15), and was raised by him after her parents died.', 'Became queen in the tenth month of the seventh year of Ahasuerus (Esth 2:16), 479/478 BC if he is Xerxes I; Haman''s plot falls in his twelfth year (3:7), 474/473 BC. Birth and death estimated.'),
(119, 'Malachi', NULL, -490, -420, 1, 1, 'possible', 'prophet', 'moderate', NULL, NULL, NULL, 'Last of the twelve Minor Prophets, who called the restored community back to faithful worship and marriage and promised that Elijah would come before the day of the Lord (Mal 4:5).', 'Usually dated to the mid-5th century BC, c. 460-430, near the time of Ezra and Nehemiah (compare Mal 2:11 with Neh 13:23-29). Birth and death estimated.'),
(120, 'Mordecai', NULL, -520, -440, 1, 1, 'possible', 'sage', 'moderate', 'Benjamin', 608, NULL, 'Esther''s cousin who raised her; uncovered a plot against the king.', 'Esther 2-10. Cousin and guardian of Esther (Esth 2:7), promoted after Haman''s fall in the twelfth year of Ahasuerus. Esth 2:6 (carried away with Jeconiah) is best read of his great-grandfather Kish, since Mordecai himself would otherwise be over 120. Birth and death estimated.'),
(224, 'Sanballat', NULL, -500, -430, 1, 1, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'Governor of Samaria who opposed Nehemiah''s rebuilding of Jerusalem''s walls.', 'Neh 2:10, 19; 4:1-8; 6:1-14. Confirmed by Elephantine Papyri.'),
(225, 'Tobiah', NULL, -500, -430, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'Ammonite official who opposed Nehemiah''s rebuilding and conspired against him.', 'Neh 2:10, 19; 4:3, 7; 6:1-14; 13:4-9.'),
(226, 'Haman', NULL, -510, -473, 1, 1, 'possible', 'ruler', 'moderate', NULL, 611, NULL, 'Persian official who plotted the genocide of the Jewish people; hanged on his own gallows.', 'Esth 3-7. Executed in the twelfth year of Ahasuerus (Esth 3:7; 7:10), 474/473 BC if he is Xerxes I. Birth estimated.'),
(227, 'Vashti', NULL, -520, -470, 1, 1, 'possible', 'queen', 'moderate', NULL, NULL, NULL, 'Queen of Persia before Esther; deposed for refusing to appear before the king.', 'Esth 1:1-22. Deposed c. 483 BC. Talmud (Megillah 12b) identifies her as Nebuchadnezzar''s granddaughter. Death unrecorded; est. c. 470 BC.'),
(228, 'Xerxes', 'Ahasuerus', -519, -465, 1, 0, 'certain', 'ruler', 'moderate', NULL, 450, 632, 'Persian king who married Esther; issued decree saving the Jews from Haman''s plot.', 'Esth 1-10. Reigned 486-465 BC. Most scholars identify him with the Ahasuerus of Esther; some older chronologers, including Ussher, identified Ahasuerus with another Persian king. Birth estimated.'),
(272, 'Abiud', NULL, -507, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 35, NULL, 'Son of Zerubbabel, ancestor of Jesus in Matthew 1:13. Post-exilic figure.', 'Post-exilic period. Known only from Matthew''s genealogy. Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(273, 'Eliakim, son of Abiud', 'Eliakim', -453, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 272, NULL, 'Son of Abiud, ancestor of Jesus in Matthew 1:13. Post-exilic figure.', 'Known only from Matthew''s genealogy. Not the Eliakim of 2 Kings 18. Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(301, 'Rhesa', NULL, -500, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 35, NULL, 'Son of Zerubbabel, ancestor of Jesus in Luke 3:27.', 'Known only from Luke''s genealogy. Post-exilic period.'),
(451, 'Artaxerxes I', 'Artaxerxes,Artaxerxes Longimanus', -485, -424, 1, 0, 'certain', 'ruler', 'minor', NULL, 228, NULL, 'Persian king, son of Xerxes, who sent Ezra to Jerusalem in his seventh year (Ezra 7) and Nehemiah, his cupbearer, in his twentieth (Neh 2:1-8). He also ordered a halt to the rebuilding of Jerusalem''s walls after complaints from its neighbours (Ezra 4:7-23).', 'Reigned 465-424 BC by Persian and Greek records. Birth estimated. Some scholars identify Ezra''s king as Artaxerxes II (404-358 BC).'),
(992, 'Rehum the chancellor', NULL, -490, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Persian', NULL, NULL, 'Royal officer of the province beyond the River, based in Samaria. With Shimshai the scribe he wrote to Artaxerxes against the Jews rebuilding Jerusalem, and when the king ordered the work stopped he enforced it.', 'Estimate. The letter was sent to a king named Artaxerxes, taken here as Artaxerxes I (reigned 465-424 BC), before Nehemiah''s mission of 445 BC (Ezra 4:8-24). Scholars differ on the exact date of the letter. Death not recorded.'),
(993, 'Shimshai the scribe', NULL, -490, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Persian', NULL, NULL, 'Scribe who wrote with Rehum the chancellor to King Artaxerxes against the rebuilding of Jerusalem, and helped stop the work by force.', 'Estimate, as for Rehum: active under Artaxerxes I (Ezra 4:8-24). Death not recorded.'),
(994, 'Eliashib the high priest', NULL, -490, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'High priest in Nehemiah''s day. He and his brother priests rebuilt the Sheep Gate, but he was also allied to Tobiah and gave him a chamber in the Temple courts, which Nehemiah threw out. A grandson married a daughter of Sanballat.', 'Estimate. High priest in 445 BC (Neh 3:1) and still in 433 BC (Neh 13:4-7, 28). Born about 490 BC; death not recorded.'),
(996, 'Geshem the Arabian', 'Gashmu', -495, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Arab', NULL, NULL, 'Arab leader who with Sanballat and Tobiah mocked the rebuilding of Jerusalem''s wall, and with Sanballat tried to lure Nehemiah to a meeting at Ono to harm him. Nehemiah 6:6 calls him Gashmu.', 'Estimate. Active in 445 BC (Neh 2:19; 6:1-6). Born about 495 BC; death not recorded.'),
(997, 'Hegai', 'Hege', -520, NULL, 1, 1, 'possible', 'other', 'minor', 'Persian', NULL, NULL, 'The king''s chamberlain who kept the women''s house at Susa. Esther pleased him; he gave her the best place and she took only what he advised before going to the king.', 'Estimate. In office when Esther was gathered to the palace, about 480 BC (Esth 2:3-15). Death not recorded.'),
(998, 'Hathach the chamberlain', 'Hatach', -515, NULL, 1, 1, 'possible', 'other', 'minor', 'Persian', NULL, NULL, 'The king''s chamberlain appointed to attend Esther. He carried messages between Esther and Mordecai when Haman''s decree against the Jews became known.', 'Estimate. Active in the twelfth year of Xerxes, 474-473 BC (Esth 4:5-10). Death not recorded.'),
(999, 'Bigthan', 'Bigthana', -510, -478, 1, 1, 'possible', 'other', 'minor', 'Persian', NULL, NULL, 'One of two door-keeping chamberlains who conspired against King Ahasuerus. Mordecai learned of it and told Esther, who told the king; both men were hanged.', 'Estimate. The plot came soon after Esther was made queen in the seventh year (Esth 2:16, 21-23). Death date approximate. The record of it is read to the king years later (Esth 6:2).'),
(1000, 'Teresh', NULL, -510, -478, 1, 1, 'possible', 'other', 'minor', 'Persian', NULL, NULL, 'The second door-keeping chamberlain in the plot against King Ahasuerus that Mordecai exposed. Both conspirators were hanged.', 'Estimate, as for Bigthan (Esth 2:21-23; 6:2).');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(35, 'Zerubbabel', NULL, -560, -500, 1, 1, 'possible', 'ruler', 'major', 'Judah', 271, NULL, 'Led the first return from exile; rebuilt the Temple.', 'Led the return under Cyrus, 536 BC on Ussher''s chain (Ezra 2:2; 3:8), and saw the temple finished in the sixth year of Darius I, 515 BC (Ezra 6:15; Zech 4:9). Birth and death estimated.'),
(117, 'Haggai', NULL, -560, -500, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Post-exilic prophet who urged rebuilding of the Temple.', 'Prophesied in the second year of Darius I, 520 BC (Hag 1:1; 2:1-20). His age is unknown: the Lives of the Prophets says he came from Babylon as a youth, while some read Hag 2:3 as implying he had seen Solomon''s temple. Birth and death estimated.'),
(118, 'Zechariah the prophet', 'Zechariah (prophet), Zechariah', -540, -480, 1, 1, 'possible', 'prophet', 'moderate', NULL, 603, NULL, 'Post-exilic prophet with messianic visions; contemporary of Haggai.', 'Prophesied 520-518 BC, in the second to fourth years of Darius I (Zech 1:1; 7:1). Grandson of Iddo (Zech 1:1), a priest who returned with Zerubbabel (Neh 12:4). Birth and death estimated.'),
(215, 'Belshazzar', NULL, -575, -538, 1, 0, 'probable', 'ruler', 'moderate', NULL, 626, NULL, 'Last king of Babylon; saw the handwriting on the wall at his feast and was killed that night when Persia took the city (Dan 5:30). Ussher identifies him with the Nabonidus of Berosus, a grandson of Nebuchadnezzar through Evil-merodach (Jer 27:7), who reigned 17 years; mainstream scholarship makes him the son and co-regent of Nabonidus, with "father" in Daniel 5 meaning predecessor or ancestor.', 'Dan 5:30. Ussher, Annals §912, 915, 938: reigned 17 years from 555 BC; slain the night Babylon fell, 538 BC. Mainstream: killed 12 October 539 BC (Nabonidus Chronicle) as the son and coregent of Nabonidus. Birth estimated.'),
(450, 'Darius I', 'Darius the Great,Darius Hystaspes', -550, -486, 1, 0, 'certain', 'ruler', 'minor', NULL, 631, NULL, 'Persian king who confirmed Cyrus''s decree and had the records searched, so that work on the Second Temple resumed and was finished in his sixth year (Ezra 5-6). Haggai and Zechariah prophesied in his second year (Hag 1:1; Zech 1:1).', 'Reigned 522-486 BC, firmly dated by Persian and Babylonian records. Birth c. 550 BC (estimate). Not Darius the Mede (Dan 5:31).'),
(820, 'Jeshua the high priest', 'Joshua the high priest, Joshua son of Josedech', -570, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'High priest of the first return from Babylon, son of Jozadak. With Zerubbabel he rebuilt the altar and laid the foundation of the Temple, and Zechariah saw him in a vision standing before the angel of the LORD.', 'Estimate: born in exile (his father Jozadak was carried away in 588 BC, 1 Chr 6:15) and high priest by the return of 536 BC (Ezra 3:2). Haggai and Zechariah address him in 520 BC. His death is not recorded.'),
(990, 'Tattenai, governor beyond the River', 'Tatnai', -560, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Persian', NULL, NULL, 'Persian governor of the province beyond the Euphrates. In 520 BC he questioned the Jews about their authority to rebuild the Temple and wrote to Darius, who confirmed Cyrus''s decree and ordered him to help.', 'Estimate. Governor in the second year of Darius I (520 BC; Ezra 5:3-6, 6:6-13); born about 560 BC so as to be an established governor then. His death is not recorded.'),
(991, 'Shethar-boznai', NULL, -560, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Persian', NULL, NULL, 'Persian official who served with Tattenai and joined him in questioning the Jews and in writing to Darius about the Temple. He and Tattenai carried out the king''s order to the letter.', 'Estimate. Active in 520 BC (Ezra 5:3, 6:13). Born about 560 BC; his death is not recorded.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(37, 'Jesus', 'Yeshua, Jesus Christ', -5, 33, 0, 0, 'probable', 'messiah', 'major', 'Judah', 122, 38, 'The central figure of the Christian faith, proclaimed as Messiah and Son of God, whose teaching, crucifixion under Pontius Pilate, and resurrection stand at the heart of the gospel. The Pilate stone from Caesarea and the Caiaphas ossuary attest the very officials named at his trial.', 'Ussher, Annals §6057: born 5 BC (before Herod''s death, Matt 2:1, 19); crucified Friday 3 April AD 33 (§6474-6477). Baptised about thirty (Luke 3:23) in AD 27 (§6288). Many modern scholars place the birth 6-4 BC; AD 30 is the main alternative for the crucifixion.'),
(39, 'John the Baptist', 'Yochanan', -5, 32, 0, 0, 'probable', 'prophet', 'major', 'Levi', 230, 231, 'A wilderness prophet who called Israel to repentance and baptism in the Jordan and pointed to Jesus as the coming one. Executed by Herod Antipas, he is also attested by Josephus, who reports that many Jews saw Antipas''s later military defeat as divine judgment for the killing.', 'Ussher, Annals §6043: born 5 BC, about six months before Jesus (Luke 1:26, 36). His ministry began in the fifteenth year of Tiberius (Luke 3:1; §6282-6283); imprisoned AD 30 after the first Passover (John 3:24; Mark 1:14; §6311) and beheaded AD 32 shortly before the feeding of the 5,000 (Matt 14:12-13; §6362). Josephus (Ant. 18.116-119) names Machaerus.'),
(40, 'Peter', 'Simon, Cephas', -2, 67, 1, 0, 'traditional', 'apostle', 'major', NULL, 640, NULL, 'A Galilean fisherman whom Jesus called to lead the apostles, remembered for his bold confession, his denial, and his restoration. He preached at Pentecost, opened the door to Gentile believers at Cornelius''s house, and by early tradition was martyred in Rome under Nero. His wife is not named: the Gospels mention his mother-in-law (Mark 1:30) and Paul says Cephas took a wife with him on his travels (1 Cor 9:5).', 'Scripture does not record his death; Jesus foretells it (John 21:18-19). Ussher, Annals 6949, following early church tradition (Eusebius), dates the martyrdom of Peter and Paul at Rome to 29 June AD 67. Many modern scholars prefer about AD 64-68, under Nero.'),
(41, 'Paul', 'Saul of Tarsus', 5, 67, 1, 0, 'traditional', 'apostle', 'major', 'Benjamin', NULL, NULL, 'A Pharisee who persecuted the church until an encounter with the risen Jesus made him the apostle to the Gentiles. His missionary journeys and letters shaped Christian theology more than any other early figure, and the Gallio inscription at Delphi helps anchor his career in history.', 'Scripture does not record his death; he expects it in 2 Tim 4:6-8. Ussher, Annals 6949, following early church tradition (Eusebius), dates the martyrdom of Peter and Paul at Rome to 29 June AD 67. His journeys and imprisonments follow Acts and Ussher: conversion AD 35, the council AD 52 (Gal 2:1), Rome AD 63-65 (Acts 28:30). Many modern scholars prefer about AD 64-68 for his death.'),
(42, 'John the Apostle', 'John, John son of Zebedee', 6, 100, 1, 1, 'possible', 'apostle', 'major', NULL, 641, 642, 'A son of Zebedee and member of Jesus'' inner circle, traditionally identified as the beloved disciple behind the fourth Gospel. Linked with Ephesus and exile on Patmos, his legacy endures in the earliest known New Testament fragment, a papyrus scrap of his Gospel known as P52. Matthew 27:56 mentions "the mother of Zebedee''s children" at the cross; Mark 15:40 names Salome in the same group, and she is commonly identified with her (an inference).', 'His death c. AD 98-100 at Ephesus is early church tradition (Irenaeus AH 2.22.5; Eusebius HE 3.23); Scripture is silent. His identification with the beloved disciple and with the author of the Gospel, the letters and Revelation is traditional and debated; John 21:20-24 does not name him.'),
(43, 'James, son of Zebedee', 'James, James the Greater', 3, 44, 1, 0, 'probable', 'apostle', 'moderate', NULL, 641, 642, 'Son of Zebedee and brother of John, one of the inner three with Peter and John. Herod Agrippa I had him killed with the sword (Acts 12:2), the only one of the Twelve whose martyrdom Scripture records. Matthew 27:56 mentions "the mother of Zebedee''s children" at the cross; Mark 15:40 names Salome in the same group, and she is commonly identified with her (an inference).', 'Killed shortly before Peter''s arrest at Passover (Acts 12:1-3); Agrippa died soon after in AD 44 (Acts 12:23; Josephus Ant. 19.343-352), so AD 44. Birth year is an estimate. The tradition of his preaching in Spain and burial at Santiago de Compostela is medieval.'),
(44, 'Stephen', NULL, 1, 33, 1, 0, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'First Christian martyr.', 'Born c. AD 1 (estimated). A Hellenistic Jewish believer, mature enough to be chosen as one of the Seven (Acts 6:5). Stoned: Ussher, Annals §6519-6521, AD 33 (was c. AD 35; Paul''s conversion follows in AD 35, §6533). Death: Ussher, Annals 6518-6521: stoned late AD 33 (Acts 7:58-60); earlier row had AD 35.'),
(45, 'Barnabas', NULL, 5, 61, 1, 1, 'possible', 'disciple', 'moderate', 'Levi', NULL, NULL, 'Companion of Paul on first missionary journey. Colossians 4:10 calls Mark his sister''s son (in other versions, cousin).', 'Joses surnamed Barnabas, a Levite of Cyprus (Acts 4:36). Birth year is an estimate. A 5th-century tradition (Acts of Barnabas) has him martyred at Salamis on Cyprus, c. AD 61; Acts is silent.'),
(46, 'Timothy', NULL, 17, 97, 1, 1, 'possible', 'church-leader', 'moderate', NULL, NULL, 645, 'Paul''s protégé; recipient of two epistles. His mother Eunice and grandmother Lois were believers (2 Tim 1:5); his father was a Greek whom Scripture does not name (Acts 16:1).', 'Born at Lystra to a Jewish mother (Eunice) and a Greek father (Acts 16:1; 2 Tim 1:5); still young when Paul wrote 1 Timothy (1 Tim 4:12). Birth c. AD 17 is an estimate. Later tradition (Acts of Timothy) has him killed at Ephesus c. AD 97.'),
(47, 'Luke', NULL, 10, 94, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Physician; author of Luke and Acts.', 'Born c. AD 10 (estimate); from Antioch according to Eusebius (HE 3.4). Physician (Col 4:14); traditionally the author of Luke-Acts. The Anti-Marcionite Prologue says he died in Boeotia aged 84, which with the birth estimate gives c. AD 94.'),
(123, 'Lazarus', 'Lazarus of Bethany', -5, 60, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Brother of Mary and Martha; raised from the dead by Jesus after four days.', 'John 11:1-44; 12:1-11. Birth and death years are estimates. Later traditions of his life (bishop of Kition on Cyprus, or Marseille) are legendary; Scripture is silent.'),
(125, 'Mary Magdalene', NULL, -5, 60, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Follower of Jesus; first witness of the resurrection.', 'Luke 8:2; Mark 15:40; 16:9; John 20:1-18. Birth and death years are estimates. She is not the sister of Lazarus (that is Mary of Bethany), and the Gospels do not identify her with the sinful woman of Luke 7; that identification is a later Western tradition (Gregory the Great, AD 591). Traditions of her later life (Ephesus; Provence) are late.'),
(127, 'Matthew', 'Levi', 2, 55, 1, 1, 'possible', 'apostle', 'moderate', NULL, 644, NULL, 'Tax collector called by Jesus (Matt 9:9), one of the Twelve; traditionally the author of the first Gospel. Mark 2:14 calls him Levi the son of Alpheus; whether this is the father of James son of Alphaeus is not stated.', 'Matt 9:9; 10:3; called Levi son of Alphaeus in Mark 2:14 and Levi in Luke 5:27. Birth and death years are estimates; Scripture does not record his death and later traditions of it disagree.'),
(128, 'Andrew', NULL, 5, 65, 1, 1, 'possible', 'apostle', 'moderate', NULL, 640, NULL, 'Brother of Peter; one of the first disciples called. Peter and Andrew were sons of Jona (John 1:42; Matt 16:17).', 'John 1:35-42; Matt 4:18-20. Death c. AD 65 by crucifixion at Patras in Achaea is later tradition (Acts of Andrew); the X-shaped cross is a medieval detail. Scripture is silent.'),
(129, 'Philip the Apostle', 'Philip', 5, 80, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Apostle from Bethsaida who brought Nathanael to Jesus.', 'John 1:43-48; 6:5-7; 14:8-9. Death c. AD 80 at Hierapolis is tradition, and ancient writers sometimes confused him with Philip the Evangelist. Scripture is silent.'),
(130, 'Bartholomew', 'Nathanael', 5, 70, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Apostle whom Jesus described as an Israelite without guile.', 'Matt 10:3; John 1:45-51. Traditionally identified with Nathanael of Cana (John 21:2). Death c. AD 70 in Armenia is later tradition; Scripture is silent.'),
(131, 'Thomas', 'Didymus', 5, 72, 1, 1, 'possible', 'apostle', 'moderate', NULL, NULL, NULL, 'Apostle known for his doubt and powerful confession of faith.', 'John 11:16; 14:5; 20:24-29. Death c. AD 72 at Mylapore near Chennai, India, is tradition (Acts of Thomas; the St Thomas Christians); Scripture is silent.'),
(132, 'James, son of Alphaeus', 'James, James the Less', 5, 62, 1, 1, 'possible', 'apostle', 'minor', NULL, 643, NULL, 'One of the twelve apostles; sometimes called James the Less. Matthew 10:3 names his father as Alphaeus; Matthew (Levi) also has a father Alphaeus (Mark 2:14), but the text does not say they are brothers.', 'Matt 10:3; Mark 3:18. Birth and death years are estimates. Later traditions of his death vary, and the year 62 may be borrowed from James the brother of Jesus. His identification with ''James the less'' (Mark 15:40) is traditional but uncertain. Scripture records nothing further.'),
(133, 'Thaddaeus', 'Judas son of James', 5, 65, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Apostle also known as Judas son of James; asked Jesus a question at the Last Supper.', 'Matt 10:3; Luke 6:16; John 14:22; Acts 1:13. Luke calls him ''Judas of James'' (KJV ''brother of James''). Not Judas Iscariot, and traditionally distinguished from Jude the brother of Jesus. Death c. AD 65 is later tradition (Armenian and Syriac); Scripture is silent.'),
(134, 'Simon the Zealot', NULL, 5, 65, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Apostle who may have been a member of the Zealot movement.', 'Matt 10:4; Luke 6:15; Acts 1:13. ''Zealot'' may describe his zeal or the Zealot movement. Death c. AD 65 is later tradition with conflicting accounts; Scripture is silent.'),
(135, 'Judas Iscariot', NULL, 3, 33, 1, 0, 'probable', 'apostle', 'moderate', NULL, NULL, NULL, 'Apostle who betrayed Jesus for thirty pieces of silver.', 'Matthew 26:14-16, 47-50; 27:3-10; Acts 1:16-20. Death in the passion week: Ussher, Annals §6473 (AD 33). Birth is an estimate.'),
(136, 'Matthias', NULL, 5, 80, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Chosen by lot to replace Judas Iscariot among the twelve.', 'Acts 1:21-26. Later tradition places his ministry in Judea, Cappadocia or Ethiopia; Scripture does not mention him after Acts 1. Birth and death years are estimates.'),
(137, 'Mark', 'John Mark', 15, 68, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, 647, 'Companion of Paul and Barnabas (Acts 12:25; 15:37-39) and later of Peter (1 Pet 5:13); traditionally the author of the second Gospel. His mother was Mary of Jerusalem, whose house served as a meeting place (Acts 12:12). Colossians 4:10 calls him "sister''s son to Barnabas" (often translated cousin).', 'Acts 12:12, 25; 15:37-39; Col 4:10; 2 Tim 4:11; 1 Pet 5:13. His identification with the evangelist and with the Mark of 1 Peter is traditional. Death c. AD 68 at Alexandria is later tradition (Eusebius HE 2.16 records his Alexandrian mission).'),
(138, 'Silas', 'Silvanus', 5, 65, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Prominent member of the Jerusalem church; companion of Paul on the second missionary journey.', 'Acts 15:22-40; 16-17; 1 Thessalonians 1:1.'),
(139, 'Titus', NULL, 10, 70, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Gentile convert and co-worker of Paul; led the church in Crete.', 'Galatians 2:1-3; 2 Corinthians 7-8; Titus 1:4-5.'),
(140, 'Priscilla', 'Prisca', 10, 68, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Wife of Aquila; together they mentored Apollos and hosted house churches.', 'Acts 18:2-3, 18-26; Romans 16:3-5.'),
(141, 'Aquila', NULL, 10, 68, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Husband of Priscilla; tentmaker who worked with Paul in Corinth.', 'Acts 18:2-3, 18-26; Romans 16:3-5.'),
(142, 'Apollos', NULL, 10, 70, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Eloquent Alexandrian Jew who preached powerfully but was further taught by Priscilla and Aquila.', 'Acts 18:24-28; 1 Corinthians 1:12; 3:4-6.'),
(143, 'Philemon', NULL, 10, 70, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Wealthy Christian in Colossae to whom Paul wrote about the slave Onesimus.', 'Philemon 1-25.'),
(144, 'James, brother of Jesus', 'James, James the Just', -2, 63, 1, 0, 'probable', 'church-leader', 'moderate', 'Judah', NULL, NULL, 'The Lord''s brother who came to faith after the resurrection and became the acknowledged leader of the Jerusalem church, remembered as James the Just. Paul names him a pillar, the historian Josephus records his execution, and the practical wisdom of his letter still guides believers.', 'Acts 15:13-21; Gal 1:19; 2:9; James 1:1. Josephus (Ant. 20.200) records his stoning (Ussher: AD 63; commonly AD 62), between the death of Festus and the arrival of Albinus; Hegesippus (in Eusebius) gives a fuller account. Birth year is an estimate that assumes the brothers were younger sons of Mary and Joseph (the common Protestant view). The Orthodox tradition holds they were sons of Joseph by an earlier marriage (older than Jesus); the Catholic tradition, following Jerome, holds they were cousins. Death: Ussher, Annals 6885-6887: AD 63, after the death of Festus (Josephus Ant. 20.200); many modern scholars give AD 62.'),
(234, 'Salome daughter of Herodias', NULL, 14, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, 233, 'Daughter of Herodias who danced before Herod and requested John the Baptist''s head. Married Philip the tetrarch, according to Josephus.', 'Estimate: she was a girl when she danced before Herod Antipas, about AD 31-32 (Mark 6:22). Her name comes from Josephus (Antiquities 18.5.4); the Gospels do not name her.'),
(237, 'Barabbas', NULL, -5, 55, 1, 1, 'possible', 'other', 'moderate', NULL, NULL, NULL, 'Criminal released by Pilate instead of Jesus at the crowd''s demand.', 'Matt 27:15-26. Released instead of Jesus in AD 33 (AD 30 on the alternative). No further record; birth and death years are estimates.'),
(242, 'Cleopas', NULL, -5, 70, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Disciple who encountered the risen Jesus on the road to Emmaus.', 'Luke 24:13-35.'),
(244, 'Ananias of Damascus', NULL, 5, 60, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Disciple in Damascus who baptized Paul after his conversion on the road to Damascus.', 'Acts 9:10-19; 22:12-16.'),
(245, 'Cornelius', NULL, -5, 60, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Roman centurion in Caesarea; first Gentile convert. His household received the Holy Spirit.', 'Acts 10:1-48; 11:1-18.'),
(246, 'Lydia', NULL, 10, 65, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Seller of purple cloth in Philippi; first European convert. Hosted Paul and Silas.', 'Acts 16:14-15, 40.'),
(248, 'Agabus', NULL, 5, 65, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Christian prophet who predicted a famine and later warned Paul of his arrest in Jerusalem.', 'Acts 11:27-28; 21:10-11.'),
(249, 'Dorcas', 'Tabitha', 5, 41, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Disciple in Joppa known for charitable works; raised from the dead by Peter.', 'Acts 9:36-43.'),
(250, 'Philip the Evangelist', NULL, 5, 70, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'One of the Seven; evangelized Samaria and baptized the Ethiopian eunuch on the Gaza road. Luke says he had four unmarried daughters who prophesied (Acts 21:9); they are not named.', 'Acts 6:5; 8:4-40; 21:8-9. Death c. AD 70 is an estimate; the Hierapolis tradition is sometimes confused with Philip the Apostle. Scripture is silent.'),
(251, 'Ethiopian Eunuch', NULL, -5, 60, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Official of the Ethiopian queen Candace; baptized by Philip after reading Isaiah.', 'Acts 8:26-39.'),
(252, 'Onesimus', NULL, 30, 80, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Runaway slave of Philemon whom Paul sent back with a letter asking Philemon to receive him no longer as a slave but as a beloved brother (Philem 16).', 'Philem 1:10-21; Col 4:9.'),
(253, 'Rhoda', NULL, 15, 70, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Servant girl who answered the door when Peter was freed from prison; was so overjoyed she forgot to open it.', 'Acts 12:13-16.'),
(255, 'Herod Agrippa II', NULL, 27, 100, 0, 1, 'probable', 'ruler', 'minor', NULL, 254, NULL, 'Last of the Herodian line; heard Paul''s defense at Caesarea. Said Paul almost persuaded him to be a Christian. Sisters of Agrippa II: Bernice (Acts 25:13) and Drusilla (Acts 24:24).', 'Acts 25:13-26:32. Born AD 27 or 28 (Josephus Ant. 19.354); king of Chalcis from AD 50, later of territories to the north-east; died c. AD 92-100 (Photius gives AD 100).'),
(257, 'Festus', 'Porcius Festus', 10, 63, 1, 0, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'Roman governor who succeeded Felix; before whom Paul appealed to Caesar.', 'Acts 25:1-12; 26:24-32. Procurator AD 62-63 on Ussher (commonly c. AD 60-62; some date his arrival to 59); died in office (Josephus Ant. 20.197, 200). Birth year is an estimate. Ussher, Annals 6868, 6885: arrived as governor AD 62 and died in office AD 63 (Josephus Ant. 20.197).'),
(258, 'Ananias and Sapphira', NULL, -5, 33, 1, 0, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Husband and wife who lied to the Holy Spirit about the price of their property; both struck dead.', 'Acts 5:1-11. Ussher, Annals §6514: AD 33, soon after Pentecost. Was 34. Birth year is an estimate. Death: Ussher, Annals 6514: AD 33, soon after Pentecost (Acts 5:1-11); earlier row had AD 34.'),
(259, 'Phoebe', NULL, 20, 70, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Deaconess of the church at Cenchreae; commended by Paul as a patron and letter-carrier of Romans.', 'Rom 16:1-2.'),
(319, 'Joses, brother of Jesus', 'Joses, Jose, Joseph', 1, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Brother of Jesus mentioned in Mark 6:3 and Matthew 13:55.', 'Mark 6:3; Matthew 13:55. Birth year is an estimate that assumes the brothers were younger sons of Mary and Joseph (the common Protestant view). The Orthodox tradition holds they were sons of Joseph by an earlier marriage (older than Jesus); the Catholic tradition, following Jerome, holds they were cousins.'),
(320, 'Simon, brother of Jesus', 'Simon', 2, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Brother of Jesus mentioned in Mark 6:3 and Matthew 13:55. Not to be confused with Simon Peter or Simon the Zealot.', 'Mark 6:3; Matthew 13:55. Birth year is an estimate that assumes the brothers were younger sons of Mary and Joseph (the common Protestant view). The Orthodox tradition holds they were sons of Joseph by an earlier marriage (older than Jesus); the Catholic tradition, following Jerome, holds they were cousins.'),
(321, 'Jude, brother of Jesus', 'Judas, Juda, Jude', 3, NULL, 1, 1, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Brother of Jesus mentioned in Mark 6:3 and Matthew 13:55. Traditionally identified as the author of the Epistle of Jude.', 'Mark 6:3 (Juda); Matthew 13:55 (Judas); Jude 1:1 (''brother of James''). Birth year is an estimate that assumes the brothers were younger sons of Mary and Joseph (the common Protestant view). The Orthodox tradition holds they were sons of Joseph by an earlier marriage (older than Jesus); the Catholic tradition, following Jerome, holds they were cousins.'),
(645, 'Eunice', NULL, -5, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, 646, 'Jewish believer of Lystra and mother of Timothy. Paul praises the "unfeigned faith" that dwelt first in Timothy''s grandmother Lois and then in Eunice (2 Tim 1:5). Timothy''s father was a Greek whom Scripture does not name (Acts 16:1).', 'Estimate only, about a generation before Timothy (born c. AD 17). Scripture gives no dates. 2 Tim 1:5 names Lois as Timothy''s grandmother and Eunice as his mother; that Lois was Eunice''s mother, not Timothy''s paternal grandmother, is the natural reading but is not stated.'),
(647, 'Mary, mother of John Mark', 'Mary of Jerusalem', -5, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Jerusalem believer in whose house many were praying when Peter came knocking after his release from prison (Acts 12:12). Her son was John, surnamed Mark. Colossians 4:10 calls Mark "sister''s son to Barnabas" (KJV; the Greek anepsios is often rendered "cousin"), which makes her Barnabas''s sister (or, if the word means cousin, his relative).', 'Estimate only, about a generation before Mark (born c. AD 15). The event is dated to AD 44 (Acts 12). Her husband is not named.'),
(651, 'Bernice', 'Berenice', 28, NULL, 1, 1, 'probable', 'queen', 'minor', NULL, 254, NULL, 'Daughter of Herod Agrippa I and sister of Agrippa II and Drusilla. She came with Agrippa II to Caesarea to greet Festus and heard Paul''s defense with him (Acts 25:13; 26:30).', 'Josephus (Ant. 19.276-277): born c. AD 28. The year of her death is not recorded; she was still living in the 70s, when she was with Titus in Rome.'),
(741, 'Vespasian', 'Titus Flavius Vespasianus', 9, 79, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Roman general sent to put down the Jewish revolt in AD 66. He was proclaimed emperor in AD 69 and left the siege of Jerusalem to his son Titus. He ruled until AD 79.', 'Standard Roman chronology: born 17 November AD 9, emperor 69-79, died 23 June AD 79.'),
(1050, 'Tychicus', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Christian from the province of Asia who travelled with Paul and carried his letters to Ephesus and Colossae, telling the churches how Paul was faring. Paul later sent him to Ephesus and offered to send him to Titus on Crete.', 'Estimate; Scripture gives no birth or death year. Active from Paul''s third journey (Acts 20:4, about 56) through 2 Timothy (66); birth set about 20 so he is an adult in 56.'),
(1051, 'Aristarchus', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Macedonian of Thessalonica and companion of Paul. He was seized in the Ephesus riot, travelled with Paul toward Asia, sailed with him on the voyage to Rome, and is called Paul''s fellow prisoner and fellow labourer.', 'Estimate; Scripture gives no birth or death year. Appears in Acts 19-27 (about 57-62) and in the prison letters (about 64); birth set about 15.'),
(1052, 'Trophimus', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Gentile Christian of Ephesus who travelled with Paul. Jews in Jerusalem falsely supposed Paul had brought him into the temple, which sparked Paul''s arrest. Paul later left him sick at Miletus.', 'Estimate; Scripture gives no birth or death year. Named in Acts 20-21 (about 56-60) and 2 Timothy (66); birth set about 20.'),
(1053, 'Demas', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Co-worker of Paul during his Roman imprisonment, who sent greetings with Luke. Near the end of Paul''s life he left him, having loved the present world, and went to Thessalonica.', 'Estimate; Scripture gives no birth or death year. Named in the prison letters (about 64) and 2 Timothy (66); birth set about 20.'),
(1054, 'Epaphras', NULL, 10, NULL, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Founder or teacher of the church at Colossae, who brought Paul news of it in prison and prayed hard for it and for Laodicea and Hierapolis. Paul calls him a fellow servant and fellow prisoner. He may be the same person as Epaphroditus, but the text does not say so; this timeline keeps them apart.', 'Estimate; Scripture gives no birth or death year. Named in the prison letters (about 64); birth set about 10.'),
(1055, 'Epaphroditus', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Messenger of the Philippian church who brought Paul their gift in prison. He fell nearly fatally ill, recovered, and was sent back with Paul''s letter to Philippi.', 'Estimate; Scripture gives no birth or death year. Named in Philippians (about 64); birth set about 15. Not the same person as Epaphras of Colossae as far as the text shows.'),
(1056, 'Onesiphorus', NULL, 10, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Christian of Ephesus whose household Paul blesses. He often refreshed Paul and was not ashamed of his chain, and in Rome he searched hard until he found him.', 'Estimate; Scripture gives no birth or death year. Named in 2 Timothy (about 66); birth set about 10. Paul wishes mercy on his ''house'' and greets it (2 Tim 4:19), which some readers take to mean he had died; the text does not say.'),
(1057, 'Archippus', NULL, 10, NULL, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Fellow soldier of Paul addressed in Philemon, who is told in Colossians to take heed to the ministry he received in the Lord. He seems to have belonged to Philemon''s household church.', 'Estimate; Scripture gives no birth or death year. Named in Colossians and Philemon (about 64); birth set about 10.'),
(1058, 'Stephanas', NULL, 10, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Corinthian whose household Paul baptised and called the firstfruits of Achaia. He gave himself to serving the saints, and with Fortunatus and Achaicus visited Paul and brought him news from Corinth.', 'Estimate; Scripture gives no birth or death year. Baptised by Paul during the 18 months at Corinth (about 54-55); visits Paul around the time 1 Corinthians was written (59); birth set about 10.'),
(1059, 'Erastus', NULL, 15, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Helper of Paul whom he sent with Timothy from Ephesus into Macedonia. A man named Erastus, the city treasurer, sends greetings in Romans from Corinth, and 2 Timothy says Erastus stayed at Corinth. The text does not say that all three are one man, though many readers think so.', 'Estimate; Scripture gives no birth or death year. Acts 19:22 (about 57), Romans (60) and 2 Timothy (66); birth set about 15.'),
(1060, 'Gaius of Macedonia', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Companion of Paul from Macedonia who was seized with Aristarchus by the Ephesus mob. The text calls him a Macedonian; the Gaius of Derbe in Acts 20:4 is described differently, so this timeline treats them as separate men, though some readers identify them.', 'Estimate; Scripture gives no birth or death year. Acts 19:29 (about 57); birth set about 15.'),
(1061, 'Gaius of Derbe', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Man of Derbe in Lycaonia who accompanied Paul into Asia at the end of the third journey, among a party that included Timothy, Tychicus and Trophimus.', 'Estimate; Scripture gives no birth or death year. Acts 20:4 (about 56); birth set about 15. Some manuscripts read ''Doberius'' for ''Derbe'', and some readers equate him with the Macedonian Gaius of Acts 19:29.'),
(1062, 'Gaius of Corinth', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Corinthian baptised by Paul and later host to Paul and to the whole church there, who sends greetings in Romans. He is probably the Gaius of 1 Corinthians 1:14.', 'Estimate; Scripture gives no birth or death year. Baptised during the Corinth ministry (about 54-55) and sending greetings from Corinth when Romans was written (60); birth set about 15.'),
(1063, 'Gaius, addressee of 3 John', NULL, 30, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Beloved friend of the elder John, praised for walking in the truth and for hospitality to travelling brothers. He is the one to whom 3 John is addressed. The text does not say whether he is one of the other Gaiuses named in the New Testament.', 'Estimate; Scripture gives no birth or death year. 3 John (about 90); birth set about 30 so he is an adult in 90.'),
(1064, 'Andronicus', NULL, 1, NULL, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Jewish Christian in Rome whom Paul calls his kinsman and fellow prisoner, ''of note among the apostles'' and in Christ before him. Usually paired with Junia.', 'Estimate; Scripture gives no birth or death year. In Christ before Paul (converted about 35), so born by about the turn of the era; named in Romans (60).'),
(1065, 'Junia', NULL, 1, NULL, 1, 1, 'possible', 'apostle', 'minor', NULL, NULL, NULL, 'Christian in Rome, greeted with Andronicus as Paul''s kinsman and fellow prisoner, ''of note among the apostles''. Most ancient writers read the name as a woman''s, and ''apostle'' here may mean one sent out rather than one of the Twelve; readers differ on both points.', 'Estimate; Scripture gives no birth or death year. Same as Andronicus: in Christ before Paul, named in Romans (60).'),
(1066, 'Tryphena', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Woman greeted by Paul in Rome as one who labours in the Lord. KJV spells the name Tryphaena. Often thought to be a sister or relative of Tryphosa, though the text does not say.', 'Estimate; Scripture gives no birth or death year. Named in Romans (60); birth set about 15.'),
(1067, 'Tryphosa', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Woman greeted by Paul in Rome as one who labours in the Lord, named together with Tryphena.', 'Estimate; Scripture gives no birth or death year. Named in Romans (60); birth set about 15.'),
(1068, 'Euodia', 'Euodias', 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Woman of the Philippian church who laboured with Paul in the gospel. Paul urges her and Syntyche to be of one mind in the Lord. KJV spells the name Euodias.', 'Estimate; Scripture gives no birth or death year. Philippians (about 64); birth set about 15.'),
(1069, 'Syntyche', NULL, 15, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Woman of the Philippian church who laboured with Paul in the gospel. Paul urges her and Euodia to be of one mind in the Lord.', 'Estimate; Scripture gives no birth or death year. Philippians (about 64); birth set about 15.'),
(1070, 'Hymenaeus', 'Hymeneus', 15, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'False teacher whom Paul says he handed over to Satan so that he would learn not to blaspheme, and who with Philetus taught that the resurrection had already happened. KJV spells the name Hymeneus.', 'Estimate; Scripture gives no birth or death year. Named in 1 Timothy (65) and 2 Timothy (66); birth set about 15.'),
(1071, 'Philetus', NULL, 15, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'False teacher named with Hymenaeus, whose talk spread like gangrene and who overturned the faith of some by saying the resurrection was already past.', 'Estimate; Scripture gives no birth or death year. Named in 2 Timothy (66); birth set about 15.'),
(1072, 'Alexander the coppersmith', NULL, 15, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Man who did Paul much harm and strongly opposed his message, so that Paul warns Timothy about him. He may be the Alexander whom Paul handed over to Satan in 1 Timothy 1:20, but the text does not say; he is also not clearly the Alexander of the Ephesus riot (Acts 19:33).', 'Estimate; Scripture gives no birth or death year. 2 Timothy (66); birth set about 15.'),
(1073, 'Diotrephes', NULL, 30, NULL, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Church leader who loved to have the first place, rejected the elder''s authority and messengers, spoke against him with malicious words, and put out of the church those who would welcome the brothers. John says he will deal with him when he comes.', 'Estimate; Scripture gives no birth or death year. 3 John (about 90); birth set about 30.'),
(1074, 'Zenas the lawyer', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Lawyer whom Paul asks Titus to help on his journey together with Apollos, so that they lack nothing. It is not clear whether he was a Roman or a Jewish legal expert.', 'Estimate; Scripture gives no birth or death year. Titus (65); birth set about 20.'),
(1075, 'Artemas', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Co-worker of Paul whom he planned to send to Titus on Crete, or else Tychicus, so that Titus could come to meet him at Nicopolis.', 'Estimate; Scripture gives no birth or death year. Titus (65); birth set about 20.'),
(1076, 'Linus', NULL, 20, NULL, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Christian in Rome who sends greetings to Timothy in Paul''s last letter. Early church writers (Irenaeus, Eusebius) name a Linus as the first bishop of Rome after the apostles and identify him with this man; that identification is tradition, not stated in Scripture.', 'Estimate; Scripture gives no birth or death year. 2 Timothy (66); birth set about 20. Tradition''s later dates for his bishopric are not used here.'),
(1077, 'Carpus', NULL, 20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Christian of Troas with whom Paul left his cloak, books and parchments, and whom Paul asks Timothy to visit on his way to Rome.', 'Estimate; Scripture gives no birth or death year. 2 Timothy (66); birth set about 20.'),
(1078, 'Tertius', NULL, 15, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Christian who wrote down Paul''s letter to the Romans as Paul dictated it, and who adds his own greeting in the Lord.', 'Estimate; Scripture gives no birth or death year. Romans (60); birth set about 15.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(38, 'Mary, mother of Jesus', 'Mary, Miriam, the Virgin Mary', -20, 48, 1, 1, 'possible', 'matriarch', 'major', NULL, NULL, NULL, 'The young woman of Nazareth chosen to bear Jesus, whose obedient response to the angel''s announcement made her the most honored woman in Scripture. Her Magnificat echoes Hannah''s song, and she appears from Bethlehem to the cross and among the praying disciples before Pentecost. Luke calls Elisabeth her "cousin" (Luke 1:36), a relative of unspecified degree; the two are not sisters.', 'Birth and death years are estimates. Scripture last mentions her at Acts 1:14. Catholic and Orthodox Christians hold her Assumption or Dormition; Protestants generally hold that Scripture is silent on the end of her life. Tradition places her later life at Jerusalem or Ephesus.'),
(122, 'Joseph of Nazareth', NULL, -25, 20, 1, 1, 'possible', 'other', 'moderate', 'Judah', 280, NULL, 'Husband of Mary and legal father of Jesus, a carpenter of Nazareth described as a righteous man (Matt 1:19). Matthew 1:16 calls him the son of Jacob, and this table follows Matthew for his father. Luke 3:23 calls him the son of Heli, so the two lists disagree. Two classic explanations are offered. Africanus (3rd century) held that Jacob and Heli were half-brothers by the same mother, and that when Heli died childless Jacob married the widow, so Joseph was Jacob''s son by birth and Heli''s by levirate law. Other writers, including many later Western and Eastern commentators, read Luke as tracing Mary''s line, with Heli as her father and Joseph as his son-in-law. The tradition of the church does not require a choice between them.', 'Matthew 1-2; Luke 2. Disappears from narrative after Jesus'' youth.'),
(124, 'Martha', NULL, -10, 60, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Sister of Lazarus and Mary; known for her hospitality and service.', 'Luke 10:38-42; John 11; 12:2. Birth and death years are estimates. Later tradition (Provence) is legendary; Scripture is silent.'),
(126, 'Nicodemus', NULL, -20, 63, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Pharisee who came to Jesus at night; helped bury Jesus.', 'John 3:1-21; 7:50-52; 19:39. Birth c. 20 BC and death c. AD 63 are estimates only: Scripture records neither and no early tradition dates his death.'),
(145, 'Herod the Great', NULL, -73, -4, 1, 0, 'certain', 'ruler', 'moderate', NULL, NULL, NULL, 'King of Judea who rebuilt the Temple but ordered the massacre of infants in Bethlehem. Father of Archelaus, Herod Antipas and Philip the tetrarch, and grandfather of Herod Agrippa I through Aristobulus IV.', 'Matthew 2:1-19; confirmed by Josephus. Death in 4 BC is well-established.'),
(146, 'Pontius Pilate', NULL, -10, 39, 1, 0, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'Roman governor of Judea who authorized the crucifixion of Jesus.', 'Prefect of Judea from AD 26 (Ussher, Annals §6279; Luke 3:1); ordered to Rome by Vitellius in AD 36 (§6564); Ussher, citing Eusebius and Jerome, has him take his own life under Caligula in AD 39 (§6609), a late tradition. Birth year is conjecture.'),
(147, 'Anna', 'Anna the Prophetess', -89, -3, 1, 1, 'possible', 'prophet', 'moderate', 'Asher', NULL, NULL, 'Elderly prophetess who recognized the infant Jesus at the Temple.', 'Luke 2:36-37: daughter of Phanuel of Asher, seven years married, then ''a widow of about fourscore and four years'', which may mean aged 84 or widowed 84 years (about 105). Taking 84 as her age at the presentation (c. 5 BC) gives a birth c. 89 BC; the death year is an estimate.'),
(229, 'Simeon of Jerusalem', 'Simeon, Simeon at the Temple', -100, -2, 1, 1, 'possible', 'prophet', 'moderate', NULL, NULL, NULL, 'Devout man in Jerusalem who held the infant Jesus and prophesied. Promised he would see the Messiah.', 'Luke 2:25-35. Luke gives no age, only that he would not die before seeing the Lord''s Christ (Luke 2:26); birth and death years are estimates.'),
(230, 'Zechariah, father of John the Baptist', 'Zechariah, Zacharias', -60, -5, 1, 1, 'possible', 'priest', 'moderate', 'Levi', NULL, NULL, 'Priest who was struck mute for doubting Gabriel''s announcement of John the Baptist''s birth.', 'Luke 1:5-25, 57-80. Luke says only that he and Elizabeth were ''well stricken in years'' (Luke 1:7); birth and death years are estimates. A second-century tradition (the Protoevangelium of James), not in Scripture, tells of his murder in the Temple; the Orthodox Church commemorates him as a martyr.'),
(231, 'Elizabeth', 'Elisabeth', -55, -3, 1, 1, 'possible', 'matriarch', 'moderate', 'Levi', NULL, NULL, 'Wife of Zechariah; mother of John the Baptist. Relative of Mary. Elizabeth was a daughter of Aaron (Luke 1:5) and Mary''s "cousin" (Luke 1:36).', 'Luke 1:5-7, 39-45, 57-60. Birth and death years are estimates.'),
(232, 'Herod Antipas', 'Herod the Tetrarch', -20, 39, 1, 1, 'probable', 'ruler', 'moderate', NULL, 145, NULL, 'Son of Herod the Great; executed John the Baptist and mocked Jesus during his trial.', 'Matt 14:1-12; Mark 6:14-29; Luke 3:1; 13:31-32; 23:6-12. Tetrarch of Galilee and Perea from 4 BC (Ussher, Annals §6079); banished in AD 39 (Ussher, Annals, under 39 AD, citing Josephus Ant. 18.240-255). His birth (c. 20 BC) is inferred and the year of his death is unknown.'),
(233, 'Herodias', NULL, -15, 39, 1, 1, 'possible', 'other', 'moderate', NULL, 650, NULL, 'Wife of Herod Antipas; orchestrated John the Baptist''s execution through her daughter. Her father was Aristobulus IV (Josephus), so she was the sister of Herod Agrippa I and Antipas''s niece. Her first husband was another son of Herod the Great (Mark 6:17 calls him Philip; Josephus calls him Herod).', 'Matt 14:3-11; Mark 6:17-28.'),
(235, 'Caiaphas', 'Joseph Caiaphas', -30, 35, 1, 1, 'possible', 'priest', 'moderate', NULL, NULL, NULL, 'High priest who presided over Jesus'' trial; declared it expedient for one man to die for the people. Annas was his father-in-law (John 18:13).', 'Matt 26:3, 57-68; John 11:49-53; 18:13-28. Ussher, Annals §6278: appointed high priest by Valerius Gratus in AD 26, after Annas''s removal; deposed by Vitellius in AD 35 (§6543; Josephus Ant. 18.95 has 36/37). The death year marks the deposition; his death is unrecorded. An ossuary found in 1990 may be his (debated). Birth year is an estimate.'),
(236, 'Annas', NULL, -25, 40, 1, 1, 'possible', 'priest', 'moderate', NULL, NULL, NULL, 'Former high priest and father-in-law of Caiaphas; influential in Jesus'' trial.', 'Luke 3:2; John 18:13-24; Acts 4:6. High priest from AD 6 (Josephus Ant. 18.26, 18.34); removed by Gratus (Ussher, Annals §6268 places the removal in AD 23); five of his sons and his son-in-law Caiaphas held the office afterwards. Ussher still calls him high priest at the trial of Stephen (§6519, AD 33), as Acts 4:6 does. Birth and death years are estimates.'),
(238, 'Joseph of Arimathea', NULL, -30, 50, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Rich member of the Sanhedrin who provided his tomb for Jesus'' burial.', 'Matt 27:57-60; Mark 15:42-46; Luke 23:50-53; John 19:38-42.'),
(239, 'Simon of Cyrene', NULL, -10, 50, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Man from Cyrene compelled to carry Jesus'' cross.', 'Matt 27:32; Mark 15:21; Luke 23:26.'),
(240, 'Zacchaeus', NULL, -20, 50, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Chief tax collector in Jericho who climbed a sycamore tree to see Jesus; converted.', 'Luke 19:1-10.'),
(241, 'Jairus', NULL, -20, 50, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Synagogue ruler whose 12-year-old daughter Jesus raised from the dead.', 'Mark 5:22-43; Luke 8:41-56. Synagogue ruler in Galilee. Daughter raised by Jesus c. AD 31. Birth and death years are estimates.'),
(243, 'Mary of Bethany', NULL, -10, 60, 1, 1, 'possible', 'disciple', 'moderate', NULL, NULL, NULL, 'Sister of Martha and Lazarus; sat at Jesus'' feet; anointed him with expensive perfume.', 'Luke 10:38-42; John 11:1-2; 12:1-8. Birth and death years are estimates. She is distinct from Mary Magdalene; the Western identification of the two (and of the sinful woman of Luke 7) goes back to Gregory the Great (AD 591), was never held in the East, and was dropped from the Roman calendar in 1969.'),
(247, 'Gamaliel', NULL, -10, 52, 1, 1, 'possible', 'sage', 'moderate', NULL, NULL, NULL, 'Respected Pharisee and teacher of Paul; counseled moderation toward the apostles.', 'Acts 5:34-39; 22:3. His counsel falls in AD 33 (Ussher, Annals §6516). Birth and death years are estimates; Scripture gives neither.'),
(254, 'Herod Agrippa I', NULL, -10, 44, 1, 0, 'certain', 'ruler', 'minor', NULL, 650, NULL, 'Grandson of Herod the Great; executed James son of Zebedee and imprisoned Peter. Struck dead by God. Son of Aristobulus IV, a son of Herod the Great, so grandson of Herod the Great; father of Agrippa II, Bernice and Drusilla, and brother of Herodias (Josephus).', 'Acts 12:1-23. Josephus says he died in AD 44 aged 54 (Ant. 19.343-352), so born c. 11/10 BC.'),
(274, 'Azor', NULL, -400, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 273, NULL, 'Son of Eliakim, ancestor of Jesus in Matthew 1:13–14.', 'Known only from Matthew''s genealogy. Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(275, 'Zadok, son of Azor', 'Zadok', -346, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 274, NULL, 'Son of Azor, ancestor of Jesus in Matthew 1:14. Not the priest Zadok of David''s time.', 'Known only from Matthew''s genealogy. Not to be confused with Zadok the priest (2 Sam 8:17). Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(276, 'Achim', 'Jachin', -293, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 275, NULL, 'Son of Zadok, ancestor of Jesus in Matthew 1:14.', 'Known only from Matthew''s genealogy. Intertestamental period. Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(277, 'Eliud', NULL, -239, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 276, NULL, 'Son of Achim, ancestor of Jesus in Matthew 1:14–15.', 'Known only from Matthew''s genealogy. Intertestamental period. Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(278, 'Eleazar, son of Eliud', 'Eleazar', -186, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 277, NULL, 'Son of Eliud, ancestor of Jesus in Matthew 1:15. Not the priest Eleazar son of Aaron.', 'Known only from Matthew''s genealogy. Not to be confused with Eleazar the priest (Num 20:28). Birth year is an inferred placeholder, evenly spaced between Zerubbabel and Joseph (Matt 1:13-16); Matthew''s list probably omits generations, as it does in 1:8 and 1:11.'),
(279, 'Matthan', NULL, -132, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 278, NULL, 'Son of Eleazar, grandfather of Joseph of Nazareth in Matthew 1:15.', 'Known only from Matthew''s genealogy (Matt 1:15). Birth year is an inferred placeholder spacing the ten generations from Zerubbabel to Joseph evenly; Matthew''s list is probably selective.'),
(280, 'Jacob, son of Matthan', 'Jacob', -79, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Judah', 279, NULL, 'Son of Matthan, father of Joseph of Nazareth in Matthew 1:15–16. Not the patriarch Jacob.', 'Known only from Matthew''s genealogy (Matt 1:15-16). Birth year is an inferred placeholder; Matthew''s list is probably selective.'),
(317, 'Matthat, father of Heli', 'Matthat', -80, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 316, NULL, 'Son of Levi, ancestor of Jesus in Luke 3:24. Post-exilic Matthat, grandfather of Joseph.', 'Known only from Luke''s genealogy. Late Second Temple period.'),
(318, 'Heli', 'Eli', -60, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 317, NULL, 'Named in Luke 3:23 as the father of Joseph, in the line running back through Matthat and Levi to Nathan, a son of David. Matthew 1:16 gives Joseph''s father as Jacob instead, and the table keeps Matthew''s link as Joseph''s father_id and shows Heli''s link as a separate parent relationship. Two classic explanations are offered. Africanus held that Heli and Jacob were half-brothers, Heli dying childless so that Jacob fathered Joseph by levirate marriage and Joseph counted as Heli''s heir. Others hold that Luke gives Mary''s ancestry, making Heli Mary''s father and Joseph his son-in-law. Scripture does not say which is right.', 'Known only from Luke''s genealogy. Some scholars identify Heli as Mary''s father, making Luke''s genealogy the natural/maternal line.'),
(452, 'Alexander the Great', 'Alexander of Macedon', -356, -323, 0, 0, 'certain', 'ruler', 'major', NULL, 633, 634, 'King of Macedon whose conquest of the Persian empire (334-323 BC) ended Persian rule over Judea and spread Greek language and culture across the east. Daniel''s vision of the he-goat whose great horn is the first king of Grecia is traditionally read as pointing to him (Dan 8:5-8, 21; 11:3-4), and 1 Maccabees opens with his conquests (1 Macc 1:1-7).', 'Born July 356 BC, died June 323 BC at Babylon. Reading the Daniel passages as Alexander is the traditional interpretation; scholars differ on the dating of Daniel itself.'),
(453, 'Antiochus IV Epiphanes', 'Antiochus Epiphanes', -215, -164, 1, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Seleucid king who plundered the temple in Jerusalem, banned Jewish practice, and set up the abomination of desolation on its altar in December 167 BC, provoking the Maccabean revolt (1 Macc 1:10-64; 2 Macc 5-6). Many readers link him to the little horn of Dan 8:9-12 and to Dan 11:21-35, while some traditions also read these passages of a later figure.', 'Reigned 175-164 BC and died late in 164 BC in Persia (1 Macc 6:1-16). Birth estimated.'),
(454, 'Judas Maccabeus', 'Judas Maccabaeus,Judah the Maccabee', -196, -161, 1, 0, 'probable', 'warrior', 'minor', 'Levi', 635, NULL, 'Third son of the priest Mattathias, who led the Jewish revolt after his father''s death in 166 BC, defeated Seleucid armies, and rededicated the temple in December 165 BC (Ussher; standard dating 164 BC), the event commemorated at Hanukkah (1 Macc 3-4; 2 Macc 8-10; John 10:22). He fell in battle at Elasa in 161 BC (1 Macc 9:5-18; Ussher).', 'Died in year 152 of the Seleucid era (1 Macc 9:3): 161 BC on Ussher (Annals §3528-3532); standard dating 160 BC. Birth estimated. The books of Maccabees are canonical for Catholic and Orthodox Christians and counted among the Apocrypha by Protestants.'),
(470, 'Caesar Augustus', 'Augustus, Octavian', -63, 14, 0, 0, 'certain', 'ruler', 'moderate', NULL, NULL, NULL, 'First Roman emperor (27 BC-AD 14). Luke says his decree that all the world should be taxed brought Joseph and Mary to Bethlehem (Luke 2:1-5). Augustus adopted his stepson Tiberius in AD 4 and named him his successor.', 'Born 23 September 63 BC; died 19 August AD 14. Luke 2:1.'),
(471, 'Tiberius Caesar', 'Tiberius', -42, 37, 0, 0, 'certain', 'ruler', 'moderate', NULL, NULL, NULL, 'Second Roman emperor (AD 14-37). Luke dates the start of John the Baptist''s preaching to his fifteenth year (Luke 3:1), and Jesus was crucified under his prefect Pontius Pilate. Born Tiberius Claudius Nero, he was the stepson of Augustus, who adopted him in AD 4.', 'Born 16 November 42 BC; emperor from 19 August AD 14; died 16 March AD 37. Luke 3:1.'),
(472, 'Claudius', 'Claudius Caesar, Tiberius Claudius Caesar', -10, 54, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Fourth Roman emperor (AD 41-54). Acts dates the famine foretold by Agabus to his reign (Acts 11:28) and says his expulsion of the Jews from Rome brought Aquila and Priscilla to Corinth (Acts 18:2).', 'Born 1 August 10 BC; died 13 October AD 54. The expulsion of the Jews: Ussher (Annals 6792) places it just before Paul reached Corinth, AD 54; Orosius gives AD 49, the usual modern date (compare Suetonius, Claudius 25).'),
(633, 'Philip II of Macedon', NULL, -382, -336, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'King of Macedon who made Macedon the leading power of Greece and was assassinated in 336 BC. Father of Alexander the Great. Not named in Scripture.', 'Standard historical record (not stated in Scripture). Born 382 BC, died 336 BC. Daniel 8:21 and 11:3 speak of the first king of Greece.'),
(634, 'Olympias', NULL, -375, -316, 1, 0, 'probable', 'queen', 'minor', NULL, NULL, NULL, 'Queen of Macedon, wife of Philip II and mother of Alexander the Great. Not named in Scripture.', 'Standard historical record (not stated in Scripture). Born about 375 BC and killed in 316 BC.'),
(640, 'Jonas, father of Peter', 'Jona, Jonah, Bar-jona', -30, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Father of Simon Peter. Jesus calls Peter "Simon Bar-jona" (Matt 16:17) and "son of Jona" (John 1:42); in John 21:15-17 the KJV reads "son of Jonas". Some manuscripts of John give the name as John. Peter''s brother Andrew is presumed to share this father.', 'Estimate only, about a generation before Peter. Scripture gives no dates for him. Andrew is called Peter''s brother (John 1:40) but only Peter is named as Jona''s son in the text; Andrew''s link rests on that.'),
(641, 'Zebedee', NULL, -25, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Galilean fisherman, father of the apostles James and John. His sons left him mending nets in the boat with his hired servants to follow Jesus.', 'Estimate only, about a generation before his sons. Scripture gives no dates for him, and he does not appear after the calling of his sons.'),
(642, 'Mother of James and John', 'Mother of Zebedee''s children, Salome (traditional identification)', -20, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Wife of Zebedee and mother of the apostles James and John. She asked Jesus that her two sons might sit at his right and left in his kingdom (Matt 20:20-21) and stood among the women at the crucifixion (Matt 27:56). Scripture does not give her name. Mark 15:40 lists a Salome in the same group of women, and many readers identify the two; that is an inference, and some traditions identify her differently. She is not Salome the daughter of Herodias.', 'Estimate only, about a generation before her sons. The identification with Salome (Mark 15:40) is a common inference, not stated in Scripture; compare Matt 27:56 with Mark 15:40.'),
(643, 'Alphaeus, father of James the apostle', 'Alpheus', -25, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Father of the apostle James son of Alphaeus (Matt 10:3), traditionally identified with James the Less (Mark 15:40). Mark 2:14 calls Levi (Matthew) "the son of Alpheus" too. Whether this is the same Alphaeus, which would make Matthew and James brothers, is not stated in the Gospels; the two are kept as separate rows here.', 'Estimate only. Scripture gives no dates for him.'),
(644, 'Alphaeus, father of Levi', 'Alpheus', -28, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Named in Mark 2:14 as the father of Levi, the tax collector whom Jesus called, usually identified with the apostle Matthew (Matt 9:9). The Gospels do not say whether he is the Alphaeus who fathered James the Less (Matt 10:3); some later writers assume so, others do not.', 'Estimate only. Scripture gives no dates for him. Kept separate from the Alphaeus of Matt 10:3 because the text does not identify them.'),
(646, 'Lois', NULL, -30, NULL, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Timothy''s grandmother, in whom Paul says the faith first dwelt before it passed to Timothy''s mother Eunice and to Timothy (2 Tim 1:5); Eunice is usually taken to be her daughter.', 'Estimate only. Scripture gives no dates.'),
(648, 'Archelaus', 'Herod Archelaus', -23, NULL, 1, 1, 'probable', 'ruler', 'minor', NULL, 145, NULL, 'Son of Herod the Great who ruled Judea, Samaria and Idumea as ethnarch after his father''s death. When Joseph heard that Archelaus reigned in Judea in his father''s place, he was afraid to go there and turned aside to Galilee (Matt 2:22). Augustus removed him in AD 6 after complaints from his subjects.', 'Josephus (Ant. 17.188; Jewish War 2.111): born c. 23 BC, ethnarch 4 BC to AD 6, banished beyond the Alps (Ussher, Annals §6174, AD 6). The year of his death is uncertain, so none is given.'),
(649, 'Philip the Tetrarch', 'Herod Philip II, Philip', -22, 34, 1, 0, 'probable', 'ruler', 'minor', NULL, 145, NULL, 'Son of Herod the Great, tetrarch of Ituraea and Trachonitis (Luke 3:1). He rebuilt Caesarea Philippi and Bethsaida, and according to Josephus married Salome, the daughter of Herodias. He should not be confused with the Philip whom Mark 6:17 calls Herodias''s first husband; Josephus names that man as another son of Herod the Great.', 'Ussher, Annals §6079, §6529: tetrarch from 4 BC (Herod''s will); died AD 34 at Julias, in the twentieth year of Tiberius, after governing thirty-seven years (Josephus Ant. 18.106-108). Birth c. 22 BC is inferred from his father''s marriage to Cleopatra of Jerusalem.'),
(650, 'Aristobulus IV', 'Aristobulus son of Herod', -35, -7, 1, 1, 'probable', 'other', 'minor', NULL, 145, NULL, 'Son of Herod the Great and the Hasmonean princess Mariamne, put to death by his father with his brother Alexander. He was the father of Herod Agrippa I and of Herodias, and so grandfather of Agrippa II, Bernice and Drusilla (Josephus). He is not named in Scripture; the link to Acts 12 is through his son.', 'Josephus (Ant. 16.394; Jewish War 1.551): executed at Sebaste, about 7 BC. Birth c. 35 BC is inferred from his mother''s marriage to Herod in 37 BC. Not in Scripture.'),
(822, 'Pompey', 'Gnaeus Pompeius Magnus', -106, -48, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Roman general who took Jerusalem in 63 BC, ending Hasmonean independence and bringing Judea under Rome; he entered the Holy of Holies but left the Temple treasury untouched (Josephus, Antiquities 14.4). He was killed in Egypt after his defeat by Julius Caesar.', 'Born 106 BC; killed in Egypt in 48 BC. Not named in Scripture.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(176, 'Melchizedek', NULL, NULL, NULL, 1, 1, 'possible', 'priest', 'moderate', NULL, NULL, NULL, 'The enigmatic king of Salem and priest of God Most High who blessed Abram and received his tithe. Psalm 110 made his order a royal-priestly ideal, the Dead Sea Scrolls cast him as a heavenly deliverer, and Hebrews sees in him the pattern of Christ''s eternal priesthood.', 'Scripture records no birth or death for Melchizedek (Heb 7:3). He is placed on the timeline by his meeting with Abraham (Gen 14:18-20). A Jewish tradition identifies him with Shem; this timeline does not assume it.'),
(256, 'Felix', 'Antonius Felix', NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'Roman governor of Judea who heard Paul''s case and left him imprisoned for two years. Husband of Drusilla, a daughter of Herod Agrippa I (Acts 24:24).', 'Acts 23:24-24:27. Procurator of Judea AD 53-62 on Ussher, Annals 6771, 6868 (commonly c. AD 52-60; Josephus, Tacitus), recalled to Rome when Festus succeeded him. His birth and death years are unknown.'),
(282, 'Mattatha', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 281, NULL, 'Son of Nathan, ancestor of Jesus in Luke 3:31.', 'Known only from Luke''s genealogy.'),
(283, 'Menna', 'Menan', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 282, NULL, 'Son of Mattatha, ancestor of Jesus in Luke 3:31.', 'Known only from Luke''s genealogy.'),
(284, 'Melea', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 283, NULL, 'Son of Menna, ancestor of Jesus in Luke 3:31.', 'Known only from Luke''s genealogy.'),
(285, 'Eliakim, son of Melea', 'Eliakim', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 284, NULL, 'Son of Melea, ancestor of Jesus in Luke 3:30. Not the Eliakim of Matthew''s line or 2 Kings 18.', 'Known only from Luke''s genealogy. Luke 3:30.'),
(286, 'Jonam', 'Jonan', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 285, NULL, 'Son of Eliakim, ancestor of Jesus in Luke 3:30.', 'Known only from Luke''s genealogy.'),
(287, 'Joseph, son of Jonam', 'Joseph', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 286, NULL, 'Son of Jonam, ancestor of Jesus in Luke 3:30. Not Joseph of Nazareth.', 'Known only from Luke''s genealogy. One of several Josephs in the lineage.'),
(288, 'Judah, son of Joseph', 'Judah, Juda', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 287, NULL, 'Son of Joseph, ancestor of Jesus in Luke 3:30. Not the patriarch Judah son of Jacob.', 'Known only from Luke''s genealogy.'),
(289, 'Simeon, son of Judah', 'Simeon', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 288, NULL, 'Son of Judah, ancestor of Jesus in Luke 3:30. Not Simeon the patriarch or Simeon at the Temple.', 'Known only from Luke''s genealogy.'),
(290, 'Levi, son of Simeon', 'Levi', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 289, NULL, 'Son of Simeon, ancestor of Jesus in Luke 3:29. Not the patriarch Levi son of Jacob.', 'Known only from Luke''s genealogy.'),
(291, 'Matthat, father of Jorim', 'Matthat', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 290, NULL, 'Son of Levi, ancestor of Jesus in Luke 3:29.', 'Known only from Luke''s genealogy. Pre-exilic Matthat, distinct from the post-exilic Matthat.'),
(292, 'Jorim', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 291, NULL, 'Son of Matthat, ancestor of Jesus in Luke 3:29.', 'Known only from Luke''s genealogy.'),
(293, 'Eliezer', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 292, NULL, 'Son of Jorim, ancestor of Jesus in Luke 3:29. Not Eliezer servant of Abraham.', 'Known only from Luke''s genealogy.'),
(294, 'Joshua, son of Eliezer', 'Joshua, Jose, Jesus', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 293, NULL, 'Son of Eliezer, ancestor of Jesus in Luke 3:29. Same name as Jesus/Joshua in Hebrew. Not Joshua of the conquest.', 'Known only from Luke''s genealogy. Greek Iesous = Hebrew Yehoshua.'),
(295, 'Er', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 294, NULL, 'Son of Joshua, ancestor of Jesus in Luke 3:28. Not Er son of Judah (Gen 38:3).', 'Known only from Luke''s genealogy.'),
(296, 'Elmadam', 'Elmodam', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 295, NULL, 'Son of Er, ancestor of Jesus in Luke 3:28.', 'Known only from Luke''s genealogy.'),
(297, 'Cosam', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 296, NULL, 'Son of Elmadam, ancestor of Jesus in Luke 3:28.', 'Known only from Luke''s genealogy.'),
(298, 'Addi', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 297, NULL, 'Son of Cosam, ancestor of Jesus in Luke 3:28.', 'Known only from Luke''s genealogy.'),
(299, 'Melchi, son of Addi', 'Melchi', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 298, NULL, 'Son of Addi, ancestor of Jesus in Luke 3:28. Pre-exilic Melchi, distinct from the post-exilic Melchi.', 'Known only from Luke''s genealogy. Luke 3:28.'),
(302, 'Joanan', 'Joannas', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 301, NULL, 'Son of Rhesa, ancestor of Jesus in Luke 3:27.', 'Known only from Luke''s genealogy.'),
(303, 'Joda', 'Judah', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 302, NULL, 'Son of Joanan, ancestor of Jesus in Luke 3:26.', 'Known only from Luke''s genealogy.'),
(304, 'Josech', 'Josec, Joseph', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 303, NULL, 'Son of Joda, ancestor of Jesus in Luke 3:26.', 'Known only from Luke''s genealogy.'),
(305, 'Semein', 'Semei', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 304, NULL, 'Son of Josech, ancestor of Jesus in Luke 3:26.', 'Known only from Luke''s genealogy.'),
(306, 'Mattathias, son of Semein', 'Mattathias', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 305, NULL, 'Son of Semein, ancestor of Jesus in Luke 3:26.', 'Known only from Luke''s genealogy. First of two Mattathias in Luke''s post-exilic line.'),
(307, 'Maath', NULL, NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 306, NULL, 'Son of Mattathias, ancestor of Jesus in Luke 3:26.', 'Known only from Luke''s genealogy.'),
(308, 'Naggai', 'Nagge', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 307, NULL, 'Son of Maath, ancestor of Jesus in Luke 3:25.', 'Known only from Luke''s genealogy.'),
(309, 'Esli', 'Hesli', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 308, NULL, 'Son of Naggai, ancestor of Jesus in Luke 3:25.', 'Known only from Luke''s genealogy.'),
(310, 'Nahum, son of Esli', 'Nahum, Naum', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 309, NULL, 'Son of Esli, ancestor of Jesus in Luke 3:25. Not the prophet Nahum.', 'Known only from Luke''s genealogy. Not to be confused with the prophet Nahum (Nah 1:1).'),
(311, 'Amos, son of Nahum', 'Amos', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 310, NULL, 'Son of Nahum, ancestor of Jesus in Luke 3:25. Not the prophet Amos.', 'Known only from Luke''s genealogy. Not to be confused with the prophet Amos (Amos 1:1).'),
(312, 'Mattathias, son of Amos', 'Mattathias', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 311, NULL, 'Son of Amos, ancestor of Jesus in Luke 3:25. Second Mattathias in Luke''s post-exilic line.', 'Known only from Luke''s genealogy. Luke 3:25.'),
(313, 'Joseph, son of Mattathias', 'Joseph', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 312, NULL, 'Son of Mattathias, ancestor of Jesus in Luke 3:24. Not Joseph of Nazareth.', 'Known only from Luke''s genealogy. One of several Josephs in the lineage.'),
(314, 'Jannai', 'Janna', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 313, NULL, 'Son of Joseph, ancestor of Jesus in Luke 3:24.', 'Known only from Luke''s genealogy.'),
(315, 'Melchi, son of Jannai', 'Melchi', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 314, NULL, 'Son of Jannai, ancestor of Jesus in Luke 3:24. Post-exilic Melchi, distinct from the pre-exilic Melchi.', 'Known only from Luke''s genealogy. Luke 3:24.'),
(316, 'Levi, son of Melchi', 'Levi', NULL, NULL, 1, 1, 'traditional', 'ancestor', 'minor', 'Judah', 315, NULL, 'Son of Melchi, ancestor of Jesus in Luke 3:24. Not the patriarch Levi son of Jacob.', 'Known only from Luke''s genealogy.'),
(570, 'Maacah, wife of Rehoboam', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Wife of King Rehoboam and mother of King Abijah of Judah. Scripture calls her Maachah or Michaiah and gives her father as Absalom (or Abishalom) in 1 Kings 15:2 and 2 Chronicles 11:20, but as Uriel of Gibeah in 2 Chronicles 13:2. Readers commonly explain this by "daughter" meaning granddaughter: Uriel her father, Absalom her grandfather through Tamar. The same name is later given to the "mother" of King Asa, whom Asa removed from being queen for making an idol; many take this to be Asa''s grandmother.', 'Birth and death are not recorded. Rehoboam''s wife and Abijah''s mother (2 Chr 11:20). Because her father is given differently in the sources, her father is not recorded in the table, and Asa''s mother_id is left empty for the same reason.'),
(571, 'Azubah, mother of Jehoshaphat', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Daughter of Shilhi and mother of King Jehoshaphat of Judah.', 'Birth and death are not recorded. Wife of Asa (Jehoshaphat''s father) and mother of Jehoshaphat, who was 35 when he began to reign (1 Kgs 22:42).'),
(572, 'Zibiah of Beer-sheba', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, mother of King Joash (Jehoash) of Judah. She came from Beer-sheba.', 'Birth and death are not recorded. Mother of Joash, who began to reign in the seventh year of Jehu (2 Kgs 12:1); her husband was Ahaziah of Judah.'),
(573, 'Jehoaddan of Jerusalem', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, mother of King Amaziah. She came from Jerusalem.', 'Birth and death are not recorded. Mother of Amaziah, who began to reign at 25 (2 Kgs 14:2); her husband was Joash of Judah.'),
(574, 'Jecholiah of Jerusalem', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, mother of King Uzziah (Azariah). She came from Jerusalem.', 'Birth and death are not recorded. Mother of Uzziah, who began to reign at 16 (2 Kgs 15:2); her husband was Amaziah.'),
(575, 'Jerusha, daughter of Zadok', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, mother of King Jotham. Her father is named Zadok; he is not identified with the priest Zadok of David''s time.', 'Birth and death are not recorded. Mother of Jotham, who began to reign at 25 (2 Kgs 15:33); her husband was Uzziah.'),
(576, 'Abi, mother of Hezekiah', 'Abijah', NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, daughter of Zachariah and mother of King Hezekiah. Second Chronicles gives her name as Abijah.', 'Birth and death are not recorded. Wife of Ahaz and mother of Hezekiah, whom Ussher dates to 752 BC (Annals §586; she is "the daughter of Zachariah" there, cf. 2 Chr 29:1). Hezekiah''s birth year in the table makes Ahaz only about 10 years older, a known difficulty in the figures of 2 Kgs 16:2 and 18:2.'),
(577, 'Hephzibah, mother of Manasseh', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah and mother of King Manasseh, who began to reign at 12. Her name means "my delight is in her."', 'Birth and death are not recorded. Wife of Hezekiah and mother of Manasseh (2 Kgs 21:1).'),
(578, 'Meshullemeth, daughter of Haruz', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, daughter of Haruz of Jotbah and mother of King Amon.', 'Birth and death are not recorded. Wife of Manasseh and mother of Amon, who began to reign at 22 (2 Kgs 21:19).'),
(579, 'Jedidah, daughter of Adaiah', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, daughter of Adaiah of Boscath and mother of King Josiah.', 'Birth and death are not recorded. Wife of Amon and mother of Josiah, who began to reign at eight (2 Kgs 22:1).'),
(580, 'Hamutal, daughter of Jeremiah of Libnah', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, mother of two kings, Jehoahaz and Zedekiah, both sons of Josiah. Her father Jeremiah of Libnah is not the prophet Jeremiah of Anathoth.', 'Birth and death are not recorded. Wife of Josiah; mother of Jehoahaz (2 Kgs 23:31) and of Zedekiah (2 Kgs 24:18).'),
(581, 'Zebudah, daughter of Pedaiah', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, daughter of Pedaiah of Rumah and mother of King Jehoiakim.', 'Birth and death are not recorded. Wife of Josiah and mother of Jehoiakim, who began to reign at 25 (2 Kgs 23:36).'),
(582, 'Nehushta, daughter of Elnathan', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Queen mother of Judah, daughter of Elnathan of Jerusalem and mother of King Jehoiachin. She went into exile in Babylon with her son.', 'Birth and death are not recorded. Wife of Jehoiakim and mother of Jehoiachin, who began to reign at 18 (2 Kgs 24:8; the exile of the queen mother is in 2 Kgs 24:12-15).'),
(583, 'Shaphat, father of Elisha', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of the prophet Elisha, who came from Abel-meholah. Elijah was told to anoint Elisha "the son of Shaphat".', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(584, 'Amoz, father of Isaiah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of the prophet Isaiah. He is named in the opening of Isaiah and in the Kings account of Hezekiah. He is a different name in Hebrew from the prophet Amos.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(587, 'Wife of Isaiah (the prophetess)', NULL, NULL, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Called "the prophetess" in Isaiah 8:3, she bore Isaiah the son named Maher-shalal-hash-baz. Her own name is not given.', 'Not recorded. The text does not give her name or dates.'),
(588, 'Hilkiah, father of Jeremiah', NULL, NULL, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'A priest of Anathoth in the land of Benjamin and father of the prophet Jeremiah. The text does not say he is the same man as Hilkiah the high priest who found the Book of the Law under Josiah, so the two are kept separate here.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(589, 'Buzi', NULL, NULL, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'Father of the prophet Ezekiel. Ezekiel is called a priest, so Buzi was presumably of a priestly family, though the text does not say so of Buzi himself.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(590, 'Amittai', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of the prophet Jonah, who came from Gath-hepher.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(591, 'Beeri, father of Hosea', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of the prophet Hosea.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(592, 'Gomer, wife of Hosea', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Daughter of Diblaim, whom Hosea married at the Lord''s command as a living picture of Israel''s unfaithfulness. She bore Jezreel and, according to the following verses, Lo-ruhamah and Lo-ammi.', 'Not recorded. She was the wife of Hosea (about 805-720 BC), so was alive in the time of Jeroboam II.'),
(593, 'Diblaim', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Gomer, the wife of the prophet Hosea.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(597, 'Pethuel', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of the prophet Joel.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(598, 'Hizkiah, ancestor of Zephaniah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Great-great-grandfather of the prophet Zephaniah, who traces his line in Zephaniah 1:1 four generations back to Hizkiah. Naming so many generations is unusual and has led many to think Hizkiah is King Hezekiah, but the text does not call him king, so this table keeps him as a separate person. Whether the two are the same is uncertain.', 'Not recorded. Not linked to King Hezekiah: the identification is likely to some readers but the text does not make it, and Zephaniah''s four-generation line would fit either way.'),
(599, 'Amariah, grandfather of Zephaniahs father', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 598, NULL, 'Son of Hizkiah, father of Gedaliah, and an ancestor of the prophet Zephaniah.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(600, 'Gedaliah, grandfather of Zephaniah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 599, NULL, 'Son of Amariah, father of Cushi, and grandfather of the prophet Zephaniah. He is not the Gedaliah who was made governor of Judah after the fall of Jerusalem.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(601, 'Cushi, father of Zephaniah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 600, NULL, 'Son of Gedaliah and father of the prophet Zephaniah.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(602, 'Iddo, grandfather of Zechariah', NULL, NULL, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Called "Iddo the prophet" in Zechariah 1:1, grandfather of the prophet Zechariah. Ezra 5:1 and 6:14 call Zechariah "the son of Iddo," as the line is shortened. A priestly family of Iddo came back with Zerubbabel (Neh 12:4, 16), and Zechariah is named as its head, but the text does not state that this Iddo is the same.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(603, 'Berechiah, father of Zechariah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 602, NULL, 'Son of Iddo and father of the prophet Zechariah. Ezra 5:1 names only Iddo as Zechariah''s father, which is usually explained as the line being shortened.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(604, 'Seraiah, ancestor of Ezra', NULL, NULL, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'First name in the line of Ezra the scribe in Ezra 7:1, which runs back through Azariah, Hilkiah, Shallum and Zadok to Phinehas and Aaron the chief priest. The list is abridged (compare 1 Chronicles 6:3-15), and "son of" in it means descendant. Most readers identify this Seraiah with Seraiah the chief priest killed at Riblah in 588 BC (2 Kings 25:18; 1 Chronicles 6:14), who is Ezra''s ancestor, not his father. Ezra''s own father is not named, so no parent link is recorded for Ezra.', 'Not recorded. If he is the Seraiah of 2 Kgs 25:18 he was killed in 588 BC, about 90 years before Ezra''s birth in this table, so "son of" in Ezra 7:1 means descendant. The rest of the line is not added as separate rows.'),
(605, 'Hacaliah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Nehemiah the governor, named in the opening of the book of Nehemiah.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(606, 'Hanani, brother of Nehemiah', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Nehemiah''s brother who came to Susa with men from Judah and told him of the broken walls of Jerusalem. Nehemiah later put him in charge of Jerusalem with Hananiah the ruler of the palace. "Brother" may mean close kinsman.', 'Not recorded. He was a contemporary of Nehemiah (about 470-400 BC) and was alive at the time of the walls in 445 BC.'),
(607, 'Abihail', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', NULL, NULL, 'Father of Esther and uncle of Mordecai, who brought Esther up as his own daughter after both her parents died.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(608, 'Jair, father of Mordecai', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', 609, NULL, 'Son of Shimei and father of Mordecai, a Benjamite of Susa. This is not the judge Jair.', 'Not recorded. Esther 2:5-6 is unclear whether it is Mordecai or his ancestor Kish who was carried away with Jeconiah in 599 BC, and the line may be abridged.'),
(609, 'Shimei, grandfather of Mordecai', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', 610, NULL, 'Son of Kish and grandfather of Mordecai. He is not identified with Shimei son of Gera, who cursed David; the text does not link them.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(610, 'Kish, ancestor of Mordecai', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Benjamin', NULL, NULL, 'A Benjamite named at the head of Mordecai''s line in Esther 2:5. He is not identified with Kish, the father of King Saul, though both were Benjamites.', 'Not recorded. The text may be telescoping the line.'),
(611, 'Hammedatha the Agagite', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Haman the Agagite, who rose high under King Ahasuerus and plotted to destroy the Jews.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(612, 'Zeresh', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Wife of Haman, who with his friends advised him to build the high gallows for Mordecai and later told him he would fall before the Jews.', 'Not recorded. She was Haman''s wife, so lived about 510-473 BC.'),
(613, 'Ahijah, father of Baasha', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', 'Issachar', NULL, NULL, 'Father of Baasha, the king of Israel who killed Nadab, of the house of Issachar. He is not the prophet Ahijah of Shiloh.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(614, 'Jehoshaphat, father of Jehu', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, 615, NULL, 'Son of Nimshi and father of Jehu, king of Israel. He is not King Jehoshaphat of Judah. In 1 Kings 19:16 Jehu is called "son of Nimshi," meaning grandson.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(615, 'Nimshi', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Jehoshaphat and grandfather of Jehu, who is called "the son of Nimshi" in 1 Kings 19:16 and 2 Kings 9:20.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(616, 'Jabesh, father of Shallum', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Shallum, who killed Zechariah and reigned one month as king of Israel.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(617, 'Gadi, father of Menahem', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Menahem, who killed Shallum and became king of Israel.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(618, 'Remaliah', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Pekah, the army captain who killed Pekahiah and became king of Israel. Isaiah 7:4-9 uses "Remaliah''s son" to mean Pekah.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(619, 'Elah, father of Hoshea', NULL, NULL, NULL, 1, 1, 'possible', 'ancestor', 'minor', NULL, NULL, NULL, 'Father of Hoshea, the last king of Israel. He is not Elah the son of Baasha, who had been king earlier.', 'Not recorded. The father is named in the text; no dates are recorded for him.'),
(620, 'Jehoiada the priest', NULL, NULL, NULL, 1, 1, 'possible', 'priest', 'minor', 'Levi', NULL, NULL, 'High priest in Jerusalem who, with his wife Jehosheba, hid the infant Joash from Athaliah, then crowned him king at age seven and guided him while Jehoiada lived. He died at 130 and was buried among the kings.', 'Not recorded as a year. He lived 130 years (2 Chr 24:15) and anointed Joash in about 878 BC, when Joash was seven.'),
(621, 'Jehosheba', 'Jehoshabeath', NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, 88, NULL, 'Daughter of King Jehoram of Judah, sister of Ahaziah and wife of Jehoiada the priest. When Athaliah killed the royal family she hid the infant Joash in the temple for six years. Second Chronicles calls her Jehoshabeath.', 'Not recorded. Her mother is not named in the text and is not recorded here.'),
(622, 'Ethbaal', 'Ithobaal', NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'King of the Zidonians, whose daughter Jezebel married Ahab of Israel and brought the worship of Baal into the northern kingdom. Outside sources know him as Ithobaal I of Tyre and Sidon.', 'Not recorded. His reign is placed around 887-856 BC by Tyrian king lists, which do not line up exactly with the dates here for Jezebel and Ahab, so no year is given.'),
(623, 'Ben-hadad, son of Hazael', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, 212, NULL, 'King of Syria who succeeded his father Hazael and continued to oppress Israel under Jehoahaz, until Joash of Israel won three victories over him. Outside sources call him Ben-hadad III.', 'Not recorded as a year. He succeeded Hazael (2 Kgs 13:24). Ussher (Annals Sec. 546) has him defeated three times, as Elisha foretold (2 Kgs 13:25), by Jehoash of Israel and his viceroy Jeroboam II, by about 836 BC.'),
(624, 'Nabopolassar', NULL, NULL, -605, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Founder of the Neo-Babylonian dynasty, who threw off Assyrian rule and, with the Medes, destroyed Nineveh. Father of Nebuchadnezzar II. He is not named in Scripture.', 'Ussher, Annals §739, 781: general under the Assyrian king, took Nineveh with Astyages in 626 BC and died in 605 BC after 21 years, while his son Nebuchadnezzar was pursuing Necho. Not named in Scripture. Mainstream: reigned 626-605 BC, with Nineveh falling in 612. Birth unknown.'),
(625, 'Evil-merodach', 'Amel-Marduk', NULL, -560, 1, 0, 'probable', 'ruler', 'minor', NULL, 214, NULL, 'Son of Nebuchadnezzar and king of Babylon, who in the first year of his reign released King Jehoiachin from prison and gave him a seat above the other kings. He is the Amel-Marduk of Babylonian records.', 'Scripture: the year he began to reign is the 37th of Jehoiachin''s captivity (2 Kgs 25:27; Jer 52:31). Ussher, Annals §890-891, 899: began 562 BC on Nebuchadnezzar''s death and was murdered by his brother-in-law Neriglissar about 560 BC, after little more than two years. Mainstream: reigned 562-560 BC.'),
(626, 'Nabonidus', NULL, NULL, NULL, 1, 1, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Last king of Babylon, who spent years at Tema in Arabia and left his son Belshazzar in charge in Babylon. He is not named in Daniel, but Belshazzar''s offer of "the third ruler in the kingdom" (Dan 5:16, 29) is commonly explained by Nabonidus holding the first place and Belshazzar the second.', 'Not named in Scripture. Ussher, Annals §912, 932-933, 938, identifies him with Belshazzar (the Nabonidus or Labynitus of Berosus and Herodotus), reigning 17 years, 555-538 BC. Mainstream: Nabonidus reigned 556-539 BC and Belshazzar was his coregent son. His fate after Cyrus took Babylon is told differently in the sources, so no death year is given.'),
(627, 'Sargon II', NULL, NULL, -705, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'King of Assyria who completed the conquest of Samaria and sent his commander against Ashdod. Father of Sennacherib.', 'Standard historical record (not stated in Scripture). Reigned 722-705 BC and was killed in battle in 705 BC. Birth unknown. Named once, in Isaiah 20:1.'),
(628, 'Esarhaddon', NULL, NULL, -669, 1, 0, 'probable', 'ruler', 'minor', NULL, 213, NULL, 'King of Assyria, son and successor of Sennacherib after Sennacherib''s sons killed him. The settlers brought into Samaria in the northern kingdom are said to have been brought by him.', 'Standard historical record (not stated in Scripture). Reigned 681-669 BC and died in 669 BC on campaign. Birth unknown.'),
(629, 'Cambyses I', NULL, NULL, -559, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'King of Anshan in Persia and father of Cyrus the Great. He is not named in Scripture.', 'Standard historical record (not stated in Scripture). Reigned about 600-559 BC. Dates are uncertain; death year is approximate. Not named in Scripture.'),
(630, 'Cambyses II', NULL, NULL, -522, 1, 0, 'probable', 'ruler', 'minor', NULL, 216, NULL, 'Son and successor of Cyrus the Great, who conquered Egypt in 525 BC. He is not named in Scripture; the Persian reign between Cyrus and Darius is passed over in Ezra 4:5.', 'Standard historical record (not stated in Scripture). Reigned 530-522 BC and died in 522 BC. Birth unknown.'),
(631, 'Hystaspes', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'Persian noble, called Vishtaspa in Persian, and father of Darius I. He served as a governor and was not king himself. Not named in Scripture.', 'Standard historical record (not stated in Scripture). Dates unknown.'),
(632, 'Atossa', NULL, NULL, NULL, 1, 1, 'possible', 'queen', 'minor', NULL, NULL, NULL, 'Persian queen, daughter of Cyrus the Great, who married Darius I and bore Xerxes. Not named in Scripture.', 'Standard historical record (not stated in Scripture). Dates unknown. Mother of Xerxes according to Herodotus.'),
(635, 'Mattathias', NULL, NULL, -166, 1, 0, 'probable', 'priest', 'minor', 'Levi', NULL, NULL, 'Priest of Modein who started the Maccabean revolt by refusing to sacrifice to the king''s idols. Father of five sons, including Judas Maccabeus, Jonathan and Simon.', 'Not in the KJV Bible; known from 1 Maccabees (accepted by Catholic and Orthodox traditions) and Josephus. He died in 166 BC soon after beginning the revolt. Birth unknown.'),
(636, 'Simon Maccabeus', 'Simon Thassi', NULL, -135, 1, 0, 'probable', 'ruler', 'minor', 'Levi', 635, NULL, 'Second son of Mattathias, who succeeded Jonathan as leader and high priest and made Judea independent. He was murdered at a banquet in 135 BC.', 'Not in the KJV Bible; known from 1 Maccabees (accepted by Catholic and Orthodox traditions) and Josephus. Died 135 BC. Birth unknown.'),
(637, 'Jonathan Maccabeus', 'Jonathan Apphus', NULL, -143, 1, 0, 'probable', 'ruler', 'minor', 'Levi', 635, NULL, 'Youngest son of Mattathias, who led after Judas died, became high priest in 152 BC and was killed by treachery in 143 BC.', 'Not in the KJV Bible; known from 1 Maccabees (accepted by Catholic and Orthodox traditions) and Josephus. Died 143 BC. Birth unknown.'),
(638, 'John Hyrcanus', 'Hyrcanus I', NULL, -108, 1, 0, 'probable', 'ruler', 'minor', 'Levi', 636, NULL, 'Son of Simon Maccabeus, high priest and ruler of Judea from 134 to 104 BC, who expanded the Hasmonean state.', 'Not in the KJV Bible; known from 1 Maccabees (accepted by Catholic and Orthodox traditions) and Josephus. Ussher, Annals §3843: died in 108 BC after 29 years as high priest. Standard dating gives his reign as 134-104 BC. Birth unknown.'),
(757, 'Alopen', 'Aluoben', NULL, NULL, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Syriac Christian missionary of the Church of the East who reached the Tang capital Chang''an in 635. The Xi''an stele of 781 records that he was received by the emperor and allowed to translate and teach the scriptures.', 'Birth and death dates are unknown. 635 is the arrival date given on the Xi''an stele.'),
(761, 'Colman of Lindisfarne', 'Colmán', NULL, 676, 1, 1, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Irish-trained bishop of Lindisfarne who defended the Ionan (Irish) Easter reckoning at Whitby. When the synod ruled against it he left Northumbria with his followers.', 'Birth year unknown. He became bishop in 661 and died in 676.'),
(769, 'Rastislav of Moravia', 'Rostislav', NULL, 870, 1, 1, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Prince of Great Moravia, who around 862 asked the Byzantine emperor for teachers able to instruct his people in their own language. Cyril and Methodius were sent in response.', 'Birth unknown. He reigned from about 846 and was deposed and blinded about 870.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(784, 'Muhammed edh-Dhib', 'Muhammad edh-Dhib', NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Young Bedouin shepherd of the Ta''amireh tribe who found the first scrolls in a cave near Qumran. The find is dated to 1946 or 1947.', 'Birth and death dates are not known. The date of discovery is given variously as late 1946 or early 1947.'),
(800, 'Augustine of Canterbury', NULL, NULL, 604, 1, 1, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Roman monk sent by Pope Gregory the Great in 597 to bring Christianity to the Anglo-Saxons of Kent. He became the first Archbishop of Canterbury. He is not the same person as Augustine of Hippo.', 'Birth year unknown. Died 26 May in 604 or 605; 604 is the usual date.'),
(821, 'Sheshbazzar', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Judah', NULL, NULL, '"Prince of Judah" to whom Cyrus entrusted the Temple vessels, and the first governor of the return, who laid the foundation of the house of God. Some identify him with Zerubbabel, others with Shenazar, an uncle of Zerubbabel (1 Chr 3:18); the text does not say.', 'Scripture gives no dates. He led the return of 536 BC (Ezra 1:8-11; 5:14-16).'),
(850, 'Shishak', 'Shoshenq I, Sefonchis', NULL, NULL, 1, 1, 'probable', 'ruler', 'moderate', NULL, NULL, NULL, 'King of Egypt who gave refuge to Jeroboam when Solomon sought his life (1 Kgs 11:40) and in the fifth year of Rehoboam came up against Jerusalem with 1,200 chariots and 60,000 horsemen, taking the treasures of the temple and the palace (1 Kgs 14:25-26; 2 Chr 12:2-9).', 'Birth and death not recorded. Scripture: invaded in Rehoboam''s 5th year (1 Kgs 14:25), 971 BC on Ussher''s chain. Ussher, Annals Sec. 474, 485: began to reign 978 BC. Mainstream: Pharaoh Shoshenq I, Karnak list, campaign c. 925 BC.'),
(851, 'Ben-hadad, son of Tabrimon', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'King of Syria at Damascus, son of Tabrimon, son of Hezion. Asa of Judah sent him the temple and palace silver to break his league with Baasha; he struck Ijon, Dan, Abel-beth-maachah and all Naphtali, and Baasha stopped building Ramah (1 Kgs 15:16-22; 2 Chr 16:1-6).', 'Birth and death not recorded. Ussher, Annals Sec. 496-497: the league with Asa falls in 940 BC (Asa''s 16th year; the ''36th year'' of 2 Chr 16:1 is counted from the division of the kingdom). Ussher leaves open whether this is the same king as Ahab''s Ben-hadad; the dataset keeps two rows.'),
(852, 'Ben-hadad, king of Aram in Ahab''s day', NULL, NULL, -885, 1, 1, 'possible', 'ruler', 'moderate', NULL, NULL, NULL, 'King of Aram who besieged Samaria with thirty-two kings and was beaten twice by Ahab, who then let him go under a covenant (1 Kgs 20). Later, sick, he sent Hazael to ask Elisha whether he would recover; Hazael smothered him and reigned in his place (2 Kgs 8:7-15).', 'Birth not recorded. Ussher, Annals Sec. 512-513: wars with Ahab from 900 BC. Death c. 885 BC is an estimate: Hazael is already king at Ramoth-gilead in 884 (Sec. 533).'),
(853, 'Mesha, king of Moab', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'King of Moab, a sheep-breeder who paid Israel a tribute of 100,000 lambs and the wool of 100,000 rams until Ahab died, then rebelled. Jehoram of Israel, Jehoshaphat and Edom invaded; besieged in Kir-hareseth, Mesha took his eldest son, who should have reigned after him, and offered him as a burnt offering on the wall (2 Kgs 3:4-27).', 'Birth and death not recorded. Ussher, Annals Sec. 524: the campaign falls in 895 BC, Jehoram of Israel''s 2nd year. Ussher (Sec. 524) reads the victim as the son of the king of Edom; Scripture says his own eldest son (2 Kgs 3:27), which is followed here. The Moabite Stone (Mesha Stele) names Omri and Mesha; mainstream dates c. 850 BC.'),
(854, 'Zerah the Ethiopian', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'Commander or king of a vast Cushite army, a million men and three hundred chariots, who came against Judah at Mareshah and was routed by Asa after he cried to the Lord (2 Chr 14:9-15).', 'Birth and death not recorded. Scripture places the invasion after ten years of quiet in Asa''s reign (2 Chr 14:1) and before the covenant of Asa''s 15th year, 941 BC (15:10-11). Ussher (Annals Sec. 494) sets it in the early part of that span; the year is not fixed.'),
(855, 'Shalmaneser', 'Shalmaneser V, Shalman', NULL, -722, 1, 0, 'probable', 'ruler', 'moderate', NULL, NULL, NULL, 'King of Assyria who came up against Hoshea, made him a tributary, and shut him up in prison when he sent to So of Egypt. He besieged Samaria three years and took it in the sixth year of Hezekiah, which was the ninth of Hoshea (2 Kgs 17:3-6; 18:9-10).', 'Modern history: reigned 727-722 BC. Scripture names him as the king who came up against Hoshea and besieged Samaria (2 Kgs 17:3-6; 18:9-10). Ussher (Annals 640) has him die in 717 BC and makes him the father of Sennacherib; on the modern account Sennacherib''s father is Sargon II.'),
(902, 'Ephron the Hittite', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Hittite', NULL, NULL, 'Hittite son of Zohar who dwelt among the children of Heth at Hebron. He sold Abraham the field and cave of Machpelah, for four hundred shekels of silver, as a burying place for Sarah.', 'No dates in Scripture. He was a living landowner at the death of Sarah in 1859 BC (Gen 23); nothing supports a birth or death year.'),
(912, 'Sihon', NULL, NULL, -1452, 1, 1, 'probable', 'king', 'minor', 'Amorite', NULL, NULL, 'Amorite king of Heshbon. He refused Israel passage through his land, fought them at Jahaz, and was defeated; Israel took his land from the Arnon to the Jabbok.', 'Death year from Ussher (Annals, 1452 BC), who places the defeat of Sihon in the fortieth year of the wandering (Num 21:21-31; Deut 2:24-36). No birth is recorded.'),
(913, 'Og', NULL, NULL, -1452, 1, 1, 'probable', 'king', 'minor', 'Amorite', NULL, NULL, 'King of Bashan, the last of the remnant of the Rephaim (giants), known for his iron bedstead nine cubits long. He fought Israel at Edrei and he, his sons and his people were destroyed.', 'Death year from Ussher (Annals, 1452 BC), who places the defeat of Og just after that of Sihon (Num 21:33-35; Deut 3:1-11). No birth is recorded.'),
(914, 'Eglon', NULL, NULL, -1325, 1, 1, 'probable', 'king', 'minor', 'Moab', NULL, NULL, 'King of Moab, very fat, whom the LORD strengthened against Israel for eighteen years. He allied with Ammon and Amalek, took Jericho, and was killed in his cool upper room by Ehud.', 'Death year from Ussher (Annals, about 1325 BC), who dates the eighteen years of oppression (Judg 3:14) to 1343-1325 BC. No birth is recorded.'),
(915, 'Jabin, king of Hazor in Deborah''s day', 'Jabin king of Canaan', NULL, -1285, 1, 1, 'probable', 'king', 'minor', 'Canaanite', NULL, NULL, 'Canaanite king who reigned at Hazor, with nine hundred iron chariots, and oppressed Israel for twenty years. His army commander was Sisera. Barak and Deborah defeated his forces, and Israel in time destroyed him. A different Jabin of Hazor is named in Joshua 11.', 'Oppression began about 1305 BC and ended with the victory of Deborah and Barak in 1285 BC (Judg 4:1-3, 24; Ussher, Annals). Death placed at that year as a rough date for the end of his reign. No birth is recorded.'),
(916, 'Zebah', NULL, NULL, -1245, 1, 1, 'probable', 'king', 'minor', 'Midian', NULL, NULL, 'One of the two kings of Midian, with Zalmunna, who fled with fifteen thousand men after Gideon''s victory. Gideon pursued and captured them and killed them himself, because they had killed his brothers at Tabor.', 'Died after the defeat of Midian, about 1245 BC (Judg 8:21; Ussher, Annals). No birth is recorded.'),
(917, 'Zalmunna', NULL, NULL, -1245, 1, 1, 'probable', 'king', 'minor', 'Midian', NULL, NULL, 'One of the two kings of Midian, with Zebah. Captured by Gideon at Karkor and put to death after he admitted they had killed Gideon''s brothers.', 'Died after the defeat of Midian, about 1245 BC (Judg 8:21; Ussher, Annals). No birth is recorded.'),
(918, 'Oreb', NULL, NULL, -1245, 1, 1, 'probable', 'ruler', 'minor', 'Midian', NULL, NULL, 'One of two Midianite princes, with Zeeb, taken by the men of Ephraim after Gideon''s victory. He was killed at the rock that bears his name.', 'Killed in the pursuit after Gideon''s victory, about 1245 BC (Judg 7:25; Ussher, Annals). No birth is recorded.'),
(919, 'Zeeb', NULL, NULL, -1245, 1, 1, 'probable', 'ruler', 'minor', 'Midian', NULL, NULL, 'One of two Midianite princes, with Oreb, taken by the men of Ephraim. He was killed at the winepress that bears his name, and the two heads were brought to Gideon beyond the Jordan.', 'Killed in the pursuit after Gideon''s victory, about 1245 BC (Judg 7:25; Ussher, Annals). No birth is recorded.'),
(930, 'Goliath of Gath', NULL, NULL, -1063, 1, 1, 'probable', 'warrior', 'moderate', NULL, NULL, NULL, 'Philistine champion from Gath, over six cubits tall, who defied the armies of Israel for forty days until the young David killed him with a sling and a stone. His sword was later kept at Nob behind the ephod.', 'Birth not recorded. Died in the valley of Elah when David was a youth, 1063 BC on this timeline (the date of the event row). Elsewhere a brother of Goliath is killed in battle (2 Sam 21:19; 1 Chr 20:5), so he was one of a family of giants from Gath.'),
(931, 'Agag king of Amalek', NULL, NULL, -1079, 1, 1, 'probable', 'king', 'minor', NULL, NULL, NULL, 'King of the Amalekites whom Saul took alive when he was commanded to destroy Amalek. Samuel had him put to death at Gilgal, and Saul''s sparing of him led to Saul''s rejection as king.', 'Birth not recorded. Died at Gilgal after the Amalekite campaign, 1079 BC on this timeline (the date of the event row). Haman, called an Agagite in Esther, is often thought to descend from Agag''s line, but the text does not say so.'),
(934, 'Doeg the Edomite', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Edomite, the chief of Saul''s herdsmen, who was at Nob when David received bread and Goliath''s sword and told Saul about it. When Saul''s guards would not strike the priests, Doeg killed eighty-five of them and destroyed the city of Nob.', 'Birth and death not recorded. Active around 1060 BC, when David fled from Saul. Psalm 52 is titled as written about Doeg.'),
(940, 'Uzzah', NULL, NULL, -1045, 1, 1, 'probable', 'other', 'minor', NULL, NULL, NULL, 'Son of Abinadab, who drove the new cart that carried the ark from his father''s house toward Jerusalem. When the oxen stumbled he steadied the ark with his hand, and God struck him dead there; the place was named Perez-uzzah.', 'Birth not recorded. Died 1045 BC on this timeline, the date of the ark''s first attempted move (2 Sam 6).'),
(945, 'Ittai the Gittite', NULL, NULL, NULL, 1, 1, 'possible', 'warrior', 'minor', NULL, NULL, NULL, 'Soldier from Gath who had joined David only recently with six hundred men. When David urged him to turn back during Absalom''s revolt, he swore to follow the king in life or death, and David gave him command of a third of the army at the battle in the forest of Ephraim.', 'Birth and death not recorded. Active in 1023 BC (2 Sam 15:19-22; 18:2).'),
(946, 'Sheba son of Bichri', NULL, NULL, -1023, 1, 1, 'probable', 'other', 'minor', 'Benjamin', NULL, NULL, 'Benjamite troublemaker who blew a trumpet after Absalom''s revolt and called Israel to leave David. Joab chased him to Abel of Beth-maachah, where the townspeople cut off his head and threw it to Joab, ending the rising.', 'Birth not recorded. Died in 1023 BC on this timeline, as the rising followed David''s return directly (2 Sam 20; Ussher).'),
(947, 'Ziba servant of Saul', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Servant of Saul''s house who told David about Mephibosheth, Jonathan''s son, and was set to farm his land with his fifteen sons and twenty servants. When David fled Absalom he brought supplies and accused Mephibosheth of treason; Mephibosheth later denied it, and David divided the land between them.', 'Birth and death not recorded. Active from about 1048 BC, when Mephibosheth is summoned (2 Sam 9), to 1023 BC.'),
(949, 'Araunah the Jebusite', 'Ornan', NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Jebusite who owned the threshing-floor at Jerusalem where the angel stopped the plague. He offered it to David free, but David paid for it and built an altar there. Chronicles calls him Ornan and says Solomon later built the Temple on that site.', 'Birth and death not recorded. Active at the time of David''s census, 1017 BC (Ussher, 2 Sam 24). The name is spelled Araunah in Samuel and Ornan in Chronicles; they are the same man.'),
(950, 'Shemaiah the prophet', NULL, NULL, NULL, 1, 1, 'possible', 'prophet', 'minor', NULL, NULL, NULL, 'Prophet in the reign of Rehoboam. He told Rehoboam not to fight the northern tribes after the kingdom split, and later told the princes of Judah that Shishak''s invasion was judgement, whereupon they humbled themselves. Chronicles says he wrote an account of Rehoboam''s acts.', 'Birth and death not recorded. Active from 975 BC (Ussher) through Shishak''s invasion in 971 BC (2 Chr 12:5).'),
(995, 'Shecaniah, son of Jehiel', 'Shechaniah', NULL, NULL, 0, 0, 'possible', 'other', 'minor', 'Judah', NULL, NULL, 'Man of the sons of Elam who spoke for the people when Ezra wept over marriages to foreign wives. He proposed a covenant to put them away and urged Ezra to act.', 'Not recorded. He spoke to Ezra in 457 BC (Ezra 10:2-4).'),
(1020, 'Quirinius, governor of Syria', 'Cyrenius, Publius Sulpicius Quirinius', NULL, 21, 1, 0, 'probable', 'ruler', 'minor', 'Roman', NULL, NULL, 'Roman senator and consul named by Luke as governor of Syria when the first census under Augustus was taken. Luke calls him Cyrenius, the Greek form of his name.', 'Death in AD 21 is from Roman historians (Tacitus). Birth unknown. Luke 2:2 ties him to the census near the birth of Jesus; how that fits his known governorship of AD 6 is debated, and Ussher places the first taxing in 5 BC.'),
(1021, 'Lysanias, tetrarch of Abilene', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Roman', NULL, NULL, 'Ruler of Abilene, a district north-west of Damascus, named by Luke among the rulers in the fifteenth year of Tiberius.', 'No dates are known. Luke 3:1 places him in the setting of the start of John the Baptist''s ministry (about AD 27). Scholars debate whether he is the same as an earlier Lysanias.'),
(1022, 'Joanna, wife of Chuza', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'Follower of Jesus who helped support his ministry from her own means. She was married to Chuza, steward of Herod Antipas, and is named among the women who brought word of the empty tomb.', 'No dates are known; she was alive in AD 30-33.'),
(1023, 'Chuza, Herod''s steward', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Steward of Herod Antipas and husband of Joanna, one of the women who followed Jesus. Luke gives only his name and office.', 'No dates are known; he was in Herod''s service during Jesus'' ministry (about AD 28-33).'),
(1024, 'Bartimaeus, son of Timaeus', 'Bartimeus', NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'Blind beggar who sat by the road outside Jericho and cried out to Jesus as Son of David. Jesus restored his sight and he followed him on the way.', 'No dates are known; the healing is placed in AD 33 with the events of Jesus'' last journey to Jerusalem. KJV spells his name Bartimeus.'),
(1025, 'Malchus, the high priest''s servant', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Servant of the high priest whose right ear Peter cut off in Gethsemane. Luke records that Jesus touched the ear and healed it.', 'No dates are known; he was alive at the arrest of Jesus in AD 33.'),
(1026, 'Alexander, son of Simon of Cyrene', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', 239, NULL, 'Named by Mark as one of the two sons of Simon of Cyrene, the man made to carry the cross of Jesus. Mark mentions him as someone known to his first readers.', 'No dates are known. A son of Simon of Cyrene (born about 10 BC) would have been born well after AD 1.'),
(1027, 'Rufus, son of Simon of Cyrene', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', 239, NULL, 'Named by Mark as the other son of Simon of Cyrene. Some readers suggest he is the Rufus greeted in Romans 16:13, but the text does not say so.', 'No dates are known.'),
(1028, 'Theophilus', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'The person to whom Luke addressed both his Gospel and the Book of Acts, called most excellent. Scripture does not say who he was; his name means friend of God.', 'No dates are known. He is placed with the writing of Luke and Acts.'),
(1029, 'Joseph Barsabas, called Justus', 'Joseph Barsabbas, Justus', NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'One of the two men put forward to replace Judas among the apostles. The lot fell to Matthias instead. Acts says he had been with the disciples from the baptism of John.', 'No dates are known; he was alive at the choosing of Matthias in AD 33.'),
(1030, 'Simon the sorcerer', 'Simon Magus', NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Samaritan', NULL, NULL, 'Sorcerer of Samaria whom the people called the great power of God. He believed and was baptized under Philip, then tried to buy the power to give the Holy Spirit and was rebuked by Peter. Later stories about him come from tradition, not Scripture.', 'No dates are known; he appears in Samaria in AD 34.'),
(1031, 'Aeneas of Lydda', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Paralysed man at Lydda who had been bedridden for eight years. Peter said that Jesus Christ made him whole, and he rose at once. Many in Lydda and Sharon turned to the Lord.', 'No dates are known. The healing came shortly before the raising of Tabitha (AD 38).'),
(1032, 'Simon the tanner of Joppa', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Tanner at Joppa whose house by the sea hosted Peter for many days. Cornelius''s messengers found Peter there.', 'No dates are known; he was in Joppa about AD 38-40.'),
(1033, 'Elymas the sorcerer', 'Bar-Jesus', NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Jewish sorcerer and false prophet at the court of Sergius Paulus on Cyprus. He opposed Barnabas and Saul and was struck blind for a time at Paul''s word.', 'No dates are known; he appears on Cyprus in AD 45.'),
(1034, 'Sergius Paulus', 'Sergius Paulus the proconsul', NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Roman', NULL, NULL, 'Roman proconsul of Cyprus, called a prudent man. He sent for Barnabas and Saul to hear the word of God and believed after seeing Elymas struck blind.', 'No dates are known; he held office on Cyprus in AD 45.'),
(1035, 'Jason of Thessalonica', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'Believer in Thessalonica who received Paul and Silas into his house. A mob attacked his house and dragged him before the city rulers.', 'No dates are known; he appears in AD 53.'),
(1036, 'Dionysius the Areopagite', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Greek', NULL, NULL, 'Member of the Areopagus council at Athens who believed after Paul''s speech. Later church stories make him a bishop of Athens; Scripture says only that he believed.', 'No dates are known; he appears in AD 54.'),
(1037, 'Damaris', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Greek', NULL, NULL, 'Woman of Athens named by Luke among those who believed after Paul spoke on the Areopagus.', 'No dates are known; she appears in AD 54.'),
(1038, 'Crispus, ruler of the synagogue at Corinth', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'Chief ruler of the synagogue at Corinth who believed on the Lord with all his household and was baptized.', 'No dates are known; he appears in AD 54-55.'),
(1039, 'Sosthenes, ruler of the synagogue at Corinth', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Jewish', NULL, NULL, 'Chief ruler of the synagogue at Corinth who was beaten before Gallio''s judgment seat. Some suppose he is the Sosthenes who joins Paul in greeting the Corinthians, but Acts does not say so.', 'No dates are known; he appears in AD 54-55.'),
(1040, 'Gallio, proconsul of Achaia', 'Lucius Junius Gallio Annaeanus', NULL, 65, 1, 0, 'probable', 'ruler', 'minor', 'Roman', NULL, NULL, 'Roman proconsul of Achaia who dismissed the Jewish charges against Paul at Corinth and cared for none of the beating of Sosthenes. He was the brother of the philosopher Seneca.', 'Death in AD 65 follows Roman historians, after Nero''s suspicion of Seneca''s family. Ussher places his proconsulship in AD 54. Birth unknown.'),
(1041, 'Demetrius the silversmith', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', 'Greek', NULL, NULL, 'Silversmith of Ephesus who made silver shrines of Diana. He roused the craftsmen against Paul because the new faith threatened their trade, and the city fell into an uproar.', 'No dates are known; he appears in AD 57.'),
(1042, 'Eutychus', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Greek', NULL, NULL, 'Young man at Troas who fell asleep in a window during Paul''s long preaching and fell from the third loft. Paul embraced him, and he was taken away alive.', 'No dates are known; the event falls on Paul''s third journey, about AD 59-60.'),
(1043, 'Mnason of Cyprus', NULL, NULL, NULL, 1, 1, 'possible', 'disciple', 'minor', 'Jewish', NULL, NULL, 'Early disciple from Cyprus with whom Paul and his companions were to lodge on the way to Jerusalem.', 'No dates are known; he appears in AD 60.'),
(1044, 'Claudius Lysias', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Roman', NULL, NULL, 'Roman commander of the garrison at Jerusalem who rescued Paul from the mob, held him, and sent him to Felix at Caesarea with a letter.', 'No dates are known; he acted in AD 60.'),
(1045, 'Tertullus the orator', NULL, NULL, NULL, 1, 1, 'possible', 'other', 'minor', NULL, NULL, NULL, 'Lawyer who spoke for the high priest and elders against Paul before Felix, calling him a pestilent fellow and a ringleader of the Nazarenes.', 'No dates are known; he spoke in AD 60.'),
(1046, 'Julius the centurion', NULL, NULL, NULL, 1, 1, 'possible', 'warrior', 'minor', 'Roman', NULL, NULL, 'Roman centurion of the Augustan band who took Paul and other prisoners to Rome. He treated Paul kindly and stopped the soldiers from killing the prisoners at the shipwreck.', 'No dates are known; he acted in AD 62-63.'),
(1047, 'Publius of Malta', NULL, NULL, NULL, 1, 1, 'possible', 'ruler', 'minor', 'Maltese', NULL, NULL, 'Chief man of the island of Malta who lodged the shipwrecked party for three days. Paul healed his father of fever and dysentery.', 'No dates are known; he appears in AD 62.'),
(1079, 'Antipas of Pergamos', NULL, NULL, 90, 1, 1, 'possible', 'disciple', 'minor', NULL, NULL, NULL, 'Christian of Pergamum called by Christ ''my faithful martyr'', killed there where ''Satan''s seat'' was. Later tradition says he was burned in a bronze bull under Domitian; that account is tradition, not Scripture.', 'Death year is an estimate: he was killed before Revelation was written (about 95) and Domitian''s reign (AD 81-96) is the traditional setting. Birth unknown. Not linked to an event because he was dead when the letter was written.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(323, 'Ignatius of Antioch', NULL, 35, 108, 1, 0, 'possible', 'church-leader', 'major', NULL, NULL, NULL, 'Bishop of Antioch and early Church Father. His seven letters on church order, the Eucharist, and martyrdom are among the earliest post-apostolic writings.', 'Birth year is unknown; c. 35 is a conventional estimate. Martyred in Rome under Trajan (reigned 98-117), traditionally dated c. 108; some scholars place it as late as c. 110-117.'),
(324, 'Polycarp of Smyrna', NULL, 69, 155, 1, 1, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Bishop of Smyrna, a leading figure of the generation after the apostles who, according to Irenaeus, had known the Apostle John. At his martyrdom he declared "Eighty-six years I have served Him, and He never did me any injury."', 'Birth c. 69 is inferred from his ''86 years'' remark (which could mean his age or the years since his conversion) and is uncertain. Martyred on 22/23 February in 155 or 156, the standard modern dating; Eusebius''s Chronicle points to c. 166-167, which most scholars now reject.'),
(473, 'Nero', 'Nero Claudius Caesar', 37, 68, 0, 0, 'certain', 'ruler', 'moderate', NULL, NULL, NULL, 'Fifth Roman emperor (AD 54-68). He was the Caesar to whom Paul appealed (Acts 25:11). Tacitus records that he blamed the Christians for the great fire of AD 64 and put many to death; church tradition places the deaths of Peter and Paul in his reign. Born Lucius Domitius Ahenobarbus, he was Claudius''s stepson and was adopted by him in AD 50, after which he succeeded him.', 'Born 15 December AD 37; died 9 June AD 68. Acts 25:11; Tacitus, Annals 15.44.'),
(652, 'Drusilla', NULL, 38, NULL, 0, 1, 'probable', 'other', 'minor', NULL, 254, NULL, 'Youngest daughter of Herod Agrippa I and wife of the Roman governor Felix. She was a Jewess, and with Felix she heard Paul speak about the faith in Christ (Acts 24:24).', 'Ussher, Annals 6592: born AD 38 (aged six at her father Agrippa I''s death in AD 44; Josephus Ant. 19.354). She married Felix c. AD 54 (6795; Josephus Ant. 20.141-143 puts it about AD 53) and heard Paul with him in AD 60 (Acts 24:24). Death not recorded.'),
(740, 'Titus, Roman emperor', 'Titus Flavius Vespasianus', 39, 81, 0, 0, 'certain', 'ruler', 'minor', NULL, 741, NULL, 'Son of Vespasian who commanded the Roman army at the siege of Jerusalem, ending with the burning of the Temple in AD 70. He became emperor in AD 79 and died after two years. Not to be confused with Titus, the companion of Paul.', 'Standard Roman chronology: born 30 December AD 39, emperor 79-81, died 13 September AD 81.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(325, 'Irenaeus of Lyon', NULL, 130, 202, 1, 1, 'possible', 'church-leader', 'major', NULL, NULL, NULL, 'Bishop of Lyon who, by his own account, heard Polycarp as a young man. His work Against Heresies is foundational for early Christian orthodoxy and appeals to Scripture, the rule of faith and the succession of bishops from the apostles as tests of true teaching.', 'Born in Asia Minor (probably Smyrna) c. 130-142; died c. 202. Both dates are estimates.'),
(326, 'Origen of Alexandria', NULL, 185, 253, 1, 1, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Prolific scholar and head of the catechetical school in Alexandria, later teaching at Caesarea in Palestine. Pioneered textual criticism and allegorical interpretation of Scripture. His Hexapla set the Hebrew Old Testament beside several Greek versions in parallel columns. Some of his speculative teachings were later condemned, but his influence on Eastern and Western exegesis was immense.', 'Born c. 185 in Alexandria; died c. 253-254 in Tyre, after suffering torture in the Decian persecution (250-251).'),
(327, 'Tertullian', 'Quintus Septimius Florens Tertullianus', 155, 220, 1, 1, 'possible', 'church-leader', 'moderate', NULL, NULL, NULL, 'Early Latin Christian writer in Carthage. The earliest surviving Latin use of the word trinitas is his, and he shaped much of Latin theological vocabulary. Later he joined the Montanist movement, which is why he is not always counted among the Church Fathers.', 'Born c. 155 in Carthage; died c. 220. Both dates are estimates.'),
(328, 'Athanasius of Alexandria', NULL, 296, 373, 1, 0, 'probable', 'church-leader', 'major', NULL, NULL, NULL, 'Bishop of Alexandria who defended Christ''s full deity against Arianism through five exiles, holding the line for the Nicene faith. His Easter festal letter contains the earliest known list of exactly the twenty-seven New Testament books, a landmark in the history of the canon.', 'Born c. 296 (estimates c. 293-298); died 2 May 373. Exiled five times by common count.'),
(490, 'Constantine the Great', 'Flavius Valerius Constantinus, Constantine I', 272, 337, 1, 0, 'probable', 'ruler', 'major', NULL, 653, 654, 'Roman emperor who, after the Milvian Bridge (312), favored Christianity, agreed with Licinius to extend toleration (313), and convened the Council of Nicaea (325). He was baptized shortly before his death in 337. Christianity became legal and favored, not the state religion, under him. His mother was Helena and his father Constantius Chlorus.', 'Born c. 272 (Naissus); died 22 May 337 near Nicomedia.'),
(653, 'Constantius I Chlorus', 'Constantius Chlorus, Flavius Valerius Constantius', 250, 306, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Roman emperor in the West (Caesar from 293, Augustus 305-306), father of Constantine the Great. His eastern colleagues carried out the Great Persecution, but his own rule in Gaul and Britain was mild. He died at York, where his troops proclaimed Constantine.', 'Born c. 250; died 25 July 306 at Eboracum (York).'),
(654, 'Helena, mother of Constantine', 'Helena, Saint Helena, Flavia Julia Helena', 250, 330, 1, 1, 'probable', 'queen', 'moderate', NULL, NULL, NULL, 'Mother of Constantine the Great, given the title Augusta by her son. Eusebius reports her pilgrimage to the Holy Land in her old age, and later tradition credits her with finding the True Cross. She is honored as a saint in the Catholic and Orthodox churches. Whether she was Constantius''s wife or concubine is debated.', 'Born c. 250 (from Eusebius, who says she was about 80 on her pilgrimage c. 327-328); died c. 330. Eusebius, Life of Constantine 3.42-47. The finding of the Cross is a later tradition.'),
(742, 'Gregory the Illuminator', NULL, 257, 331, 1, 1, 'traditional', 'church-leader', 'minor', NULL, NULL, NULL, 'Traditional founder and first head of the Armenian Church. According to Armenian tradition he converted King Tiridates III, who made Christianity the state religion of Armenia.', 'Dates are traditional and approximate; the Armenian sources are later accounts. The conversion is traditionally put at 301, though some scholars date it a decade or so later.'),
(743, 'Tiridates III of Armenia', 'Trdat III the Great', 250, 330, 1, 1, 'probable', 'king', 'minor', NULL, NULL, NULL, 'King of Armenia who, according to Armenian tradition, was converted by Gregory the Illuminator and made Armenia the first state to adopt Christianity as its official religion.', 'His reign is usually given as about 287-330; birth year is an estimate. The date of his conversion is traditionally 301 and debated.'),
(744, 'Diocletian', 'Gaius Aurelius Valerius Diocletianus', 244, 311, 1, 1, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Roman emperor from 284 to 305 who reorganised the empire under a shared rule of four. In 303 he and his colleagues began the last and most severe empire-wide persecution of Christians. He abdicated in 305.', 'Born about 244; abdicated 305; died c. 311 (3 December 311 is usual; some give 312). The first persecution edict was issued at Nicomedia in February 303.'),
(745, 'Galerius', 'Gaius Galerius Valerius Maximianus', 260, 311, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Roman emperor who is generally thought to have urged Diocletian toward persecuting Christians. In 311, shortly before his death, he issued an edict of toleration ending the persecution in the East.', 'Born about 260; died in 311, soon after the Edict of Serdica (also called the Edict of Toleration).');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(329, 'Jerome', 'Eusebius Sophronius Hieronymus', 347, 420, 1, 0, 'probable', 'church-leader', 'major', NULL, NULL, NULL, 'A learned and irascible monk and biblical scholar who revised the Latin Gospels and Psalms and translated most of the Old Testament into Latin from the Hebrew, settling in Bethlehem around 386. The resulting Vulgate, a composite text that gradually replaced the Old Latin versions, became the Bible of the Western church for about a thousand years.', 'Born c. 347 (some scholars c. 342) in Stridon; died 30 September 420 in Bethlehem.'),
(330, 'Augustine of Hippo', 'Aurelius Augustinus', 354, 430, 0, 0, 'certain', 'church-leader', 'major', NULL, 656, 655, 'A North African rhetorician converted in a Milan garden who became bishop of Hippo and the most influential theologian of the Western church. His Confessions pioneered spiritual autobiography, and his teaching on grace, sin, and the City of God shaped Catholic and Protestant thought alike. His mother Monica and father Patricius are known from the Confessions; his son Adeodatus was born in 372.', 'Born November 13, 354 in Thagaste; died August 28, 430 in Hippo.'),
(332, 'Patrick of Ireland', 'Patricius', 385, 461, 1, 1, 'possible', 'church-leader', 'moderate', NULL, NULL, NULL, 'Missionary to Ireland. Captured as a slave at about 16, he escaped and later returned to evangelize the Irish. Irish Christianity went on to become a notable center of monastic learning and mission.', 'Traditional dates c. 385-461; many modern scholars place his mission in the later fifth century (died c. 490s). Born in Roman Britain; his own Confessio gives no years.'),
(491, 'John Chrysostom', 'Golden-mouthed, John of Antioch', 347, 407, 1, 0, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Archbishop of Constantinople, famed for his preaching and his expositions of Scripture, who criticized the wealthy and the imperial court and died in exile. Honored in the Eastern and Western churches; his name means Golden-mouthed.', 'Born c. 347 (344-354) in Antioch; died 14 September 407 at Comana in Pontus.'),
(655, 'Monica of Hippo', 'Monnica, Saint Monica', 331, 387, 1, 0, 'probable', 'other', 'moderate', NULL, NULL, NULL, 'Christian mother of Augustine of Hippo, who prayed and wept for his conversion for many years and followed him to Milan. She died at Ostia in 387 on the journey home to Africa, shortly after the conversation with her son recorded in the Confessions (book 9). Honored as a saint in the Catholic and Orthodox churches.', 'Born 331 in Thagaste; died 387 at Ostia. Augustine, Confessions 9.8-13.'),
(656, 'Patricius, father of Augustine', 'Patricius', 320, 371, 1, 1, 'probable', 'other', 'minor', NULL, NULL, NULL, 'Pagan town councillor of Thagaste, Augustine''s father, who was baptized shortly before his death. He is known from Augustine''s Confessions (book 2 and book 9), which describes his ambitions for his son''s education.', 'Estimate. Augustine says he died when Augustine was seventeen, c. 371 (Confessions 3.4). His birth year is inferred.'),
(657, 'Adeodatus', 'Adeodatus, son of Augustine', 372, 390, 1, 1, 'probable', 'other', 'minor', NULL, 330, NULL, 'Son of Augustine and his unnamed concubine. He was baptized with his father at Milan in 387 and appears as a speaker in Augustine''s dialogue De Magistro. He died young, not long after returning to Africa.', 'Born 372 in Carthage; died c. 390. Confessions 4.2, 9.6. Augustine''s companion is not named in any source.'),
(746, 'Theodosius I', 'Theodosius the Great', 347, 395, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Roman emperor who, in 380, made Nicene Christianity the religion of the empire. He summoned the Council of Constantinople in 381, which confirmed the Nicene faith.', 'Born 11 January 347, emperor in the East 379 and of the whole empire 392-395, died 17 January 395.'),
(747, 'Gregory of Nazianzus', 'Gregory the Theologian', 329, 390, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Cappadocian bishop and theologian, honoured in the Eastern Church as "the Theologian." He led the Nicene congregation in Constantinople and briefly presided over the Council of 381 before resigning.', 'Born about 329-330; died 390.'),
(748, 'Gregory of Nyssa', NULL, 335, 395, 1, 1, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Cappadocian bishop and theologian, younger brother of Basil the Great. He took an important part in the Council of Constantinople in 381 and in shaping the doctrine of the Trinity.', 'Birth about 335; death about 395 (last attested that year).'),
(749, 'Cyril of Alexandria', NULL, 376, 444, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Patriarch of Alexandria from 412 to 444. He opposed Nestorius and presided over the Council of Ephesus in 431, which affirmed the title Theotokos ("God-bearer") for Mary.', 'Born about 376; died 27 June 444.'),
(750, 'Nestorius', NULL, 386, 451, 1, 1, 'possible', 'church-leader', 'minor', NULL, NULL, NULL, 'Patriarch of Constantinople from 428 who objected to calling Mary Theotokos. The Council of Ephesus deposed him in 431 and he died in exile in Egypt. The Church of the East, often called Nestorian, did not accept his condemnation as fair, and scholars still debate what he actually taught.', 'Born about 386; died after 451, probably that year. Exact dates are not recorded.'),
(751, 'Theodosius II', NULL, 401, 450, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Eastern Roman emperor from 408 to 450. He summoned the Council of Ephesus in 431 and the second Council of Ephesus in 449.', 'Born 10 April 401; died 28 July 450 after a riding accident.'),
(752, 'Pope Leo I', 'Leo the Great', 400, 461, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Bishop of Rome from 440 to 461. His letter to Flavian, known as the Tome of Leo, set out the teaching of two natures in one person of Christ and shaped the definition of Chalcedon in 451. He is also remembered for persuading Attila to withdraw from Italy in 452.', 'Birth year about 400; died 10 November 461.'),
(753, 'Marcian', NULL, 392, 457, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Eastern Roman emperor from 450 to 457. He summoned the Council of Chalcedon in 451, together with his wife Pulcheria, to settle the disputes over the nature of Christ.', 'Born about 392; emperor 450-457; died January 457.'),
(754, 'Odoacer', NULL, 433, 493, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Germanic military commander who deposed the last Western Roman emperor in 476 and ruled Italy as king. He was killed by Theodoric the Ostrogoth in 493.', 'Birth year is an estimate. He was killed 15 March 493.'),
(755, 'Romulus Augustulus', 'Romulus Augustus', 465, NULL, 1, 1, 'possible', 'ruler', 'minor', NULL, NULL, NULL, 'The last emperor of the Western Roman Empire. A boy raised to the throne by his father in 475, he was deposed by Odoacer in 476. He was allowed to live, and little more is known of him.', 'Birth year is an estimate (a young teenager in 475-476). Deposed in September 476; the date of his death is unknown.'),
(808, 'Ambrose of Milan', NULL, 339, 397, 1, 0, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Roman governor made Bishop of Milan by popular acclaim in 374. His preaching influenced Augustine of Hippo, and he baptised him at Easter 387. Western tradition counts him one of the four Doctors of the Church.', 'Born about 339; died 4 April 397.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(331, 'Benedict of Nursia', NULL, 480, 547, 1, 1, 'probable', 'church-leader', 'major', NULL, NULL, NULL, 'Founder of Monte Cassino and author of the Rule of St. Benedict, which became the standard rule of Western monasticism. Its balance of prayer, work and study, later summed up in the motto "ora et labora", shaped monastic communities that preserved learning in the early Middle Ages.', 'Born c. 480 in Nursia; died c. 547 (some sources c. 543) at Monte Cassino. Almost all details come from Gregory the Great''s Dialogues, book II.'),
(492, 'Gregory the Great', 'Gregory I', 540, 604, 1, 0, 'probable', 'church-leader', 'major', NULL, NULL, NULL, 'Pope from 590 to 604, who strengthened the Roman see, sent Augustine of Canterbury to England, and wrote the Pastoral Rule and the Dialogues (the main source for the life of Benedict). He is honored by Catholic and Orthodox churches.', 'Born c. 540 in Rome; died 12 March 604.'),
(756, 'Muhammad', 'Muhammad ibn Abdullah', 570, 632, 1, 0, 'probable', 'other', 'moderate', NULL, NULL, NULL, 'Arab religious and political leader of Mecca and Medina, regarded by Muslims as the final prophet and the one through whom the Quran was revealed. He founded the Muslim community; within a few years of his death in 632 the armies of his successors, the caliphs, began the conquests of the Byzantine and Persian territories.', 'Traditionally born in Mecca about 570; died at Medina on 8 June 632. Early Muslim sources are the main record and were written some generations later.'),
(758, 'Emperor Taizong of Tang', 'Li Shimin', 599, 649, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Second emperor of the Tang dynasty, who reigned from 626 to 649. According to the Xi''an stele, he welcomed Alopen in 635 and had the Christian teaching examined and permitted.', 'Born 23 January 599 (the Chinese lunar year 598 ends in January 599, hence the common 598); emperor 626-649; died 10 July 649.'),
(759, 'Oswiu of Northumbria', 'Oswy', 612, 670, 1, 0, 'probable', 'king', 'minor', NULL, NULL, NULL, 'King of Northumbria from 642 to 670. He brought together the Synod of Whitby in 664, which decided that the kingdom would follow the Roman method of calculating Easter.', 'Born about 612; died 15 February 670.'),
(760, 'Wilfrid', 'Wilfrid of York', 634, 709, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Northumbrian churchman, later bishop of York, who spoke for the Roman Easter at the Synod of Whitby in 664. His career is told in the Life by Stephen of Ripon.', 'Born about 634; died 709.'),
(762, 'Hilda of Whitby', 'Hild', 614, 680, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Abbess of Whitby, a noble Northumbrian woman and a counsellor to kings and bishops. Her monastery hosted the synod of 664. Bede praises her wisdom and the learning of those she trained.', 'Born about 614; died 17 November 680.'),
(763, 'Empress Irene', 'Irene of Athens', 752, 803, 1, 0, 'probable', 'ruler', 'minor', NULL, NULL, NULL, 'Byzantine empress who ruled as regent for her son from 780 and in her own right from 797 to 802. She summoned the Second Council of Nicaea in 787, which restored the veneration of icons. The Orthodox Church honours her as a saint.', 'Born about 752; died 9 August 803 in exile.'),
(764, 'Pope Adrian I', 'Hadrian I', 700, 795, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Bishop of Rome from 772 to 795. He did not attend the Second Council of Nicaea in 787 but was represented there by legates, and he approved its decisions on icons. He was an ally of Charlemagne.', 'Birth year is an estimate; he died 25 December 795.'),
(765, 'Charlemagne', 'Charles the Great, Carolus Magnus', 748, 814, 1, 0, 'probable', 'ruler', 'moderate', NULL, NULL, NULL, 'King of the Franks from 768, who united much of western Europe and supported church reform and learning. He was crowned emperor by Pope Leo III in Rome on Christmas Day, 800.', 'Birth is given as 747 or 748 (sources differ; 742 has also been proposed). He died 28 January 814.'),
(766, 'Pope Leo III', NULL, 750, 816, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Bishop of Rome from 795 to 816. After Charlemagne helped him against his enemies in Rome, he crowned Charlemagne emperor on 25 December 800.', 'Birth year about 750; died 12 June 816.'),
(767, 'Cyril (Constantine the Philosopher)', 'Constantine the Philosopher, Saint Cyril', 826, 869, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Scholar from Thessalonica who, with his brother Methodius, went to Moravia in 863 and devised the Glagolitic alphabet to translate the scriptures and liturgy into Slavic. He took the name Cyril as a monk shortly before his death in Rome.', 'Born 826 or 827; died 14 February 869.'),
(768, 'Methodius', 'Saint Methodius of Thessalonica', 815, 885, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Brother of Cyril and fellow missionary to the Slavs. After Cyril''s death he was made archbishop for Moravia and Pannonia and continued the Slavic translation work despite opposition.', 'Born about 815; died 6 April 885.'),
(770, 'Michael I Cerularius', 'Michael Keroularios', 1000, 1059, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Patriarch of Constantinople from 1043 to 1058. His dispute with the papal legates in 1054 ended with mutual excommunications and is traditionally counted as the start of the East-West Schism.', 'Born about 1000; died January 1059.'),
(771, 'Cardinal Humbert of Silva Candida', 'Humbert of Moyenmoutier', 1000, 1061, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Papal legate to Constantinople in 1054. On 16 July he laid the bull of excommunication against Patriarch Michael Cerularius on the altar of Hagia Sophia.', 'Born about 1000; died 5 May 1061.'),
(772, 'Pope Leo IX', NULL, 1002, 1054, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Bishop of Rome from 1049 who set the papacy on a course of reform. He sent the legates to Constantinople in 1054, but he had died in April of that year, before the excommunication was delivered in July.', 'Born 21 June 1002; died 19 April 1054.'),
(773, 'Pope Urban II', 'Odo of Châtillon', 1035, 1099, 1, 0, 'probable', 'church-leader', 'minor', NULL, NULL, NULL, 'Pope from 1088 to 1099. At the Council of Clermont in November 1095 he called on Western Christians to aid the Byzantine Empire against the Turks, a call that launched the First Crusade.', 'Born about 1035; died 29 July 1099. No contemporary record preserves his exact words at Clermont.'),
(801, 'Aethelberht of Kent', 'Ethelbert', 560, 616, 1, 0, 'probable', 'king', 'minor', NULL, NULL, NULL, 'King of Kent who received Augustine of Canterbury in 597 and was later baptised, the first Anglo-Saxon king to become Christian. His wife Bertha, a Frankish Christian, had already encouraged the faith at his court.', 'Born about 560; reigned about 590-616; baptism usually put about 601.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(333, 'Francis of Assisi', 'Giovanni di Pietro di Bernardone', 1182, 1226, 1, 0, 'certain', 'church-leader', 'major', NULL, NULL, NULL, 'Founder of the Franciscan Order. Renounced wealth to live in radical poverty and preached to the poor. According to tradition he received the stigmata in 1224. Patron saint of animals and ecology.', 'Born 1181 or 1182 in Assisi; died October 3, 1226.'),
(334, 'Thomas Aquinas', NULL, 1225, 1274, 1, 0, 'certain', 'church-leader', 'major', NULL, NULL, NULL, 'Dominican friar and one of the most influential medieval theologians, honored in the Catholic Church as a Doctor of the Church. His Summa Theologiae brought Aristotelian philosophy into a systematic account of Christian doctrine.', 'Born c. 1224-25 at Roccasecca; died 7 March 1274 at Fossanova Abbey.'),
(335, 'John Wycliffe', NULL, 1328, 1384, 1, 0, 'probable', 'reformer', 'major', NULL, NULL, NULL, 'An Oxford theologian who challenged papal wealth and authority and inspired the first complete Bible in English, rendered from the Latin Vulgate by his associates. Condemned after death at the Council of Constance, his remains were exhumed and burned in 1428; his Lollard followers and later admirers gave him the title morning star of the Reformation.', 'Born c. 1328 in Yorkshire; died December 31, 1384.'),
(336, 'Jan Hus', 'John Hus', 1372, 1415, 1, 0, 'probable', 'reformer', 'moderate', NULL, NULL, NULL, 'Czech reformer and rector of the University of Prague. Influenced by Wycliffe, he preached in the common language and challenged papal authority. Burned at the stake at the Council of Constance.', 'Born c. 1372; burned July 6, 1415.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(337, 'Johannes Gutenberg', NULL, 1400, 1468, 1, 0, 'probable', 'other', 'major', NULL, NULL, NULL, 'Goldsmith of Mainz who developed movable-type printing in Europe. His Gutenberg Bible (c. 1455) transformed the spread of Scripture, and the printing press greatly aided the Reformation.', 'Born c. 1400 in Mainz; died February 3, 1468.'),
(338, 'Martin Luther', NULL, 1483, 1546, 0, 0, 'certain', 'reformer', 'major', NULL, NULL, NULL, 'An Augustinian monk whose Ninety-five Theses against indulgences ignited the Protestant Reformation. At the Diet of Worms he refused to recant unless convinced by Scripture and plain reason, and while hidden at the Wartburg he translated the New Testament into German, reshaping both church and language. He married Katharina von Bora in 1525.', 'Born November 10, 1483; died February 18, 1546.'),
(339, 'William Tyndale', NULL, 1494, 1536, 1, 0, 'probable', 'reformer', 'major', NULL, NULL, NULL, 'A gifted linguist who translated the New Testament into English directly from the Greek, printing it abroad and smuggling copies into England in bales of cloth. Strangled and burned as a heretic, his phrasing lives on, since much of the King James Version, above all its New Testament, descends from his work.', 'Born c. 1494; strangled and burned at Vilvoorde near Brussels in early October 1536 (6 October is the traditional date; the exact day is not recorded).'),
(340, 'John Calvin', 'Jean Cauvin', 1509, 1564, 0, 0, 'certain', 'reformer', 'major', NULL, NULL, NULL, 'French theologian and reformer. His Institutes of the Christian Religion (1536) is the foundational text of Reformed theology. Led the church in Geneva.', 'Born July 10, 1509; died May 27, 1564.'),
(341, 'John Knox', NULL, 1514, 1572, 1, 0, 'probable', 'reformer', 'moderate', NULL, NULL, NULL, 'Scottish reformer and a principal leader of the Reformation in Scotland. His preaching and writing helped shape the Church of Scotland, whose Reformed, Presbyterian character emerged from the 1560 Reformation Parliament.', 'Born between c. 1505 and 1514 (c. 1514 is conventional); died 24 November 1572 in Edinburgh.'),
(493, 'Bartolome de las Casas', 'Bartolomé de las Casas', 1484, 1566, 1, 0, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Spanish Dominican friar and Bishop of Chiapas who opposed the enslavement and abuse of Indigenous peoples in the Spanish Americas and wrote A Short Account of the Destruction of the Indies.', 'Born 1484 (older sources 1474); died 17 July 1566 in Madrid.'),
(494, 'Francis Xavier', 'Francisco de Jasso y Azpilicueta', 1506, 1552, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'Spanish Jesuit missionary, a co-founder of the Society of Jesus, who preached in India, Southeast Asia and Japan and died off the coast of China in 1552.', 'Born 7 April 1506; died 3 December 1552 on Shangchuan Island.'),
(658, 'Katharina von Bora', 'Katharina Luther, Katie Luther', 1499, 1552, 0, 0, 'certain', 'other', 'moderate', NULL, NULL, NULL, 'Former nun who fled her convent in 1523 and married Martin Luther in 1525. She managed the household and finances of the Black Cloister at Wittenberg and bore six children. Her marriage became the model of the Protestant clergy household.', 'Born 29 January 1499; died 20 December 1552 at Torgau. Married Luther 13 June 1525.'),
(774, 'Mehmed II', 'Mehmed the Conqueror', 1432, 1481, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Ottoman sultan who captured Constantinople on 29 May 1453 after a siege of about seven weeks, ending the Byzantine Empire. He ruled again from 1451 to 1481.', 'Born 30 March 1432; died 3 May 1481.'),
(775, 'Constantine XI Palaiologos', NULL, 1405, 1453, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Last Byzantine emperor, crowned in 1449. He led the defence of Constantinople and is believed to have died in the final assault of 29 May 1453.', 'Born 8 February 1405; died 29 May 1453. The manner of his death is not fully certain.'),
(776, 'Pope Paul III', 'Alessandro Farnese', 1468, 1549, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Pope from 1534 to 1549. He called the Council of Trent, which opened in December 1545, and approved the Society of Jesus in 1540.', 'Born 29 February 1468; died 10 November 1549.'),
(777, 'James VI and I', 'King James', 1566, 1625, 0, 0, 'certain', 'king', 'minor', NULL, NULL, NULL, 'King of Scotland from 1567 and of England from 1603. At the Hampton Court Conference of 1604 he agreed to a new English translation of the Bible, which appeared in 1611 as the King James or Authorized Version.', 'Born 19 June 1566; died 27 March 1625.'),
(778, 'Lancelot Andrewes', NULL, 1555, 1626, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Anglican bishop and scholar who led the Westminster company of translators responsible for Genesis through 2 Kings in the King James Version. He was known for his learning in ancient languages and his devotional writing.', 'Born 1555; died 25 September 1626.'),
(802, 'Juan Gines de Sepulveda', NULL, 1494, 1573, 0, 0, 'certain', 'other', 'minor', NULL, NULL, NULL, 'Spanish humanist and priest who argued at Valladolid that the conquest of the Indies could be justified by natural law and Aristotles idea of natural servitude. Las Casas opposed him, arguing that Native Americans were free people with a right to be won by peaceful preaching.', 'Born about 1494; died 17 November 1573.'),
(803, 'Ignatius of Loyola', NULL, 1491, 1556, 0, 0, 'certain', 'church-leader', 'major', NULL, NULL, NULL, 'Spanish soldier turned priest who wrote the Spiritual Exercises and with six companions founded the Society of Jesus, approved by Pope Paul III in 1540. He served as its first Superior General until his death. Catholic tradition honours him as a saint.', 'Born 1491; died 31 July 1556.'),
(804, 'John Bunyan', NULL, 1628, 1688, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'English Baptist preacher and tinker who was imprisoned at Bedford for preaching without a licence. He wrote The Pilgrims Progress, among the most widely read Christian books in English.', 'Baptised 30 November 1628; died 31 August 1688.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(342, 'John Wesley', NULL, 1703, 1791, 0, 0, 'certain', 'church-leader', 'major', NULL, 659, 660, 'Anglican clergyman and leader of the Methodist movement, which separated from the Church of England only after his death. His heart was "strangely warmed" at Aldersgate Street (1738). Traditional estimates say he traveled about 250,000 miles and preached over 40,000 sermons. Son of Samuel and Susanna Wesley; his brother Charles wrote many of the movement''s hymns.', 'Born June 28, 1703; died March 2, 1791.'),
(343, 'Jonathan Edwards', NULL, 1703, 1758, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'American Congregationalist theologian and preacher of the First Great Awakening. His sermon "Sinners in the Hands of an Angry God" (preached at Enfield, 1741) is among the most famous in American history.', 'Born October 5, 1703; died March 22, 1758.'),
(344, 'William Carey', NULL, 1761, 1834, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'English Baptist missionary often called the "father of modern missions." Worked in India for over 40 years; he and his Serampore colleagues translated Scripture, in whole or in part, into dozens of languages of South Asia.', 'Born August 17, 1761; died June 9, 1834.'),
(345, 'Charles Spurgeon', 'C.H. Spurgeon', 1834, 1892, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'English Baptist preacher known as the "Prince of Preachers." Pastored the Metropolitan Tabernacle in London (seating 5,000). Sermons still widely read.', 'Born June 19, 1834; died January 31, 1892.'),
(346, 'D.L. Moody', 'Dwight Lyman Moody', 1837, 1899, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'American evangelist whose revival campaigns reached millions. Founded the Moody Bible Institute (1886) and the Moody Church in Chicago.', 'Born February 5, 1837; died December 22, 1899.'),
(348, 'C.S. Lewis', 'Clive Staples Lewis', 1898, 1963, 0, 0, 'certain', 'other', 'moderate', NULL, NULL, NULL, 'British scholar and author. Converted from atheism to theism in 1929 and to Christianity in 1931. Works such as Mere Christianity and The Screwtape Letters remain among the most widely read Christian apologetics, and he also wrote the Chronicles of Narnia.', 'Born November 29, 1898; died November 22, 1963.'),
(495, 'George Whitefield', NULL, 1714, 1770, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'Anglican evangelist whose open-air preaching in Britain and the American colonies was central to the First Great Awakening and helped spread evangelicalism.', 'Born 16 December 1714; died 30 September 1770 at Newburyport.'),
(496, 'Samuel Ajayi Crowther', 'Samuel Adjai Crowther', 1809, 1891, 1, 0, 'probable', 'church-leader', 'moderate', NULL, NULL, NULL, 'Yoruba-born freed slave who became the first African Anglican bishop (consecrated 1864), led the Niger Mission, and translated the Bible into Yoruba and other languages.', 'Born c. 1809 in Osogun; died 31 December 1891 in Lagos.'),
(659, 'Samuel Wesley', 'Samuel Wesley Sr.', 1662, 1735, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Anglican priest and poet, rector of Epworth in Lincolnshire, father of John and Charles Wesley.', 'Born December 1662; died 25 April 1735 at Epworth.'),
(660, 'Susanna Wesley', 'Susanna Annesley', 1669, 1742, 0, 0, 'certain', 'other', 'moderate', NULL, NULL, NULL, 'Wife of Samuel Wesley and mother of John and Charles Wesley. She educated her children herself at the Epworth rectory by a strict method, and is often called the mother of Methodism.', 'Born 20 January 1669; died 23 July 1742 in London. She bore nineteen children, of whom ten lived to adulthood.'),
(661, 'Charles Wesley', NULL, 1707, 1788, 0, 0, 'certain', 'church-leader', 'moderate', NULL, 659, 660, 'Younger brother of John Wesley and co-founder of Methodism, author of about six thousand hymns including "Hark! The Herald Angels Sing" and "O for a Thousand Tongues to Sing".', 'Born 18 December 1707; died 29 March 1788 in London.'),
(779, 'Thomas Charles', 'Thomas Charles of Bala', 1755, 1814, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Welsh clergyman and Methodist leader at Bala. His effort to supply Welsh-speaking people with Bibles in 1802 is regarded as the immediate cause for founding the British and Foreign Bible Society in 1804.', 'Born 14 October 1755; died 5 October 1814.'),
(780, 'William Wilberforce', NULL, 1759, 1833, 0, 0, 'certain', 'reformer', 'minor', NULL, NULL, NULL, 'English politician and evangelical who led the parliamentary campaign against the slave trade. He was an early and prominent supporter of the British and Foreign Bible Society.', 'Born 24 August 1759; died 29 July 1833.'),
(781, 'Elias Boudinot', NULL, 1740, 1821, 0, 0, 'certain', 'other', 'minor', NULL, NULL, NULL, 'American lawyer and statesman, president of the Continental Congress in 1782-83 and director of the US Mint. He was the first president of the American Bible Society when it was formed in 1816.', 'Born 2 May 1740; died 24 October 1821.'),
(782, 'William J. Seymour', NULL, 1870, 1922, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'African American preacher who led the Azusa Street Mission in Los Angeles from 1906. The multiracial revivals there are widely seen as the beginning of the worldwide Pentecostal movement.', 'Born 2 May 1870; died 28 September 1922.'),
(783, 'John R. Mott', NULL, 1865, 1955, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'American Methodist layman and leader of the YMCA and the Student Volunteer Movement. He chaired the World Missionary Conference in Edinburgh in 1910, and received the Nobel Peace Prize in 1946.', 'Born 25 May 1865; died 31 January 1955.'),
(785, 'Eleazar Sukenik', 'Eleazar Lipa Sukenik', 1889, 1953, 0, 0, 'certain', 'other', 'minor', NULL, NULL, NULL, 'Archaeologist of the Hebrew University in Jerusalem. In November 1947 he obtained the first Dead Sea Scrolls for the university and recognised their antiquity.', 'Born 12 August 1889; died 28 February 1953.'),
(787, 'David Ben-Gurion', NULL, 1886, 1973, 0, 0, 'certain', 'ruler', 'minor', NULL, NULL, NULL, 'Zionist leader who read the Declaration of the Establishment of the State of Israel on 14 May 1948 and became its first prime minister.', 'Born 16 October 1886; died 1 December 1973.'),
(788, 'Pope John XXIII', 'Angelo Roncalli', 1881, 1963, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'Pope from 1958 to 1963. He called the Second Vatican Council, which opened on 11 October 1962, and died before it ended. The Catholic Church canonised him in 2014.', 'Born 25 November 1881; died 3 June 1963.'),
(789, 'Pope Paul VI', 'Giovanni Battista Montini', 1897, 1978, 0, 0, 'certain', 'church-leader', 'minor', NULL, NULL, NULL, 'Pope from 1963 to 1978. He continued the Second Vatican Council after John XXIII''s death and closed it in December 1965.', 'Born 26 September 1897; died 6 August 1978.'),
(805, 'Hudson Taylor', NULL, 1832, 1905, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'English missionary who went to China in 1853 and in 1865 founded the China Inland Mission, which sent workers to the inland provinces. He dressed and lived as Chinese people did and welcomed missionaries from many denominations and unmarried women.', 'Born 21 May 1832; died 3 June 1905 at Changsha.');
INSERT INTO people (id, name, alt_names, birth_year, death_year, birth_approx, death_approx, date_confidence, role, significance, tribe, father_id, mother_id, description, date_notes) VALUES
(347, 'Dietrich Bonhoeffer', NULL, 1906, 1945, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'German Lutheran pastor and theologian who opposed Nazism and was a leader of the Confessing Church. Arrested in 1943 and hanged at Flossenburg concentration camp on 9 April 1945, weeks before its liberation. Author of The Cost of Discipleship and Life Together.', 'Born February 4, 1906; hanged April 9, 1945.'),
(349, 'Billy Graham', 'William Franklin Graham Jr.', 1918, 2018, 0, 0, 'certain', 'church-leader', 'major', NULL, NULL, NULL, 'An American evangelist whose stadium crusades and broadcasts carried a simple gospel invitation to more people than perhaps any preacher in history. A counselor to presidents who insisted on integrated seating at his meetings, he became the face of twentieth-century evangelicalism.', 'Born November 7, 1918; died February 21, 2018.'),
(786, 'John C. Trever', NULL, 1916, 2006, 0, 0, 'certain', 'other', 'minor', NULL, NULL, NULL, 'American biblical scholar at the American Schools of Oriental Research in Jerusalem. In 1948 he photographed the Isaiah scroll and recognised its similarity to ancient scripts, helping to establish its date.', 'Born 1916; died 2006.'),
(806, 'Martin Luther King Jr.', NULL, 1929, 1968, 0, 0, 'certain', 'reformer', 'major', NULL, NULL, NULL, 'Baptist minister and leader of the American civil-rights movement, who held that nonviolent resistance followed from the Christian command to love. He was assassinated in Memphis on 4 April 1968.', 'Born 15 January 1929; died 4 April 1968.'),
(807, 'Mother Teresa', NULL, 1910, 1997, 0, 0, 'certain', 'church-leader', 'moderate', NULL, NULL, NULL, 'Albanian-born Catholic nun who went to India in 1929 and in 1950 founded the Missionaries of Charity to serve the poorest in Calcutta. She received the Nobel Peace Prize in 1979 and was canonised by the Catholic Church in 2016.', 'Born 26 August 1910 at Skopje; died 5 September 1997.');
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(1, 'Creation', -4004, NULL, 0, 1, 'traditional', 'creation', 'major', 'In the Bible''s opening scene, God speaks an ordered cosmos into being, crowning it with humanity made in the divine image and a day of rest. Unlike Babylon''s Enuma Elish, where creation follows divine combat, Genesis presents one sovereign God whose word alone brings light, life, and order.', 'Ussher, Annals sec. 1: 4004 BC (AM 1), beginning at the evening before 23 October. Mainstream scholarship does not derive the age of the world from the Genesis genealogies, which may omit generations; Ussher''s figure is one traditional reading.', 10),
(2, 'The Fall', -4004, NULL, 0, 1, 'traditional', 'judgment', 'major', 'In Eden, Adam and Eve eat from the forbidden tree at the serpent''s urging, breaking trust with their Creator. Their exile from the garden brings sin, death, and alienation into the human story, setting the stage for the long biblical drama of redemption that Scripture traces to Christ.', 'Ussher, Annals secs. 10-11: 4004 BC, probably on the 10th day of the world (1 November).', 20),
(3, 'The Flood', -2349, -2348, 0, 0, 'traditional', 'judgment', 'major', 'Grieved by human violence, God cleanses the earth with a flood while preserving Noah, his family, and the animals in the ark, then seals a covenant with the rainbow sign. Mesopotamian epics like Gilgamesh and Atrahasis preserve parallel flood tales, yet Genesis uniquely grounds the deluge in divine justice.', 'Ussher: began 2349 BC (AM 1656), ended 2348 BC. Gen 8:13-14 puts the drying of the earth in Noah''s 601st year. Mainstream scholarship does not date the Flood from the Genesis genealogies.', 50),
(4, 'Tower of Babel', -2247, NULL, 1, 1, 'traditional', 'judgment', 'moderate', 'United humanity builds a tower on the plain of Shinar to make a name for itself, and God scatters the builders by confusing their language. The story evokes Mesopotamian ziggurats such as Babylon''s Etemenanki and explains the dispersion of nations, which Genesis places generations before God''s call of Abraham.', 'Ussher: 2247 BC (AM 1757), when Peleg was born and the earth was divided (Gen 10:25), about 326 years before Abraham left Haran in 1921 BC.', 60),
(300, 'Cain Kills Abel', -3880, NULL, 1, 1, 'possible', 'death', 'moderate', 'Cain, angered that God accepted Abel''s offering and not his own, kills his brother in the field. It is the first death recorded in Scripture, and God sends Cain away as a restless wanderer, yet under a protective mark.', 'Scripture: Abel was killed before Seth was born when Adam was 130 (Gen 4:25; 5:3), so no later than 3874 BC. Ussher, Annals sec. 13 (130 AM, 3874 BC): Seth was given after the murder, with man about 128 years on the earth. Exact year not fixed; 3880 BC is a display estimate.', 30),
(301, 'Enoch Taken by God', -3017, NULL, 0, 1, 'traditional', 'miracle', 'moderate', 'Enoch walks with God for 300 years after the birth of Methuselah and then is not, for God takes him in the 365th year of his life. Hebrews says he was taken up without seeing death.', 'Ussher: AM 987 from Gen 5:21-24 (born 3382 BC, aged 365). Matches the year given in Enoch''s row.', 40);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(5, 'Call of Abraham', -1921, NULL, 0, 1, 'traditional', 'covenant', 'major', 'God summons Abram to leave his homeland and his father''s house, going by way of Haran, for a country God would show him, promising to make him a great nation and a blessing to all peoples of the earth. His obedient departure launches the covenant story that the rest of Scripture traces through Israel to the Messiah.', 'Ussher, Annals secs. 71-72: 1921 BC (AM 2083), when Abraham left Haran aged 75 (Gen 12:4) after Terah''s death at 205 (Acts 7:4). Acts 7:2-4 and Gen 15:7 indicate that God first called him in Ur, which Ussher places in 1922 BC (sec. 70).', 70),
(6, 'Abrahamic Covenant', -1912, NULL, 0, 1, 'traditional', 'covenant', 'major', 'In a solemn night ceremony, God passes between divided animal carcasses as a smoking firepot and blazing torch, swearing to give Abram countless descendants and the land of Canaan. The rite mirrors ancient Near Eastern treaty customs, yet here God alone walks the path, bearing the covenant obligation himself.', 'Ussher, Annals sec. 77: 1912 BC (AM 2092), after Abram''s defeat of Chedorlaomer and the blessing by Melchizedek (sec. 76; Gen 14), when God renewed the promise and made the covenant of Gen 15.', 80),
(7, 'Binding of Isaac', -1871, NULL, 0, 1, 'traditional', 'covenant', 'moderate', 'God tests Abraham by commanding the sacrifice of Isaac, the son of promise, on Mount Moriah; at the final moment an angel stays the knife and a ram is offered instead. Known in Jewish tradition as the Akedah, the event affirms that God himself provides the sacrifice, a theme Christians hear echoed at Calvary.', 'Ussher, Annals sec. 90: 1871 BC (AM 2133). Scripture gives no age for Isaac (Gen 22:5 calls him a lad); Ussher''s dates make him 25, and Josephus (Antiquities 1) says 25 (Annals sec. 91).', 130),
(8, 'Destruction of Sodom and Gomorrah', -1897, NULL, 0, 1, 'traditional', 'judgment', 'moderate', 'Fire and sulfur destroy Sodom and Gomorrah after the outcry against their wickedness reaches heaven, though angels lead Lot''s family out; his wife looks back and becomes a pillar of salt. The doomed cities of the Dead Sea plain become Scripture''s enduring emblem of judgment, invoked by prophets and by Jesus.', 'Ussher: c. 1897 BC (Gen 19). Abraham was 99 years old.', 100),
(9, 'Covenant of Circumcision', -1897, NULL, 0, 1, 'traditional', 'covenant', 'moderate', 'God gives Abraham circumcision as the enduring sign of the covenant, marking every male of his household and renaming Abram and Sarai as heirs of the promise of nations and kings. Though circumcision was practiced in Egypt and elsewhere, Israel uniquely made it a covenant emblem binding each generation to God.', 'Ussher: c. 1897 BC. Abraham aged 99 (Gen 17:1, 24).', 110),
(10, 'Jacob Wrestles God', -1739, NULL, 0, 1, 'traditional', 'miracle', 'moderate', 'Jacob wrestles with God and is renamed Israel.', 'Ussher: c. 1739 BC (Gen 32:22-32).', 180),
(11, 'Joseph Sold into Slavery', -1728, NULL, 0, 1, 'traditional', 'other', 'moderate', 'Joseph''s brothers sell him to traders going to Egypt.', 'Scripture: Joseph was 17 when sold (Gen 37:2) and 30 when he stood before Pharaoh (Gen 41:46), so 13 years before 1715 BC = 1728 BC. Ussher, Annals section 128, agrees.', 190),
(12, 'Joseph Made Ruler of Egypt', -1715, NULL, 0, 1, 'traditional', 'kingdom', 'moderate', 'Sold by his brothers yet raised from prison to Pharaoh''s right hand, Joseph interprets dreams of coming famine and administers Egypt''s grain stores. His rise turns betrayal into rescue, positioning him to preserve Jacob''s family, the fledgling covenant line, through seven years of scarcity.', 'Scripture: Joseph was 30 when he stood before Pharaoh (Gen 41:46), nine years before Jacob stood before Pharaoh at 130 in 1706 BC (two years of famine after seven of plenty, Gen 45:6; 47:9), so 1715 BC. Ussher, Annals section 131, agrees.', 200),
(302, 'Birth of Ishmael', -1910, NULL, 0, 1, 'traditional', 'birth', 'moderate', 'After ten years in Canaan Sarai gives her servant Hagar to Abram, and Hagar bears Ishmael when Abram is 86. God hears the boy''s cry and promises to make him a great nation, though the covenant line runs through Isaac.', 'Gen 16:3, 16: Abram aged 86 (Ussher 1910 BC).', 90),
(303, 'Birth of Isaac', -1896, NULL, 0, 1, 'traditional', 'birth', 'moderate', 'Isaac is born to Abraham at 100 and Sarah at 90, the child of promise whose name means laughter. He is circumcised on the eighth day, and the covenant line runs through him.', 'Gen 21:5; 17:17: Abraham aged 100 (Ussher 1896 BC).', 120),
(304, 'Death of Sarah and Purchase of Machpelah', -1859, NULL, 0, 1, 'traditional', 'death', 'moderate', 'Sarah dies at 127 in Hebron, and Abraham buys the cave of Machpelah from Ephron the Hittite for 400 shekels of silver. It is his only possession in the promised land, and later holds Abraham, Isaac, Rebekah, Leah and Jacob.', 'Gen 23:1-20: Sarah aged 127 (born 1986 BC).', 140),
(305, 'Isaac Marries Rebekah', -1856, NULL, 0, 1, 'traditional', 'other', 'moderate', 'Abraham''s servant travels to Mesopotamia and brings back Rebekah, who marries Isaac when he is 40, three years after Sarah''s death. Isaac is comforted after his mother''s death.', 'Gen 24; 25:20: Isaac aged 40 (born 1896 BC).', 150),
(306, 'Jacob Flees to Haran', -1760, NULL, 0, 1, 'traditional', 'other', 'moderate', 'Having gained Isaac''s blessing and the birthright, Jacob flees Esau''s anger toward Haran, and at Bethel dreams of a ladder to heaven where God confirms the Abrahamic promise to him.', 'Ussher, Annals sections 111-112: 1760 BC (AM 2245). Jacob was 77 when he left (Gen 27-28), because he was 91 at Joseph''s birth (Gen 41:46; 45:6; 47:9) at the end of 14 years of service (Gen 30:25; 31:41).', 160),
(307, 'Jacob Marries Leah and Rachel', -1753, NULL, 0, 1, 'traditional', 'other', 'moderate', 'Jacob serves Laban seven years for Rachel but is given Leah; he receives Rachel a week later and serves seven more. Eleven of the twelve tribal ancestors and Dinah are born over the following years.', 'Scripture: Jacob served seven years for Rachel before the marriage (Gen 29:18-21), then received Leah and, a week later, Rachel (29:22-28); he arrived in Haran in 1760 BC (Ussher, Annals 111), so the marriages fall in 1753 BC, and Joseph is born at the end of the second seven years, 1745 BC (30:25; 31:41). Ussher (Annals 114-115, following Tremellius) instead puts both marriages in 1760 BC with the service afterwards; the text is followed here.', 170),
(308, 'Seven Years of Famine Begin', -1708, NULL, 0, 1, 'traditional', 'other', 'moderate', 'After seven years of plenty, famine spreads across Egypt and the nearby lands, and Joseph opens the storehouses. Jacob''s sons come twice to buy grain; on the second journey, when two years of the famine have passed and five remain, Joseph reveals himself to them (Gen 45:6).', 'Scripture: Joseph was 30 when he stood before Pharaoh (Gen 41:46) and seven plenteous years follow (Gen 41:47-53), so the famine begins 1715 - 7 = 1708 BC (Ussher, Annals section 133: from the harvest of that year). At the reunion two years of famine had passed and five were to come (Gen 45:6), i.e. 1706 BC, the beginning of the third year (Ussher, sections 137-138); the first journey, when Simeon was held, is 1707 BC (section 134). Jacob enters Egypt 1706 BC.', 210),
(400, 'Judah and Tamar', -1708, NULL, 1, 1, 'possible', 'other', 'moderate', 'Judah fails to give his widowed daughter-in-law Tamar to his youngest son, and Tamar secures her rights by a bold ruse; Judah himself concedes, "She hath been more righteous than I." Her twin sons Perez and Zerah are born, and Perez stands in the line of David and of Jesus (Matt 1:3).', 'Ussher does not date Genesis 38 in the Annals. It must fall between Judah''s birth in 1755 BC (section 120) and the descent into Egypt in 1706 BC (section 138), but it does not fit neatly into the lives of Judah''s sons, so the year is only anchored on Perez''s birth in this table. Estimate.', 220);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(13, 'Israel Enters Egypt', -1706, NULL, 0, 1, 'traditional', 'other', 'moderate', 'Jacob and his whole household migrate to Egypt at Joseph''s invitation, settling in the fertile land of Goshen and growing there into a numerous people. Egyptian art such as the Beni Hasan tomb painting depicts Semitic families entering Egypt, illustrating this well-traveled path in times of famine.', 'Scripture: Jacob was 130 when he stood before Pharaoh (Gen 47:9), two years into the famine (Gen 45:6). Jacob''s birth in 1836 BC is Ussher''s, so 1836 - 130 = 1706 BC (Ussher, Annals section 138, AM 2298). Gen 41:46 and 45:6 give the same result from Joseph''s age: 91 + 30 + 9 = 130. The 215 years from here to the Exodus are the second half of the 430 of Exod 12:40 counted from Abraham''s call in 1921 BC (Gal 3:17); Ussher, Annals section 138.', 240),
(14, 'The Exodus', -1491, NULL, 0, 0, 'traditional', 'salvation', 'major', 'After ten plagues break Pharaoh''s resistance, Israel departs Egypt under Moses on Passover night, freed from slavery to become a covenant nation. The Merneptah Stele, an Egyptian victory monument, preserves the earliest known extrabiblical mention of Israel as a people.', 'Scripture: 430 years from the promise to Abraham (Exod 12:40-41; Gal 3:17) and the 480th year before the founding of the Temple in Solomon''s fourth year (1 Kgs 6:1), which Ussher fixes at 1012 BC; 1012 plus 479 years (the 480th year) gives 1491 BC. Ussher, Annals 172-190: AM 2513, 1491 BC, on the fifteenth day of the first month (Num 33:3). Many scholars favour an early date c. 1446 BC (also from 1 Kgs 6:1, counting 480 years to a Temple dated c. 966 BC); others a late date c. 1260-1250 BC.', 300),
(15, 'Crossing the Red Sea', -1491, NULL, 0, 0, 'traditional', 'miracle', 'major', 'Trapped between Pharaoh''s chariots and the sea, Israel watches God part the waters at Moses'' outstretched hand, crossing on dry ground while the pursuing army is drowned. The Song of the Sea celebrating this rescue is reckoned among the oldest poetry preserved in the Hebrew Bible.', 'Ussher: 1491 BC.', 310),
(16, 'Giving of the Law', -1491, NULL, 0, 0, 'traditional', 'law', 'major', 'Amid thunder and fire on Mount Sinai, God speaks the Ten Commandments and gives Moses the Torah, constituting rescued slaves as a kingdom of priests and a holy nation. Scholars note that the covenant''s structure parallels ancient suzerainty treaties, casting God as Israel''s sovereign King.', 'Ussher: 1491 BC (AM 2513), third month after Exodus.', 320),
(17, 'Wilderness Wandering', -1491, -1451, 0, 0, 'traditional', 'judgment', 'moderate', 'After refusing to enter Canaan at the spies'' fearful report, Israel wanders the wilderness for forty years until the unbelieving generation passes away. Sustained by manna, water from the rock, and the guiding cloud, the nation is disciplined and shaped for covenant life in the promised land.', 'Ussher: 1491-1451 BC.', 330),
(18, 'Tabernacle Completed', -1490, NULL, 0, 0, 'traditional', 'worship', 'moderate', 'Following the pattern revealed on Sinai, Israel completes the tabernacle, a portable tent sanctuary where God''s glory descends to dwell at the center of the camp. Its gilded frames recall Egyptian portable shrines of the era, while its design anticipates the temple and, for Christians, the incarnation.', 'Ussher: 1490 BC (Exod 40:17). One year after the Exodus.', 350),
(401, 'Joseph Reveals Himself to His Brothers', -1706, NULL, 0, 1, 'probable', 'salvation', 'moderate', 'After two years of famine, with five still to come, Joseph can hold back no longer and tells his brothers who he is. He assures them that God sent him ahead to preserve life, and sends for his father Jacob to come to Egypt.', 'Scripture: Gen 45:6, two years of famine behind and five ahead; the famine began 1708 BC (Joseph ruler at 30 in 1715 + seven plenteous years, Gen 41:46-53), so 1706 BC. Ussher, Annals section 137 agrees: 1706 BC, the same year Jacob''s household went down (section 138, the beginning of the third year of the famine). The first journey, when Simeon was held, is 1707 BC (section 134).', 230),
(402, 'Jacob Blesses His Sons and Dies', -1689, NULL, 0, 1, 'probable', 'death', 'moderate', 'Gathered at his bedside in Egypt, Jacob adopts Joseph''s sons Ephraim and Manasseh and pronounces a blessing over each of his twelve sons, including the promise that the sceptre will not depart from Judah. He charges them to bury him at Machpelah and dies; Joseph and his brothers carry him to Canaan.', 'Scripture: Jacob lived 17 years in Egypt and was 147 at his death (Gen 47:28), so 1706 - 17 = 1689 BC. Ussher, Annals section 145, agrees (1689 BC, AM 2315).', 250),
(403, 'Birth of Moses', -1571, NULL, 0, 1, 'probable', 'birth', 'moderate', 'In the days when Pharaoh ordered every newborn Hebrew boy thrown into the Nile, a Levite woman hides her son for three months and then sets him afloat in a basket of reeds. Pharaoh''s daughter finds him and raises him as her own, with his own mother as nurse.', 'Scripture: Moses was 80 when he spoke to Pharaoh (Exod 7:7), the year of the Exodus (1491 BC), so 1571 BC; he died at 120 (Deut 34:7) in 1451 BC. Ussher, Annals section 162, agrees. The Exodus year itself is Ussher''s, from the 430 years of Exod 12:40-41 and Gal 3:17 counted from Abraham''s call in 1921 BC. Most modern scholars place Moses a century or more later.', 260),
(404, 'Moses at the Burning Bush', -1491, NULL, 0, 1, 'probable', 'prophecy', 'moderate', 'While tending Jethro''s flock at Horeb, Moses sees a bush that burns without being consumed, and God calls him by name to bring Israel out of Egypt. God reveals his name, "I AM THAT I AM," and sends Aaron to speak for Moses.', 'Ussher: Moses was eighty when he stood before Pharaoh (Exod 7:7), which puts his call in 1491 BC, shortly before the Exodus; the interval is not given in the text. Ussher, Annals §172: 1491 BC (AM 2513).', 270),
(405, 'The Ten Plagues and the First Passover', -1491, NULL, 0, 1, 'probable', 'judgment', 'major', 'When Pharaoh refuses to let Israel go, ten plagues strike Egypt, from the Nile turned to blood to the death of the firstborn. Israel is spared by the blood of the Passover lamb on their doorposts, and Pharaoh at last sends them out; the feast is kept as a lasting memorial.', 'Ussher: the plagues fall in the months before the Exodus in 1491 BC, ending with the Passover on the fourteenth day of the first month (Exod 12:6). Annals §179-190.', 280),
(406, 'The Golden Calf', -1491, NULL, 0, 1, 'probable', 'worship', 'moderate', 'While Moses is on Sinai receiving the tablets, the people press Aaron to make them gods, and he casts a golden calf. Moses breaks the tablets, destroys the calf, and intercedes for the people; the Levites rally to him, and about three thousand die.', 'Ussher: 1491 BC, during the forty days Moses spent on Sinai soon after the giving of the Law (Exod 24:18; 32:1). Annals §198-199 (AM 2513d, fourth month).', 290),
(407, 'The Twelve Spies at Kadesh', -1490, NULL, 0, 1, 'probable', 'judgment', 'moderate', 'Moses sends twelve men, one from each tribe, to explore Canaan. Ten bring back a report of giants and walled cities, and the people refuse to enter; only Joshua and Caleb urge them on, and God decrees forty years in the wilderness for that generation.', 'Ussher: the second year after the Exodus (Num 10:11; 13:20), 1490 BC. Annals §239-241.', 340),
(408, 'Balaam and Balak', -1452, NULL, 0, 1, 'probable', 'prophecy', 'moderate', 'Balak, king of Moab, hires the seer Balaam to curse Israel camped on the plains of Moab. Balaam''s donkey sees the angel he cannot, and each time he opens his mouth he can only bless, including a prophecy of a star out of Jacob and a sceptre out of Israel.', 'Ussher: the fortieth year in the wilderness (1452 BC), after Israel''s defeat of Sihon and Og (Num 21) and before the death of Moses. Annals §281-284.', 360);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(19, 'Conquest of Canaan', -1451, -1445, 0, 0, 'traditional', 'conquest', 'major', 'Under Joshua, Israel crosses the Jordan and campaigns through Canaan, defeating coalitions of kings and allotting the land among the twelve tribes. Destruction layers at sites like Hazor, the greatest Canaanite city of the region, fuel lively scholarly debate over the conquest''s scope and character.', 'Ussher: the war began in 1451 BC (AM 2553), after forty years in the wilderness, and ended in 1445 BC, when Caleb was 85 (Josh 14:7-10) and "the land rested from war" (Josh 11:23; 14:15). Early-date scholars place the conquest c. 1406 BC; late-date scholars c. 1220 BC.', 410),
(20, 'Fall of Jericho', -1451, NULL, 0, 0, 'traditional', 'miracle', 'moderate', 'Israel circles Jericho for seven days behind the ark until the walls collapse at the trumpet blast and shout, giving Joshua his first victory in Canaan; only faithful Rahab''s family is spared. Famous excavations by John Garstang and Kathleen Kenyon made Jericho a landmark case in biblical archaeology.', 'Ussher: 1451 BC.', 420),
(21, 'Period of the Judges', -1443, -1095, 1, 0, 'traditional', 'other', 'moderate', 'Between Joshua and the monarchy, Israel cycles through apostasy, oppression, and rescue as God raises deliverers such as Deborah, Gideon, and Samson. Archaeology reveals a surge of small highland villages in this era, the material footprint of early Israel taking root in Canaan''s hill country.', 'Scripture first. 1 Kgs 6:1 puts Solomon''s fourth year, when the Temple was founded (1012 BC), in the 480th year from the Exodus: 1491 to 1012 is 479 years and 16 days (Ussher, Annals 465, 4053). Inside that span Scripture gives 40 years in the wilderness, Saul 40 (Acts 13:21), David 40 (1 Kgs 2:11) and three full years of Solomon, leaving 356 years from the crossing of the Jordan (1451) to Saul (1095) for Joshua, the elders and every judge. The judges'' own figures (Cushan 8, rest 40, Moab 18, rest 80, Jabin 20, rest 40, Midian 7, Gideon 40, Abimelech 3, Tola 23, Jair 22, Ammon 18, Jephthah 6, Ibzan 7, Elon 10, Abdon 8, Philistines 40) total 390 if laid end to end, before Joshua, Eli and Samuel, so they cannot all run in sequence if 1 Kgs 6:1 stands. Ussher reconciles them as follows. (1) Each rest figure (Judg 3:11, 3:30, 5:31, 8:28) is counted from the previous deliverance and so contains the oppression that ended it: Othniel 1405 (40 years from the rest of c. 1445, Cushan 1413-1405), Ehud 1325 (80 years from Othniel, Moab 1343-1325), Deborah 1285 (40 from Ehud, Jabin 1305-1285), Gideon 1245 (40 from Deborah, Midian 1252-1245; he died 1236). (2) The Ammonite oppression (1206-1188) runs inside Jair''s 22 years, and the Philistine forty years inside Eli''s forty and Samson''s twenty (Samson died 1117, Eli 1116). The sequence then reads Abimelech 1236-1233, Tola to 1210, Jair to 1188, Jephthah to 1182, Ibzan, Elon and Abdon to 1157, Eli 1156-1116, Samuel at Mizpah 1096 and Saul 1095. Acts 13:20 ("about 450 years") does not conflict: Ussher (Annals 337) counts it from the birth of Isaac (1896) to the allotment of the land (1445), about 451 years. The start is Joshua''s death, 1443 BC (Ussher, Annals 340; Judg 1:1), and is approximate. Mainstream scholarship places the judges c. 1200-1050 BC, many of them regional and overlapping.', 440),
(22, 'Deborah Defeats Sisera', -1285, NULL, 0, 1, 'possible', 'war', 'moderate', 'Deborah and Barak defeat Canaanite general Sisera.', 'Ussher: c. 1285 BC, after twenty years of oppression by Jabin (Judg 4:3). Annals §351 (AM 2719d).', 450),
(23, 'Gideon Defeats Midian', -1245, NULL, 0, 1, 'possible', 'war', 'moderate', 'Gideon defeats the Midianites with 300 men.', 'Ussher: c. 1245 BC, after seven years of Midianite oppression (Judg 6:1). Annals §354, §356 (AM 2759d).', 460),
(24, 'Ark Captured by Philistines', -1116, NULL, 0, 1, 'traditional', 'judgment', 'minor', 'The Philistines capture the Ark of the Covenant at the battle of Aphek. Eli dies upon hearing the news.', 'Ussher: 1116 BC (1 Sam 4:1-22). Eli, aged 98, died on hearing the news, having judged Israel forty years (1 Sam 4:15-18). Annals §386 (AM 2888d); §365 has Eli dying in AM 2888.', 530),
(320, 'Death of Moses', -1451, NULL, 0, 0, 'traditional', 'death', 'moderate', 'At 120 years old, his eye not dim nor his strength abated, Moses climbs Mount Nebo, views the promised land, and dies in Moab; the LORD buries him in a valley there and no one knows his grave. Israel mourns thirty days, and Joshua, full of the spirit of wisdom, leads in his place.', 'Ussher: 1451 BC, in the last month of the 40th year after the Exodus (Deut 1:3; 34:5-8).', 370),
(321, 'Israel Crosses the Jordan', -1451, NULL, 0, 0, 'traditional', 'miracle', 'moderate', 'On the tenth day of the first month, the priests bearing the ark step into the Jordan in flood and the waters stand up in a heap; the whole nation crosses on dry ground. Twelve stones from the riverbed are set up at Gilgal as a memorial.', 'Ussher: 1451 BC, forty years after the Exodus (Josh 4:19).', 380),
(322, 'Death of Joshua', -1443, NULL, 1, 1, 'possible', 'death', 'moderate', 'Joshua son of Nun dies at 110 and is buried at Timnath-serah in Mount Ephraim. Israel serves the LORD all his days and the days of the elders who outlived him.', 'Scripture: he died aged 110 (Josh 24:29-30) and Israel served the LORD all the days of the elders who outlived him (Josh 24:31; Judg 2:7); no year is given. Ussher, Annals 340-341: AM 2561, 1443 BC, placed in the same year as his building of Timnath-serah, after the land had rest (Josh 23:1; 1445 BC); the apostasy and the first oppression (Cushan, eight years, 1413-1405 BC) follow. Marked approximate because Ussher places it by summary. An earlier figure of c. 1426 BC came from Josephus (Antiquities 5.117, 25 years of leadership after Moses), which is neither Scripture nor Ussher.', 430),
(326, 'Jephthah Defeats the Ammonites', -1188, NULL, 0, 1, 'traditional', 'war', 'moderate', 'Recalled from exile by the elders of Gilead, Jephthah argues Israel''s title to the land and then defeats the Ammonites, ending eighteen years of oppression. His vow to offer whatever first came out of his house to meet him falls on his only daughter.', 'Ussher: 1188 BC, ending the eighteen-year oppression begun c. 1206 BC (Judg 10:8). Annals §367-371.', 470),
(327, 'Death of Samson', -1117, NULL, 0, 1, 'traditional', 'death', 'moderate', 'Blinded and set to grind in the prison at Gaza after Delilah''s betrayal, Samson is brought out to entertain the Philistines at a feast to Dagon. Praying for strength one last time, he pulls down the pillars of the temple, killing more Philistines at his death than in his life.', 'Ussher: 1117 BC, after Samson had judged Israel twenty years (Judg 15:20; 16:31). Annals §384.', 520),
(329, 'Samuel Judges Israel at Mizpah', -1096, NULL, 0, 1, 'traditional', 'war', 'moderate', 'After twenty years of the ark at Kirjath-jearim, Samuel calls Israel to put away their idols and gathers them at Mizpah to fast and confess. When the Philistines attack, the LORD thunders against them and Israel routs them; Samuel sets up the stone Ebenezer, "Hitherto hath the LORD helped us."', 'Ussher: 1096 BC, twenty years after the ark came to Kirjath-jearim (1 Sam 7:2) and a year before Saul. Annals §390 (AM 2908c).', 540),
(409, 'Achan''s Sin and the Defeat at Ai', -1451, NULL, 0, 1, 'probable', 'conquest', 'moderate', 'After Jericho, Achan keeps some of the devoted spoil, and Israel is routed in its first attack on Ai. When Achan is exposed by lot and put to death, Israel takes Ai by an ambush.', 'Ussher: the first year in Canaan (1451 BC), directly after the fall of Jericho (Josh 6-8). Annals §313.', 390),
(410, 'The Sun Stands Still at Gibeon', -1451, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'Five Amorite kings attack Gibeon, which had made peace with Israel. Joshua marches up overnight and, as the enemy flees, asks the Lord that the sun and moon stand still; the day is lengthened and the kings are defeated.', 'Ussher, Annals §315-319: 1451 BC (AM 2553c), the same year as the crossing of the Jordan and the fall of Jericho; §320 sums up "that most busy year of the world, 2553".', 400),
(411, 'Birth of Samson', -1155, NULL, 0, 1, 'probable', 'birth', 'moderate', 'An angel of the Lord promises a barren wife of Dan that she will bear a son who will begin to deliver Israel from the Philistines, and Samson is born a Nazirite from the womb. His parents Manoah and his wife are told he must never touch a razor or strong drink.', 'Ussher, Annals §380: born 1155 BC (AM 2849b), soon after the forty-year Philistine oppression began (§378). He judged Israel twenty years, 1137-1117 BC (§382, §384).', 490),
(412, 'Ruth and Boaz', -1172, -1170, 1, 0, 'possible', 'other', 'moderate', 'Naomi returns to Bethlehem from Moab with her widowed daughter-in-law Ruth, who gleans in the field of Boaz and wins his notice. Boaz redeems the family''s land and marries Ruth, and their son Obed becomes the grandfather of David.', 'The book says only "in the days when the judges ruled" (Ruth 1:1). The years are estimated back from Obed''s birth c. 1170 BC and David''s birth in 1085 BC (Ruth 4:17-22), as in the life dates of Ruth, Naomi and Boaz.', 480),
(413, 'Hannah''s Prayer and the Birth of Samuel', -1150, NULL, 1, 1, 'possible', 'birth', 'moderate', 'Childless Hannah weeps and prays at Shiloh, vowing to give a son to the Lord if he will grant her one. Eli blesses her, Samuel is born, and when he is weaned she brings him to serve at the sanctuary and sings a song of thanks.', 'Ussher: the Eli years run 1157-1116 BC (Annals §378, §386), and Samuel was a child at Shiloh before Eli''s death; 1150 BC follows the table''s birth year for Samuel (approximate).', 500),
(414, 'The Call of Samuel', -1138, NULL, 1, 1, 'possible', 'prophecy', 'moderate', 'As a boy serving under Eli, Samuel hears his name called in the night and learns it is the Lord. The word he receives is a judgment on Eli''s house, and from then on all Israel knows that Samuel is a prophet.', 'Scripture gives Samuel''s age only as a boy (1 Sam 3:1). Josephus says twelve, which gives about 1138 BC from the table''s birth year; the date is approximate.', 510);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(25, 'Saul Anointed King', -1095, NULL, 0, 1, 'traditional', 'kingdom', 'major', 'When the people demand a king like the nations, God directs Samuel to anoint Saul of Benjamin as Israel''s first monarch. Tall, striking, and initially victorious over Ammon and the Philistines, Saul forfeits his dynasty through disobedience, opening the way for David''s rise.', 'Ussher, Annals 391: 1095 BC. Scripture: Saul reigned forty years (Acts 13:21); 1 Sam 13:1 is textually difficult in the Hebrew (the age and length of reign are damaged or missing), so Acts 13:21 is the figure used. Mainstream scholarship places his accession c. 1050 BC.', 550),
(26, 'David Anointed by Samuel', -1063, NULL, 0, 1, 'traditional', 'kingdom', 'moderate', 'God sends Samuel to Bethlehem to anoint David, Jesse''s youngest son and a shepherd, declaring that the Lord looks on the heart rather than outward stature. The Tel Dan inscription''s reference to the house of David gives his dynasty its earliest extrabiblical attestation.', 'Ussher, Annals §395: 1063 BC, forty years before Absalom''s revolt (2 Sam 15:7); David was then a youth keeping his father''s sheep (1 Sam 16:11-12). He became king at Hebron only after Saul''s death, in 1055 BC.', 580),
(27, 'David Captures Jerusalem', -1048, NULL, 0, 1, 'traditional', 'conquest', 'moderate', 'David takes the Jebusite stronghold of Zion and makes Jerusalem his capital, uniting the tribes around a city belonging to none of them; a few years later he brings the ark there (2 Sam 6). Excavations in the City of David, including the massive Stepped Stone Structure, illuminate the ancient citadel he claimed.', 'Ussher: 1048 BC, at the start of David''s 33 years in Jerusalem (2 Sam 5:5-9).', 630),
(28, 'Davidic Covenant', -1044, NULL, 0, 1, 'traditional', 'covenant', 'major', 'Through the prophet Nathan, God promises David an everlasting house, kingdom, and throne, pledging a son whose reign will never end. This oath anchors the royal psalms and Israel''s prophetic hope, and the New Testament proclaims Jesus, son of David, as its ultimate fulfillment.', 'Ussher, Annals §428: 1044 BC, when David was settled in his house of cedar (2 Sam 7:1-2).', 650),
(29, 'Solomon Builds Temple', -1012, -1005, 0, 0, 'traditional', 'worship', 'major', 'Solomon builds the first temple on Jerusalem''s Mount Moriah, a cedar-lined house of hewn stone where the ark comes to rest and God''s glory fills the sanctuary at its dedication. Its long-room, tripartite plan resembles excavated Syrian temples such as Ain Dara, rooting it firmly in its ancient world.', 'Scripture: begun in the fourth year of Solomon''s reign, the 480th year after the Exodus (1 Kgs 6:1), in the month Zif; finished in the eleventh year, in the month Bul, "seven years" in building (6:37-38); Solomon''s own house then took thirteen years (7:1), 1005-992 BC. Ussher, Annals 465: begun 1012 BC (AM 2992). Mainstream chronology (Thiele) dates the start c. 966 BC.', 710),
(323, 'Death of Saul at Gilboa', -1055, NULL, 0, 0, 'traditional', 'death', 'moderate', 'Routed by the Philistines on Mount Gilboa, with Jonathan and two other sons already dead, the wounded Saul falls on his own sword. The men of Jabesh-gilead recover the bodies from the wall of Beth-shan and bury them.', 'Ussher, Annals 405: 1055 BC, closing Saul''s forty-year reign (Acts 13:21; 1 Sam 31). David was thirty and Ish-bosheth forty at their accessions the same year (2 Sam 5:4; 2 Sam 2:10).', 600),
(324, 'David Made King at Hebron', -1055, NULL, 0, 0, 'traditional', 'kingdom', 'moderate', 'After Saul''s death, David goes up to Hebron and the men of Judah anoint him king over the house of Judah. Abner sets up Saul''s son Ish-bosheth over the other tribes, and David reigns in Hebron seven and a half years.', 'Scripture: David was thirty when he began to reign, forty years in all, seven years and six months at Hebron over Judah and thirty-three at Jerusalem over all Israel and Judah (2 Sam 5:4-5; 1 Kgs 2:11). Ussher, Annals 409-410: 1055 BC, the year Saul died.', 610),
(325, 'David Anointed King over All Israel', -1048, NULL, 0, 0, 'traditional', 'kingdom', 'moderate', 'After Abner''s death and the murder of Ish-bosheth, the elders of all the tribes come to David at Hebron, make a covenant with him, and anoint him king over Israel. He goes on to reign thirty-three years over all Israel and Judah.', 'Scripture: seven years and six months at Hebron (2 Sam 5:5). Ussher, Annals 413-416: 1048 BC, after Abner''s defection and Ish-bosheth''s murder; David was thirty-seven.', 620),
(328, 'David Defeats Goliath', -1063, NULL, 1, 1, 'possible', 'war', 'major', 'In the valley of Elah the Philistine champion Goliath of Gath defies the armies of Israel for forty days. The young David, sent by Jesse with food for his brothers, faces him in the name of the LORD and kills him with a sling stone, and Israel routs the Philistines.', 'Year estimated: soon after Samuel anointed David (Ussher c. 1063 BC) and before David fled from Saul to Gath (Ussher 1060 BC).', 570),
(330, 'David Brings the Ark to Jerusalem', -1045, NULL, 0, 1, 'traditional', 'worship', 'moderate', 'David brings the ark up from Kirjath-jearim; after Uzzah is struck down it rests three months in the house of Obed-edom, then enters the city of David with sacrifice and dancing. Michal despises David for dancing before the LORD.', 'Ussher, Annals §422: 1045 BC, a sabbatical year (2 Sam 6; 1 Chr 13; 15-16).', 640),
(415, 'Saul Rejected as King', -1079, NULL, 1, 1, 'possible', 'judgment', 'moderate', 'Sent to destroy the Amalekites, Saul spares their king Agag and the best of the flocks and then offers excuses. Samuel tells him that obedience is better than sacrifice and that the Lord has rejected him as king.', 'The text gives no year, and Ussher dates none (Annals §395 says only that Saul had been rejected before Samuel anointed David in 1063 BC). Placed in the middle of Saul''s reign (1095-1055 BC); approximate.', 560),
(416, 'David Spares Saul at En-gedi', -1059, NULL, 1, 1, 'possible', 'other', 'moderate', 'Pursued by Saul with three thousand men, David is hidden in a cave where Saul comes in alone. He cuts off a corner of Saul''s robe but refuses to harm the Lord''s anointed, and Saul weeps and admits that David will be king.', 'The text gives no year and Ussher does not date it; it falls between David''s flight to Gath (Ussher §397, 1060 BC) and Saul''s death (1055 BC) and is approximate.', 590),
(417, 'David and Bathsheba', -1035, NULL, 0, 1, 'probable', 'other', 'moderate', 'David sees Bathsheba bathing, takes her, and arranges the death of her husband Uriah at the siege of Rabbah. The prophet Nathan confronts him with the story of the ewe lamb, and David confesses (Ps 51); the child dies, and Solomon is born to them later.', 'Ussher: 1035 BC (2 Sam 11), the year given for Uriah''s death in this table.', 660),
(418, 'Absalom Kills Amnon', -1030, NULL, 0, 1, 'probable', 'death', 'minor', 'Amnon wrongs his half-sister Tamar, and her brother Absalom hides his anger for two years before having Amnon killed at a sheepshearing feast. Absalom flees to Geshur, and David mourns for both sons.', 'Ussher, Annals §437: 1030 BC, two years after Amnon''s rape of Tamar (§436, 1032 BC); Absalom then spent three years in Geshur (§438) and returned in 1027 BC (§439).', 670),
(419, 'Absalom''s Revolt', -1023, NULL, 0, 1, 'probable', 'war', 'moderate', 'Absalom wins the hearts of Israel, has himself proclaimed king at Hebron, and drives David out of Jerusalem. Hushai''s counsel defeats Ahithophel''s, David''s army wins in the forest of Ephraim, and Joab kills Absalom against the king''s orders.', 'Ussher, Annals §442: 1023 BC, forty years after Samuel anointed David (2 Sam 15:7), between Passover and Pentecost; Absalom died the same year (§445).', 680),
(420, 'Solomon Anointed King', -1015, NULL, 0, 1, 'probable', 'kingdom', 'moderate', 'As David lies dying, Adonijah has himself proclaimed king. Bathsheba and Nathan appeal to David, who has Zadok and Nathan anoint Solomon at Gihon, and David dies soon after.', 'Ussher: 1015 BC, the year David died and Solomon began to reign (1 Kgs 2:10-11).', 690),
(421, 'Solomon Asks for Wisdom', -1013, NULL, 0, 1, 'possible', 'other', 'moderate', 'At Gibeon Solomon offers a thousand burnt offerings, and God appears to him in a dream, offering whatever he asks. He asks for an understanding heart to judge the people, and is given wisdom, riches and honour besides.', 'Ussher, Annals §463: 1013 BC (AM 2991c), at Gibeon, after Solomon''s marriage to Pharaoh''s daughter (§462, 1014 BC). The text of Kings gives no year.', 700),
(422, 'Dedication of the Temple', -1004, NULL, 0, 1, 'probable', 'worship', 'moderate', 'Once the Temple is complete the priests carry the ark into the Most Holy Place, and a cloud fills the house so that they cannot minister. Solomon prays before the altar, blesses the people, and holds a seven-day festival.', 'Ussher: 1004 BC, the year after the Temple was finished (1 Kgs 6:38; 8:2); some place it in the same year as completion.', 720),
(423, 'Solomon''s Apostasy', -985, NULL, 1, 1, 'possible', 'judgment', 'moderate', 'In his old age Solomon''s many foreign wives turn his heart to their gods, and he builds high places for Chemosh and Molech. The Lord tells him the kingdom will be torn away from his son, and the prophet Ahijah promises Jeroboam ten tribes.', 'The text gives no year, only that it happened when Solomon was old (1 Kgs 11:4), before his death in 975 BC.', 730);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(30, 'Kingdom Divides', -975, NULL, 0, 1, 'traditional', 'kingdom', 'major', 'After Solomon''s death, Rehoboam''s harsh answer at Shechem drives ten northern tribes to crown Jeroboam, splitting the nation into Israel and Judah. The rupture sets the two kingdoms on divergent paths, and Pharaoh Shishak''s invasion, carved at Karnak, soon exploited their weakness.', 'Ussher: 975 BC (AM 3029), upon Solomon''s death. Thiele and most modern scholars date the division c. 931/930 BC.', 750),
(31, 'Elijah on Mount Carmel', -905, NULL, 1, 1, 'traditional', 'miracle', 'moderate', 'On Mount Carmel, Elijah stands alone against the prophets of Baal, and fire from heaven consumes his water-drenched sacrifice, turning Israel''s heart back to the Lord. The contest confronts Baal, the Canaanite storm god, on his own claimed terrain of fire and rain, and ends a long drought at God''s word.', 'Ussher: during Ahab''s reign (918-897 BC). 1 Kgs 18:20-40.', 840),
(32, 'Fall of Samaria', -721, NULL, 0, 1, 'certain', 'judgment', 'major', 'Shalmaneser of Assyria besieges Samaria three years, from Hoshea''s seventh year, and takes it in the sixth year of Hezekiah, the ninth of Hoshea. The Israelites are carried to Halah, Habor and Gozan and the cities of the Medes, and foreigners are settled in their place, which ends the northern kingdom (2 Kgs 17:3-6, 24; 18:9-11). Mainstream scholarship credits Sargon II, whose annals boast of 27,290 captives.', 'Scripture: Hezekiah''s 6th year and Hoshea''s 9th (2 Kgs 18:10); Ussher, Annals §633: 721 BC (AM 3283), toward the end of the third year of the siege begun in Hoshea''s 7th. Mainstream: 722 or 721 BC.', 1070),
(33, 'Hezekiah''s Deliverance', -713, NULL, 0, 1, 'probable', 'salvation', 'moderate', 'When Sennacherib''s armies overrun Judah, Hezekiah spreads the Assyrian threat before the Lord and Isaiah promises rescue; the invader withdraws with Jerusalem untaken. Sennacherib''s prism boasts of shutting Hezekiah up like a caged bird yet claims no capture, while the Lachish reliefs depict the campaign''s fury.', 'Ussher, Annals §642, §645: 713 BC, the end of the 14th year of Hezekiah (2 Kgs 18:13; Isa 36:1), fifteen years before his death in 698 (2 Kgs 20:6). (The Annals place the Egyptian campaign and Lachish under 710 BC, but §645 fixes the slaughter in Hezekiah''s 14th year.) Sennacherib''s prism dates the campaign to 701 BC, which most scholars follow, placing Hezekiah''s accession c. 715 BC.', 1090),
(34, 'Josiah''s Reforms', -624, NULL, 0, 1, 'probable', 'worship', 'moderate', 'King Josiah finds the Book of the Law and reforms worship.', 'Ussher, Annals §742: 624 BC, the 18th year of Josiah (2 Kgs 22:3; 2 Chr 34:8), counting his accession as 641 BC. Ussher takes the covenant renewal as the start of the 30 years of Ezek 1:1, which end at Ezekiel''s call in 595 BC. The purge had begun in his 12th year (2 Chr 34:3). Modern scholarship: 622 BC.', 1150),
(94, 'Healing of Naaman', -890, NULL, 1, 1, 'possible', 'miracle', 'moderate', 'Naaman, commander of Aram''s army, sought healing from leprosy on the word of a captive Israelite servant girl. Directed by the prophet Elisha to wash seven times in the Jordan, he was cleansed and confessed Israel''s God; Jesus later cited him at Nazareth as a Gentile who received God''s mercy.', '2 Kgs 5:1-27; during the ministry of Elisha, in the reign of Jehoram of Israel (896-884 BC on Ussher''s chain). Year estimated.', 910),
(430, 'Jeroboam''s Golden Calves', -975, NULL, 0, 1, 'probable', 'worship', 'moderate', 'Fearing that pilgrimage to Jerusalem would draw his people back to Rehoboam, Jeroboam sets up golden calves at Bethel and Dan and appoints his own priests and feast. The Bible repeatedly names this the sin of Jeroboam that Israel''s later kings never abandoned.', 'Ussher: 975 BC, the year of the division (1 Kgs 12:25-33). Mainstream chronology places the division c. 931/930 BC.', 740),
(431, 'Shishak Invades Judah', -971, NULL, 1, 1, 'probable', 'war', 'moderate', 'In Rehoboam''s fifth year Shishak of Egypt marches against Jerusalem with a great army. Rehoboam and the princes humble themselves, and the city is spared, but the temple and palace treasures, including Solomon''s gold shields, are carried off.', 'Ussher: 971 BC, Rehoboam''s 5th year (1 Kgs 14:25; 2 Chr 12:2). Shishak is Pharaoh Shoshenq I; his Karnak relief records the campaign, usually dated c. 925 BC.', 760),
(432, 'Abijah Defeats Jeroboam at Mount Zemaraim', -957, NULL, 0, 1, 'probable', 'war', 'minor', 'Abijah of Judah calls out to Jeroboam and his army from Mount Zemaraim, reminding Israel of the Lord''s covenant with David. Trusting in God, Judah wins a great victory and takes Bethel and nearby towns.', 'Ussher, Annals §487: 957 BC (3047c AM), Abijah''s 2nd year and Jeroboam''s 19th (2 Chr 13). Mainstream chronology dates Abijah about 30 years later.', 770),
(433, 'Baasha Destroys the House of Jeroboam', -953, NULL, 0, 1, 'probable', 'kingdom', 'minor', 'Baasha of Issachar assassinates Nadab, son of Jeroboam, during the siege of Gibbethon, and kills every member of Jeroboam''s family. It fulfils the word of the prophet Ahijah and begins a new dynasty that proves no better.', 'Ussher: 953 BC, Nadab''s 2nd year (1 Kgs 15:25-30).', 780),
(434, 'Asa''s Reform and Covenant', -941, NULL, 0, 1, 'probable', 'reform', 'moderate', 'After defeating Zerah the Ethiopian, Asa hears the prophet Azariah and removes idols from Judah. He deposes his grandmother Maacah as queen mother for her idol and gathers the people to renew the covenant by oath.', 'Ussher, Annals §492, §494: 941 BC (3063c AM), Asa''s 15th year, in the third month (2 Chr 15:10). Mainstream dates are about 30 years later.', 790),
(435, 'Zimri''s Coup and Omri''s Rise', -929, NULL, 0, 1, 'probable', 'kingdom', 'minor', 'Zimri murders King Elah while he is drunk and destroys Baasha''s house, but reigns only seven days. When the army besieging Gibbethon proclaims its commander Omri king, Zimri burns the palace over himself.', 'Ussher: 929 BC, Elah''s 2nd year (1 Kgs 16:8-20).', 800),
(436, 'Omri Founds Samaria', -924, NULL, 0, 1, 'probable', 'kingdom', 'moderate', 'Omri buys the hill of Shemer and builds Samaria as the new capital of the northern kingdom. It remains the capital until its fall two centuries later, and Assyrian records still call Israel the land of the house of Omri.', 'Ussher, Annals §505: 924 BC (3080d AM), when Omri had reigned 6 years in Tirzah (1 Kgs 16:23-24); his reign counts from 929 BC (§500-501). Mainstream c. 880 BC.', 810),
(437, 'Elijah Fed by Ravens and the Widow of Zarephath', -910, -906, 1, 1, 'possible', 'miracle', 'moderate', 'Elijah announces a drought to Ahab, then is fed by ravens at the brook Cherith and, when it dries up, by a Phoenician widow in Zarephath whose flour and oil never run out. He raises her son from death, and she confesses that the word of the Lord in his mouth is truth.', 'Ussher: the drought began c. 910 BC and lasted three and a half years (1 Kgs 17:1; Luke 4:25; Jas 5:17).', 830),
(438, 'Elijah at Mount Horeb', -904, NULL, 1, 1, 'possible', 'prophecy', 'moderate', 'Fleeing Jezebel''s threat, Elijah walks to Horeb, where the Lord comes to him not in wind, earthquake or fire but in a still small voice. He is sent to anoint Hazael, Jehu and Elisha, and finds Elisha ploughing.', 'Ussher: shortly after the contest on Carmel (1 Kgs 19). The year is an estimate.', 850),
(439, 'Naboth''s Vineyard', -899, NULL, 0, 1, 'probable', 'judgment', 'moderate', 'Naboth refuses to sell his family vineyard beside the palace at Jezreel. Jezebel arranges his death by false witnesses and Ahab seizes the land, and Elijah meets him there with God''s sentence on his house.', 'Ussher, Annals §514: 899 BC (3105 AM), Ahab''s 20th year, the year after Ben-hadad''s surrender, two years before Ahab''s death in 897 BC (1 Kgs 21).', 860),
(440, 'Jehoshaphat''s Reforms', -912, NULL, 0, 1, 'probable', 'reform', 'moderate', 'Jehoshaphat removes the high places, sends officials and Levites through Judah with the book of the law, and later appoints judges in the fortified cities with the charge to judge for the Lord. His reign is remembered as a time of peace and teaching.', 'Ussher, Annals §509: 912 BC (3092c AM), the 3rd year of his reign (914-889 BC; 2 Chr 17:7-10). The later judges (2 Chr 19:4-11) are not dated by Ussher.', 820),
(441, 'Death of Ahab at Ramoth-gilead', -897, NULL, 0, 1, 'probable', 'war', 'moderate', 'Ahab and Jehoshaphat go to war against Aram to retake Ramoth-gilead. The prophet Micaiah foretells defeat, and Ahab, though disguised, is killed by an arrow shot at random, as Elijah had said.', 'Ussher: 897 BC, the last year of Ahab (1 Kgs 22; 2 Chr 18).', 870),
(442, 'Elijah Calls Fire on Ahaziah''s Messengers', -896, NULL, 0, 1, 'probable', 'judgment', 'minor', 'Ahaziah of Israel, injured in a fall, sends to ask Baal-zebub of Ekron whether he will recover. Elijah intercepts the messengers with the Lord''s rebuke, and fire falls on two companies of soldiers sent to seize him before the third captain begs for mercy.', 'Ussher, Annals §521: 896 BC (3108b AM), Ahaziah''s fall and death in Samaria, before Elijah was taken up (2 Kgs 1).', 880),
(443, 'Elijah Taken Up and Elisha Succeeds Him', -896, NULL, 0, 1, 'probable', 'miracle', 'major', 'At the Jordan Elijah parts the water and is carried up to heaven in a whirlwind with a chariot and horses of fire. Elisha takes up his fallen mantle, asks for a double portion of his spirit and parts the river again.', 'Ussher, Annals §523: 896 BC (3108c AM), the first year of Jehoram of Israel (2 Kgs 2).', 890),
(444, 'Israel and Judah Attack Moab', -895, NULL, 0, 1, 'probable', 'war', 'minor', 'Jehoram of Israel, Jehoshaphat and the king of Edom march against Moab after Mesha stops paying tribute. With no water for the army, Elisha promises a miraculous flood, and the allies drive Moab back to Kir-hareseth.', 'Ussher, Annals §524: 895 BC (3109c AM), Jehoram of Israel''s 2nd year, while Edom was still under Judah (2 Kgs 3). Moab''s side is told in the Mesha Stele.', 900),
(445, 'Hazael Becomes King of Aram', -885, NULL, 1, 1, 'possible', 'kingdom', 'minor', 'Ben-hadad of Damascus, ill, sends Hazael to ask Elisha whether he will recover. Elisha weeps at what Hazael will do to Israel; the next day Hazael smothers the king and takes the throne.', 'Ussher does not date the accession itself: Annals §533 says that by 884 BC (Ramoth-gilead) Hazael had recently succeeded Benhadad as Elisha foretold (2 Kgs 8:7-15); c. 885 BC is the estimate. Assyrian records of Shalmaneser III also name Hazael as king of Damascus.', 920),
(446, 'Jehu''s Revolt', -884, NULL, 0, 1, 'probable', 'judgment', 'moderate', 'Elisha sends a young prophet to anoint Jehu, an army commander at Ramoth-gilead. Jehu drives to Jezreel and kills Jehoram of Israel and Ahaziah of Judah, Jezebel is thrown from her window, and Ahab''s seventy sons and the priests of Baal are destroyed.', 'Ussher: 884 BC (2 Kgs 9-10); the Black Obelisk of Shalmaneser III shows Jehu paying tribute, usually dated c. 841 BC.', 930),
(447, 'Athaliah Seizes the Throne of Judah', -884, -878, 0, 1, 'probable', 'kingdom', 'moderate', 'When her son Ahaziah is killed, Athaliah destroys the royal family of Judah and rules for six years. Only the infant Joash is saved, hidden in the temple by his aunt Jehosheba.', 'Ussher: 884-878 BC (2 Kgs 11:1-3; 2 Chr 22:10-12).', 940),
(448, 'Joash Crowned by Jehoiada', -878, NULL, 0, 1, 'probable', 'kingdom', 'moderate', 'In the seventh year Jehoiada the priest brings out the seven-year-old Joash, crowns him in the temple and makes a covenant with the king and the people. Athaliah cries treason and is put to death, and the house of Baal is torn down.', 'Ussher: 878 BC (2 Kgs 11:4-20; 2 Chr 23).', 950),
(449, 'Joash Repairs the Temple', -856, NULL, 0, 1, 'probable', 'reform', 'minor', 'In his 23rd year Joash finds the priests have not repaired the temple and has a chest set at the altar for the people''s gifts. The money is paid straight to the workmen and the house of the Lord is restored.', 'Ussher, Annals §538, §540: the poll-tax repair is ordered in 857 BC and, in Joash''s 23rd year (3148c AM, 856 BC), the king takes the work from the slow priests (2 Kgs 12:4-16).', 960),
(450, 'Jonah''s Mission to Nineveh', -771, NULL, 1, 1, 'possible', 'mission', 'major', 'Called to warn Nineveh, Jonah flees by sea, is swallowed by a great fish and prays from its belly. Sent again, he preaches in the Assyrian capital, the city repents, and God relents, to Jonah''s anger and the Lord''s rebuke.', 'Scripture dates Jonah only to the reign of Jeroboam II (2 Kgs 14:25; Ussher 825-784 BC, Annals §555) and does not date the mission. Ussher says only that he was "later sent to Nineveh" and takes the repentant king to be Pul (§575, under 771 BC), so the mission is placed there. Estimate within Ussher''s reading.', 1000),
(451, 'Jeroboam II Restores Israel''s Borders', -800, -784, 1, 1, 'possible', 'kingdom', 'minor', 'Jeroboam II, though he continues the sin of Jeroboam, restores Israel''s coast from Hamath to the Dead Sea as Jonah had foretold. It is the northern kingdom''s last season of power and wealth, which Amos and Hosea would condemn.', 'Ussher: Jeroboam II reigned 825-784 BC (2 Kgs 14:23-29).', 970),
(452, 'Amos Prophesies at Bethel', -787, NULL, 1, 1, 'possible', 'prophecy', 'moderate', 'Amos, a herdsman of Tekoa, comes north in the days of Uzziah and Jeroboam II, two years before the earthquake. He denounces Israel''s injustice and false worship and is ordered to leave Bethel.', 'Ussher, Annals §553, §557: Amos was called two years before the earthquake in the days of Uzziah and Jeroboam II (810-784 BC, Amos 1:1; 7:10-15); §553 mentions him under the 13th Jubilee (808 BC) but gives no single year. 787 BC is an estimate within the reign of Jeroboam II. Mainstream c. 760 BC.', 980),
(453, 'Hosea''s Ministry to Israel', -785, -721, 1, 1, 'possible', 'prophecy', 'moderate', 'Hosea marries Gomer at God''s command, and the names of his children become messages of judgment and hope. His long ministry from Jeroboam II to Hezekiah pictures the Lord''s faithful love for an unfaithful people.', 'Ussher, Annals §554-556: Hosea prophesied under Jeroboam II (825-784 BC, Hos 1:1-3) and lived to see Israel''s ruin in 721 BC, continuing into Hezekiah''s time. The start (-785) and end are estimates within those limits.', 990),
(454, 'Uzziah Struck with Leprosy', -771, -759, 1, 0, 'possible', 'judgment', 'minor', 'Strong and proud, Uzziah enters the temple to burn incense, which only priests may do. Leprosy breaks out on his forehead, he is shut out of the temple, and his son Jotham governs until his death.', 'Ussher, Annals §564: struck with leprosy as an old man, soon after Menahem took the throne of Israel (about 771 BC), not in his 25th year as the Jews held; Jotham ruled in the king''s house until Uzziah died in 759 BC (§584). Scripture gives no year (2 Chr 26:16-21; 2 Kgs 15:5). The start is an inference from Ussher''s words "a short time later".', 1010),
(455, 'Isaiah''s Vision and Call', -759, NULL, 0, 1, 'probable', 'prophecy', 'major', 'In the year King Uzziah dies Isaiah sees the Lord high and lifted up in the temple, with seraphim crying holy, holy, holy. A burning coal touches his lips and he answers, Here am I; send me.', 'Ussher, Annals §583-584: 759 BC, the year of Uzziah''s death and the 14th Jubilee (Isa 6:1).', 1020),
(456, 'Micah''s Ministry', -759, -698, 1, 1, 'possible', 'prophecy', 'moderate', 'Micah of Moresheth prophesies against Samaria and Jerusalem under Jotham, Ahaz and Hezekiah, denouncing the greed of the powerful. He foretells that the ruler of Israel will come from Bethlehem.', 'Ussher, Annals §585: Micah and Isaiah succeeded Jotham-era prophets from 759 BC; §653: Micah prophesied in Hezekiah''s days (to 698 BC). The span of the three kings named (Mic 1:1); the exact years of his ministry are an estimate.', 1030),
(457, 'Syro-Ephraimite War', -742, -740, 1, 1, 'possible', 'war', 'moderate', 'Rezin of Aram and Pekah of Israel march on Jerusalem to force Ahaz into an alliance against Assyria. Isaiah meets Ahaz with the sign of Immanuel and tells him to trust God, but Ahaz sends tribute to Tiglath-pileser instead.', 'Ussher, Annals §598-599: Rezin and Pekah come against Judah at the end of Jotham''s reign and the accession of Ahaz (742 BC; Isa 7); §600: Ahaz is defeated in 741 BC (2 Chr 28:5-15); §604: the war ends when Tiglath-pileser takes Damascus in 740 BC. Mainstream c. 735-732 BC.', 1040),
(458, 'Tiglath-pileser Takes Damascus and Galilee', -740, NULL, 0, 1, 'probable', 'war', 'moderate', 'Answering Ahaz''s call, Tiglath-pileser of Assyria captures Damascus and kills Rezin, and carries off the people of Galilee and Gilead. Ahaz goes to meet him at Damascus and copies its altar for the temple.', 'Ussher, Annals §604, §607: 740 BC, the third year of Ahaz (2 Kgs 15:29; 16:7-10). Assyrian records date the campaign to 733-732 BC.', 1050),
(459, 'Hezekiah''s Reform and Passover', -726, NULL, 0, 1, 'probable', 'reform', 'major', 'In his first year Hezekiah reopens and cleanses the temple, and removes the high places and the bronze serpent. He invites all Israel to a great Passover in Jerusalem, and the whole assembly keeps a second week of joy.', 'Ussher, Annals §620-623: 726 BC, the first year of Hezekiah; the temple is cleansed in the first month and the Passover kept in the second month (2 Kgs 18:1-6; 2 Chr 29-31).', 1060),
(460, 'Hezekiah''s Illness and the Babylonian Envoys', -713, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'Told by Isaiah to set his house in order, Hezekiah prays and is given fifteen more years, with the shadow going back ten steps as a sign. Envoys of Merodach-baladan of Babylon then come, and Hezekiah shows them all his treasures, which Isaiah says will one day be carried to Babylon.', 'Scripture: fifteen years were added to Hezekiah''s life (2 Kgs 20:6; Isa 38:5), and he reigned 29 years (2 Kgs 18:2), so the illness fell in his 14th year, 713 BC on Ussher''s chain (Annals §643-650); the envoys come at the beginning of his 15th year (2 Kgs 20:1-19; Isa 38-39). Ussher puts the illness before the slaughter of Sennacherib''s army (§644).', 1080),
(461, 'Manasseh''s Apostasy', -698, NULL, 1, 1, 'possible', 'worship', 'moderate', 'Manasseh rebuilds the high places, sets altars to the host of heaven in the temple and passes his son through the fire. He fills Jerusalem with innocent blood, and the Lord announces that the city will be wiped like a dish.', 'Ussher, Annals §682: Manasseh reigned from 698 BC (55 years, 2 Kgs 21:1) and at once rebuilt the high places and set up altars in the temple (2 Kgs 21:2-16; 2 Chr 33:2-9). The date is the start of his reign; the rest of the evil continued through it.', 1100),
(462, 'Sennacherib Assassinated', -681, NULL, 0, 1, 'probable', 'death', 'minor', 'Sennacherib returns to Nineveh and is killed by his own sons as he worships in the house of Nisroch, and his son Esarhaddon succeeds him. The Bible records it as the end of the king who defied the Lord at Jerusalem.', 'Standard Assyrian date, 681 BC, from the Babylonian Chronicle (2 Kgs 19:36-37; Isa 37:37-38). Ussher, Annals §668-669, puts it 45 to 55 days after the slaughter of his army in Hezekiah''s 14th year (713 BC).', 1110),
(463, 'Manasseh''s Captivity and Repentance', -677, NULL, 0, 1, 'probable', 'salvation', 'moderate', 'The Assyrians take Manasseh in hooks to Babylon, and there he humbles himself and prays. God hears him and returns him to Jerusalem, where he removes the idols and rebuilds the wall.', 'Ussher, Annals §697-699: taken to Babylon in 677 BC, the 22nd year of his reign, under Esarhaddon, and restored after repenting, 33 years before his death (2 Chr 33:10-20). Not mentioned in Kings.', 1120),
(464, 'Josiah''s Passover', -623, NULL, 0, 1, 'probable', 'worship', 'moderate', 'After the covenant renewal, Josiah keeps the Passover in Jerusalem on a scale not seen since the days of Samuel. Priests and Levites are set in their courses and the whole assembly takes part.', 'Ussher, Annals §743: 623 BC, the Passover of the same 18th year of Josiah, on the 14th of the first month (Monday, 4 May). The reforms of §742 fall earlier, in 624 BC (2 Kgs 23:21-23; 2 Chr 35:1-19).', 1160),
(465, 'Jeremiah''s Call', -629, NULL, 0, 1, 'probable', 'prophecy', 'major', 'In Josiah''s 13th year the word of the Lord comes to Jeremiah, a priest''s son from Anathoth: before you were formed I knew you. Though he protests that he is a youth, God touches his mouth and appoints him over nations and kingdoms.', 'Ussher, Annals §737: 629 BC, Josiah''s 13th year (Jer 1:2). Ussher places Zephaniah''s warnings in the same year.', 1130),
(466, 'Fall of Nineveh', -626, NULL, 0, 1, 'probable', 'judgment', 'moderate', 'A Babylonian and Median coalition destroys Nineveh, the Assyrian capital, as Nahum and Zephaniah had foretold. Assyria''s power is broken.', 'Ussher, Annals §739: 626 BC, when Nabopolassar and Astyages took Nineveh and its king (Nah 1-3; Zeph 2:13-15). Mainstream: 612 BC (Babylonian Chronicle).', 1140),
(467, 'Death of Josiah at Megiddo', -610, NULL, 0, 1, 'probable', 'death', 'moderate', 'Josiah goes out to stop Pharaoh Necho marching to Carchemish and is shot by archers at Megiddo. All Judah mourns, and Jeremiah composes a lament.', 'Ussher, Annals §753-754: 610 BC, the year Necho marched against Carchemish (2 Kgs 23:29-30; 2 Chr 35:20-27). Mainstream 609 BC.', 1170),
(468, 'Daniel Taken to Babylon', -607, NULL, 0, 1, 'probable', 'exile', 'major', 'Nebuchadnezzar besieges Jerusalem in Jehoiakim''s reign and carries off temple vessels and young nobles. Daniel, Hananiah, Mishael and Azariah, renamed Shadrach, Meshach and Abednego, are trained for the king''s service and refuse his food.', 'Ussher, Annals §774-776: 607 BC, the 9th month (Chisleu) of Jehoiakim''s 4th year, which Ussher counts as Nebuchadnezzar''s first as viceroy (Dan 1:1-7; Jer 25:1). Ussher starts the 70 years of captivity here (§775). Mainstream 605 BC.', 1180),
(469, 'Nebuchadnezzar''s Dream of the Statue', -604, NULL, 0, 1, 'probable', 'prophecy', 'moderate', 'Nebuchadnezzar''s dream of a great statue of gold, silver, bronze and iron leaves him troubled, and his wise men cannot tell it. God reveals it to Daniel, who explains the kingdoms to come and the stone cut without hands, and the king promotes him.', 'Ussher, Annals §786: 604 BC, Nebuchadnezzar''s 2nd year (Dan 2:1), after the three years of training of §785.', 1190),
(470, 'Jehoiachin Exiled to Babylon', -599, NULL, 0, 1, 'probable', 'exile', 'major', 'After Jehoiakim''s death, Nebuchadnezzar takes Jerusalem, carries King Jehoiachin, his mother and ten thousand leading men to Babylon and makes Zedekiah king. Ezekiel is among the captives.', 'Ussher, Annals §794-796: 599 BC, Nebuchadnezzar''s 8th year; Ezekiel and Mordecai are among the captives (2 Kgs 24:8-17; 2 Chr 36:9-10). Babylonian Chronicle: 597 BC.', 1200),
(471, 'Ezekiel''s Call by the Chebar', -595, NULL, 0, 1, 'probable', 'prophecy', 'major', 'In the fifth year of Jehoiachin''s exile Ezekiel, a priest among the captives, sees the heavens opened and the glory of the Lord on a throne above living creatures. God sends him as a watchman to a rebellious people.', 'Ussher, Annals §821: 595 BC, the 4th month, 5th day (Saturday, 24 July) of the 5th year of Jehoiachin''s captivity (Ezek 1:1-3), which Ussher counts as 30 years from Josiah''s reform of 624 BC.', 1210),
(472, 'Siege of Jerusalem Begins', -590, NULL, 0, 1, 'probable', 'war', 'moderate', 'Zedekiah rebels against Babylon, and Nebuchadnezzar camps against Jerusalem in Zedekiah''s ninth year. Jeremiah urges surrender, and the siege lasts until the city falls.', 'Ussher, Annals §831: 590 BC, Zedekiah''s 9th year, tenth month, tenth day (2 Kgs 25:1-2; Jer 52:4-5). Mainstream January 588 BC.', 1220),
(473, 'Jeremiah Cast into the Cistern', -589, NULL, 0, 1, 'probable', 'persecution', 'minor', 'Accused of weakening the soldiers'' morale, Jeremiah is thrown into a muddy cistern. Ebed-melech, an Ethiopian court official, has him lifted out, and Zedekiah secretly asks him again for God''s word.', 'Ussher, Annals §842: 589 BC, late in the siege, when the princes cast Jeremiah into Malchiah''s dungeon and Ebed-melech brought him out (Jer 38). His earlier imprisonment in the house of Jonathan falls in 590 BC (§837; Jer 37).', 1230);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(35, 'Fall of Jerusalem', -588, NULL, 0, 1, 'traditional', 'judgment', 'major', 'Nebuchadnezzar''s Babylonian army breaches Jerusalem after a long siege, burning the temple, razing the walls, and deporting Judah''s people. The Babylonian Chronicle independently records his earlier seizure of the city, corroborating the biblical account of Judah''s collapse and exile.', 'Ussher, Annals §846-850: 588 BC (AM 3416), the 11th year of Zedekiah and 19th of Nebuchadnezzar (2 Kgs 25:2, 8): the city is broken up on the 9th of the 4th month, and the temple burnt on the 10th of the 5th (Jer 39:2; 52:12-13). Most modern scholarship dates the fall to 587 or 586 BC, anchored in the Babylonian Chronicle.', 1240),
(36, 'Babylonian Exile', -588, -537, 0, 0, 'traditional', 'exile', 'major', 'Uprooted to Babylon, Judah''s exiles mourn Zion by foreign rivers while prophets like Ezekiel and Daniel proclaim God''s presence far from the ruined temple. Cuneiform records, including ration tablets naming King Jehoiachin and the Al-Yahudu archive, document the exiled community''s life in Babylonia.', 'Dated here from the fall of Jerusalem (588 BC, Ussher, Annals §846-850) to Cyrus''s edict (537 BC, §948-949). Ussher counts the seventy years (Jer 25:11-12; 29:10; Dan 9:2) from the first deportation in 607 BC (§775) to the edict in 537 BC; the first return followed in 536 BC (§951). Modern scholarship dates the exile 586-538 BC.', 1250),
(37, 'Edict of Cyrus', -537, NULL, 0, 1, 'probable', 'salvation', 'major', 'Cyrus of Persia, having taken Babylon, decrees that the exiled Judeans may return to Jerusalem to rebuild the house of the Lord, restoring the plundered temple vessels. The Cyrus Cylinder reflects his wider policy of restoring displaced peoples and shrines, and Isaiah strikingly names him God''s anointed.', 'Ussher, Annals §948-949: 537 BC (AM 3468), the first year of Cyrus (Ezra 1:1) as Ussher counts it, after the two years of Darius the Mede from 538 BC; the seventy years from 607 BC end here. The return follows in 536 BC (§951). Modern scholarship dates the decree to 538 BC; the Cyrus Cylinder reflects the same policy.', 1300),
(340, 'Fall of Babylon to Cyrus', -538, NULL, 0, 1, 'probable', 'conquest', 'moderate', 'Babylon falls to the Medes and Persians in a single night. Belshazzar is killed after the writing on the wall is read at his feast, and Darius the Mede takes the kingdom (Dan 5). The Nabonidus Chronicle independently records the city''s capture without a battle.', 'Ussher, Annals §935-939: 538 BC (AM 3466), the night Belshazzar was slain and Darius the Mede took the kingdom (Dan 5:30-31), the year before Cyrus''s edict of 537. Mainstream: 12 October 539 BC (Nabonidus Chronicle).', 1280),
(474, 'The Fiery Furnace', -580, NULL, 1, 1, 'possible', 'miracle', 'moderate', 'Shadrach, Meshach and Abednego refuse to bow to Nebuchadnezzar''s golden image and are thrown into a furnace heated seven times hotter. The king sees four men walking in the fire, one like a son of the gods, and brings them out unharmed.', 'Scripture gives no year (Dan 3) and the Annals do not date it. The date is an estimate between the dream (604 BC, Ussher §786) and the king''s humbling.', 1260),
(475, 'Daniel in the Lions'' Den', -538, NULL, 0, 1, 'probable', 'miracle', 'major', 'Darius the Mede is tricked into a decree forbidding prayer, and Daniel keeps praying three times a day and is thrown to the lions. God shuts their mouths, Daniel''s accusers are cast in instead, and Darius honours the God of Daniel.', 'Ussher, Annals §939-944: 538 BC, in the first year of Darius the Mede, the same year Ussher gives for the fall of Babylon (Dan 6).', 1290),
(476, 'Jehoiachin Released by Evil-merodach', -562, NULL, 0, 1, 'probable', 'salvation', 'minor', 'In the 37th year of his exile, Evil-merodach lifts Jehoiachin out of prison, gives him a seat above other kings and a place at his table for life. The book of Kings ends on this sign that David''s line is not finished.', 'Ussher, Annals §891: 562 BC, the 37th year of Jehoiachin''s captivity, about the 25th of the 12th month, in Evil-merodach''s first year (2 Kgs 25:27-30; Jer 52:31-34). Mainstream 561 BC.', 1270);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(38, 'Second Temple Built', -515, NULL, 0, 1, 'certain', 'worship', 'major', 'Led by Zerubbabel and Jeshua and stirred by the prophets Haggai and Zechariah, the returned exiles complete a new temple in Jerusalem despite opposition and slender means. Elders wept remembering Solomon''s house, yet this second temple would anchor Jewish worship for centuries until the Roman era.', 'Begun in the second year of the return (Ezra 3:8), halted, and resumed in the second year of Darius I, 520 BC (Hag 1:1; Ezra 4:24); finished on 3 Adar in his sixth year (Ezra 6:15), March 515 BC. Ussher likewise gives 515 BC.', 1340),
(39, 'Ezra''s Return', -458, NULL, 0, 1, 'probable', 'worship', 'moderate', 'Ezra leads a second return and reforms worship.', 'Seventh year of Artaxerxes I (Ezra 7:7-9): 458 BC by Persian reckoning, 457 BC if his years are counted autumn to autumn (the traditional start of the seventy weeks). Ussher, Annals §1203-1204, dates the departure and arrival to 467 BC, because his Artaxerxes begins reigning about nine years earlier; this dataset keeps the standard date. Some scholars place Ezra in 398 BC under Artaxerxes II.', 1380),
(40, 'Nehemiah Rebuilds Walls', -445, NULL, 0, 1, 'probable', 'reform', 'moderate', 'Nehemiah, cupbearer to the Persian king, returns to Jerusalem and rallies the people to rebuild the ruined walls in fifty-two days despite armed opposition from Sanballat and Tobiah. The Elephantine papyri independently name Sanballat as governor of Samaria, anchoring the memoir in Persian-era history.', 'Twentieth year of Artaxerxes I (Neh 2:1), 445/444 BC; the wall was finished in 52 days (Neh 6:15). Ussher, Annals §1226-1234, has Nehemiah''s news in 455 BC (9th month, 20th year) and the wall built in 454 BC; this dataset keeps the standard date.', 1400),
(41, 'Esther Saves Her People', -473, NULL, 1, 1, 'possible', 'salvation', 'moderate', 'In the Persian court at Susa, the Jewish queen Esther risks her life to expose Haman''s plot to annihilate her people, and the king''s counter-decree turns doom into deliverance. Commemorated each year at Purim, the story displays providence at work even though God is never named in the book.', 'The lot was cast in the twelfth year of Ahasuerus and the decree fell on 13 Adar (Esth 3:7; 9:1), 473 BC if Ahasuerus is Xerxes I (486-465 BC).', 1370),
(480, 'First Return under Zerubbabel and Jeshua', -536, NULL, 0, 1, 'probable', 'salvation', 'moderate', 'After Cyrus''s decree, about 42,000 exiles led by Zerubbabel and the priest Jeshua go up from Babylon to Judah, carrying back the temple vessels that Nebuchadnezzar had taken. Sheshbazzar, the prince of Judah, receives the vessels. The return is the first step in restoring worship at Jerusalem.', 'Ussher, Annals §951: 536 BC, the year after Cyrus''s edict of 537 BC (§948-949) (Ezra 1:1; 2:1-2). Mainstream dating places the edict in 538 BC and the first return c. 538-537 BC.', 1310),
(481, 'Altar Rebuilt and Temple Foundation Laid', -536, -535, 0, 0, 'probable', 'worship', 'moderate', 'In the seventh month the returned exiles gather at Jerusalem, and Jeshua and Zerubbabel set up the altar and restore the daily burnt offerings, though the temple foundation is not yet laid. In the second year of their coming the builders lay the foundation to trumpets and praise; the young shout for joy and the old who remembered the first temple weep.', 'Ussher, Annals §952-953: altar in the seventh month of 536 BC, foundation in the second month of 535 BC (Ezra 3:1-13). Mainstream dating puts these a year or two earlier, c. 538-536 BC.', 1320),
(482, 'Haggai and Zechariah Rouse the Rebuilding', -520, NULL, 0, 1, 'probable', 'prophecy', 'moderate', 'After the work on the temple has stalled for years under local opposition, the word of the LORD comes by Haggai in the second year of Darius, and Zechariah begins to prophesy soon after. Zerubbabel the governor and Jeshua the high priest obey, and the building resumes within a few weeks.', 'Haggai 1:1 dates the first oracle to the first day of the sixth month of Darius''s second year, 520 BC (Ussher, Annals §1015-1018: the building resumed on the 24th day of the ninth month). Ezra 5:1-2; Zechariah 1:1 (eighth month, same year). Standard historical dating also gives 520 BC.', 1330),
(483, 'Vashti Deposed', -483, NULL, 1, 1, 'probable', 'kingdom', 'minor', 'At the end of a six-month display of the wealth of his empire and a feast at Susa, king Ahasuerus (Xerxes) summons Queen Vashti, and she refuses to come. On the advice of his counsellors he deposes her and issues a decree to every province, which clears the way for a new queen.', 'Esther 1:3 dates the feast to the third year of Ahasuerus. Taking Ahasuerus as Xerxes I (reigned 486-465 BC, standard historical dating), that is 484/483 BC. Ussher identifies Ahasuerus with Darius Hystaspes and Vashti with Atossa (Annals §1009, §1027), so he places the feast in 518 BC; this dataset follows the standard identification, as for the existing Esther event.', 1350),
(484, 'Esther Made Queen', -479, NULL, 1, 1, 'probable', 'kingdom', 'moderate', 'Esther, a Jewish orphan raised by her cousin Mordecai, is taken to Ahasuerus at Susa in the tenth month of his seventh year. He loves her above the other candidates, sets the royal crown on her head and makes her queen in place of Vashti. Esther keeps her people and family secret at Mordecai''s direction.', 'Esther 2:16 gives the tenth month of the seventh year of Ahasuerus, i.e. Tebeth, January 478 BC on Xerxes I (reigned 486-465 BC); entered as 479 BC, the regnal year. Ussher (Annals §1035), reading Ahasuerus as Darius Hystaspes, has this in 514 BC.', 1360),
(485, 'Ezra Reads the Law at the Water Gate', -445, NULL, 1, 1, 'possible', 'teaching', 'moderate', 'On the first day of the seventh month the people gather in the square before the Water Gate and ask Ezra the scribe to bring the book of the law of Moses. From morning until midday he reads it, and the Levites give the sense so that all understand. The people weep, then keep the Feast of Booths with joy, and a solemn assembly follows.', 'Nehemiah 8:1-2 gives the first day of the seventh month, soon after the wall was finished. Standard dating follows the wall (445 BC, Artaxerxes'' twentieth year), so c. 445/444 BC. Ussher, Annals §1238-1239, puts the reading in 454 BC, the year he finishes the wall (his Artaxerxes reigns from 474/5 BC, about nine years earlier than the standard reckoning). Some scholars place Ezra after Nehemiah.', 1390),
(486, 'Malachi''s Ministry', -430, NULL, 1, 1, 'possible', 'prophecy', 'moderate', 'Malachi, the last of the prophets of the Old Testament, rebukes a restored community that has grown careless: priests offer blemished sacrifices, tithes are withheld and marriages are broken faith. He promises a messenger to prepare the way of the Lord and ends with the promise of Elijah to come before the great day of the LORD.', 'The book is undated. Its abuses match the time of Nehemiah''s second term, so c. 430 BC is an estimate; scholars place Malachi between c. 480 and 430 BC. Ussher (Annals §1305) has him in 416 BC, contemporary with Nehemiah''s second return.', 1410);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(42, 'Birth of Jesus', -5, NULL, 0, 1, 'probable', 'birth', 'major', 'In Bethlehem, Mary gives birth to Jesus, announced by angels to shepherds and honored by magi from the east; Matthew and Luke present him as Messiah, son of David, and Immanuel. The Gospels root his birth in Micah''s prophecy of a ruler from Bethlehem, opening the fulfillment of Israel''s long story.', 'Ussher, Annals §6057, headed 5 BC (Quirinius'' census, Luke 2:1-7; §6049-6056). Matthew places the birth before the death of Herod the Great (Matt 2:1, 19), whom Ussher dates to 4 BC (§6080), so the year agrees with Scripture''s order. Many modern scholars give 6-4 BC.', 1520),
(43, 'Baptism of Jesus', 27, NULL, 0, 1, 'possible', 'other', 'major', 'Jesus is baptized by John in the Jordan River, where the Spirit descends like a dove and a voice from heaven declares him the beloved Son. The moment inaugurates his public ministry; John himself is independently attested by the historian Josephus, who records his baptizing movement and death.', 'Ussher, Annals §6288: AD 27, early in the year, after John''s ministry began in the fifteenth year of Tiberius reckoned from his co-regency (Luke 3:1; John begins October AD 26, §6280-6283). Luke 3:23 says ''about thirty''; on Ussher''s birth in late 5 BC he is about 31, which Scripture allows. The first Passover of the ministry is AD 30 (John 2:13, 20; §6302), so Ussher leaves about three years between baptism and that Passover; John 1:19-2:13 reads as continuous, a tension the Annals do not remove. Was AD 29 (Tiberius'' fifteenth year counted from his accession in AD 14, giving AD 28/29); some place it in AD 26.', 1560),
(44, 'Sermon on the Mount', 31, NULL, 0, 1, 'possible', 'teaching', 'major', 'On a Galilean hillside, Jesus delivers his most famous teaching, opening with the Beatitudes and pressing the Law to its deepest intent on anger, love of enemies, and prayer, including the Lord''s Prayer. Matthew presents him as the authoritative teacher of a righteousness surpassing that of the scribes.', 'Matthew 5-7; compare Luke 6:20-49. Ussher, Annals §6338: AD 31. Luke places the Sermon on the Plain after the withered hand and the choosing of the Twelve (Luke 6:6-20).', 1660),
(58, 'Water Turned to Wine', 30, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'At a wedding in Cana of Galilee, prompted by his mother Mary, Jesus turned water in six stone purification jars into choice wine. John alone records this first sign, which revealed Jesus'' glory to his disciples and inaugurated his public ministry with an image of messianic abundance.', 'John 2:1-11. Ussher, Annals §6301: AD 30. Placed by Ussher just before the first Passover (John 2:13).', 1570),
(59, 'Healing of the Official''s Son', 30, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a royal official''s son in Capernaum from a distance.', 'John 4:46-54; second sign in John (John 4:54). Ussher, Annals §6316: AD 30. After the stay at Sychar (John 4:35).', 1580),
(60, 'Great Catch of Fish', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus directs a miraculous catch of fish on the Sea of Galilee.', 'Luke 5:1-11; calling of the first disciples. Ussher, Annals §6325: AD 31.', 1610),
(61, 'Healing of a Demon-Possessed Man in Capernaum', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus casts out an unclean spirit in the Capernaum synagogue.', 'Mark 1:21-28; Luke 4:31-37. Ussher, Annals §6319: AD 31.', 1590),
(62, 'Healing of Peter''s Mother-in-Law', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals Simon Peter''s mother-in-law of a fever.', 'Matthew 8:14-15; Mark 1:29-31; Luke 4:38-39. Ussher, Annals §6320: AD 31.', 1600),
(63, 'Cleansing of a Leper', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a man with leprosy by touching him.', 'Matthew 8:1-4; Mark 1:40-45; Luke 5:12-16. Ussher, Annals §6327: AD 31.', 1620),
(64, 'Healing of the Paralytic', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'In Capernaum, four friends lowered a paralyzed man through the roof to reach Jesus, who first forgave his sins and then commanded him to walk. Matthew, Mark, and Luke record the miracle, which joined Jesus'' power to heal with his authority to forgive; Capernaum excavations reveal the crowded basalt houses such a scene assumes.', 'Matthew 9:1-8; Mark 2:1-12; Luke 5:17-26. Ussher, Annals §6328: AD 31.', 1630),
(65, 'Healing at the Pool of Bethesda', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a man who had been an invalid for 38 years.', 'John 5:1-17; on a Sabbath. Ussher takes the unnamed feast of John 5:1 as the second Passover (some take it as Tabernacles or Purim). Ussher, Annals §6332: AD 31.', 1640),
(66, 'Healing of a Withered Hand', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a man''s withered hand on the Sabbath in the synagogue.', 'Matthew 12:9-14; Mark 3:1-6; Luke 6:6-11. Ussher, Annals §6333: AD 31.', 1650),
(67, 'Healing of the Centurion''s Servant', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'A Roman centurion in Capernaum asked Jesus to heal his dying servant, insisting a word from a distance would suffice. Jesus marveled that he had found no such faith in Israel and healed the servant without entering the house; Luke adds that this Gentile officer had built the town''s synagogue.', 'Matthew 8:5-13; Luke 7:1-10. Ussher, Annals §6339: AD 31.', 1670),
(68, 'Raising of the Widow''s Son at Nain', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'Meeting a funeral procession at the gate of Nain, Jesus was moved by a widow who had lost her only son, touched the bier, and restored the young man to life. Found only in Luke, the miracle echoes Elijah''s raising of the widow''s son at Zarephath and led the crowd to hail a great prophet.', 'Luke 7:11-17; only in Luke. Ussher, Annals §6340: AD 31.', 1680),
(69, 'Calming the Storm', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'When a sudden squall threatened to swamp the disciples'' boat on the Sea of Galilee, Jesus rose from sleep and stilled wind and waves with a word. All three synoptic gospels record the awed question of who this could be; a first-century fishing boat excavated from the lake''s mud vividly illustrates the scene.', 'Matthew 8:23-27; Mark 4:35-41; Luke 8:22-25. Ussher, Annals §6347: AD 31.', 1690),
(70, 'Healing of the Gerasene Demoniac', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'In the Decapolis east of the Sea of Galilee, Jesus freed a tomb-dwelling man possessed by a legion of demons, which entered a herd of pigs and perished in the sea. Sent home rather than allowed to follow, the man became the first herald of Jesus in Gentile lands; manuscripts vary between Gerasenes, Gadarenes, and Gergesenes.', 'Matthew 8:28-34; Mark 5:1-20; Luke 8:26-39. Ussher, Annals §6348: AD 31.', 1700),
(71, 'Healing of the Woman with the Issue of Blood', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'A woman touches Jesus'' garment and is healed after 12 years of bleeding.', 'Matthew 9:20-22; Mark 5:25-34; Luke 8:43-48. Ussher, Annals §6349-6351: AD 31.', 1710),
(72, 'Raising of Jairus'' Daughter', 31, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'Jairus, a synagogue leader, begged Jesus to save his dying daughter, and though word came that she had died, Jesus took her hand and raised her. Mark preserves the original Aramaic command, Talitha koum, and all three synoptics interweave the story with the healing of the hemorrhaging woman.', 'Matthew 9:18-26; Mark 5:21-43; Luke 8:40-56. Ussher, Annals §6351: AD 31.', 1720),
(73, 'Healing of Two Blind Men', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus restores sight to two blind men who follow him crying for mercy.', 'Matthew 9:27-31. Ussher, Annals §6352: AD 31. Matthew sets it directly after Jairus'' daughter.', 1730),
(74, 'Healing of a Mute Man', 31, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus casts out a demon and the mute man speaks.', 'Matthew 9:32-34. Ussher, Annals §6353: AD 31.', 1740),
(75, 'Feeding of the 5,000', 32, NULL, 0, 1, 'possible', 'miracle', 'major', 'With five loaves and two fish from the crowd, Jesus fed thousands beside the Sea of Galilee, with twelve baskets left over. It is the only miracle of his ministry recorded in all four gospels, recalling the manna in the wilderness and prompting John''s discourse on Jesus as the bread of life.', 'Matthew 14:13-21; Mark 6:30-44; Luke 9:10-17; John 6:1-15. Only miracle in all four Gospels. At the Passover of John 6:4 (Ussher''s third). Ussher, Annals §6367: AD 32.', 1760),
(76, 'Walking on Water', 32, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'In the night after feeding the multitude, Jesus came to his storm-battered disciples walking across the Sea of Galilee. Matthew, Mark, and John record the event, with Matthew adding Peter''s brief walk and sinking; Jesus'' reassurance, echoing the divine I am, moved the disciples to worship him as God''s Son.', 'Matthew 14:22-33; Mark 6:45-52; John 6:16-21. The night after the feeding of the 5,000. Ussher, Annals §6367-6368: AD 32.', 1770),
(77, 'Healing of the Syrophoenician Woman''s Daughter', 32, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a Gentile woman''s demon-possessed daughter.', 'Matthew 15:21-28; Mark 7:24-30. Ussher, Annals §6370: AD 32.', 1780),
(78, 'Healing of a Deaf and Mute Man', 32, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a deaf man with a speech impediment in the Decapolis.', 'Mark 7:31-37. Ussher, Annals §6371: AD 32.', 1790),
(79, 'Feeding of the 4,000', 32, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'In the largely Gentile Decapolis region, Jesus fed a crowd that had stayed with him three days, multiplying seven loaves and a few fish with seven baskets remaining. Recorded by Matthew and Mark as distinct from the earlier feeding, it signals that the messianic banquet extends beyond Israel to the nations.', 'Matthew 15:32-39; Mark 8:1-10. Ussher, Annals §6373: AD 32.', 1800),
(80, 'Healing of a Blind Man at Bethsaida', 32, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus heals a blind man in two stages at Bethsaida.', 'Mark 8:22-26; only in Mark. Ussher, Annals §6377: AD 32.', 1810),
(81, 'Transfiguration', 32, NULL, 0, 1, 'possible', 'miracle', 'major', 'On a high mountain, Peter, James, and John saw Jesus transfigured in dazzling glory, conversing with Moses and Elijah as a voice from the cloud declared him the beloved Son. All three synoptics record the scene, which links law and prophets to Jesus; 2 Peter appeals to it as eyewitness testimony.', 'Matthew 17:1-13; Mark 9:2-13; Luke 9:28-36. Six (Luke: about eight) days after Peter''s confession (Matt 17:1; Luke 9:28). Ussher, Annals §6379: AD 32.', 1820),
(82, 'Healing of a Boy with a Demon', 32, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus casts out a demon the disciples could not.', 'Matthew 17:14-21; Mark 9:14-29; Luke 9:37-43. Ussher, Annals §6380: AD 32.', 1830),
(83, 'Coin in the Fish''s Mouth', 32, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus instructs Peter to find a coin in a fish''s mouth for Temple tax.', 'Matthew 17:24-27; only in Matthew. Ussher, Annals §6382: AD 32.', 1840),
(84, 'Healing of the Man Born Blind', 32, NULL, 0, 1, 'possible', 'miracle', 'moderate', 'Jesus anointed the eyes of a man blind from birth and sent him to wash in the Pool of Siloam, where he received sight. John alone tells the story, following the man''s bold testimony under interrogation; the stepped first-century pool itself has been uncovered in recent Jerusalem excavations.', 'John 9:1-41; extended discourse on spiritual blindness. Follows the Feast of Tabernacles (John 7:2, 37; autumn AD 32) and precedes the Feast of Dedication (John 10:22). Ussher, Annals §6394: AD 32.', 1850),
(85, 'Healing of a Crippled Woman', 32, NULL, 1, 1, 'possible', 'miracle', 'minor', 'Jesus heals a woman bent over for 18 years on the Sabbath.', 'Luke 13:10-17; only in Luke. Within Luke''s journey to Jerusalem (Luke 9:51-19:28). Ussher, Annals §6407-6408 places it after the Tabernacles of AD 32 and on the way to the Dedication (Dec AD 32), yet the printed heading over §6399-6452 reads AD 33; the year is kept at AD 32 (winter AD 32/33) and flagged approximate.', 1860),
(360, 'Annunciation to Mary', -5, NULL, 0, 1, 'possible', 'birth', 'moderate', 'The angel Gabriel announces to Mary at Nazareth that she will conceive by the Holy Spirit and bear a son named Jesus, and Mary consents. She then visits her relative Elizabeth, who is six months pregnant with John. Matthew tells of the angel''s message to Joseph in a dream.', 'Ussher, Annals §6039: 5 BC, in the sixth month after John was conceived (Luke 1:26, 36), nine months before the birth of Jesus. Scripture gives no year.', 1500),
(361, 'Birth of John the Baptist', -5, NULL, 0, 1, 'possible', 'birth', 'moderate', 'Elizabeth bears a son to the aged priest Zechariah, who regains his speech when he writes that the child''s name is John. Zechariah''s song (the Benedictus) foretells that the child will prepare the way of the Lord.', 'Ussher, Annals §6043: 5 BC, about six months before the birth of Jesus (Luke 1:26, 36). Scripture gives no year.', 1510),
(362, 'Visit of the Magi and Flight into Egypt', -4, -3, 0, 0, 'possible', 'birth', 'moderate', 'Magi from the east follow a star to Jerusalem and Bethlehem, worship the child Jesus and, warned in a dream, go home another way. Herod the Great orders the killing of the boys of Bethlehem aged two and under; Joseph, warned by an angel, takes Mary and the child to Egypt until Herod''s death and then settles in Nazareth.', 'Ussher, Annals §6060, §6064: the Magi come and the flight to Egypt falls in 4 BC, before Herod''s death (late 4 BC, §6080; Matt 2:1, 19); the return to Nazareth after Herod''s death is headed 3 BC (§6084; Matt 2:19-23), so the event runs 4 BC to 3 BC. Matthew does not say the Magi were three, or kings. The massacre is recorded only by Matthew.', 1540),
(363, 'Presentation of Jesus in the Temple', -4, NULL, 0, 1, 'possible', 'worship', 'minor', 'Forty days after the birth, Mary and Joseph bring Jesus to the Temple to present him to the Lord and offer the sacrifice of the poor. The aged Simeon takes him in his arms and blesses God (the Nunc Dimittis), and the prophetess Anna speaks of him to all who looked for redemption.', 'Ussher, Annals §6061: headed 4 BC, on the fortieth day after the birth (Luke 2:22; Lev 12:2-4); the birth being late in 5 BC in the Annals, the presentation falls early in 4 BC. Was 5 BC.', 1530),
(364, 'Boy Jesus in the Temple', 8, NULL, 0, 1, 'possible', 'worship', 'minor', 'At twelve, Jesus goes up to Jerusalem with Mary and Joseph for Passover and stays behind; after three days they find him in the Temple among the teachers, who are astonished at his understanding. He returns with them to Nazareth and grows in wisdom and stature. It is the last time Joseph appears in the Gospels.', 'Ussher, Annals §6185: the Passover of AD 8, in the twelfth year of his age (Luke 2:41-42), on a 5 BC birth.', 1550),
(493, 'Death of John the Baptist', 32, NULL, 0, 1, 'possible', 'death', 'moderate', 'Herod Antipas has John imprisoned for condemning his marriage to Herodias, his brother Philip''s former wife. At Herod''s birthday banquet Herodias''s daughter pleases him with a dance and, prompted by her mother, asks for John''s head, which is carried in on a platter. John''s disciples bury the body and tell Jesus. Josephus names the fortress of Machaerus as the prison.', 'Matt 14:1-12; Mark 6:17-29. Ussher dates the imprisonment to AD 30 (§6311, John 3:24) and the beheading to AD 32, before the feeding of the 5,000 (Matt 14:12-13). Machaerus is Josephus''s account, not the Gospels''. Ussher, Annals §6362: AD 32.', 1750);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(45, 'Crucifixion', 33, NULL, 0, 1, 'probable', 'salvation', 'major', 'Condemned under Pontius Pilate, Jesus is crucified at Golgotha outside Jerusalem at Passover, and the Gospels present his death as an atoning sacrifice foretold by the prophets. Pilate is attested by an inscription found at Caesarea, and a crucified man''s heel bone from Jerusalem confirms the Roman practice.', 'Ussher: Friday 3 April AD 33; AD 30 (Friday 7 April) is the main alternative. Both fall within Pilate''s prefecture (AD 26-36). Ussher, Annals §6467-6479: AD 33.', 1990),
(46, 'Resurrection', 33, NULL, 0, 1, 'probable', 'salvation', 'major', 'On the third day, women find Jesus'' tomb empty and meet the risen Lord, who then appears to his disciples over forty days. Paul preserves an early creed listing eyewitnesses of the resurrection, the event Christians confess as death''s defeat and the firstfruits of the new creation.', 'The third day after the crucifixion (Ussher: Sunday 5 April AD 33); AD 33 (AD 30 on the main alternative). Ussher, Annals §6484: AD 33.', 2000),
(47, 'Ascension', 33, NULL, 0, 1, 'probable', 'miracle', 'major', 'Forty days after the resurrection, Jesus blesses his disciples on the Mount of Olives and is taken up into heaven, commissioning them as witnesses to the ends of the earth. Angels declare he will return as he departed, framing the church''s mission between promise and hope.', 'Forty days after the resurrection (Acts 1:3). Ussher, Annals §6493, §6506: AD 33.', 2080),
(48, 'Pentecost', 33, NULL, 0, 1, 'probable', 'miracle', 'major', 'On the feast of Pentecost, fifty days after Passover, the Holy Spirit descends on the disciples with rushing wind and tongues of fire, and Peter''s sermon draws about three thousand into the newborn church. Falling on Shavuot, the harvest festival, the event launches the gospel''s spread from Jerusalem.', 'Fifty days after the Passover of the crucifixion year (Acts 2:1; Lev 23:15-16); Ussher: 24 May AD 33 (AD 30 on the main alternative). Ussher, Annals §6510: AD 33.', 2090),
(49, 'Stoning of Stephen', 33, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'Stephen, one of the seven (Acts 6:5), is arrested, defends himself before the council and is stoned outside the city while Saul consents; he becomes the first Christian martyr (Acts 6:8-8:2).', 'Ussher, Annals 6518-6521: late AD 33, soon after Pentecost; the great persecution and scattering follow in AD 34 (6524, Acts 8:1). Scripture gives no year. Earlier row had AD 35; some place it AD 31-36.', 1880),
(50, 'Conversion of Paul', 35, NULL, 0, 1, 'probable', 'miracle', 'major', 'On the Damascus road, Saul of Tarsus, traveling to arrest followers of Jesus, was confronted by a blinding vision of the risen Christ. Acts recounts the event three times and Paul''s letters confirm it, marking the turning point that made the church''s fiercest persecutor its apostle to the Gentiles.', 'Ussher, Annals 6533-6538: AD 35, the year after the dispersion (Acts 8:1; 9:1-19). Scripture''s intervals: Paul went up to Jerusalem "after three years" (Gal 1:18; Ussher AD 37, 6587) and again "fourteen years after" (Gal 2:1; Ussher AD 52, 6753), so 17 years from conversion to the council on inclusive counting. Scholars commonly give AD 33-36.', 2120),
(51, 'Paul''s First Missionary Journey', 45, 45, 0, 0, 'probable', 'mission', 'moderate', 'Barnabas and Saul, sent out from Antioch by the Holy Spirit (Acts 13:2-3), travel through Cyprus and southern Galatia (Pisidian Antioch, Iconium, Lystra, Derbe) and return to Antioch.', 'Ussher, Annals 6691-6710: AD 45, after the famine visit of AD 44 (Acts 12:25; 13:1-3); they then stayed at Antioch "a long time" (Acts 14:28; 6712). Earlier row had AD 47-49 (a common modern estimate).', 2180),
(52, 'Council of Jerusalem', 52, NULL, 0, 1, 'probable', 'council', 'major', 'Apostles and elders gathered to decide whether Gentile converts must be circumcised and keep the law of Moses. After Peter testified that Jews and Gentiles alike are saved through the grace of the Lord Jesus (Acts 15:11) and James gave his judgment, the council freed Gentile believers from circumcision and asked them to abstain from food offered to idols, blood, things strangled and sexual immorality (Acts 15:20, 29).', 'Ussher, Annals 6753-6757: AD 52, "fourteen years after" Paul''s first Jerusalem visit of AD 37 (Gal 1:18; 2:1), Gal 2 being identified with Acts 15. Earlier row had AD 49; modern scholars range AD 48-50, and some identify Gal 2:1 with the famine visit of Acts 11:30.', 2250),
(53, 'Paul''s Second Missionary Journey', 53, 56, 0, 0, 'probable', 'mission', 'moderate', 'Paul brings the gospel to Greece.', 'Ussher, Annals 6780-6819: begins AD 53, after the council (AD 52) and a stay at Antioch (Acts 15:35-36); Corinth AD 54-56 (Acts 18:11); return to Caesarea, Jerusalem and Antioch AD 56 (Acts 18:22). Earlier row had AD 50-52.', 2260),
(54, 'Paul''s Third Missionary Journey', 56, 60, 0, 0, 'probable', 'mission', 'moderate', 'Paul strengthens churches in Asia Minor and Greece.', 'Ussher, Annals 6819-6848: begins AD 56 after the stay at Antioch (Acts 18:22-23); Ephesus AD 57-59 (Acts 19:8-10; 20:31); Macedonia and three months in Greece AD 60 (Acts 20:2-3); Jerusalem by Pentecost AD 60 (Acts 20:16). Earlier row had AD 54-58.', 2380),
(55, 'Destruction of Jerusalem', 70, NULL, 0, 1, 'certain', 'judgment', 'major', 'Roman legions under Titus crushed the Jewish revolt, burning the city and demolishing the Second Temple. The catastrophe ended sacrificial worship, scattered the Jewish people, and echoed Jesus'' warning that no stone would be left on another; the Arch of Titus in Rome still depicts the looted menorah.', 'Standard history (the Annals end at AD 73): Josephus, War 6; the Temple burned in the month of Av (August) AD 70. Ussher agrees (Annals 6968ff.); Masada fell AD 73 (6992).', 2670),
(56, 'John Writes Revelation', 95, NULL, 1, 1, 'traditional', 'scripture', 'moderate', 'Exiled on the rocky island of Patmos, John received sweeping visions of the risen Christ, letters for seven churches of Asia Minor, and the final triumph of the Lamb. Written to believers under Roman pressure, it closes the canon with the promise of a new heaven and new earth; Irenaeus placed it late in Domitian''s reign.', 'Standard history: Irenaeus (Against Heresies 5.30.3) places the vision late in Domitian''s reign (81-96), c. AD 95; Ussher''s Annals do not reach it. Early date (c. AD 65, Nero) is the main alternative.', 2720),
(86, 'Healing of a Man with Dropsy', 33, NULL, 1, 1, 'possible', 'miracle', 'minor', 'Jesus heals a man with dropsy (edema) on the Sabbath.', 'Luke 14:1-6; only in Luke. Within Luke''s journey to Jerusalem (Luke 9:51-19:28). Ussher, Annals §6411-6412 lies under the heading AD 33 but before the Dedication paragraph (§6422, December); year kept at AD 33 and flagged approximate.', 1890),
(87, 'Raising of Lazarus', 33, NULL, 0, 1, 'possible', 'miracle', 'major', 'At Bethany, Jesus called Lazarus out of the tomb four days after his death, having declared to Martha that he is the resurrection and the life. This climactic sign, recorded only in John, drew crowds toward Jerusalem and hardened the authorities'' resolve to put Jesus to death.', 'John 11:1-44; catalyst for the plot to kill Jesus. After the Feast of Dedication (John 10:22, winter) and the stay beyond the Jordan (John 10:40), and shortly before the last Passover (John 11:55). Ussher, Annals §6427: AD 33.', 1910),
(88, 'Healing of Ten Lepers', 33, NULL, 1, 1, 'possible', 'miracle', 'minor', 'Jesus heals ten lepers; only one (a Samaritan) returns to give thanks.', 'Luke 17:11-19; only in Luke. On the final journey to Jerusalem through Samaria and Galilee (Luke 17:11). Ussher, Annals §6418 lies under the heading AD 33 but before the Dedication paragraph (§6422, December); year kept at AD 33 and flagged approximate.', 1900),
(89, 'Healing of Blind Bartimaeus', 33, NULL, 0, 1, 'possible', 'miracle', 'minor', 'As Jesus leaves Jericho on his last journey to Jerusalem, blind Bartimaeus son of Timaeus cries out to the Son of David and receives his sight (Mark 10:46-52). Matthew tells of two blind men (Matt 20:29-34) and Luke sets the healing as Jesus drew near to Jericho (Luke 18:35-43); most harmonies treat the three accounts as one incident.', 'Mark 10:46-52; Matthew 20:29-34; Luke 18:35-43. Days before the Triumphal Entry. Ussher, Annals §6432: AD 33.', 1920),
(91, 'Cursing of the Fig Tree', 33, NULL, 0, 1, 'possible', 'miracle', 'minor', 'Jesus curses a barren fig tree and it withers.', 'Matthew 21:18-22; Mark 11:12-14, 20-25. The Monday of passion week. Ussher, Annals §6443: AD 33.', 1950),
(92, 'Healing of Malchus'' Ear', 33, NULL, 0, 1, 'probable', 'miracle', 'minor', 'Jesus heals the ear of the high priest''s servant during his arrest.', 'Luke 22:49-51; John 18:10-11. Night of the arrest. Ussher, Annals §6463: AD 33.', 1980),
(93, 'Catch of 153 Fish', 33, NULL, 0, 1, 'probable', 'miracle', 'minor', 'The risen Jesus directs a miraculous catch of 153 fish.', 'John 21:1-14; post-resurrection appearance at the Sea of Tiberias. Ussher, Annals §6492: AD 33.', 2060),
(143, 'Appearance to Mary Magdalene', 33, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'Weeping at the empty tomb, Mary Magdalene mistook the risen Jesus for the gardener until he spoke her name, and she answered, Rabbouni. John records this first appearance, and Jesus'' commission made her the first herald of the resurrection, honored in tradition as apostle to the apostles.', 'John 20:11-18; Mark 16:9-11. First post-resurrection appearance. Ussher, Annals §6486: AD 33.', 2010),
(144, 'Road to Emmaus', 33, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'Two downcast disciples walking to Emmaus were joined by the risen Jesus, unrecognized, who opened Moses and all the prophets to show that the Messiah had to suffer and enter glory. Luke alone tells the story in full; their eyes were opened when he broke the bread, and their hearts burned within them.', 'Luke 24:13-35; Mark 16:12-13. On the day of resurrection. Ussher, Annals §6488: AD 33.', 2020),
(145, 'Appearance to the Disciples', 33, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'On the evening of the resurrection, Jesus stood among his disciples behind locked doors, greeted them with peace, and showed them his hands and side. Luke notes that he ate broiled fish to prove he was no ghost, and John records him breathing on them the Holy Spirit and sending them as the Father sent him.', 'John 20:19-25; Luke 24:36-43. Thomas is absent. Ussher, Annals §6489: AD 33.', 2030),
(146, 'Appearance to Thomas', 33, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'A week after the resurrection, Jesus invited doubting Thomas to touch his wounds, and Thomas answered with the gospels'' most direct confession of Jesus'' deity, calling him his Lord and his God. Found only in John, the scene ends with a blessing on all who believe without seeing.', 'John 20:26-29. A week after the resurrection. Ussher, Annals §6490: AD 33.', 2040),
(147, 'Restoration of Peter', 33, NULL, 0, 1, 'probable', 'mission', 'moderate', 'Over a charcoal-fire breakfast by the Sea of Tiberias, the risen Jesus asked Peter three times whether he loved him, mirroring Peter''s three denials, and charged him to feed his sheep. John 21 records this restoration, which recommissioned the fallen disciple as shepherd of the early church.', 'John 21:15-19. Parallels Peter''s three denials. Ussher, Annals §6492: AD 33.', 2070),
(148, 'Great Commission', 33, NULL, 0, 1, 'probable', 'mission', 'major', 'On a mountain in Galilee, the risen Jesus claimed all authority in heaven and on earth and sent his disciples to make disciples of all nations, baptizing in the name of the Father, Son, and Holy Spirit. Matthew closes with this charge and the promise of Christ''s presence to the end of the age.', 'Matthew 28:16-20; Mark 16:15-18. Foundation of Christian mission. Ussher, Annals §6491: AD 33.', 2050),
(149, 'James Written', 49, NULL, 1, 1, 'possible', 'scripture', 'minor', 'James, brother of Jesus, writes the earliest NT epistle from Jerusalem — practical wisdom on faith and works, addressed to Jewish Christians scattered abroad.', 'Estimate, consistent with Scripture and Ussher: written before the council of AD 52 and by AD 63, when James was martyred (Ussher 6886). Often dated AD 45-49; some date it later (AD 60s).', 2240),
(150, 'Galatians Written', 58, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes to the Galatian churches defending justification by faith alone against Judaizers who insisted Gentile converts must follow the Mosaic Law.', 'Ussher, Annals 6830: AD 58, soon after Paul left the Galatians (Acts 18:23); Gal 2:1-10 recounts the Jerusalem visit Ussher identifies with the council of AD 52, so the letter must be later. Earlier row had AD 49 on the South Galatian theory; North Galatian theory c. AD 53-55.', 2400),
(151, '1 Thessalonians Written', 54, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes from Corinth, with Silvanus and Timothy (1 Thess 1:1; 3:6), to encourage the young Thessalonian church, with teaching on the return of Christ. It is the earliest of Paul''s letters in this chronology.', 'Ussher, Annals 6803: AD 54, after Timothy returned from Macedonia to Corinth (1 Thess 3:6; Acts 18:5). Earlier row had AD 51.', 2320),
(152, '2 Thessalonians Written', 55, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Paul writes a follow-up to Thessalonica, correcting misunderstandings about the Day of the Lord and urging believers to continue working.', 'Ussher, Annals 6803: written "later" than 1 Thessalonians with Silvanus and Timothy still with Paul (2 Thess 1:1), so during the Corinth stay of AD 54-56. AD 55 is an estimate within that span.', 2350),
(153, '1 Corinthians Written', 59, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes from Ephesus to the divided Corinthian church, addressing disputes, immorality, spiritual gifts, and the resurrection — including the great love chapter (ch. 13).', 'Ussher, Annals 6835: AD 59, written from Ephesus ("I will tarry at Ephesus until Pentecost", 1 Cor 16:8). Earlier row had AD 57.', 2410),
(154, 'Matthew Written', 55, NULL, 1, 1, 'possible', 'scripture', 'moderate', 'The Gospel of Matthew is composed, presenting Jesus as the fulfillment of Old Testament prophecy, structured around five major discourses.', 'Estimate: Ussher does not date it. Early tradition (Irenaeus, Origen) puts Matthew first, c. AD 50-60; most modern scholars place it after Mark, c. AD 70-90.', 2360),
(155, 'Mark Written', 55, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Mark composes a fast-paced account of Jesus'' ministry. Early church tradition (Papias, Irenaeus) says it records Peter''s preaching; most modern scholars regard it as the earliest Gospel, while the church fathers generally placed Matthew first.', 'Estimate: Ussher does not date the Gospel, and records that Mark died at Alexandria in Nero''s 8th year (Jerome; Annals 6864), though 2 Tim 4:11 has Mark alive in AD 66. AD 55 is a tradition-based estimate; Irenaeus places Mark after the deaths of Peter and Paul, Clement of Alexandria during Peter''s life. Modern range AD 50-70.', 2370),
(156, '2 Corinthians Written', 60, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes his most personal letter from Macedonia, defending his apostleship and describing his sufferings — "when I am weak, then I am strong."', 'Ussher, Annals 6841: AD 60, from Macedonia after Titus''s report (2 Cor 2:12-13; 7:5-7). Scripture: 2 Cor 12:2 looks back "fourteen years" to an experience Ussher places in AD 45 (6703). Earlier row had AD 57.', 2420),
(157, 'Romans Written', 60, NULL, 0, 1, 'probable', 'scripture', 'moderate', 'Paul writes his theological masterpiece from Corinth to the Roman church — the fullest exposition of justification by faith, the role of the Law, and God''s plan for Jews and Gentiles.', 'Ussher, Annals 6843: AD 60, from Corinth during the three months in Greece (Acts 20:2-3; Rom 15:25-26; 16:1, 23). Earlier row had AD 57.', 2430),
(158, 'Luke Written', 60, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Luke the physician composes his orderly Gospel account, addressed to Theophilus — the most detailed account of Jesus'' birth and parables unique to Luke.', 'Estimate: Luke wrote before Acts (Acts 1:1) and was with Paul at Caesarea in AD 60-62 (Acts 27:1; Ussher 6784, 6855-6873). Traditional range AD 58-63.', 2440),
(159, 'Ephesians Written', 64, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes from Roman imprisonment on the cosmic scope of God''s plan — the church as the body of Christ, spiritual blessings, and the armor of God.', 'Ussher, Annals 6910-6912: AD 64, during the two years in Rome (Acts 28:30; AD 63-65), carried by Tychicus (Eph 6:21). Earlier row had AD 62; some place the Prison Epistles at Caesarea or Ephesus.', 2540),
(160, 'Colossians Written', 64, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes from prison to Colossae affirming Christ''s supremacy over all creation and warning against false philosophy — "in him the whole fullness of deity dwells bodily."', 'Ussher, Annals 6909: AD 64, sent with Onesimus and Tychicus (Col 4:7-9) during the Roman imprisonment of AD 63-65. Earlier row had AD 62.', 2550),
(161, 'Philemon Written', 64, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes a brief personal letter from prison urging Philemon to receive his runaway slave Onesimus back as a brother in Christ — a window into early Christian social ethics.', 'Ussher, Annals 6906, 6909: AD 64, sent with Onesimus (Phlm 10-12) during the Roman imprisonment of AD 63-65. Earlier row had AD 62.', 2560),
(162, 'Philippians Written', 64, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes his letter of joy from prison to his most supportive church — including the great Christ-hymn (2:5-11) and "I can do all things through him who strengthens me."', 'Ussher, Annals 6905, 6908: AD 64, sent by Epaphroditus during the Roman imprisonment of AD 63-65 (Phil 2:25; 4:18). Earlier row had AD 62-63.', 2570),
(163, 'Acts Written', 65, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Luke composes Acts as the sequel to his Gospel, tracing the spread of the church from Jerusalem to Rome — ending abruptly with Paul under house arrest.', 'Scripture: Acts ends after Paul''s "two whole years" in Rome (Acts 28:30), which Ussher dates AD 63-65 (6878, 6915), so the book is finished about AD 65. Estimate: the date of writing is not given. Earlier row had AD 63; many scholars date Acts AD 80-90.', 2600),
(164, '1 Timothy Written', 65, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes to his young protégé Timothy at Ephesus with instructions on church leadership, false teaching, and godly conduct — "fight the good fight of the faith."', 'Ussher, Annals 6923-6924: AD 65, after Paul''s release (6915) and journey from Ephesus to Macedonia (1 Tim 1:3). Assumes release after Acts 28:30 (early tradition: 1 Clement 5). Earlier row had AD 64.', 2610),
(165, 'Titus Written', 65, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes to Titus on Crete with instructions for appointing elders and promoting sound doctrine — "the grace of God has appeared, bringing salvation for all people."', 'Ussher, Annals 6918, 6925: AD 65, written after Paul left Titus in Crete (Titus 1:5) and planned to winter at Nicopolis (Titus 3:12). Assumes release after Acts 28:30. Earlier row had AD 64.', 2620),
(166, '1 Peter Written', 64, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Peter writes from Rome (called "Babylon") to persecuted Christians scattered across Asia Minor, encouraging them to stand firm — "you are a chosen race, a royal priesthood."', 'Estimate: Ussher does not date it. Written from Rome (1 Pet 5:13, "Babylon") before 2 Peter (AD 66; 2 Pet 3:1), and before or about the persecution of AD 64. Range AD 62-64.', 2580),
(167, 'Jude Written', 65, NULL, 1, 1, 'possible', 'scripture', 'minor', 'Jude, brother of Jesus, writes a brief, urgent letter warning against false teachers who have infiltrated the church — "contend for the faith once delivered to the saints."', 'Estimate: Ussher does not date it. Jude was a brother of James (Jude 1), who died in AD 63; 2 Peter (AD 66) appears to draw on it, so c. AD 65. Modern range AD 65-80, and some reverse the dependence.', 2630),
(168, 'Hebrews Written', 64, NULL, 0, 1, 'probable', 'scripture', 'minor', 'An unknown author writes this sophisticated argument for Christ''s superiority over angels, Moses, and the Levitical priesthood — "Jesus Christ is the same yesterday, today, and forever."', 'Ussher, Annals 6907, 6913: AD 64, soon after Timothy''s release (Heb 13:23) with greetings from "they of Italy" (Heb 13:24); Ussher takes Paul as author. Authorship is not stated in the text and was long debated. Earlier row had AD 67.', 2590),
(169, '2 Timothy Written', 66, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Paul writes his final letter from a Roman dungeon to Timothy — a deeply personal farewell: "I have fought the good fight, I have finished the race, I have kept the faith."', 'Ussher, Annals 6937, 6939: AD 66, second Roman imprisonment, Paul expecting death (2 Tim 4:6-8). Earlier row had AD 67; death under Nero is tradition (1 Clement 5; Ussher AD 67, 6949).', 2640),
(170, '2 Peter Written', 66, NULL, 0, 1, 'probable', 'scripture', 'minor', 'Peter writes his final letter shortly before his martyrdom, warning against false teachers and affirming the certainty of Christ''s return — "with the Lord one day is as a thousand years."', 'Ussher, Annals 6937-6938: AD 66, shortly before Peter''s death (2 Pet 1:14); written after a first letter (2 Pet 3:1). Earlier row had AD 67.', 2650),
(171, 'John Written', 85, NULL, 1, 1, 'traditional', 'scripture', 'moderate', 'The apostle John composes his Gospel in Ephesus — a theological masterpiece opening with "In the beginning was the Word," presenting Jesus as the divine Son of God.', 'Estimate (tradition): Irenaeus and Eusebius place John at Ephesus into the 80s-90s. Range AD 85-95.', 2680),
(172, '1 John Written', 90, NULL, 1, 1, 'traditional', 'scripture', 'minor', 'John writes his first epistle from Ephesus, countering early Gnostic-like heresies and declaring that "God is light" and "God is love."', 'Estimate (tradition): AD 85-95, Ephesus.', 2690),
(173, '2 John Written', 90, NULL, 1, 1, 'traditional', 'scripture', 'minor', 'John writes a brief letter to "the elect lady and her children" — a local church — warning against false teachers who deny Christ came in the flesh.', 'Estimate (tradition): AD 85-95, Ephesus.', 2700),
(174, '3 John Written', 90, NULL, 1, 1, 'traditional', 'scripture', 'minor', 'John writes to Gaius commending his hospitality to traveling missionaries and rebuking Diotrephes, who "likes to put himself first."', 'Estimate (tradition): AD 85-95, Ephesus.', 2710),
(175, 'Philip Preaches in Samaria', 34, NULL, 0, 1, 'probable', 'mission', 'minor', 'Philip the evangelist proclaims Christ in Samaria; many believe and miracles accompany his preaching.', 'Ussher, Annals 6526: AD 34, after the scattering that followed Stephen''s death (Acts 8:1, 4-5).', 2100),
(176, 'Ethiopian Eunuch Baptized', 34, NULL, 0, 1, 'probable', 'mission', 'minor', 'Philip meets an Ethiopian official on the Gaza road, explains Isaiah 53, and baptizes him.', 'Ussher, Annals 6532: AD 34, after Philip''s work in Samaria (Acts 8:26-40).', 2110),
(177, 'Peter Raises Tabitha in Joppa', 38, NULL, 0, 1, 'probable', 'miracle', 'moderate', 'Peter raises the disciple Tabitha (Dorcas) from the dead in Joppa.', 'Ussher, Annals 6599-6600: AD 38, in Peter''s tour of the churches that had rest (Acts 9:31-43); before Cornelius (AD 40).', 2130),
(178, 'Peter and Cornelius in Caesarea', 40, NULL, 0, 1, 'probable', 'mission', 'major', 'Guided by paired visions, Peter entered the house of Cornelius, a centurion of the Italian Cohort in Caesarea, and preached Christ to Gentiles. When the Holy Spirit fell on the hearers before baptism, this Gentile Pentecost convinced the Jerusalem church that God shows no partiality, opening the door to the nations.', 'Ussher, Annals 6657-6659: AD 40, in the first year of Claudius (Acts 10-11). Scripture gives no year.', 2140),
(179, 'Church Established in Antioch', 43, NULL, 0, 1, 'probable', 'mission', 'moderate', 'Believers are first called Christians in Antioch as Barnabas and Saul teach the church for a year.', 'Ussher, Annals 6667: AD 43, when Barnabas brought Saul to Antioch and they taught "a whole year" (Acts 11:26); the gospel first came to Greeks there about AD 40 (6664, Acts 11:19-21).', 2150),
(180, 'Barnabas and Saul in Cyprus', 45, NULL, 0, 1, 'probable', 'miracle', 'minor', 'Paul blinds the sorcerer Bar-Jesus on Cyprus; the Roman proconsul Sergius Paulus believes.', 'Ussher, Annals 6692: AD 45, first stop of the first journey (Acts 13:4-12).', 2190),
(181, 'Paul Preaches in Pisidian Antioch', 45, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul preaches in the synagogue at Pisidian Antioch; many believe but Jews stir up opposition and drive the missionaries out.', 'Ussher, Annals 6698-6699: AD 45 (Acts 13:14-52).', 2200),
(182, 'Iconium — Belief and Opposition', 45, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul and Barnabas preach in Iconium; the city divides; they flee before a planned stoning.', 'Ussher, Annals 6700-6701: AD 45 (Acts 14:1-7).', 2210),
(183, 'Lystra — Healing and Stoning', 45, NULL, 0, 1, 'probable', 'miracle', 'minor', 'Paul heals a man lame from birth in Lystra; the crowd hails them as gods, then stones Paul and leaves him for dead.', 'Ussher, Annals 6702-6705: AD 45 (Acts 14:8-20). Ussher also thinks Paul''s rapture to the third heaven (2 Cor 12:2-4, "fourteen years" before 2 Corinthians) may belong here (6703).', 2220),
(184, 'Derbe — Many Disciples', 45, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul and Barnabas make many disciples in Derbe and begin the return journey strengthening the new churches.', 'Ussher, Annals 6706: AD 45 (Acts 14:20-21).', 2230),
(185, 'Macedonian Vision at Troas', 53, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul receives a vision at Troas: "Come over to Macedonia and help us." The gospel crosses into Europe.', 'Ussher, Annals 6783-6784: AD 53 (Acts 16:8-10).', 2270),
(186, 'Lydia Converted in Philippi', 53, NULL, 0, 1, 'probable', 'mission', 'moderate', 'Lydia, a seller of purple cloth, becomes the first European convert; Paul and Silas are imprisoned and the jailer is converted.', 'Ussher, Annals 6785-6787: AD 53 (Acts 16:11-40).', 2280),
(187, 'Paul in Thessalonica', 53, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul reasons in the synagogue at Thessalonica for three Sabbaths; opponents accuse the missionaries of "turning the world upside down."', 'Ussher, Annals 6788-6790: AD 53 (Acts 17:1-9; three Sabbath days, Acts 17:2).', 2290),
(188, 'Noble-Minded Bereans', 53, NULL, 0, 1, 'probable', 'mission', 'minor', 'The Bereans receive the word eagerly and examine the Scriptures daily to verify Paul''s message.', 'Ussher, Annals 6791: AD 53, after Thessalonica (Acts 17:10-15).', 2300),
(189, 'Paul on the Areopagus in Athens', 54, NULL, 0, 1, 'probable', 'mission', 'moderate', 'Paul addresses the philosophers of Athens on Mars Hill, proclaiming the "Unknown God" and the resurrection.', 'Ussher, Annals 6793-6794: AD 54, while Paul waited at Athens for Silas and Timothy (Acts 17:16-34).', 2330),
(190, 'Paul in Corinth — 18 Months', 54, 56, 0, 1, 'probable', 'mission', 'moderate', 'Paul stays 18 months with Aquila and Priscilla in Corinth; the proconsul Gallio dismisses charges against him.', 'Ussher, Annals 6798-6818: Paul reaches Corinth in AD 54, stays "a year and six months" (Acts 18:11) with Gallio''s judgment in late AD 54 (6815, Acts 18:12-17), and sails in AD 56. The Gallio inscription at Delphi is commonly dated AD 51-52, which would move Paul''s stay to c. AD 50-52.', 2340),
(191, 'Paul in Ephesus — 2 Years', 57, 59, 0, 0, 'probable', 'mission', 'moderate', 'Paul teaches in Ephesus for over two years with extraordinary miracles; new believers burn their occult scrolls; Demetrius the silversmith starts a riot.', 'Ussher, Annals 6822-6838: Paul reaches Ephesus in AD 57 and leaves in AD 59; Acts 19:10 gives two years in the school of Tyrannus (Acts 20:31 "three years" counts the whole stay).', 2390),
(192, 'Farewell to Ephesian Elders at Miletus', 60, NULL, 0, 1, 'probable', 'teaching', 'minor', 'Paul calls the Ephesian elders to Miletus for an emotional farewell: "I have not coveted anyone''s silver or gold."', 'Ussher, Annals 6848: spring AD 60, as Paul hurried to reach Jerusalem by Pentecost (Acts 20:16). Earlier row had AD 58.', 2450),
(193, 'Paul Arrested in Jerusalem', 60, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'Paul is seized in the temple, beaten by the crowd, and transferred to Roman custody under the tribune Claudius Lysias.', 'Ussher, Annals 6851-6853: Pentecost AD 60 (Acts 21:17-23:10). Earlier row had AD 58 (many scholars AD 57).', 2460),
(194, 'Paul''s Trial before Felix and Festus', 60, 62, 0, 0, 'probable', 'persecution', 'moderate', 'Paul is held in Caesarea two years under Felix (Acts 24:27), then stands before his successor Festus; he defends himself before Agrippa II and Bernice and appeals to Caesar.', 'Scripture: two years under Felix, then Festus (Acts 24:27). Ussher, Annals 6855-6869: Paul is in Caesarea AD 60-62; Festus arrives AD 62 (6868) and Agrippa II hears Paul (Acts 25-26). Earlier row had AD 58-60.', 2470),
(195, 'Storm and Fair Havens of Crete', 62, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul warns against sailing late in the season; a violent northeaster batters the ship for 14 days as it drifts toward Malta.', 'Ussher, Annals 6873-6874: autumn AD 62, after the Day of Atonement fast (Acts 27:9). Earlier row had AD 60.', 2480),
(196, 'Shipwreck on Malta', 62, 63, 0, 0, 'probable', 'miracle', 'moderate', 'All 276 aboard reach shore safely; Paul is bitten by a viper but unharmed and heals the sick on the island for three months.', 'Ussher, Annals 6874-6877: shipwreck late AD 62; three months on Malta (Acts 28:11) until early AD 63. Earlier row had AD 60.', 2490),
(197, 'Landing at Puteoli', 63, NULL, 0, 1, 'probable', 'mission', 'minor', 'Paul and his companions land at the Italian port of Puteoli and stay seven days with believers there.', 'Ussher, Annals 6877-6878: spring AD 63, after the winter on Malta (Acts 28:11-14). Earlier row had AD 61.', 2510),
(198, 'Paul Arrives in Rome', 63, 65, 0, 0, 'probable', 'mission', 'moderate', 'After appealing to Caesar, surviving shipwreck at Malta, Paul reached Rome under guard and spent two years in rented lodging, welcoming all and preaching the kingdom unhindered. Acts closes with the gospel proclaimed in the empire''s capital, and tradition places several prison epistles in this period.', 'Scripture: "two whole years" in his own hired house (Acts 28:30). Ussher, Annals 6878, 6915: arrival AD 63, release AD 65. Earlier row had AD 61-63.', 2520),
(365, 'Triumphal Entry into Jerusalem', 33, NULL, 0, 1, 'probable', 'kingdom', 'major', 'Jesus rides into Jerusalem on a colt while the crowds spread garments and branches and cry Hosanna to the Son of David, as in Zechariah 9:9. It opens the week of his passion.', 'The Sunday before the crucifixion (John 12:1, 12). Ussher gives 29 March AD 33 (AD 30 on the main alternative). Ussher, Annals §6438: AD 33.', 1940),
(366, 'Last Supper', 33, NULL, 0, 1, 'probable', 'covenant', 'major', 'On the night he was betrayed Jesus eats a final meal with the Twelve, washes their feet (John 13), gives them the bread and the cup as his body and his blood of the new covenant, and foretells Judas''s betrayal and Peter''s denial. Christians understand the Lord''s Supper differently but all trace it to this meal.', 'The Synoptic Gospels call it the Passover meal (Luke 22:15); John places the crucifixion on the day of preparation (John 18:28; 19:14), a long-debated question of harmonisation. Ussher: Thursday 2 April AD 33. Ussher, Annals §6454: AD 33.', 1960),
(367, 'Arrest and Trials of Jesus', 33, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'After praying in Gethsemane, Jesus is arrested by a party guided by Judas and taken to Annas and Caiaphas and before the council, while Peter denies him three times. In the morning he is brought to Pilate, who sends him to Herod Antipas and then, after offering to release him instead of Barabbas, hands him over to be crucified.', 'From the night of the Last Supper to the morning of the crucifixion (Ussher: 3 April AD 33). Ussher, Annals §6467: AD 33.', 1970),
(368, 'James Killed and Peter Imprisoned by Agrippa I', 44, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'Herod Agrippa I has James the brother of John killed with the sword and, seeing that it pleased the people, arrests Peter during the days of unleavened bread. An angel frees Peter, who goes to the house of Mary the mother of John Mark. Soon afterwards Agrippa is struck down at Caesarea and dies.', 'Ussher, Annals 6674-6679: AD 44, at Passover shortly before Agrippa I died at Caesarea (Acts 12:2-3, 23; Josephus Ant. 19.343-352).', 2160),
(369, 'Martyrdom of James, Brother of Jesus', 63, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'James, leader of the Jerusalem church, is condemned by the high priest Ananus and stoned at Jerusalem while Judea is without a Roman governor. Josephus records the event, and the second-century writer Hegesippus (quoted by Eusebius) gives a fuller account. Scripture does not record it.', 'Ussher, Annals 6885-6887: AD 63, after the death of Festus and before Albinus arrived (Josephus Ant. 20.197-203). Many modern scholars date this AD 62.', 2500),
(370, 'Great Fire of Rome and Nero''s Persecution', 64, NULL, 0, 1, 'certain', 'persecution', 'moderate', 'In July AD 64 a fire destroys much of Rome. Rumour blames Nero, who fastens the guilt on the Christians and has many of them put to death with great cruelty (Tacitus). It is the first known Roman state violence against Christians.', 'Tacitus, Annals 15.38-44, dates the fire to July AD 64.', 2530),
(371, 'Martyrdom of Peter and Paul', 67, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'Early church tradition holds that Peter and Paul were both put to death at Rome under Nero, Paul by the sword and Peter by crucifixion (1 Clement 5; Eusebius). Scripture does not record either death, though Jesus foretells Peter''s (John 21:18-19) and Paul anticipates his own (2 Tim 4:6-8).', 'Ussher, Annals 6949: Paul beheaded at Rome on 29 June AD 67, Peter martyred at the same time (Dionysius of Corinth; Origen), both before Nero''s death in June AD 68. Scripture does not record either death. Eusebius''s Chronicle gives AD 67/68; some link it to the AD 64 persecution.', 2660),
(492, 'Zacchaeus Meets Jesus in Jericho', 33, NULL, 0, 1, 'possible', 'salvation', 'moderate', 'As Jesus passes through Jericho on the way to Jerusalem, Zacchaeus, a wealthy chief tax collector too short to see over the crowd, climbs a sycamore tree. Jesus calls him down and stays at his house; Zacchaeus gives half his goods to the poor and repays fourfold. Jesus declares that salvation has come to the house.', 'Luke 19:1-10. Just before the Triumphal Entry (Luke 19:28). Ussher, Annals §6433: AD 33.', 1930),
(494, 'Gamaliel''s Counsel before the Sanhedrin', 33, NULL, 0, 1, 'probable', 'persecution', 'moderate', 'After the apostles are arrested and freed by an angel, they are brought before the council and Peter answers that they must obey God rather than men. When the council wants to kill them, the Pharisee Gamaliel advises restraint: if the movement is of men it will come to nothing, but if of God no one can overthrow it. They beat the apostles and release them.', 'Ussher, Annals 6516: AD 33, the year of Pentecost (Acts 5 follows Acts 2-4 closely). Earlier row put it in AD 34 by harmonisation.', 1870),
(495, 'Famine Relief Sent from Antioch to Judea', 44, NULL, 0, 1, 'probable', 'mission', 'minor', 'The prophet Agabus comes to Antioch and foretells a great famine, which comes in the reign of Claudius. The disciples there decide each according to his means to send relief to the believers in Judea, and Barnabas and Saul carry the gift to the elders at Jerusalem.', 'Ussher, Annals 6668, 6673: Agabus foretells the famine in AD 43; the gift is sent and carried in AD 44, the year of Agrippa I''s death (Acts 11:27-30; 12:25). Ussher also notes a famine in Claudius''s second year (AD 41, 6666) and an eleventh-year famine. Earlier row had AD 46.', 2170),
(496, 'Claudius Expels the Jews from Rome', 54, NULL, 1, 1, 'possible', 'persecution', 'minor', 'The emperor Claudius orders all Jews to leave Rome. Among those who go is the couple Aquila and Priscilla, who settle in Corinth and there welcome Paul. The edict is probably tied to disturbances in the Jewish community, which the Roman historian Suetonius links to a certain "Chrestus".', 'Scripture: Aquila and Priscilla were "lately come from Italy" when Paul reached Corinth (Acts 18:2). Ussher, Annals 6792, 6798: places the expulsion immediately before Paul''s arrival in AD 54 (Claudius died October AD 54); he does not date the decree separately. Orosius gives AD 49, the common modern date.', 2310);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(57, 'Death of John', 100, NULL, 1, 1, 'traditional', 'death', 'minor', 'According to early tradition (Irenaeus, Eusebius), John lived at Ephesus into the reign of Trajan (from AD 98) and died there, the last of the Twelve; his death is taken to close the Apostolic Age. Scripture records nothing about it (John 21:23 only corrects a rumour that he would not die).', 'Tradition (Irenaeus, Eusebius): died at Ephesus under Trajan (from AD 98), c. AD 98-100. Estimate; not in Scripture or the Annals.', 2730),
(95, 'Martyrdom of Ignatius of Antioch', 108, NULL, 1, 1, 'probable', 'persecution', 'moderate', 'Bishop Ignatius of Antioch is taken to Rome and executed under Trajan; his seven letters on church order, the Eucharist and martyrdom are among the earliest post-apostolic writings.', 'Traditional date c. 108 (Eusebius, Church History III.36, under Trajan, 98-117); modern estimates range from c. 107 to c. 117.', 2740),
(96, 'Martyrdom of Polycarp', 155, NULL, 1, 1, 'probable', 'persecution', 'moderate', 'Bishop Polycarp of Smyrna is put to death in the stadium at Smyrna, saying "Eighty-six years I have served Him, and He never did me any injury." In the earliest account the flames did not consume him and he was finally stabbed.', '22/23 February, 155 or 156 (standard modern view); Eusebius''s Chronicle implies c. 166-167, which most scholars reject.', 2750),
(97, 'Irenaeus Writes Against Heresies', 180, NULL, 1, 1, 'probable', 'teaching', 'moderate', 'Irenaeus of Lyon writes Against Heresies (the Greek original is largely lost; a complete Latin translation survives), refuting Gnostic teaching and appealing to Scripture, the rule of faith and the succession of bishops from the apostles.', 'Written in Greek, c. 175-185, while Irenaeus was bishop of Lyon (Book III mentions Eleutherus as pope, 174-189).', 2760),
(98, 'Origen Opens Catechetical School', 203, NULL, 1, 1, 'probable', 'teaching', 'minor', 'Origen, at about age 18, becomes head of the catechetical school in Alexandria, beginning a career of biblical scholarship and allegorical interpretation.', 'Eusebius, Church History VI.3, gives his age as 18 under Bishop Demetrius; c. 203.', 2780),
(99, 'Diocletian Persecution Begins', 303, NULL, 0, 1, 'certain', 'persecution', 'major', 'Emperor Diocletian and his co-emperors issue edicts ordering churches destroyed, scriptures burned and clergy imprisoned: the most severe empire-wide persecution, though enforcement varied widely from region to region.', 'Eusebius, Church History VIII; Diocletian issued edicts in 303-304.', 2800),
(390, 'Conversion of Armenia', 301, NULL, 1, 1, 'traditional', 'mission', 'moderate', 'According to Armenian tradition, Gregory the Illuminator converts King Tiridates III, making Armenia the first state to adopt Christianity officially. The Armenian Apostolic Church remains one of the oldest national churches.', 'Traditional date 301; some scholars prefer c. 314.', 2790),
(510, 'Tertullian Writes the Apology', 197, NULL, 1, 1, 'probable', 'teaching', 'minor', 'Tertullian of Carthage addresses the Roman governors in defence of Christians, arguing that they are loyal subjects and that persecution is unjust. He is the first major Christian author to write in Latin, and the work shows the church in North Africa.', 'Apologeticus is usually dated to 197.', 2770),
(512, 'Constantine Proclaimed Emperor at York', 306, NULL, 0, 1, 'certain', 'kingdom', 'minor', 'When Constantius I dies at York in July 306, his troops proclaim his son Constantine emperor. After years of civil war this begins his rise to sole rule and the end of imperial persecution.', 'Constantius died 25 July 306; Constantine was acclaimed that day.', 2810);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(100, 'Edict of Milan', 313, NULL, 0, 0, 'certain', 'kingdom', 'major', 'In 313 the emperors Constantine and Licinius agreed to extend religious toleration to Christians and other cults and to restore confiscated church property, building on Galerius''s edict of toleration (311). Christianity became a legally protected faith, though not yet the state religion.', 'Agreement reached at Milan in early 313; the text survives as Licinius''s rescript issued at Nicomedia in June 313 (Lactantius, De Mortibus Persecutorum 48; Eusebius, Church History X.5). Galerius had already granted toleration in 311.', 2820),
(101, 'Council of Nicaea', 325, NULL, 0, 0, 'certain', 'council', 'major', 'Constantine convened bishops from across the empire at Nicaea to settle the Arian controversy over the Son''s divinity. The council confessed Christ as homoousios, of one being with the Father; the Nicene Creed in use today is the form expanded at Constantinople in 381. Tradition numbers the assembled bishops at 318.', 'First Ecumenical Council, convened by Constantine at Nicaea, May-June 325.', 2830),
(102, 'Athanasius Lists the 27 NT Books', 367, NULL, 0, 0, 'certain', 'scripture', 'major', 'In his thirty-ninth Festal Letter from Alexandria, Bishop Athanasius listed exactly the twenty-seven books of today''s New Testament, the earliest surviving list to match it precisely. Calling them the springs of salvation, he distinguished canonical Scripture from disputed and spurious writings.', 'Athanasius, 39th Festal Letter (367 AD).', 2860),
(103, 'Council of Carthage Affirms the Biblical Canon', 397, NULL, 0, 0, 'probable', 'scripture', 'moderate', 'A synod of North African bishops, in which Augustine took part, affirmed a list of Scripture that included the twenty-seven New Testament books and an Old Testament that included the books Protestants call the Apocrypha. Following the earlier synod of Hippo (393), it was a regional statement that later received wider authority in the West; the Eastern churches and the Reformers did not adopt it unchanged.', 'Council of Carthage, 397 AD (the list is also reaffirmed at Carthage in 419).', 2900),
(104, 'Jerome Translates the Latin Bible (the Vulgate)', 382, 405, 1, 1, 'probable', 'scripture', 'moderate', 'Beginning at the request of Pope Damasus in Rome (382) and continuing in his monastery at Bethlehem, Jerome revised the Latin Gospels and Psalms and translated the Old Testament from the Hebrew text he called the hebraica veritas rather than from the Greek Septuagint. The resulting Vulgate became the standard Bible of Western Christendom for about a thousand years.', 'Begun 382 under Damasus; the Old Testament translation from Hebrew was finished c. 405. The name ''Vulgate'' and the final composition of the book came later.', 2880),
(105, 'Council of Chalcedon', 451, NULL, 0, 0, 'certain', 'council', 'major', 'Bishops meeting at Chalcedon defined that Christ is one person in two natures, fully God and fully man, without confusion or separation. Guided by Pope Leo''s Tome against Eutyches'' teaching, the definition became the standard of Christology for the Catholic, Eastern Orthodox and most Protestant churches; the Oriental Orthodox churches did not accept it, and the division has lasted.', 'Fourth Ecumenical Council, Chalcedon (451 AD).', 2940),
(391, 'Conversion of the Kingdom of Aksum (Ethiopia)', 330, NULL, 1, 1, 'possible', 'mission', 'moderate', 'Under King Ezana, Aksum embraces Christianity through the missionary Frumentius, consecrated first bishop by Athanasius of Alexandria. The Ethiopian Orthodox Tewahedo Church traces its origin here.', 'c. 330-340; Rufinus (Church History I.9) and Ezana''s inscriptions and coins.', 2850),
(392, 'Council of Constantinople', 381, NULL, 0, 1, 'certain', 'council', 'major', 'The Second Ecumenical Council, called by Theodosius I, reaffirms Nicaea against Arian and Macedonian views and confesses the deity of the Holy Spirit. The creed now recited as the Nicene Creed (the Niceno-Constantinopolitan Creed) is linked to this council.', 'May-July 381.', 2870),
(393, 'Council of Ephesus', 431, NULL, 0, 1, 'certain', 'council', 'moderate', 'The Third Ecumenical Council, meeting June-July 431, condemns Nestorius, affirms that Mary may be called Theotokos (God-bearer), and upholds the unity of Christ''s person. The Church of the East did not accept it.', 'Opened 22 June 431.', 2920),
(511, 'Helena Journeys to the Holy Land', 327, 328, 1, 1, 'probable', 'other', 'minor', 'Helena, mother of Constantine, travels to Jerusalem and Palestine and supports church building at sites tied to the life of Christ. Later tradition says she found the True Cross; this is a legend first recorded decades afterward, not something Eusebius reports. Constantines churches at the Holy Sepulchre and Bethlehem belong to the same programme.', 'Eusebius dates the visit shortly before her death c. 330; 326-328 in modern accounts. The True Cross story is later tradition.', 2840),
(513, 'Augustines Conversion and Baptism', 386, 387, 0, 1, 'certain', 'salvation', 'major', 'In a garden at Milan in 386, Augustine hears a childs voice say take up and read, opens Romans 13, and is converted. With his son Adeodatus he is baptised by Ambrose at Easter 387. He describes it in his Confessions; his mother Monica died soon after, on the way back to Africa.', 'Confessions Books 8-9. Conversion August 386; baptism Easter 24-25 April 387.', 2890),
(514, 'John Chrysostom Preaches at Constantinople', 398, 404, 0, 0, 'certain', 'teaching', 'moderate', 'Appointed archbishop of Constantinople in 398, John gains the name Chrysostom (golden-mouthed) for preaching that presses wealth, justice and care for the poor. His criticism of the court brings him exile in 403 and a final banishment in 404. He died in exile in 407.', 'Consecrated 26 February 398; exiled finally June 404; died 14 September 407.', 2910),
(515, 'Patricks Mission to Ireland', 432, NULL, 1, 1, 'traditional', 'mission', 'moderate', 'Patrick, a Briton once taken to Ireland as a slave, returns as a missionary bishop and plants churches there. His own Confession is the main source. Tradition puts his arrival in 432 and the founding of Armagh a little later; many modern scholars place his work later in the fifth century.', 'Traditional date 432 from later Irish annals; the date is disputed.', 2930);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(106, 'Fall of the Western Roman Empire', 476, NULL, 0, 0, 'certain', 'kingdom', 'moderate', 'Romulus Augustulus, traditionally counted as the last Western Roman emperor, is deposed by Odoacer. The church, already organised under bishops across the former provinces, became a main carrier of continuity in a fragmented West.', 'Traditional date: 476 AD.', 2950),
(107, 'Benedict Writes His Rule', 530, NULL, 1, 1, 'probable', 'reform', 'major', 'Benedict of Nursia writes his Rule for monks, which became the standard foundation of Western monastic life and helped preserve learning in the early Middle Ages. The later motto "ora et labora" (pray and work) sums up its spirit.', 'Rule of St. Benedict, traditionally c. 530 at Monte Cassino; some scholars date it to c. 540s. It draws on the earlier anonymous Rule of the Master.', 2960),
(108, 'Synod of Whitby', 664, NULL, 0, 0, 'certain', 'council', 'minor', 'King Oswiu of Northumbria decides in favor of the Roman method of dating Easter and the Roman tonsure over the Ionan (Celtic) customs, aligning the Northumbrian church with Rome.', 'Bede, Ecclesiastical History of the English People, III.25.', 3000),
(109, 'Rise of Islam and Muslim Conquests', 632, 750, 0, 1, 'certain', 'conquest', 'moderate', 'After Muhammad''s death (632), Muslim armies conquer Syria, Egypt and North Africa, most of them long Christian lands, and the Sasanian Persian Empire, home to the Church of the East, within about a century, permanently altering the geography of Christianity.', 'Rapid expansion of the Rashidun and Umayyad caliphates, 632–750 AD.', 2980),
(110, 'Charlemagne Crowned Emperor', 800, NULL, 0, 0, 'certain', 'kingdom', 'moderate', 'Pope Leo III crowns Charlemagne emperor of the Romans on Christmas Day, 800, reviving the imperial title in the West; the Byzantine empire contested it. The title ''Holy Roman Emperor'' came later.', 'December 25, 800 AD; recorded by Einhard and the Royal Frankish Annals.', 3020),
(394, 'Alopen Brings Christianity to China', 635, NULL, 0, 1, 'probable', 'mission', 'moderate', 'The Church of the East missionary Alopen reaches Chang''an and is received by Emperor Taizong. The Xi''an Stele (781) records the early Christian presence in Tang China.', 'Arrival 635 per the Xi''an Stele (781).', 2990),
(395, 'Second Council of Nicaea', 787, NULL, 0, 1, 'certain', 'council', 'moderate', 'The Seventh Ecumenical Council restores the veneration of icons after the iconoclast controversy, distinguishing veneration from the worship due to God alone. It is the last council accepted by both Catholic and Orthodox churches as ecumenical.', 'September-October 787.', 3010),
(396, 'Cyril and Methodius Mission to Moravia', 863, NULL, 0, 1, 'certain', 'mission', 'moderate', 'The Byzantine brothers Cyril and Methodius reach Great Moravia, creating the Glagolitic script and translating Scripture and liturgy into Slavic, laying the foundation for Slavic Christianity.', 'Arrival 863; Cyril died 869, Methodius 885.', 3030),
(516, 'Gregory the Great Sends Augustine to England', 597, NULL, 0, 1, 'certain', 'mission', 'moderate', 'Pope Gregory I sends the monk Augustine and about forty companions to Kent. King Aethelberht lets them preach in Canterbury, and the mission founds the English churchs see there.', 'Landing in Kent 597 (Bede, Ecclesiastical History I).', 2970);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(111, 'Great Schism: East-West Split', 1054, NULL, 0, 0, 'certain', 'other', 'major', 'In July 1054 Cardinal Humbert, legate of Pope Leo IX (who had died that April), laid a bull of excommunication on the altar of Hagia Sophia, and Patriarch Michael Cerularius and his synod responded in kind. The episode became the conventional date for the division of Christendom into a Roman Catholic West and an Orthodox East, though the estrangement over papal authority, the filioque clause and diverging customs was gradual and long in the making.', 'In July 1054 Cardinal Humbert and Patriarch Michael Cerularius excommunicated one another, an episode that became the conventional date for the split; the estrangement was gradual and the mutual anathemas of 1054 were lifted in 1965.', 3040),
(112, 'Council of Clermont — First Crusade Called', 1095, NULL, 0, 0, 'certain', 'war', 'moderate', 'Pope Urban II calls on Christians to aid the Byzantine Empire and recover Jerusalem; the exact wording of the speech is known only from later accounts. The First Crusade captured Jerusalem in 1099, beginning two centuries of Crusading warfare.', 'Pope Urban II''s speech at the Council of Clermont, November 1095.', 3050),
(113, 'Francis of Assisi Founds the Franciscans', 1209, NULL, 1, 0, 'probable', 'reform', 'moderate', 'Francis renounces his wealthy life and founds the Order of Friars Minor, preaching radical poverty, simplicity, and care for the poor.', 'Francis received papal approval in 1209/1210.', 3060),
(114, 'Thomas Aquinas Writes the Summa Theologiae', 1265, 1273, 1, 0, 'probable', 'teaching', 'moderate', 'Aquinas works on his Summa Theologiae from about 1265 until he stops writing in December 1273, leaving the third part unfinished at his death in 1274. It became one of the most influential works of Christian theology, setting out faith and reason in a single systematic plan.', 'Begun c. 1265; Aquinas ceased writing in December 1273 and died 7 March 1274, leaving the work incomplete.', 3070),
(115, 'The Wycliffe Bible Appears in English', 1382, NULL, 0, 1, 'probable', 'scripture', 'major', 'The first complete Bible in English, translated from the Latin Vulgate, appears in the Wycliffe circle: an Early Version c. 1382, largely by Nicholas Hereford, and a smoother Later Version c. 1388-1395 by John Purvey and others. Spread in hand-copied manuscripts by his Lollard followers, it survives in nearly 250 copies; Wycliffe himself was condemned after death.', 'Early Version c. 1382 (largely Nicholas Hereford); Later Version c. 1388-1395 (John Purvey and others). Wycliffe''s personal share is uncertain.', 3080);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(116, 'Jan Hus Martyred', 1415, NULL, 0, 0, 'certain', 'persecution', 'moderate', 'Czech reformer Jan Hus is condemned as a heretic and burned at the stake at the Council of Constance, which judged his teaching on the church and papal authority heretical; he had also preached in Czech.', 'July 6, 1415, at the Council of Constance.', 3090),
(117, 'Gutenberg Prints the Bible', 1455, NULL, 1, 1, 'probable', 'scripture', 'major', 'In Mainz, Johannes Gutenberg used movable metal type to print the Latin Vulgate in a run of perhaps 180 copies on paper and vellum, of which about 49 survive. The 42-line Bible was the first major book printed with movable type in Europe, and the press it launched would carry Scripture and reform across the continent.', 'Gutenberg Bible printed c. 1454-1455 in Mainz; copies were on sale by March 1455.', 3110),
(118, 'Martin Luther Posts the 95 Theses', 1517, NULL, 0, 0, 'certain', 'reform', 'major', 'Martin Luther challenged the sale of indulgences with ninety-five theses for academic debate, which he sent to Archbishop Albert of Mainz; that he also posted them on the Wittenberg castle church door is traditional. Printers spread them across Germany within weeks, and they became the opening of the Reformation.', '31 October 1517: Luther sent the Theses to Archbishop Albert of Mainz on this date, which is certain. Whether he also nailed them to the Castle Church door is traditional and doubted by some historians.', 3120),
(119, 'Diet of Worms', 1521, NULL, 0, 0, 'certain', 'reform', 'major', 'Summoned before Emperor Charles V, Martin Luther refused to recant his writings, declaring his conscience captive to the Word of God. Outlawed by the Edict of Worms (May 1521), he was sheltered at Wartburg Castle, where he translated the New Testament into German from the Greek.', 'April 17-18, 1521.', 3130),
(120, 'Tyndale''s New Testament Published', 1526, NULL, 0, 0, 'certain', 'scripture', 'moderate', 'William Tyndale published the first printed English New Testament, translated directly from Erasmus'' Greek text and smuggled into England in bales of cloth. Though Tyndale was later executed, his vivid phrasing endured, shaping much of the King James New Testament''s wording.', 'Printing began in Cologne in 1525 but was stopped by the authorities; the first complete printed English New Testament appeared at Worms in 1526. Tyndale was executed in 1536.', 3150),
(121, 'Calvin Publishes Institutes of the Christian Religion', 1536, NULL, 0, 0, 'certain', 'teaching', 'moderate', 'John Calvin publishes the first edition of the Institutes in Basel at age 26, expanded in later editions to the definitive 1559 Latin text, which became a foundational statement of Reformed theology.', 'First edition 1536; expanded final edition 1559.', 3170),
(122, 'Council of Trent', 1545, 1563, 0, 0, 'certain', 'council', 'major', 'Meeting in three periods between 1545 and 1563, the Council of Trent defined Catholic doctrine on Scripture, justification and the sacraments, and enacted reforms of clergy and discipline in response to Protestant challenges.', 'Council of Trent, 1545–1563 (three periods over 18 years).', 3190),
(123, 'King James Version Published', 1611, NULL, 0, 0, 'certain', 'scripture', 'major', 'Commissioned by James I after the Hampton Court Conference (1604), about fifty scholars in six companies at Westminster, Oxford and Cambridge produced a new English Bible from the Hebrew and Greek. Building heavily on Tyndale, the King James Version became among the most influential books in the English language.', 'Published 1611.', 3230),
(124, 'Westminster Confession of Faith', 1643, 1646, 0, 0, 'certain', 'council', 'moderate', 'The Westminster Assembly (1643-1653) produces a Reformed confession, completed in 1646, that became the standard of English-speaking Presbyterian churches and shaped Congregational and Baptist confessions.', 'The Assembly first met in 1643; the Confession was completed in 1646 and adopted by the Church of Scotland (1647); the English Parliament approved most of it in 1648.', 3240),
(397, 'Fall of Constantinople', 1453, NULL, 0, 1, 'certain', 'war', 'moderate', 'On 29 May 1453 Ottoman forces under Mehmed II take Constantinople, ending the Byzantine Empire and placing the Ecumenical Patriarchate under Ottoman rule.', '29 May 1453.', 3100),
(517, 'Ignatius Founds the Jesuits', 1540, NULL, 0, 1, 'certain', 'reform', 'moderate', 'Pope Paul III approves the Society of Jesus on 27 September 1540. Founded by Ignatius of Loyola and his companions, it centres on education, missions and obedience to the pope and becomes a major force in Catholic renewal and world missions.', 'Bull Regimini militantis ecclesiae, 27 September 1540.', 3180),
(518, 'Francis Xavier Reaches Japan', 1549, NULL, 0, 1, 'certain', 'mission', 'moderate', 'Francis Xavier, a Jesuit co-founder, lands at Kagoshima on 15 August 1549 and begins the first Christian mission in Japan. After two years he leaves a small community that grows into one of the largest in Asia before later persecution.', 'Landed 15 August 1549; left Japan in 1551.', 3200),
(519, 'Luther Marries Katharina von Bora', 1525, NULL, 0, 0, 'certain', 'other', 'minor', 'A former nun who left her convent in 1523, Katharina marries Martin Luther at Wittenberg on 13 June 1525. Their household becomes the model of the Protestant parsonage, and she manages its finances and the Black Cloister.', '13 June 1525.', 3140),
(520, 'Valladolid Debate on the Indies', 1550, 1551, 0, 0, 'certain', 'council', 'moderate', 'At Charles Vs order, Bartolome de las Casas and Juan Gines de Sepulveda argue before a council of theologians whether Spain may wage war on the native peoples. The judges gave no formal verdict and both sides claimed success, but Las Casass defence of Native Americans dignity became a landmark.', 'Sessions August-September 1550 and April-May 1551.', 3210),
(521, 'Scottish Reformation', 1560, NULL, 0, 1, 'certain', 'reform', 'moderate', 'The Scottish Parliament meeting at Edinburgh in August 1560 abolishes papal authority and the Mass and adopts the Scots Confession, drafted by John Knox and five others. The Church of Scotland takes a Reformed, Presbyterian course.', 'Reformation Parliament, 1-27 August 1560.', 3220),
(532, 'William Tyndale Executed', 1536, NULL, 0, 1, 'certain', 'persecution', 'minor', 'Tyndale is strangled and burned at Vilvoorde near Brussels in October 1536 for translating the Bible into English. His wording largely shaped the King James Version.', 'Early October 1536; the exact day is unknown.', 3160);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(125, 'Peace of Westphalia', 1648, NULL, 0, 0, 'certain', 'kingdom', 'moderate', 'The treaties ending the Thirty Years'' War confirm the settlement of the Peace of Augsburg (1555) and extend its toleration to the Reformed church, ending a long period of European religious wars. The principle of cuius regio, eius religio dates from Augsburg, not 1648.', 'Treaties signed October 24, 1648.', 3250),
(126, 'John Wesley''s Aldersgate Experience', 1738, NULL, 0, 0, 'certain', 'reform', 'moderate', 'Wesley feels his heart "strangely warmed" at a Moravian society meeting on Aldersgate Street, an experience he treated as a turning point in his own assurance of faith and that is often seen as the spiritual birth of the Methodist revival.', 'May 24, 1738.', 3300),
(127, 'Jonathan Edwards and the First Great Awakening', 1734, 1743, 1, 1, 'probable', 'reform', 'major', 'Revival in Jonathan Edwards'' Northampton church (1734-35) and George Whitefield''s preaching tours from 1739 spread the First Great Awakening through the American colonies, alongside the Evangelical Revival in Britain. Edwards'' sermon "Sinners in the Hands of an Angry God" (1741) became its best-known sermon.', 'First Great Awakening, c. 1734–1743.', 3290),
(128, 'William Carey Sails for India', 1793, NULL, 0, 0, 'certain', 'mission', 'moderate', 'The Baptist missionary William Carey sails from England on 13 June 1793 and reaches Calcutta in November, beginning a lifelong work of Bible translation, education and social reform; he is often called the "father of modern missions".', 'Carey departed June 13, 1793; established Serampore Mission.', 3310),
(129, 'British and Foreign Bible Society Founded', 1804, NULL, 0, 0, 'certain', 'scripture', 'moderate', 'The British and Foreign Bible Society is founded in London to make the Scriptures available in every language, becoming the model for Bible societies around the world.', 'Founded March 7, 1804.', 3320),
(130, 'American Bible Society Founded', 1816, NULL, 0, 0, 'certain', 'scripture', 'minor', 'Founded to distribute Bibles across the expanding American frontier.', 'Founded May 11, 1816 in New York.', 3340),
(131, 'Charles Spurgeon Begins Preaching in London', 1854, NULL, 0, 0, 'certain', 'teaching', 'minor', 'Spurgeon, the "Prince of Preachers," begins pastoring at New Park Street Chapel at age 19; his later Metropolitan Tabernacle seats about 5,000.', 'Spurgeon preached to millions over 38 years (1854–1892).', 3350),
(132, 'D.L. Moody''s Revival Campaigns', 1873, 1899, 0, 0, 'certain', 'reform', 'minor', 'Dwight L. Moody''s transatlantic revival campaigns in Britain and America bring millions to evangelistic meetings. He founds Moody Bible Institute (1886).', 'Major campaigns: Britain (1873–75), America (1875–99).', 3380),
(522, 'Rescue from the Epworth Rectory Fire', 1709, NULL, 0, 0, 'certain', 'other', 'minor', 'On 9 February 1709 the rectory at Epworth burns down, and five-year-old John Wesley is pulled from an upstairs window. Susanna Wesley, who taught her children at home, saw it as Gods special care for him, and Wesley later called himself a brand plucked from the burning.', '9 February 1709.', 3270),
(523, 'The Holy Club at Oxford', 1729, 1735, 0, 1, 'certain', 'reform', 'moderate', 'Charles Wesley and friends meet at Oxford for study, prayer, Communion and visiting prisoners. John Wesley soon leads the group, and its disciplined method earns the nickname Methodists. George Whitefield joins a few years later.', 'Begun 1729; John Wesley took the lead later that year; members dispersed after 1735.', 3280),
(524, 'Pilgrims Progress Published', 1678, NULL, 0, 0, 'certain', 'scripture', 'moderate', 'John Bunyan publishes the first part of The Pilgrims Progress, an allegory of the Christian life. It is written in plain English from the Bible and has been translated into over two hundred languages.', 'Part 1 published 1678; Part 2 in 1684. Composition during imprisonment at Bedford is likely but debated.', 3260),
(525, 'Slave Trade Abolished in the British Empire', 1807, NULL, 0, 0, 'certain', 'reform', 'moderate', 'Parliament passes the Slave Trade Act on 25 March 1807 after twenty years of campaigning led by William Wilberforce and many others, especially evangelical Christians and Quakers. Slavery itself was abolished across the empire in 1833, days before Wilberforce died.', 'Royal Assent 25 March 1807; Slavery Abolition Act 1833.', 3330),
(526, 'Samuel Ajayi Crowther Consecrated Bishop', 1864, NULL, 0, 0, 'certain', 'mission', 'moderate', 'Crowther, born in Yorubaland, enslaved as a boy, rescued by the Royal Navy and educated in Sierra Leone, is consecrated at Canterbury Cathedral on 29 June 1864. He is the first African Anglican bishop and oversees the Niger mission. He also translated the Bible into Yoruba.', '29 June 1864.', 3360),
(527, 'Hudson Taylor Founds the China Inland Mission', 1865, NULL, 0, 0, 'certain', 'mission', 'moderate', 'Hudson Taylor founds the China Inland Mission in 1865 to carry the gospel to Chinas inland provinces. It is non-denominational and depends on prayer rather than appeals for funds, and by 1900 it is the largest mission in China.', 'Founded in June 1865.', 3370);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(133, 'Azusa Street Revival', 1906, 1909, 0, 0, 'certain', 'reform', 'moderate', 'William Seymour leads a multiracial revival on Azusa Street in Los Angeles, a major catalyst of the global Pentecostal movement, which with the charismatic movements now numbers hundreds of millions.', 'Azusa Street Revival, 312 Azusa Street, April 1906 – c. 1909.', 3390),
(134, 'Edinburgh Missionary Conference', 1910, NULL, 0, 0, 'certain', 'mission', 'moderate', 'The World Missionary Conference in Edinburgh brings together about 1,200 delegates, mostly from Protestant and Anglican societies, and is widely seen as a starting point of the modern ecumenical movement.', 'June 14–23, 1910.', 3400),
(135, 'Barmen Declaration', 1934, NULL, 0, 0, 'certain', 'council', 'minor', 'Meeting at Barmen, the Confessing Church in Germany adopts a declaration, drafted chiefly by Karl Barth with the Lutheran Hans Asmussen and Thomas Breit, rejecting Nazi ideology''s claims over the church. Bonhoeffer and Martin Niemoller supported the Confessing movement but were not its authors.', 'Barmen Declaration, May 31, 1934.', 3410),
(136, 'Discovery of the Dead Sea Scrolls', 1947, NULL, 0, 0, 'certain', 'scripture', 'major', 'A Bedouin shepherd''s find in a cave near Qumran in 1946-47 opened one of the greatest manuscript finds of modern times: some 900 scrolls from eleven caves, usually linked to a Jewish community at Qumran, often identified as Essene. Every Hebrew Bible book except Esther is represented, and the Great Isaiah Scroll predates the earlier known Hebrew manuscripts by about a thousand years.', 'First scrolls found in 1946-47; excavations continued through 1956.', 3440),
(137, 'State of Israel Established', 1948, NULL, 0, 0, 'certain', 'kingdom', 'moderate', 'As the British Mandate ended, David Ben-Gurion proclaimed the State of Israel, the first sovereign Jewish state in the land since antiquity. The ingathering of Jewish exiles and the revival of Hebrew as a living national language gave the ancient biblical homeland renewed centrality in Jewish life and Christian reflection.', 'May 14, 1948.', 3450),
(138, 'Second Vatican Council', 1962, 1965, 0, 0, 'certain', 'council', 'major', 'Pope John XXIII convenes Vatican II, transforming Catholic worship (Mass in the vernacular), affirming religious liberty, and opening dialogue with Protestants and other faiths.', 'Vatican II, October 11, 1962 – December 8, 1965.', 3480),
(139, 'Billy Graham''s Global Crusades', 1949, 2005, 0, 1, 'certain', 'mission', 'moderate', 'Graham preached the gospel in person to an estimated 215 million people in more than 185 countries over a career of some five decades, according to the Billy Graham Evangelistic Association.', 'Los Angeles Crusade (1949) launched Graham''s global ministry.', 3460),
(140, 'Lausanne Congress on World Evangelization', 1974, NULL, 0, 0, 'certain', 'mission', 'minor', 'Billy Graham convenes about 2,700 evangelical leaders and guests from some 150 nations; the resulting Lausanne Covenant, drafted under John Stott, shapes evangelical mission for a generation.', 'July 16–25, 1974, Lausanne, Switzerland.', 3500),
(141, 'Fall of the Soviet Union', 1991, NULL, 0, 0, 'certain', 'other', 'minor', 'The dissolution of the USSR on 26 December 1991 ends some seven decades of official state atheism and opens the former Soviet republics to far greater religious freedom, with a revival of Orthodox and other churches.', 'December 26, 1991.', 3520),
(142, 'Christianity Shifts to the Global South', 1980, 2000, 1, 1, 'possible', 'mission', 'moderate', 'Between about 1980 and 2000 the center of gravity of world Christianity moved: the majority of Christians came to live in Africa, Asia and Latin America rather than in Europe and North America.', 'Estimates of when the crossover occurred vary with the counting method; see Philip Jenkins, The Next Christendom (2002), and Pew Research Center data.', 3510),
(528, 'C. S. Lewis Broadcasts on the BBC', 1941, 1944, 0, 0, 'certain', 'teaching', 'moderate', 'During the Second World War Lewis gives radio talks on Christian belief on the BBC. They are published as separate books and in 1952 as Mere Christianity, a widely read defence of Christianity across denominations.', 'Talks 1941-1944; collected as Mere Christianity in 1952.', 3420),
(529, 'Bonhoeffer Executed at Flossenburg', 1945, NULL, 0, 0, 'certain', 'death', 'moderate', 'Dietrich Bonhoeffer, a pastor in the Confessing Church who joined the plot against Hitler, is hanged on 9 April 1945, a month before the war ended. His Cost of Discipleship and Letters and Papers from Prison remain widely read.', '9 April 1945.', 3430),
(530, 'Letter from Birmingham Jail', 1963, NULL, 0, 0, 'certain', 'teaching', 'moderate', 'Imprisoned for protesting segregation, Martin Luther King Jr. writes an open letter on 16 April 1963 to white clergy who had urged him to wait. He appeals to Scripture, Augustine and Aquinas to explain why unjust laws must be resisted nonviolently.', 'Written 16 April 1963.', 3490),
(531, 'Mother Teresa Founds the Missionaries of Charity', 1950, NULL, 0, 0, 'certain', 'mission', 'moderate', 'On 7 October 1950 the diocese of Calcutta approves Mother Teresas new order, which serves the dying and destitute. It grows into thousands of sisters in over a hundred countries.', 'Approved 7 October 1950.', 3470);
INSERT INTO events (id, name, start_year, end_year, start_approx, end_approx, date_confidence, category, significance, description, date_notes, sort_order) VALUES
(341, 'Alexander Conquers the Persian Empire', -334, -323, 0, 0, 'certain', 'conquest', 'moderate', 'Alexander of Macedon defeats Persia at the Granicus, Issus and Gaugamela and rules an empire from Greece to India. Judea passes from Persian to Greek rule and, after his death in 323 BC, to the rival Ptolemies and Seleucids (1 Macc 1:1-9). Daniel''s vision of the he-goat is traditionally read of these events (Dan 8:5-8, 21-22; 11:3-4).', 'Campaign 334-323 BC; Alexander died at Babylon in June 323 BC. Reading the Daniel passages as Alexander is traditional.', 1420),
(342, 'Maccabean Revolt', -167, -161, 0, 0, 'certain', 'war', 'major', 'After Antiochus IV desecrates the temple and bans the Law, the priest Mattathias refuses to sacrifice at Modein and raises a revolt (1 Macc 2). His son Judas wins a string of victories, retakes Jerusalem and rededicates the temple in December 165 BC on Ussher''s dating (1 Macc 4:36-59). Judas falls at Elasa in 161 BC (Ussher).', 'The temple was desecrated on 15 Kislev 145 of the kingdom of the Greeks (1 Macc 1:54): 167 BC, Ussher, Annals §3347. Judas fell in 152 of that era (1 Macc 9:3): 161 BC on Ussher (§3528-3532). Standard dating counts the era a year later: rededication 164 BC and Judas''s death 160 BC. 1-2 Maccabees are canonical for Catholics and Orthodox and among the Apocrypha for Protestants.', 1440),
(343, 'Rededication of the Temple', -165, NULL, 0, 1, 'certain', 'worship', 'moderate', 'On 25 Kislev, three years after its desecration, Judas Maccabeus cleanses the temple, builds a new altar and restores the daily offerings with eight days of celebration (1 Macc 4:36-59; 2 Macc 10:1-8). The feast of Dedication (Hanukkah) that remembers it is named in John 10:22.', '25 Kislev 148 of the kingdom of the Greeks (1 Macc 4:52). Ussher, Annals §3417-3421, places it in 165 BC; this dataset follows Ussher. Standard dating: December 164 BC.', 1460),
(487, 'Septuagint Translation Begun in Alexandria', -277, NULL, 1, 1, 'traditional', 'scripture', 'moderate', 'Tradition holds that at the request of Ptolemy II Philadelphus, seventy-two Jewish scholars from Jerusalem translated the Law into Greek at Alexandria. The Greek Old Testament that grew from this work, the Septuagint, became the Bible of Greek-speaking Jews and of most New Testament writers who quote Scripture.', 'Tradition, from the Letter of Aristeas (a legendary account, probably written in the second century BC). Ussher, Annals §2774 (after Epiphanius), dates the translation by 72 translators to the seventh year of Ptolemy Philadelphus, 277 BC. Historians accept that the Pentateuch was translated in Alexandria in the third century BC, c. 280-250 BC; the other books followed over the next two centuries.', 1430),
(488, 'Antiochus IV Desecrates the Temple', -167, NULL, 0, 1, 'certain', 'persecution', 'moderate', 'Antiochus IV Epiphanes forbids circumcision, the Sabbath and the Law, and in December 167 BC an altar to Zeus is set up on the altar of burnt offering in the Jerusalem temple. Daniel 11:31 is often read as pointing to these acts. The outrage leads directly to the Maccabean Revolt.', 'Standard historical dating from 1 and 2 Maccabees (1 Macc 1:54, 15 Kislev, 145 of the Seleucid era = December 167 BC). Maccabees is not in the KJV text used here; the Daniel link is a traditional reading, not a certainty.', 1450),
(489, 'Pompey Takes Jerusalem', -63, NULL, 0, 1, 'certain', 'conquest', 'moderate', 'The Roman general Pompey, called in to settle a quarrel between the Hasmonean brothers Hyrcanus II and Aristobulus II, besieges the temple mount for three months and storms it. He enters the Holy of Holies but leaves the treasury untouched. Judea becomes a Roman tributary, the political setting of the Gospels.', 'Standard historical dating from Josephus (Antiquities 14.57-71; War 1.141-154): 63 BC.', 1470),
(490, 'Herod Made King of Judea by Rome', -40, -37, 0, 0, 'certain', 'kingdom', 'moderate', 'Driven from Judea by the Parthians, Herod goes to Rome, where the Senate, with the support of Mark Antony and Octavian, names him king of the Jews. He takes Jerusalem with Roman help in 37 BC and rules until his death c. 4 BC. This is the "Herod the king" of the birth narratives.', 'Standard historical dating from Josephus (Antiquities 14.381-389; 14.468-491): appointed 40 BC, took Jerusalem 37 BC.', 1480),
(491, 'Herod Begins Rebuilding the Temple', -19, NULL, 1, 1, 'probable', 'worship', 'moderate', 'Herod the Great begins to rebuild and enlarge the Jerusalem temple in the eighteenth year of his reign, with the sanctuary itself finished in about eighteen months and the surrounding courts and porches continuing for decades. The Jews tell Jesus the work has been going on forty-six years.', 'Ussher, Annals §5938: in the eighteenth year of Herod, counted from the death of Antigonus in 37 BC, he announced the rebuilding: 19 BC (Josephus, Antiquities 15.380; some date it 20/19 BC). John 2:20 (46 years) would then fall in AD 27/28; the figure counts building in progress and is not a precise anchor.', 1490);
