(4, 1, 11, 1, 11, 9, 'Genesis 11:1-9'),
(5, 1, 12, 1, 12, 9, 'Genesis 12:1-9'),
(6, 1, 15, 1, 15, 21, 'Genesis 15:1-21'),
(7, 1, 22, 1, 22, 19, 'Genesis 22:1-19'),
