INSERT INTO locations (id, name, modern_name, latitude, longitude, region, description) VALUES
(1, 'Eden', NULL, NULL, NULL, 'Unidentified', 'Garden where God placed Adam and Eve (Gen 2:8-14). Its location is unknown: Genesis names four rivers, including the Tigris and Euphrates, and proposals range from southern Mesopotamia to Armenia; the world before the Flood may no longer exist. No coordinates are given.'),
(2, 'Ur', 'Tell el-Muqayyar', 30.96, 46.1, 'Mesopotamia', 'Home city of Abraham''s family, "Ur of the Chaldees" (Gen 11:28, 31; Acts 7:2-4), traditionally Tell el-Muqayyar in southern Iraq. Some scholars propose a northern Ur near Haran; the southern site is the majority identification.'),
(3, 'Haran', 'Harran', 36.86, 39.03, 'Mesopotamia', 'Where Abraham''s family settled before Canaan.'),
(4, 'Canaan', 'Israel/Palestine', 32.0, 35.2, 'Levant', 'The land west of the Jordan promised to Abraham (Gen 12:7; 17:8). The map pin marks the middle of the region, not a city.'),
(5, 'Egypt', 'Egypt', 29.85, 31.25, 'North Africa', 'Where Israel settled under Joseph and was later enslaved. Scripture gives 430 years for the sojourn of Israel (Exod 12:40-41) and 400 years of affliction (Gen 15:13; Acts 7:6). On Ussher''s chronology the 430 years run from Abraham''s call in 1921 BC to the Exodus in 1491 BC, with about 215 years spent in Egypt (from 1706 BC). The pin is a centre-of-country marker.'),
(6, 'Mount Sinai', 'Jebel Musa (traditional)', 28.54, 33.97, 'Sinai Peninsula', 'Where God gave Moses the Law (Exod 19-20). Jebel Musa in the southern Sinai is the traditional identification (from about the 4th century AD); other proposals include Jebel Sin Bisher, Har Karkom and Jebel al-Lawz in Arabia (Midian). The site is not certain.'),
(7, 'Jerusalem', 'Jerusalem', 31.77, 35.23, 'Judah', 'City of David; location of the Temple.'),
(8, 'Bethlehem', 'Bethlehem', 31.7, 35.21, 'Judah', 'Birthplace of David and Jesus.'),
(9, 'Babylon', 'Hillah, Iraq', 32.54, 44.42, 'Mesopotamia', 'Capital of Babylonian Empire; place of exile.'),
(10, 'Nazareth', 'Nazareth', 32.7, 35.3, 'Galilee', 'Hometown of Jesus.'),
(11, 'Capernaum', 'Kfar Nahum', 32.8831, 35.5747, 'Galilee', 'Base of Jesus'' Galilean ministry.'),
(12, 'Damascus', 'Damascus', 33.51, 36.29, 'Syria', 'Where Paul was converted.'),
(13, 'Antioch', 'Antakya', 36.2, 36.16, 'Syria', 'Center of early Gentile Christianity.'),
(14, 'Rome', 'Rome', 41.9, 12.5, 'Italy', 'Capital of the Roman Empire; center of early church.'),
(15, 'Patmos', 'Patmos', 37.32, 26.55, 'Aegean Sea', 'Island where John wrote Revelation.'),
(16, 'Cana', 'Kafr Kanna (traditional)', 32.75, 35.34, 'Galilee', 'Galilean village where Jesus turned water into wine (John 2:1-11). Kafr Kanna is the traditional site; Khirbet Qana, about 13 km north of Nazareth, is a leading alternative.'),
(17, 'Sea of Galilee', 'Lake Tiberias', 32.83, 35.58, 'Galilee', 'Lake where Jesus calmed the storm and walked on water.'),
(18, 'Bethsaida', 'Et-Tell', 32.91, 35.63, 'Galilee', 'Fishing village on the north shore of the Sea of Galilee; home of Peter, Andrew and Philip (John 1:44). Et-Tell is the usual identification; el-Araj is a proposed alternative.'),
(19, 'Nain', 'Nein', 32.63, 35.35, 'Galilee', 'Village where Jesus raised the widow''s son.'),
(20, 'Bethany', 'Al-Eizariya', 31.77, 35.26, 'Judea', 'Village near Jerusalem; home of Mary, Martha, and Lazarus.'),
(21, 'Gadara', 'Umm Qais', 32.66, 35.68, 'Decapolis', 'Decapolis city whose territory Matthew places the healing of the demon-possessed man in (Matt 8:28). Mark 5:1 and Luke 8:26 read "Gerasenes" (Gerasa or Kursi) in many manuscripts, and some read "Gergesenes"; the exact site is uncertain.'),
(22, 'Jericho', 'Jericho', 31.87, 35.44, 'Judea', 'Ancient city near the Jordan; site of Bartimaeus'' healing.'),
(23, 'Tyre & Sidon', 'Tyre/Saida', 33.27, 35.2, 'Phoenicia', 'Coastal cities of Phoenicia where Jesus healed the Syrophoenician woman''s daughter (Matt 15:21-28). The map pin marks Tyre; Sidon lies about 35 km to the north.'),
(24, 'Decapolis', NULL, 32.6, 35.8, 'Transjordan', 'League of ten Greco-Roman cities east of the Jordan.'),
(25, 'Jordan River', NULL, 31.84, 35.55, 'Judea', 'River where Naaman was healed and Jesus was baptized.'),
(26, 'Samaria', 'Sebastia', 32.28, 35.19, 'Samaria', 'Philip preached and performed miracles here (Acts 8).'),
(27, 'Gaza Road', NULL, 31.5, 34.47, 'Judea', 'Desert road from Jerusalem to Gaza where Philip baptized the Ethiopian official (Acts 8:26). The map pin marks Gaza at the end of the road.'),
(28, 'Joppa', 'Jaffa (Tel Aviv-Yafo)', 32.05, 34.75, 'Judea', 'Where Peter raised Tabitha and had the vision of the sheet (Acts 9-10).'),
(29, 'Caesarea', 'Caesarea', 32.5, 34.89, 'Judea', 'Roman capital of Judea; house of Cornelius; Paul''s imprisonment (Acts 10, 23-26).'),
(30, 'Cyprus', 'Cyprus', 34.92, 33.63, 'Mediterranean', 'Home of Barnabas; first stop on Paul''s first journey (Acts 13:4-12).'),
(31, 'Pisidian Antioch', 'Yalvaç', 38.3, 31.18, 'Asia Minor', 'Paul preached in the synagogue; many believed (Acts 13:14-52).'),
(32, 'Iconium', 'Konya', 37.87, 32.49, 'Asia Minor', 'Paul and Barnabas preached but were driven out (Acts 14:1-7).'),
(33, 'Lystra', 'Hatunsaray', 37.57, 32.36, 'Asia Minor', 'Paul healed a lame man; later stoned (Acts 14:8-20).'),
(34, 'Derbe', 'Kerti Höyük', 37.36, 33.35, 'Asia Minor', 'Lycaonian city where Paul and Barnabas made many disciples (Acts 14:20-21). Kerti Hoyuk is the usual identification; Devri Sehri is another proposal.'),
(35, 'Troas', 'Dalyan', 39.76, 26.18, 'Asia Minor', 'Paul received the Macedonian vision (Acts 16:8-10).'),
(36, 'Philippi', 'Kavala region', 41.01, 24.29, 'Macedonia', 'First European church; Lydia converted; Paul imprisoned (Acts 16:11-40).'),
(37, 'Thessalonica', 'Thessaloniki', 40.63, 22.95, 'Macedonia', 'Paul preached in synagogue; accused of sedition (Acts 17:1-9).'),
(38, 'Berea', 'Veria', 40.52, 22.2, 'Macedonia', 'Bereans examined Scriptures daily to verify Paul''s teaching (Acts 17:10-15).'),
(39, 'Athens', 'Athens', 37.97, 23.73, 'Greece', 'Paul preached on the Areopagus about the Unknown God (Acts 17:16-34).'),
(40, 'Corinth', 'Ancient Corinth', 37.91, 22.88, 'Greece', 'Paul stayed 18 months; Gallio tribunal (Acts 18:1-17).'),
(41, 'Ephesus', 'Selçuk', 37.94, 27.34, 'Asia Minor', 'Paul taught 2 years; riot of Demetrius the silversmith (Acts 19).'),
(42, 'Miletus', 'Balat', 37.53, 27.28, 'Asia Minor', 'Paul''s farewell to Ephesian elders (Acts 20:17-38).'),
(43, 'Crete', 'Crete', 35.24, 24.9, 'Mediterranean', 'Mediterranean island where Paul''s ship put in at Fair Havens (Acts 27:7-12). The map pin marks the middle of the island.'),
(44, 'Malta', 'Malta', 35.94, 14.38, 'Mediterranean', 'Paul shipwrecked; healed the sick (Acts 27:39–28:10).'),
(45, 'Puteoli', 'Pozzuoli', 40.82, 14.12, 'Italy', 'Port where Paul landed in Italy (Acts 28:13).'),
(46, 'Shechem', 'Nablus', 32.21, 35.28, 'Samaria', 'Abraham built an altar here; Jacob bought land. First stop in Canaan.'),
(47, 'Hebron', 'Al-Khalil', 31.53, 35.1, 'Judah', 'Abraham settled at the oaks of Mamre; burial site of the patriarchs.'),
(48, 'Beersheba', 'Be''er Sheva', 31.25, 34.79, 'Negev', 'Well of the oath between Abraham and Abimelech; Isaac and Jacob lived here.'),
(49, 'Goshen', 'Wadi Tumilat', 30.55, 31.8, 'Egypt', 'Region in eastern Egypt where Israel settled (Gen 45-47).'),
(50, 'Peniel', 'Tulul ed-Dhahab', 32.19, 35.66, 'Transjordan', 'Where Jacob wrestled with God and was renamed Israel (Gen 32:22-32).'),
(51, 'Red Sea Crossing', 'Head of the Gulf of Suez (traditional area; site unknown)', 29.95, 32.56, 'Sinai', 'Where Israel crossed the "sea" (Hebrew yam suph, "sea of reeds"; Exod 14). The exact place is unknown. Proposals include the head of the Gulf of Suez (the traditional area, shown here), the Bitter Lakes and Lake Timsah, Lake Sirbonis on the Mediterranean coast, and the Gulf of Aqaba.'),
(52, 'Marah', 'Ain Hawarah', 29.18, 33.11, 'Sinai', 'Bitter waters made sweet by Moses (Exod 15:23-25). Ain Hawarah is the traditional identification and is uncertain.'),
(53, 'Elim', 'Wadi Gharandel', 28.98, 33.1, 'Sinai', 'Oasis with twelve springs and seventy palm trees (Exod 15:27). Wadi Gharandel is the traditional identification and is uncertain.'),
(54, 'Rephidim', 'Wadi Feiran', 28.7, 33.63, 'Sinai', 'Where God gave water from the rock and Israel fought Amalek (Exod 17). Wadi Feiran is the traditional identification; other sites are proposed.'),
(55, 'Kadesh Barnea', 'Ein el-Qudeirat', 30.6, 34.4, 'Negev', 'Israel camped before entering Canaan; spies sent out (Num 13-14).'),
(56, 'Nineveh', 'Mosul, Iraq', 36.36, 43.15, 'Mesopotamia', 'Capital of Assyria where Jonah preached repentance.'),
(57, 'Emmaus', 'Emmaus Nicopolis', 31.84, 34.99, 'Judea', 'Village about 60 stadia (c. 11 km) from Jerusalem where the risen Jesus appeared to two disciples (Luke 24:13-35). Its site is disputed: Emmaus-Nicopolis (Latrun, shown here) fits the reading of 160 stadia found in some manuscripts; Qubeibeh, Abu Ghosh and Motza better fit the 60 stadia of most manuscripts.'),
(58, 'Constantinople', 'Istanbul, Turkey', 41.01, 28.98, 'Asia Minor', 'Capital of the Eastern Roman Empire; seat of ecumenical patriarchate.'),
(59, 'Carthage', 'Tunis, Tunisia', 36.86, 10.32, 'North Africa', 'Important early church centre; home of Tertullian and Cyprian, and where Augustine studied and taught before his conversion.'),
(60, 'Hippo Regius', 'Annaba, Algeria', 36.9, 7.77, 'North Africa', 'Bishopric of Augustine of Hippo.'),
(61, 'Nicaea', 'İznik, Turkey', 40.43, 29.72, 'Asia Minor', 'Site of the First Ecumenical Council (325 AD).'),
(62, 'Chalcedon', 'Kadıköy, Istanbul', 40.98, 29.03, 'Asia Minor', 'Site of the Council of Chalcedon (451 AD).'),
(63, 'Wittenberg', 'Wittenberg, Germany', 51.87, 12.65, 'Europe', 'Where Martin Luther posted the 95 Theses (1517).'),
(64, 'Geneva', 'Geneva, Switzerland', 46.2, 6.15, 'Europe', 'Center of John Calvin''s Reformed tradition.'),
(65, 'Mainz', 'Mainz, Germany', 50.0, 8.27, 'Europe', 'Gutenberg''s city; birthplace of the printing press.'),
(66, 'Canterbury', 'Canterbury, England', 51.28, 1.08, 'Europe', 'Seat of the Archbishop of Canterbury; English Christianity.'),
(67, 'Worms', 'Worms, Germany', 49.63, 8.37, 'Europe', 'Diet of Worms (1521); Luther''s "Here I stand."'),
(68, 'Trent', 'Trento, Italy', 46.07, 11.12, 'Europe', 'Council of Trent (1545–1563); Catholic Counter-Reformation.'),
(69, 'Aldersgate', 'London, England', 51.52, -0.1, 'Europe', 'Site of John Wesley''s evangelical conversion (1738).'),
(70, 'Edinburgh', 'Edinburgh, Scotland', 55.95, -3.19, 'Europe', 'Edinburgh Missionary Conference (1910).'),
(71, 'Azusa Street', 'Los Angeles, USA', 34.05, -118.25, 'Americas', 'Azusa Street Revival (1906); birth of Pentecostalism.'),
(72, 'Serampore', 'Serampore, India', 22.75, 88.34, 'Asia', 'William Carey''s mission base; Bible translation center.'),
(73, 'Qumran', 'Qumran, Israel', 31.74, 35.46, 'Judea', 'Site where the Dead Sea Scrolls were discovered (1947).'),
(74, 'Northampton', 'Northampton, MA, USA', 42.33, -72.63, 'Americas', 'Jonathan Edwards and the First Great Awakening.'),
(75, 'Assisi', 'Assisi, Italy', 43.07, 12.62, 'Europe', 'Home of Francis of Assisi.'),
(76, 'Nuremberg', 'Nuremberg, Germany', 49.45, 11.08, 'Europe', 'Center of Reformation-era publishing and reform.'),
(77, 'Whitby', 'Whitby, England', 54.49, -0.62, 'Europe', 'Synod of Whitby (664); Celtic vs. Roman church.'),
(78, 'Clermont', 'Clermont-Ferrand, France', 45.78, 3.08, 'Europe', 'Council of Clermont (1095); Pope Urban II calls the First Crusade.'),
(79, 'Wycliffe Country', 'Lutterworth, England', 52.46, -1.2, 'Europe', 'Home of John Wycliffe; Morning Star of the Reformation.'),
(100, 'Bethel', 'Beitin', 31.94, 35.24, 'Ephraim/Benjamin', 'Where Abraham built an altar and where Jacob dreamed of a ladder to heaven (Gen 12:8; 28:10-22). The identification with Beitin is widely accepted.'),
(101, 'Dothan', 'Tel Dothan', 32.42, 35.28, 'Samaria', 'Where Joseph found his brothers and was sold to the Ishmaelite traders (Gen 37:17-28); Elisha was later here (2 Kgs 6:13).'),
(102, 'Mount Ararat', 'Agri Dagi, Turkey', 39.7, 44.3, 'Armenia', '"The mountains of Ararat" (Gen 8:4) where the ark came to rest; the region is Urartu. Scripture names no single peak. Agri Dagi is the traditional modern identification; others propose Cudi Dagi.'),
(103, 'Mediterranean Sea', 'Mediterranean Sea', 33.0, 34.0, 'Mediterranean', 'The "great sea" west of Israel (Num 34:6); Jonah''s ship sailed from Joppa toward Tarshish on it (Jonah 1:3-4). The pin is a point at sea off the coast.'),
(104, 'Gath-hepher', 'Khirbet ez-Zurra / Mashhad', 32.72, 35.33, 'Galilee', 'Hometown of the prophet Jonah in Zebulun (2 Kgs 14:25; Josh 19:13). Identification with Khirbet ez-Zurra or Mashhad is probable.'),
(105, 'Mount of Olives', 'Jebel et-Tur', 31.78, 35.245, 'Judea', 'Ridge east of Jerusalem: site of Jesus'' Olivet discourse and of Gethsemane, and where the disciples returned from after the Ascension (Acts 1:12). Bethany lies on its eastern slope (Luke 24:50).'),
(106, 'Susa', 'Shush, Iran', 32.19, 48.26, 'Persia', 'Winter capital of the Persian kings where Esther, Mordecai and Haman lived (Esth 1:2) and where Nehemiah served (Neh 1:1).'),
(107, 'Caesarea Philippi', 'Banias', 33.25, 35.69, 'Golan / Hermon foothills', 'Where Peter confessed Jesus as the Christ (Matt 16:13-20). The Transfiguration followed about a week later on a "high mountain" that the Gospels do not name.'),
(108, 'Mount Carmel', 'Mount Carmel, Israel', 32.72, 35.05, 'Carmel ridge', 'Where Elijah confronted the prophets of Baal (1 Kgs 18:19-40). Muhraka, at the south-east end of the ridge, is the traditional site.'),
(109, 'Smyrna', 'Izmir, Turkey', 38.42, 27.14, 'Asia Minor', 'City of the church addressed in Rev 2:8-11 and the see of Polycarp.'),
(110, 'Tel Aviv', 'Tel Aviv, Israel', 32.08, 34.78, 'Coastal plain', 'Where the State of Israel was proclaimed on 14 May 1948.'),
(111, 'Sodom', 'Bab edh-Dhra / Tall el-Hammam (proposed)', 31.25, 35.53, 'Dead Sea region', 'One of the cities of the plain destroyed by God (Gen 18-19). Its site is disputed: Bab edh-Dhra at the south-east of the Dead Sea (pinned here) and Tall el-Hammam in the northern Jordan plain are the leading proposals.'),
(112, 'Alexandria', 'Alexandria, Egypt', 31.2, 29.92, 'North Africa', 'Great Hellenistic city and early Christian centre: home of Apollos (Acts 18:24), Origen and Athanasius.'),
(113, 'Milan', 'Milan, Italy', 45.46, 9.19, 'Europe', 'Imperial city where the Edict of Milan was issued (AD 313) and where Ambrose was bishop.'),
(114, 'Constance', 'Konstanz, Germany', 47.66, 9.17, 'Europe', 'Site of the Council of Constance (1414-1418), where Jan Hus was condemned and burned (1415).'),
(115, 'Fair Havens', 'Kaloi Limenes, Crete', 34.93, 24.08, 'Mediterranean', 'Harbour on the south coast of Crete where Paul''s ship put in and Paul advised against sailing on (Acts 27:8-12).'),
(116, 'Basel', 'Basel, Switzerland', 47.56, 7.59, 'Europe', 'Rhine city and printing centre where the first edition of Calvin''s Institutes was published in 1536.'),
(117, 'Mount Tabor', 'Har Tavor, Israel', 32.687, 35.39, 'Galilee', 'Isolated mountain in lower Galilee, scene of Barak''s muster (Judg 4:6). Since at least the fourth century it has been the traditional site of the Transfiguration; the Gospels name only "a high mountain" (Matt 17:1), and Mount Hermon is the main alternative.'),
(120, 'Mount Nebo', 'Jebel Nebo (Siyagha), Jordan', 31.7679, 35.7253, 'Transjordan', 'Mountain east of the Jordan from which Moses viewed the promised land and where he died (Deut 34:1-5).'),
(121, 'Mount Gilboa', 'Gilboa ridge, West Bank / Israel', 32.55, 35.38, 'Samaria', 'Ridge on the south-east edge of the Jezreel valley where Saul and Jonathan died fighting the Philistines (1 Sam 31:1-6).'),
(122, 'Valley of Elah', 'Wadi es-Sant, Israel', 31.69, 35.0, 'Judah', 'Valley between Socoh and Azekah in the Judean lowlands where Israel and the Philistines faced each other and David fought Goliath (1 Sam 17:1-3).');
INSERT INTO locations (id, name, modern_name, latitude, longitude, region, description) VALUES
(123, 'Mizpah of Benjamin', 'Tell en-Nasbeh, West Bank', 31.8956, 35.2158, 'Ephraim/Benjamin', 'Town in Benjamin where Samuel gathered Israel to repent and judged them (1 Sam 7:5-6). The identification with Tell en-Nasbeh is widely accepted.'),
(124, 'Shiloh', 'Khirbet Seilun, West Bank', 32.0556, 35.2903, 'Ephraim/Benjamin', 'Site of the tabernacle and the sanctuary of Eli in the time of the judges (1 Sam 1-4).'),
(125, 'Aphek', 'Tel Afek (Aphek-Antipatris), Israel', 32.1, 34.93, 'Coastal plain', 'Philistine staging ground at the head of the Yarkon river, where Israel was defeated and the ark taken (1 Sam 4:1-11).'),
(126, 'Spring of Harod', 'Ein Harod / Ein Jalud, Israel', 32.5497, 35.3578, 'Galilee', 'Spring at the foot of Mount Gilboa where Gideon tested his army before attacking Midian (Judg 7:1-7); the exact spring is a traditional identification.'),
(127, 'Gaza', 'Gaza City', 31.5, 34.4667, 'Coastal plain', 'Philistine coastal city where Samson was imprisoned and died in the temple of Dagon (Judg 16:21-30).'),
(128, 'Mount of Beatitudes', 'Mount of Beatitudes, near Tabgha, Israel', 32.8806, 35.5575, 'Galilee', 'Hillside above the north-west shore of the Sea of Galilee, the traditional site of the Sermon on the Mount; Matthew says only that Jesus went up "into a mountain" (Matt 5:1).'),
(129, 'Ein Karem', 'Ein Karem, Jerusalem', 31.7678, 35.1595, 'Judea', 'Village in the hill country west of Jerusalem, the traditional home of Zechariah and Elizabeth; Luke names only "a city of Juda" (Luke 1:39). Location is by tradition.'),
(130, 'Lyon', 'Lyon, France', 45.764, 4.8357, 'Europe', 'Roman Lugdunum; Irenaeus was bishop of its church in the second century.'),
(131, 'Nicomedia', 'Izmit, Turkey', 40.7667, 29.9167, 'Asia Minor', 'Eastern imperial capital under Diocletian; the first edict against Christians was posted there in February 303 and the church was demolished.'),
(132, 'Ravenna', 'Ravenna, Italy', 44.4184, 12.2035, 'Italy', 'Residence of the last western emperors, where Odoacer deposed Romulus Augustulus in 476.'),
(133, 'Monte Cassino', 'Montecassino, Italy', 41.4901, 13.814, 'Italy', 'Hilltop monastery founded by Benedict of Nursia around 529, where the Rule is traditionally said to have been written.'),
(134, 'Mecca', 'Mecca, Saudi Arabia', 21.4225, 39.8262, 'Arabia', 'Birthplace of Muhammad and the first centre of Islam.'),
(135, 'Medina', 'Medina, Saudi Arabia', 24.4672, 39.6111, 'Arabia', 'City of the Hijra in 622 and the base from which the early Muslim conquests began.'),
(136, 'London', 'London, England', 51.5074, -0.1278, 'Europe', 'Capital of England; place of the Westminster Assembly, the King James Version commission and the founding of the British and Foreign Bible Society.'),
(137, 'Munster', 'Munster, Germany', 51.9607, 7.6261, 'Europe', 'One of the two Westphalian cities where the 1648 peace treaties were negotiated and signed.'),
(138, 'Osnabruck', 'Osnabruck, Germany', 52.2799, 8.0472, 'Europe', 'The other Westphalian city where the 1648 peace treaties were negotiated and signed.'),
(139, 'New York', 'New York City, USA', 40.7128, -74.006, 'Americas', 'Where the American Bible Society was founded in 1816.'),
(140, 'Barmen', 'Wuppertal-Barmen, Germany', 51.27, 7.2, 'Europe', 'District of Wuppertal where the Confessing Church synod met in May 1934 and issued the Barmen Declaration.'),
(141, 'Vatican City', 'Vatican City', 41.9022, 12.4539, 'Italy', 'Seat of the papacy; St Peter''s Basilica hosted the Second Vatican Council.'),
(142, 'Lausanne', 'Lausanne, Switzerland', 46.5197, 6.6323, 'Europe', 'Host city of the 1974 International Congress on World Evangelization.'),
(143, 'Moscow', 'Moscow, Russia', 55.7558, 37.6173, 'Europe', 'Capital of the Soviet Union, where the state was dissolved in December 1991.'),
(144, 'Vagharshapat', 'Vagharshapat (Etchmiadzin), Armenia', 40.1655, 44.2918, 'Armenia', 'Royal city of Armenia and, by tradition, the place where Gregory the Illuminator brought King Tiridates III to faith around 301.'),
(145, 'Axum', 'Axum, Ethiopia', 14.1217, 38.7187, 'Africa', 'Capital of the Aksumite kingdom, whose king Ezana accepted Christianity in the fourth century.'),
(146, 'Chang''an', 'Xi''an, China', 34.2658, 108.9541, 'Asia', 'Tang imperial capital where the Persian monk Alopen was received in 635; the Xi''an stele (781) records the mission.'),
(147, 'Mikulcice', 'Mikulcice, Czech Republic', 48.8097, 17.0561, 'Europe', 'Major stronghold of Great Moravia, the realm to which Cyril and Methodius were sent in 863.'),
(170, 'Ai', 'et-Tell (identification debated)', 31.9167, 35.2667, 'Canaan', 'Canaanite city near Bethel; Israel was defeated there after Achan''s sin and then took it by ambush (Josh 7-8).'),
(171, 'Gibeon', 'el-Jib', 31.8497, 35.1853, 'Canaan', 'Hivite city north-west of Jerusalem; its people made peace with Joshua, and Solomon sacrificed at its high place (Josh 9-10; 1 Kgs 3).'),
(172, 'En-gedi', 'Ein Gedi', 31.4617, 35.3892, 'Judah', 'Oasis with caves on the western shore of the Dead Sea where David hid from Saul (1 Sam 24).'),
(173, 'Gilgal', 'Near Jericho (site uncertain)', 31.8667, 35.45, 'Canaan', 'Israel''s first camp in Canaan and a centre of Samuel''s and Saul''s time; the exact site is debated (Josh 4-5; 1 Sam 15).'),
(174, 'Plains of Moab', 'East of the Jordan opposite Jericho', 31.8, 35.65, 'Moab', 'Israel''s camp east of the Jordan in the last year of Moses, where Balaam was hired to curse them (Num 22).'),
(175, 'Megiddo', 'Tel Megiddo', 32.585, 35.185, 'Jezreel Valley', 'Fortress city guarding the pass from the coast into the Jezreel Valley; King Josiah died here.'),
(176, 'Ramoth-gilead', 'Tell Ramith', 32.57, 36.02, 'Gilead', 'Israelite city east of the Jordan, long contested with Aram.'),
(177, 'Jezreel', 'Tel Jezreel', 32.5575, 35.3294, 'Jezreel Valley', 'Royal city of Ahab and Jezebel in the Jezreel Valley; Naboth''s vineyard lay beside it.'),
(178, 'Zarephath', 'Sarafand', 33.4569, 35.2967, 'Phoenicia', 'Phoenician town near Sidon where Elijah stayed with a widow.'),
(179, 'Dan', 'Tel Dan', 33.2488, 35.6519, 'Northern Israel', 'Northern border city where Jeroboam set up one of his golden calves.'),
(180, 'Chebar Canal', 'Near Nippur', 32.1267, 45.1811, 'Babylonia', 'Canal in Babylonia beside which the Judean exiles lived and Ezekiel saw his vision.'),
(181, 'Kir-hareseth', 'Kerak', 31.18, 35.7, 'Moab', 'Chief fortress of Moab, besieged by Israel and Judah.'),
(185, 'Machaerus', 'Mukawir, Jordan', 31.5693, 35.6117, 'Perea', 'Herodian hilltop fortress east of the Dead Sea. Josephus (Antiquities 18.119) names it as the prison where Herod Antipas held John the Baptist; the Gospels do not name the place.'),
(190, 'York', 'York, England', 53.96, -1.0873, 'Europe', 'Roman fortress city (Eboracum) where Constantine was proclaimed emperor in 306.'),
(191, 'Armagh', 'Armagh, Northern Ireland', 54.3503, -6.6528, 'Europe', 'Ecclesiastical capital of Ireland, traditionally founded by Patrick c. 444.'),
(192, 'Valladolid', 'Valladolid, Spain', 41.6523, -4.7245, 'Europe', 'Castilian city where the debate over the treatment of Native Americans was held, 1550-51.'),
(193, 'Kagoshima', 'Kagoshima, Japan', 31.5966, 130.5571, 'Asia', 'Port in southern Japan where Francis Xavier landed in 1549.'),
(194, 'Epworth', 'Epworth, England', 53.5273, -0.8186, 'Europe', 'Lincolnshire town where Samuel Wesley was rector and John and Charles Wesley were raised.'),
(195, 'Oxford', 'Oxford, England', 51.752, -1.2577, 'Europe', 'University town where the Wesleys formed the Holy Club.'),
(196, 'Kolkata', 'Kolkata (Calcutta), India', 22.5726, 88.3639, 'Asia', 'City where Mother Teresa founded the Missionaries of Charity in 1950.'),
(197, 'Flossenburg', 'Flossenburg, Germany', 49.7366, 12.3544, 'Europe', 'Site of the concentration camp where Dietrich Bonhoeffer was executed in April 1945.'),
(198, 'Birmingham, Alabama', 'Birmingham, Alabama, USA', 33.5186, -86.8104, 'North America', 'Centre of the 1963 civil-rights campaign and site of Martin Luther King Jr.s imprisonment.'),
(199, 'Vilvoorde', 'Vilvoorde, Belgium', 50.9283, 4.4286, 'Europe', 'Town near Brussels where William Tyndale was executed in 1536.'),
(200, 'Mount Hor', 'Jebel Harun (traditional)', 30.3167, 35.4083, 'Edom', 'Mountain on the border of Edom where Aaron died; the traditional site is Jebel Harun near Petra, though the identification is uncertain.'),
(201, 'Way of the Red Sea (Arabah)', 'Wadi Arabah, south of the Dead Sea (uncertain)', 30.0, 35.15, 'Edom / Arabah', 'Route south from Mount Hor toward the Red Sea to go around Edom; the exact camp where the serpents came is not known.'),
(202, 'Mount Ebal', 'Jebel Eybal', 32.24, 35.28, 'Samaria', 'Mountain north of Shechem where Joshua built an altar and read the law; Mount Gerizim faces it to the south.'),
(203, 'Debir', 'Khirbet Rabud (probable)', 31.4333, 35.0333, 'Judah hill country', 'Hill-country city taken by Othniel; Khirbet Rabud is the usual identification, though some propose Tell Beit Mirsim.'),
(204, 'Ophrah of Abiezer', 'Uncertain, possibly near Afula', 32.61, 35.29, 'Manasseh', 'Gideon''s home town in Manasseh; the site is not certainly identified and the coordinates are approximate.'),
(205, 'Mizpah of Gilead', 'Uncertain, possibly Khirbet Jal''ad', 32.2, 35.78, 'Gilead', 'Gilead town where Jephthah was recalled and made his vow; the location is uncertain and the coordinates approximate.'),
(206, 'Zorah', 'Tel Sar''ah', 31.7647, 34.9803, 'Shephelah', 'Town of the tribe of Dan and home of Manoah and Samson.'),
(207, 'Timnah', 'Tel Batash', 31.7794, 34.9086, 'Shephelah', 'Philistine town in the Sorek valley where Samson found his wife.'),
(210, 'Gibeah of Saul', 'Tell el-Ful, north of Jerusalem', 31.8256, 35.2294, 'Benjamin', 'Saul''s hometown and royal seat (1 Sam 10:26; 15:34; 22:6), identified with Tell el-Ful on the ridge north of Jerusalem.'),
(211, 'Nob', 'Uncertain; a ridge near Jerusalem such as Mount Scopus (proposed)', 31.795, 35.245, 'Benjamin', 'Priestly town where the tabernacle stood in Saul''s day and Ahimelech fed David (1 Sam 21-22); the site is uncertain, with proposals on the ridge just north-east of Jerusalem, so these coordinates are approximate.'),
(212, 'Gath', 'Tell es-Safi', 31.7008, 34.8481, 'Philistia', 'Philistine city, home of Goliath and ruled by King Achish (1 Sam 17:4; 21:10; 27:2), identified with Tell es-Safi.'),
(213, 'Adullam', 'Tel Adullam / Khirbet esh-Sheikh Madhkur', 31.6492, 34.9967, 'Judah', 'Town and cave in the Judean lowland where David gathered his band (1 Sam 22:1), identified with Tel Adullam; the exact cave is not known.'),
(214, 'Keilah', 'Khirbet Qila', 31.6108, 35.0092, 'Judah', 'Judean town David delivered from the Philistines (1 Sam 23:1-5), identified with Khirbet Qila in the hills near Hebron.'),
(215, 'Ziklag', 'Uncertain; Khirbet al-Ra''i or Tell es-Sharia (proposed)', 31.39, 34.7, 'Negev', 'Town in the south given to David by Achish of Gath (1 Sam 27:6); its site is disputed between several tells in the western Negev, so these coordinates are approximate.'),
(216, 'Mahanaim', 'Uncertain; Tulul edh-Dhahab or Tell Hajjaj (proposed)', 32.2, 35.68, 'Gilead', 'Town in Gilead east of the Jordan, Ish-bosheth''s capital and David''s refuge from Absalom (2 Sam 2:8; 17:24); the site is uncertain, so these coordinates are approximate.'),
(217, 'Brook Cherith', 'Uncertain; Wadi Qelt (tradition) or Wadi Yabis (proposed)', 31.835, 35.37, 'Jordan Valley', 'Brook "before Jordan" where Elijah hid and the ravens fed him (1 Kgs 17:3-5); the identification is uncertain, and Wadi Qelt near Jericho is the traditional choice, so these coordinates are approximate.'),
(218, 'Abel-meholah', 'Uncertain; Tell Abu Sifri (proposed)', 32.42, 35.54, 'Jordan Valley', 'Hometown of Elisha son of Shaphat (1 Kgs 19:16); a Jordan Valley site south of Beth-shean, with Tell Abu Sifri and other tells proposed, so these coordinates are approximate.'),
(219, 'Shunem', 'Solem', 32.6089, 35.3158, 'Jezreel Valley', 'Town on the south side of the Jezreel Valley where the Shunammite woman hosted Elisha (2 Kgs 4:8), identified with modern Solem.'),
(220, 'Riblah', 'Tell Zerur (Ribleh), Syria', 34.4167, 36.5, 'Syria', 'Nebuchadnezzar''s field headquarters on the Orontes, where Zedekiah was judged and Judah''s leaders were put to death.'),
(221, 'Tahpanhes', 'Tell Defenneh, Egypt', 30.87, 32.17, 'Egypt', 'A fortress town on Egypt''s eastern Delta frontier where the Judean remnant took Jeremiah after the murder of Gedaliah.'),
(222, 'River Ahava', 'uncertain, a canal or stream in Babylonia', 33.64, 42.83, 'Babylonia', 'The stream where Ezra mustered the returning exiles. The exact site is uncertain; Hit on the Euphrates, in the Babylonian homeland, is one proposal.'),
(230, 'Bethabara beyond Jordan', 'Al-Maghtas (Qasr el-Yahud area), proposed', 31.8372, 35.5497, 'Jordan valley', 'Where John was baptizing (John 1:28). The King James text reads Bethabara; most Greek manuscripts read Bethany. The east-bank site of Al-Maghtas is the leading modern proposal; the exact place is uncertain.'),
(231, 'Sychar and Jacobs Well', 'Balata / Bir Yaqub, Nablus', 32.2133, 35.2808, 'Samaria', 'Where Jesus met the Samaritan woman at Jacobs well near the parcel of ground Jacob gave Joseph (John 4:5-6). The well beside Tell Balata is the long-standing identification; Sychar is usually placed at nearby Askar.'),
(232, 'Pool of Bethesda', 'Bethesda pools, St Annes, Jerusalem', 31.78, 35.2358, 'Jerusalem', 'The pool by the sheep market with five porches where Jesus healed a man infirm 38 years (John 5:2-9). The twin pools north of the Temple Mount are the accepted site.'),
(233, 'Pool of Siloam', 'Silwan, Jerusalem', 31.7704, 35.2354, 'Jerusalem', 'Where the man born blind washed and received sight (John 9:7). The pool at the south end of the City of David, fed by Hezekiahs tunnel, is the traditional site; a larger Second Temple pool has been uncovered nearby.'),
(234, 'Ephraim', 'et-Taiyiba', 31.9456, 35.3003, 'Judean hills', 'The city near the wilderness where Jesus stayed with his disciples before the last Passover (John 11:54). Identification with et-Taiyiba, north-east of Jerusalem, is probable but not certain.'),
(235, 'Temple Mount', 'Haram esh-Sharif, Jerusalem', 31.778, 35.2354, 'Jerusalem', 'Site of Herods temple with its courts and Solomons porch on the east side (John 10:23; Acts 3:11) and the Beautiful gate (Acts 3:2).'),
(236, 'Gethsemane', 'Garden of Gethsemane, Mount of Olives', 31.7794, 35.2397, 'Judea', 'The garden across the brook Cedron where Jesus went with his disciples and was arrested (John 18:1-12; Matt 26:36). The groves at the foot of the Mount of Olives are the traditional site.'),
(237, 'Golgotha', 'Church of the Holy Sepulchre, Jerusalem', 31.7784, 35.2296, 'Jerusalem', 'The place of a skull outside the city wall, with a garden and a new tomb nearby (John 19:17, 41-42). Marked here at the ancient tradition under the Church of the Holy Sepulchre; the Garden Tomb, north of the Damascus Gate, is a nineteenth-century proposal.'),
(238, 'Lydda', 'Lod, Israel', 31.9516, 34.8953, 'Plain of Sharon', 'Town where Peter healed Aeneas, eaten with palsy eight years (Acts 9:32-35); near Joppa (Acts 9:38). Identified with modern Lod.');
