INSERT INTO journeys (id, name, description, book_id) VALUES
(1, 'Book of Acts', 'The spread of the early church from Jerusalem to Rome, following the narrative of Acts.', 44),
(2, 'Book of Genesis', 'From Creation through the patriarchs — Abraham, Isaac, Jacob, and Joseph — ending with Israel in Egypt.', 1),
(3, 'Book of Exodus', 'The deliverance of Israel from Egypt, through the wilderness to Mount Sinai and the building of the Tabernacle, then on to Kadesh Barnea and the Jordan.', 2),
(4, 'Gospel of Luke', 'The life of Jesus from birth through resurrection, following Luke''s orderly account.', 42),
(5, 'Book of Jonah', 'The prophet Jonah flees from God, is swallowed by a great fish, and ultimately preaches repentance to Nineveh.', 32),
(6, 'Into the Promised Land', 'From Kadesh through the last wilderness years, across the Jordan and through the conquest to the covenant at Shechem.', 6),
(7, 'The Judges and Ruth', 'The deliverers raised up across the land, with Ruth''s road from Moab to Bethlehem and Samuel''s beginnings at Shiloh.', 7),
(8, 'David: Shepherd to King', 'David is anointed in Bethlehem, faces Goliath, flees Saul, is made king at Hebron and Jerusalem, and returns from exile in Absalom''s revolt.', 9),
(9, 'Elijah and Elisha', 'The prophets Elijah and Elisha, from the brook Cherith and Mount Carmel to the chariot of fire, and Elisha''s ministry from Shunem to Damascus.', 11),
(10, 'Exile and Return', 'Judah is carried away to Babylon, lives and witnesses there, and comes home in waves under Zerubbabel, Ezra and Nehemiah to rebuild the Temple and the walls.', 27),
(11, 'Jesus in John''s Gospel', 'Jesus'' ministry as John tells it: from the Jordan to Cana, the feasts at Jerusalem, Lazarus, the Passion and the breakfast by the Sea of Tiberias.', 43),
(12, 'Peter', 'Simon Peter after the Ascension: Pentecost, Jerusalem, Samaria, the coast, Cornelius, prison and the council, ending at Antioch.', 44);
INSERT INTO journey_stops (id, journey_id, sort_order, location_id, event_id, label, description, year, chapter) VALUES
(1, 1, 10, 7, 48, 'Pentecost in Jerusalem', 'The Holy Spirit descends on the apostles; Peter preaches and 3,000 are baptized.', 33, 'Acts 2:1-47'),
(2, 1, 20, 7, 49, 'Stoning of Stephen', 'Stephen is stoned; persecution scatters believers beyond Jerusalem.', 33, 'Acts 6:8–7:60'),
(3, 1, 30, 26, 175, 'Philip Preaches in Samaria', 'Philip performs miracles in Samaria; Simon the sorcerer believes.', 34, 'Acts 8:4-25'),
(4, 1, 40, 27, 176, 'Ethiopian Eunuch Baptized', 'Philip meets an Ethiopian official on the Gaza road and baptizes him.', 34, 'Acts 8:26-40'),
(5, 1, 50, 12, 50, 'Conversion of Saul', 'Saul encounters Christ on the Damascus road; Ananias restores his sight.', 35, 'Acts 9:1-19'),
(6, 1, 60, 28, 177, 'Peter Raises Tabitha in Joppa', 'Peter raises the disciple Tabitha (Dorcas) from the dead.', 38, 'Acts 9:36-43'),
(7, 1, 70, 29, 178, 'Peter and Cornelius in Caesarea', 'Peter receives a vision; the first Gentiles receive the Holy Spirit.', 40, 'Acts 10:1-48'),
(8, 1, 80, 13, 179, 'Church Established in Antioch', 'Believers first called "Christians" in Antioch; Barnabas and Saul teach.', 43, 'Acts 11:19-30'),
(9, 1, 90, 30, 180, 'Barnabas and Saul in Cyprus', 'Paul blinds the sorcerer Bar-Jesus; proconsul Sergius Paulus believes.', 45, 'Acts 13:4-12'),
(10, 1, 100, 31, 181, 'Paul Preaches in Pisidian Antioch', 'Paul''s sermon in the synagogue; many believe but Jews stir up opposition.', 45, 'Acts 13:14-52'),
(11, 1, 110, 32, 182, 'Iconium — Belief and Opposition', 'Paul and Barnabas preach; the city divides; they flee before stoning.', 45, 'Acts 14:1-7'),
(12, 1, 120, 33, 183, 'Lystra — Healing and Stoning', 'Paul heals a lame man; mistaken for gods; then stoned and left for dead.', 45, 'Acts 14:8-20'),
(13, 1, 130, 34, 184, 'Derbe — Many Disciples', 'Paul and Barnabas make many disciples and begin the return journey.', 45, 'Acts 14:20-21'),
(14, 1, 140, 7, 52, 'Council of Jerusalem', 'Church leaders decide Gentiles need not be circumcised.', 52, 'Acts 15:1-35'),
(15, 1, 150, 35, 185, 'Macedonian Vision at Troas', 'Paul receives a vision: "Come over to Macedonia and help us."', 53, 'Acts 16:8-10'),
(16, 1, 160, 36, 186, 'Lydia Converted in Philippi', 'Lydia believes; Paul and Silas imprisoned; jailer converted.', 53, 'Acts 16:11-40'),
(17, 1, 170, 37, 187, 'Paul in Thessalonica', 'Paul reasons in the synagogue; accused of "turning the world upside down."', 53, 'Acts 17:1-9'),
(18, 1, 180, 38, 188, 'Noble-Minded Bereans', 'The Bereans examine the Scriptures daily to verify Paul''s message.', 53, 'Acts 17:10-15'),
(19, 1, 190, 39, 189, 'Paul on the Areopagus in Athens', 'Paul preaches about the "Unknown God" on Mars Hill.', 54, 'Acts 17:16-34'),
(20, 1, 200, 40, 190, 'Paul in Corinth — 18 Months', 'Paul stays with Aquila and Priscilla; Gallio dismisses charges.', 54, 'Acts 18:1-17'),
(21, 1, 210, 41, 191, 'Paul in Ephesus — 2 Years', 'Extraordinary miracles; burning of occult scrolls; riot of Demetrius.', 57, 'Acts 19:1-41'),
(22, 1, 220, 42, 192, 'Farewell to Ephesian Elders at Miletus', 'Paul''s emotional farewell: "I have not coveted anyone''s silver or gold."', 60, 'Acts 20:17-38'),
(23, 1, 230, 7, 193, 'Paul Arrested in Jerusalem', 'Paul seized in the temple; transferred to Roman custody.', 60, 'Acts 21:27–23:10'),
(24, 1, 240, 29, 194, 'Paul''s Trial before Felix and Festus', 'Paul held in Caesarea for two years; appeals to Caesar.', 60, 'Acts 23:23–26:32'),
(25, 1, 250, 115, 195, 'Storm and Fair Havens of Crete', 'Paul warns against sailing; a violent storm batters the ship 14 days.', 62, 'Acts 27:7-44'),
(26, 1, 260, 44, 196, 'Shipwreck on Malta', 'All 276 aboard survive; Paul bitten by a viper but unharmed; heals the sick.', 62, 'Acts 27:39–28:10'),
(27, 1, 270, 45, 197, 'Landing at Puteoli', 'Paul welcomed by believers at the Italian port.', 63, 'Acts 28:13-14'),
(28, 1, 280, 14, 198, 'Paul Arrives in Rome', 'Paul preaches the kingdom of God under house arrest for two years.', 63, 'Acts 28:16-31'),
(29, 2, 10, 1, 1, 'Creation', 'God creates the heavens, the earth, and mankind in His image.', -4004, 'Genesis 1:1–2:25'),
(30, 2, 20, 1, 2, 'The Fall', 'Adam and Eve disobey God and are expelled from the Garden of Eden.', -4004, 'Genesis 3:1-24'),
(31, 2, 30, 102, 3, 'The Flood', 'God judges the earth with a flood; Noah and his family are saved on the ark.', -2349, 'Genesis 6:1–9:29'),
(32, 2, 40, 9, 4, 'Tower of Babel', 'Humanity is scattered when God confuses their language at the tower.', -2247, 'Genesis 11:1-9'),
(33, 2, 50, 2, 5, 'Call of Abraham', 'God appears to Abram in Mesopotamia before he settles in Haran (Acts 7:2-4) and tells him to leave for a land He will show him (Gen 12:1-3). Ussher dates his departure from Haran to 1921 BC.', -1921, 'Genesis 11:31–12:3; Acts 7:2-4'),
(34, 2, 60, 3, NULL, 'Abraham in Haran', 'Abram settles in Haran with Terah; after Terah''s death, he departs for Canaan.', -1921, 'Genesis 11:31–12:4'),
(35, 2, 70, 46, NULL, 'Abraham at Shechem', 'Abram arrives in Canaan; God promises the land. Abraham builds an altar.', -1920, 'Genesis 12:6-7'),
(37, 2, 80, 5, NULL, 'Abram in Egypt', 'Famine drives Abram to Egypt; Pharaoh takes Sarai but is plagued.', -1919, 'Genesis 12:10-20'),
(36, 2, 90, 47, 6, 'Abrahamic Covenant at Hebron', 'God makes a covenant with Abraham at the oaks of Mamre, promising countless descendants.', -1912, 'Genesis 13:18; 15:1-21'),
(39, 2, 100, 47, 9, 'Covenant of Circumcision', 'God establishes circumcision as the sign of His covenant with Abraham.', -1897, 'Genesis 17:1-27'),
(40, 2, 110, 47, 8, 'Destruction of Sodom and Gomorrah', 'Abraham intercedes; God destroys the cities but Lot escapes.', -1897, 'Genesis 18:1–19:38'),
(38, 2, 120, 48, NULL, 'Hagar and Ishmael at Beersheba', 'Hagar and Ishmael sent away; God provides a well in the wilderness.', -1892, 'Genesis 21:8-21'),
(41, 2, 130, 7, 7, 'Binding of Isaac on Mount Moriah', 'Abraham''s faith tested; God provides a ram as a substitute.', -1871, 'Genesis 22:1-19'),
(42, 2, 140, 48, NULL, 'Isaac Settles at Beersheba', 'Driven by famine and strife from Gerar, Isaac settles at Beersheba, where God renews the covenant and Abimelech makes peace with him. Jacob and Esau had been born twenty years after his marriage (Gen 25:19-26).', -1804, 'Genesis 26:23-33'),
(100, 2, 150, 100, NULL, 'Jacob''s Dream at Bethel', 'Fleeing Esau, Jacob dreams of a ladder reaching to heaven and God renews to him the promise made to Abraham.', -1760, 'Genesis 28:10-22'),
(43, 2, 160, 3, NULL, 'Jacob Flees to Haran', 'Jacob leaves home, reaches Haran and serves Laban for twenty years, marrying Leah and Rachel (Gen 29-31).', -1760, 'Genesis 27:1–31:55'),
(44, 2, 170, 50, 10, 'Jacob Wrestles God at Peniel', 'Jacob wrestles with God and is renamed Israel.', -1739, 'Genesis 32:22-32'),
(45, 2, 180, 46, NULL, 'Jacob Returns to Shechem', 'Jacob returns to Canaan and buys land at Shechem; Dinah incident.', -1738, 'Genesis 33:18–34:31'),
(46, 2, 190, 47, NULL, 'Jacob Returns to Hebron', 'Jacob comes to his father Isaac at Mamre (Hebron); Rachel has died near Bethlehem on the way (Gen 35:16-20). Isaac dies at 180 and is buried by his sons (Gen 35:28-29).', -1732, 'Genesis 35:16-29'),
(47, 2, 200, 101, 11, 'Joseph Sold into Slavery', 'Joseph''s brothers sell him to traders headed for Egypt.', -1728, 'Genesis 37:1-36'),
(48, 2, 210, 5, 12, 'Joseph Made Ruler of Egypt', 'After interpreting Pharaoh''s dreams, Joseph becomes second-in-command.', -1715, 'Genesis 41:1-57'),
(49, 2, 220, 49, 13, 'Israel Enters Goshen', 'Jacob''s family (70 people) settles in Goshen at Pharaoh''s invitation.', -1706, 'Genesis 46:1–47:31'),
(50, 3, 10, 49, NULL, 'Israel Enslaved in Goshen', 'A new Pharaoh arises who does not know Joseph; Israel is enslaved and multiplies.', -1571, 'Exodus 1:1-22'),
(51, 3, 20, 5, 14, 'The Ten Plagues', 'Moses confronts Pharaoh; God sends ten plagues upon Egypt, ending with the death of every firstborn.', -1491, 'Exodus 7:1–12:36'),
(52, 3, 30, 49, NULL, 'The Passover and Departure', 'Israel keeps the first Passover and sets out from Rameses with great wealth.', -1491, 'Exodus 12:1-42'),
(53, 3, 40, 51, 15, 'Crossing the Red Sea', 'God parts the sea; Israel passes through on dry ground; Pharaoh''s army is destroyed.', -1491, 'Exodus 14:1-31'),
(54, 3, 50, 52, NULL, 'Bitter Waters of Marah', 'Israel''s first crisis: bitter water is made sweet by a tree God shows Moses.', -1491, 'Exodus 15:22-25'),
(55, 3, 60, 53, NULL, 'Rest at Elim', 'Israel camps at an oasis with twelve springs and seventy palm trees.', -1491, 'Exodus 15:27'),
(56, 3, 70, 54, NULL, 'Water from the Rock at Rephidim', 'God provides water from a rock; Israel defeats Amalek while Moses'' hands are raised.', -1491, 'Exodus 17:1-16'),
(57, 3, 80, 6, 16, 'Giving of the Law at Sinai', 'God descends on Mount Sinai in fire and thunder; gives the Ten Commandments and the Law.', -1491, 'Exodus 19:1–24:18'),
(58, 3, 90, 6, NULL, 'The Golden Calf', 'While Moses is on the mountain, Aaron makes a golden calf; God''s anger and Moses'' intercession.', -1491, 'Exodus 32:1-35'),
(59, 3, 100, 6, 18, 'The Tabernacle Completed', 'Israel builds the Tabernacle according to God''s pattern; the glory of the Lord fills it.', -1490, 'Exodus 35:1–40:38'),
(60, 3, 110, 55, 17, 'Wilderness Wandering — Kadesh Barnea', 'The twelve spies return; ten give a bad report. Israel is condemned to wander 40 years.', -1490, 'Numbers 13:1–14:45'),
(61, 3, 120, 25, NULL, 'Arrival at the Jordan', 'After 40 years, the new generation reaches the Jordan River opposite the Promised Land.', -1451, 'Deuteronomy 34:1-12; Joshua 1:1-18'),
(62, 4, 10, 7, NULL, 'Zechariah in the Temple', 'The angel Gabriel announces the birth of John the Baptist to the priest Zechariah.', -6, 'Luke 1:5-25'),
(63, 4, 20, 10, 360, 'Annunciation in Nazareth', 'Gabriel tells the virgin Mary she will bear the Son of God.', -5, 'Luke 1:26-38'),
(64, 4, 30, 8, 42, 'Birth of Jesus in Bethlehem', 'Jesus is born in a manger; angels announce the birth to shepherds.', -5, 'Luke 2:1-20'),
(65, 4, 40, 7, 363, 'Presentation at the Temple', 'Mary and Joseph present Jesus at the Temple; Simeon and Anna prophesy.', -4, 'Luke 2:22-40'),
(66, 4, 50, 10, 364, 'The Boy Jesus in Nazareth', 'Jesus grows up in Nazareth; at age 12 astounds the teachers in the Temple.', 8, 'Luke 2:39-52'),
(67, 4, 60, 25, 43, 'Baptism of Jesus at the Jordan', 'Jesus is baptized by John; the Holy Spirit descends; the Father speaks.', 27, 'Luke 3:21-22'),
(68, 4, 70, 10, NULL, 'Rejected at Nazareth', 'Jesus reads Isaiah in the synagogue; his hometown tries to throw him off a cliff.', 31, 'Luke 4:16-30'),
(69, 4, 80, 11, 61, 'Ministry Begins in Capernaum', 'Jesus drives out a demon in the synagogue and heals Peter''s mother-in-law.', 31, 'Luke 4:31-41'),
(70, 4, 90, 17, 60, 'Great Catch of Fish', 'Jesus calls Simon Peter, James, and John after a miraculous catch of fish.', 31, 'Luke 5:1-11'),
(71, 4, 100, 19, 68, 'Raising the Widow''s Son at Nain', 'Jesus raises a widow''s only son from the dead; "God has visited His people."', 31, 'Luke 7:11-17'),
(72, 4, 110, 17, 69, 'Calming the Storm', 'Jesus rebukes the wind and waves; the disciples ask, "Who is this?"', 31, 'Luke 8:22-25'),
(73, 4, 120, 21, 70, 'Healing of the Gerasene Demoniac', 'Jesus casts Legion out of a man among the tombs on the eastern shore; Matthew places it at Gadara, Mark and Luke at the country of the Gerasenes.', 31, 'Luke 8:26-39'),
(74, 4, 130, 18, 75, 'Feeding of the 5,000 near Bethsaida', 'Jesus feeds 5,000 men with five loaves and two fish.', 32, 'Luke 9:10-17'),
(75, 4, 140, 22, NULL, 'The Good Samaritan — Road to Jericho', 'Jesus tells the parable of the Good Samaritan to a lawyer''s question.', 32, 'Luke 10:25-37'),
(76, 4, 150, 20, NULL, 'Mary and Martha in Bethany', 'Martha serves while Mary sits at Jesus'' feet; "Mary has chosen the good portion."', 32, 'Luke 10:38-42'),
(77, 4, 160, 22, 89, 'Healing of Blind Bartimaeus', 'Jesus heals a blind man near Jericho; Zacchaeus believes.', 33, 'Luke 18:35–19:10'),
(78, 4, 170, 7, 45, 'Crucifixion in Jerusalem', 'Jesus is crucified at Golgotha; "Father, forgive them, for they know not what they do."', 33, 'Luke 23:1-56'),
(79, 4, 180, 7, 46, 'The Empty Tomb', 'Women find the tomb empty; angels declare, "He is not here; He has risen!"', 33, 'Luke 24:1-12'),
(80, 4, 190, 57, NULL, 'Road to Emmaus', 'The risen Jesus walks with two disciples; revealed in the breaking of bread.', 33, 'Luke 24:13-35'),
(81, 4, 200, 20, 47, 'Ascension near Jerusalem', 'Jesus blesses the disciples and is taken up into heaven near Bethany.', 33, 'Luke 24:50-53'),
(82, 5, 10, 104, NULL, 'God''s Call to Jonah', 'The word of the Lord comes to Jonah (the text names no place; his home was Gath-hepher): "Go to Nineveh, that great city, and cry out against it."', -771, 'Jonah 1:1-2'),
(83, 5, 20, 28, NULL, 'Jonah Flees to Joppa', 'Instead of obeying, Jonah goes down to Joppa and boards a ship bound for Tarshish — away from God.', -771, 'Jonah 1:3'),
(84, 5, 30, 103, NULL, 'The Great Storm at Sea', 'God hurls a great wind; the sailors cast lots; Jonah confesses and is thrown overboard.', -771, 'Jonah 1:4-16'),
(85, 5, 40, 103, NULL, 'Swallowed by the Great Fish', 'God appoints a great fish to swallow Jonah. He prays from its belly for three days and nights.', -771, 'Jonah 1:17–2:10'),
(86, 5, 50, 56, NULL, 'Jonah Preaches in Nineveh', 'Jonah walks through the great city crying, "Yet forty days, and Nineveh shall be overthrown!"', -771, 'Jonah 3:1-4'),
(87, 5, 60, 56, NULL, 'Nineveh Repents', 'The king and all the people repent in sackcloth and ashes; God relents from disaster.', -771, 'Jonah 3:5-10'),
(88, 5, 70, 56, NULL, 'Jonah''s Anger and the Vine', 'Jonah is angry that God showed mercy. God teaches him compassion through a vine and a worm.', -771, 'Jonah 4:1-11'),
(200, 6, 10, 55, NULL, 'Kadesh: Miriam Dies, Moses Strikes the Rock', 'In the fortieth year Miriam dies at Kadesh, the people have no water, and Moses strikes the rock; Edom refuses them passage.', -1452, 'Numbers 20:1-21'),
(201, 6, 20, 200, NULL, 'Aaron Dies on Mount Hor', 'Moses takes Aaron and Eleazar up the mountain, strips Aaron of the priestly garments and puts them on Eleazar; Aaron dies there.', -1452, 'Numbers 20:22-29'),
(202, 6, 30, 201, NULL, 'The Bronze Serpent', 'Discouraged on the road around Edom, the people are bitten by fiery serpents; Moses lifts up a bronze serpent and all who look live.', -1452, 'Numbers 21:4-9'),
(203, 6, 40, 174, 408, 'Plains of Moab: Balak and Balaam', 'Israel camps on the plains of Moab; Balak hires Balaam, who can only bless Israel.', -1452, 'Numbers 22:1–24:25'),
(204, 6, 50, 120, 320, 'Moses Views the Land from Nebo', 'Moses climbs Mount Nebo, sees the land he will not enter, and dies there.', -1451, 'Deuteronomy 34:1-12'),
(205, 6, 60, 25, 321, 'Crossing the Jordan', 'The priests carry the ark into the Jordan, the waters stand up, and Israel crosses on dry ground; twelve stones are set up.', -1451, 'Joshua 3:1–4:24'),
(206, 6, 70, 173, NULL, 'Gilgal: Circumcision and Passover', 'At Gilgal the new generation is circumcised, keeps the Passover, eats the produce of the land, and the manna ceases.', -1451, 'Joshua 5:1-15'),
(207, 6, 80, 22, 20, 'The Fall of Jericho', 'Israel marches round the city for seven days and the wall falls; Rahab and her household are saved.', -1451, 'Joshua 6:1-27'),
(208, 6, 90, 170, 409, 'Ai: Achan''s Sin and Victory', 'Israel is defeated at Ai because of Achan''s theft; after Achan is judged, Joshua takes the city by ambush.', -1451, 'Joshua 7:1–8:29'),
(209, 6, 100, 202, NULL, 'Mount Ebal and Mount Gerizim', 'Joshua builds an altar on Mount Ebal and reads the blessings and curses of the law to all Israel between Ebal and Gerizim.', -1451, 'Joshua 8:30-35'),
(210, 6, 110, 171, 410, 'Gibeon: The Sun Stands Still', 'Joshua defends the Gibeonites against five kings, and the sun and moon stand still while Israel wins the day.', -1451, 'Joshua 10:1-15');
INSERT INTO journey_stops (id, journey_id, sort_order, location_id, event_id, label, description, year, chapter) VALUES
(211, 6, 120, 124, NULL, 'The Tabernacle Set Up at Shiloh', 'The whole congregation gathers at Shiloh and sets up the tabernacle; the land is then surveyed and divided by lot.', -1444, 'Joshua 18:1-10'),
(212, 6, 130, 46, 322, 'Shechem: Joshua''s Covenant', 'Joshua gathers the tribes, recounts God''s dealings with them, and calls them to choose: ''as for me and my house, we will serve the LORD.''', -1443, 'Joshua 24:1-33'),
(220, 7, 10, 203, NULL, 'Othniel Delivers Israel', 'Othniel of Debir, who had taken the city and won Achsah as his wife (Judg 1:11-13), is raised up when Israel serves Cushan-rishathaim; the Spirit of the LORD comes on him and the land has rest forty years.', -1405, 'Judges 3:7-11'),
(221, 7, 20, 22, NULL, 'Ehud Kills Eglon', 'Ehud, a left-handed Benjamite, brings tribute to Eglon of Moab at the city of palm trees and kills him; Israel then defeats Moab at the fords of the Jordan.', -1325, 'Judges 3:12-30'),
(222, 7, 30, 117, 22, 'Deborah and Barak at Tabor and the Kishon', 'Deborah summons Barak to Mount Tabor; the LORD routs Sisera''s chariots by the river Kishon, and Jael kills Sisera.', -1285, 'Judges 4:1–5:31'),
(223, 7, 40, 204, NULL, 'Gideon Called at Ophrah', 'The angel of the LORD calls Gideon from the winepress at Ophrah; he pulls down his father''s altar of Baal.', -1245, 'Judges 6:1-40'),
(224, 7, 50, 126, 23, 'Gideon at the Spring of Harod', 'Gideon''s army is cut from thirty-two thousand to three hundred at the spring of Harod, and Midian is routed with trumpets and pitchers.', -1245, 'Judges 7:1-25'),
(225, 7, 60, 205, 326, 'Jephthah at Mizpah of Gilead', 'Gilead recalls Jephthah, who makes his vow at Mizpah and defeats the Ammonites.', -1188, 'Judges 11:1-40'),
(226, 7, 70, 174, 412, 'Ruth Leaves Moab', 'After the deaths of her husband and sons, Naomi returns toward Judah and Ruth clings to her: ''thy people shall be my people.''', -1172, 'Ruth 1:1-18'),
(227, 7, 80, 8, NULL, 'Ruth and Boaz at Bethlehem', 'Ruth gleans in Boaz''s field, Boaz redeems the family land and marries her, and their line leads to David.', -1171, 'Ruth 1:19–4:22'),
(228, 7, 90, 206, 411, 'Samson Born at Zorah', 'The angel announces a son to Manoah''s wife; Samson is born a Nazirite and the Spirit begins to move him.', -1155, 'Judges 13:1-25'),
(229, 7, 100, 124, 413, 'Hannah''s Prayer at Shiloh', 'Barren Hannah prays at the house of the LORD in Shiloh, Eli blesses her, and she bears Samuel.', -1150, '1 Samuel 1:1–2:11'),
(230, 7, 110, 124, 414, 'The Call of Samuel at Shiloh', 'The LORD calls the boy Samuel in the night and Eli hears the word of judgment on his house.', -1138, '1 Samuel 3:1-21'),
(231, 7, 120, 207, NULL, 'Samson at Timnah', 'Samson goes down to Timnah, takes a Philistine wife, kills a lion and poses his riddle.', -1135, 'Judges 14:1-20'),
(232, 7, 130, 127, 327, 'Samson at Gaza', 'Samson carries off the gates of Gaza, and is later brought back there blind; he pulls down the temple of Dagon.', -1117, 'Judges 16:1-31'),
(233, 7, 140, 123, 329, 'Samuel Judges Israel at Mizpah', 'Israel gathers at Mizpah, puts away its idols and fasts; the LORD thunders on the Philistines and Samuel sets up Ebenezer.', -1096, '1 Samuel 7:3-17'),
(250, 8, 10, 8, 26, 'Samuel Anoints David', 'Samuel comes to Jesse''s house and, passing over the older sons, anoints the youngest, David, who is keeping the sheep.', -1063, '1 Samuel 16:1-13'),
(251, 8, 20, 122, 328, 'David and Goliath', 'David, sent with food for his brothers, takes up Goliath''s challenge and kills him with a sling and a stone.', -1063, '1 Samuel 17:1-58'),
(252, 8, 30, 210, NULL, 'In Saul''s Court at Gibeah', 'David serves Saul and befriends Jonathan, but Saul''s jealousy turns murderous and David escapes with the help of Michal and Jonathan.', -1062, '1 Samuel 18:1–19:24'),
(253, 8, 40, 211, NULL, 'Bread at Nob', 'Fleeing Saul, David receives holy bread and Goliath''s sword from Ahimelech the priest at Nob.', -1060, '1 Samuel 21:1-9'),
(254, 8, 50, 212, NULL, 'Feigning Madness at Gath', 'David goes to Achish king of Gath, is recognised, and escapes by pretending to be mad.', -1060, '1 Samuel 21:10-15'),
(255, 8, 60, 213, NULL, 'The Cave of Adullam', 'David hides in the cave of Adullam, and his family and about four hundred distressed men gather to him.', -1060, '1 Samuel 22:1-5'),
(256, 8, 70, 214, NULL, 'Rescuing Keilah', 'David defeats the Philistines at Keilah, then learns that the town would hand him over to Saul and leaves.', -1060, '1 Samuel 23:1-13'),
(257, 8, 80, 172, 416, 'Sparing Saul at En-gedi', 'David cuts off the corner of Saul''s robe in a cave and refuses to harm the Lord''s anointed.', -1059, '1 Samuel 24:1-22'),
(258, 8, 90, 215, NULL, 'Ziklag', 'Achish gives David Ziklag. After the Amalekites burn it and take the families, David pursues and recovers everything.', -1056, '1 Samuel 27:1-12'),
(259, 8, 100, 47, 324, 'Made King at Hebron', 'After Saul''s death David goes up to Hebron, and the men of Judah anoint him king over Judah.', -1055, '2 Samuel 2:1-11'),
(260, 8, 110, 47, 325, 'King over All Israel', 'The tribes of Israel come to David at Hebron and anoint him king over all Israel.', -1048, '2 Samuel 5:1-5'),
(261, 8, 120, 7, 27, 'Jerusalem Taken', 'David takes the stronghold of Zion from the Jebusites and makes it the city of David.', -1048, '2 Samuel 5:6-10'),
(262, 8, 130, 7, 330, 'The Ark Comes to Jerusalem', 'David brings the ark of God up to Jerusalem with rejoicing and sets it in a tent.', -1045, '2 Samuel 6:1-23'),
(263, 8, 140, 216, 419, 'Refuge at Mahanaim', 'Driven from Jerusalem by Absalom''s revolt, David crosses the Jordan to Mahanaim, where Joab leads his army to victory and Absalom dies.', -1023, '2 Samuel 17:24–18:33'),
(264, 8, 150, 7, NULL, 'Return to Jerusalem', 'Judah invites David back, he crosses the Jordan, and he comes again to his house in Jerusalem.', -1023, '2 Samuel 19:9–20:3'),
(270, 9, 10, 217, 437, 'Fed at the Brook Cherith', 'After telling Ahab there will be no rain, Elijah hides by the brook Cherith and ravens bring him bread and meat.', -910, '1 Kings 17:1-7'),
(271, 9, 20, 178, 437, 'The Widow of Zarephath', 'The brook dries up and Elijah goes to Zarephath, where the widow''s flour and oil do not run out and her son is raised.', -910, '1 Kings 17:8-24'),
(272, 9, 30, 108, 31, 'Fire on Mount Carmel', 'Elijah challenges the prophets of Baal; the fire of the Lord falls and the people turn back to Him.', -905, '1 Kings 18:1-40'),
(273, 9, 40, 177, NULL, 'Racing Ahab to Jezreel', 'Rain ends the drought, and Elijah runs ahead of Ahab''s chariot to the entrance of Jezreel.', -905, '1 Kings 18:41-46'),
(274, 9, 50, 48, NULL, 'The Juniper Tree', 'Threatened by Jezebel, Elijah flees to Beersheba and then into the wilderness, where an angel feeds him under a juniper tree.', -904, '1 Kings 19:3-8'),
(275, 9, 60, 6, 438, 'The Still Small Voice at Horeb', 'Elijah travels forty days to Horeb, the mount of God, and hears the Lord in a still small voice.', -904, '1 Kings 19:8-18'),
(276, 9, 70, 218, NULL, 'Elisha Called at Abel-meholah', 'Elijah finds Elisha ploughing, throws his mantle over him, and Elisha leaves the oxen to follow him.', -904, '1 Kings 19:16-21'),
(277, 9, 80, 177, 439, 'Naboth''s Vineyard', 'Jezebel has Naboth killed so Ahab can take his vineyard at Jezreel, and Elijah pronounces judgment on Ahab and Jezebel.', -899, '1 Kings 21:1-29'),
(278, 9, 90, 100, NULL, 'Bethel', 'Elijah and Elisha come down from Gilgal to Bethel, and Elisha refuses to leave his master.', -896, '2 Kings 2:1-3'),
(279, 9, 100, 22, NULL, 'Jericho', 'At Jericho the sons of the prophets tell Elisha that his master will be taken, and the two go on towards the Jordan.', -896, '2 Kings 2:4-8'),
(280, 9, 110, 25, 443, 'The Chariot of Fire', 'Elijah parts the Jordan and is taken up in a whirlwind by a chariot of fire; Elisha takes up his mantle and parts the river again.', -896, '2 Kings 2:6-15'),
(281, 9, 120, 219, NULL, 'The Shunammite''s Son', 'At Shunem Elisha is hosted by a woman whose son he later raises from the dead.', -893, '2 Kings 4:8-37'),
(282, 9, 130, 25, 94, 'Naaman Healed in the Jordan', 'Naaman, the Aramean commander, washes seven times in the Jordan and is cleansed, while Gehazi''s greed brings leprosy on himself.', -890, '2 Kings 5:1-27'),
(283, 9, 140, 101, NULL, 'The Army at Dothan', 'The king of Aram sends an army to seize Elisha at Dothan, and the Lord opens the eyes of Elisha''s servant to see the horses and chariots of fire.', -889, '2 Kings 6:8-23'),
(284, 9, 150, 26, NULL, 'Samaria Besieged', 'Ben-hadad besieges Samaria and famine grips the city, until the Lord scatters the Arameans and the people feast on their camp.', -888, '2 Kings 6:24–7:20'),
(285, 9, 160, 12, 445, 'Hazael at Damascus', 'Elisha comes to Damascus and foretells that Hazael will be king of Aram; Hazael takes the throne.', -885, '2 Kings 8:7-15'),
(300, 10, 10, 7, 468, 'Daniel Taken from Jerusalem', 'Nebuchadnezzar besieges Jerusalem and carries off vessels of the Temple and young nobles of Judah, among them Daniel, Hananiah, Mishael and Azariah, to be trained in Babylon.', -607, 'Daniel 1:1-7'),
(301, 10, 20, 7, 470, 'Jehoiachin Carried Away', 'Nebuchadnezzar''s army returns to the city; King Jehoiachin, the court, the craftsmen and ten thousand captives are taken to Babylon.', -599, '2 Kings 24:10-16'),
(302, 10, 30, 180, 471, 'Ezekiel by the Chebar', 'Among the exiles on the river Chebar, the priest Ezekiel sees the heavens opened and the glory of God above the living creatures.', -595, 'Ezekiel 1:1-28'),
(303, 10, 40, 7, 35, 'Jerusalem Falls', 'After a siege of about a year and a half the wall is breached; the Temple and the city are burned, the walls thrown down and the people carried away.', -588, '2 Kings 25:1-21'),
(304, 10, 50, 220, NULL, 'Zedekiah Judged at Riblah', 'Caught on the plains of Jericho, Zedekiah is brought to Nebuchadnezzar at Riblah, where his sons are killed before his eyes and he is blinded and bound for Babylon.', -588, '2 Kings 25:4-7'),
(305, 10, 60, 221, NULL, 'Jeremiah and the Remnant at Tahpanhes', 'Against Jeremiah''s warning, the captains lead the remnant into Egypt, taking the prophet and Baruch with them as far as Tahpanhes.', -588, 'Jeremiah 43:1-7'),
(306, 10, 70, 9, 474, 'The Fiery Furnace', 'Shadrach, Meshach and Abednego refuse to bow to Nebuchadnezzar''s golden image and are cast into the furnace; a fourth figure walks with them and they come out unharmed.', -580, 'Daniel 3:1-30'),
(307, 10, 80, 9, 340, 'Belshazzar''s Feast', 'A hand writes on the wall during Belshazzar''s feast; Daniel reads it, and that night Babylon is taken and Darius the Median receives the kingdom.', -538, 'Daniel 5:1-31'),
(308, 10, 90, 9, 475, 'Daniel in the Lions'' Den', 'Daniel is thrown to the lions for praying to his God and is found unharmed in the morning.', -538, 'Daniel 6:1-28'),
(309, 10, 100, 7, 480, 'Cyrus Frees the Exiles', 'Cyrus decrees that the Temple be rebuilt; Zerubbabel and Jeshua lead the first company of about forty-two thousand home to Judah.', -536, 'Ezra 1:1–2:70'),
(310, 10, 110, 7, 38, 'The Temple Finished', 'After delays and the prophets'' urging, the Temple is completed and dedicated, and the Passover is kept.', -515, 'Ezra 6:1-22'),
(311, 10, 120, 106, 41, 'Esther at Susa', 'Esther, made queen of Persia, and her cousin Mordecai turn Haman''s decree against the Jews, and Purim is established.', -473, 'Esther 8:1–9:32'),
(312, 10, 130, 222, NULL, 'Ezra Gathers the Exiles at the Ahava', 'Ezra musters the returning company by the river Ahava, finds no Levites among them, sends for some, and the people fast and pray for a safe way.', -458, 'Ezra 8:15-23'),
(313, 10, 140, 7, 39, 'Ezra Arrives in Jerusalem', 'After a journey of four months Ezra reaches Jerusalem with the king''s gifts and the Temple vessels, which are weighed into the Temple.', -458, 'Ezra 8:31-36'),
(314, 10, 150, 106, NULL, 'Nehemiah''s Prayer at Susa', 'Hearing that Jerusalem''s walls are broken, the king''s cupbearer Nehemiah prays, and Artaxerxes sends him to Judah as governor.', -445, 'Nehemiah 1:1–2:10'),
(315, 10, 160, 7, 40, 'Nehemiah Rebuilds the Walls', 'Nehemiah surveys the ruined wall by night, the people build despite opposition, and the wall is finished in fifty-two days.', -445, 'Nehemiah 2:11–6:15'),
(330, 11, 10, 230, 43, 'Bethabara beyond Jordan', 'John bears witness to Jesus where he is baptizing beyond the Jordan; Jesus is baptized and John points him out as the Lamb of God.', 27, 'John 1:19-34'),
(331, 11, 20, 16, 58, 'Wedding at Cana', 'At a marriage in Cana of Galilee Jesus turns water into wine, the beginning of his miracles.', 30, 'John 2:1-11'),
(332, 11, 30, 11, NULL, 'Capernaum', 'Jesus goes down to Capernaum with his mother, his brethren and his disciples and stays a few days.', 30, 'John 2:12'),
(333, 11, 40, 235, NULL, 'Temple Cleansed at the First Passover', 'At the Passover Jesus drives the merchants and moneychangers from the temple and speaks of raising up the temple of his body.', 30, 'John 2:13-22'),
(334, 11, 50, 231, NULL, 'Jacobs Well at Sychar', 'Passing through Samaria, Jesus talks with a woman of Sychar at Jacobs well, and many Samaritans believe.', 30, 'John 4:1-42'),
(335, 11, 60, 16, 59, 'The Officials Son', 'Back in Cana, Jesus tells a nobleman of Capernaum that his son lives, and the man believes.', 30, 'John 4:46-54'),
(336, 11, 70, 232, 65, 'Pool of Bethesda', 'At a feast of the Jews Jesus heals a man who had been infirm 38 years and teaches on the authority of the Son.', 31, 'John 5:1-47'),
(337, 11, 80, 17, 75, 'Five Thousand Fed by the Sea of Tiberias', 'Jesus feeds a great crowd from five loaves and two fishes, walks on the sea and teaches on the bread of life.', 32, 'John 6:1-71'),
(338, 11, 90, 235, NULL, 'Feast of Tabernacles in Jerusalem', 'Jesus goes up to the feast in the middle of it and teaches in the temple about living water and the light of the world.', 32, 'John 7:1–8:59'),
(339, 11, 100, 233, 84, 'Pool of Siloam', 'Jesus gives sight to a man born blind and sends him to wash in the pool of Siloam.', 32, 'John 9:1-41'),
(340, 11, 110, 235, NULL, 'Solomons Porch at the Feast of Dedication', 'In winter Jesus walks in Solomons porch and tells the Jews, I and my Father are one.', 32, 'John 10:22-39'),
(341, 11, 120, 20, 87, 'Lazarus Raised at Bethany', 'Jesus comes to Bethany, weeps with Mary and Martha, and calls Lazarus out of the tomb.', 33, 'John 11:1-44'),
(342, 11, 130, 234, NULL, 'Ephraim', 'After the plot against him Jesus withdraws to Ephraim near the wilderness with his disciples.', 33, 'John 11:54'),
(343, 11, 140, 20, NULL, 'Anointing at Bethany', 'Six days before the Passover Mary anoints Jesus feet at supper while Lazarus sits at the table.', 33, 'John 12:1-8'),
(344, 11, 150, 7, 365, 'Entry into Jerusalem', 'Jesus rides into Jerusalem on a young ass as the crowd cries Hosanna.', 33, 'John 12:12-19'),
(345, 11, 160, 7, 366, 'The Upper Room', 'At supper Jesus washes the disciples feet, speaks of the Comforter and prays for them.', 33, 'John 13:1–17:26'),
(346, 11, 170, 236, 367, 'Gethsemane', 'Jesus goes over the brook Cedron into a garden where Judas leads the officers to arrest him.', 33, 'John 18:1-12'),
(347, 11, 180, 237, 45, 'Golgotha', 'Jesus is crucified at the place of a skull and dies after saying, It is finished.', 33, 'John 19:17-37'),
(348, 11, 190, 237, 46, 'The Tomb', 'Joseph and Nicodemus bury Jesus in the garden tomb; on the first day Mary Magdalene finds it empty and sees the risen Lord.', 33, 'John 19:38–20:18'),
(349, 11, 200, 17, 93, 'Breakfast by the Sea of Tiberias', 'Jesus shows himself to seven disciples after a night of fishing and feeds them on the shore.', 33, 'John 21:1-14'),
(350, 12, 10, 7, 48, 'Pentecost in Jerusalem', 'The Spirit falls on the disciples; Peter stands up with the eleven and preaches, and about three thousand are added.', 33, 'Acts 2:1-47'),
(351, 12, 20, 235, NULL, 'The Lame Man at the Beautiful Gate', 'Peter and John heal a man lame from birth at the temple gate and Peter preaches in Solomons porch.', 33, 'Acts 3:1-26'),
(352, 12, 30, 7, 494, 'Before the Council', 'Peter and John, and later all the apostles, answer the rulers: We ought to obey God rather than men.', 33, 'Acts 4:1–5:42'),
(353, 12, 40, 26, 175, 'Samaria with John', 'Peter and John come down from Jerusalem, pray for the Samaritans to receive the Holy Ghost, and rebuke Simon the sorcerer.', 34, 'Acts 8:14-25'),
(354, 12, 50, 238, NULL, 'Lydda and Aeneas', 'Passing through the quarters, Peter heals Aeneas, who had kept his bed eight years with palsy.', 38, 'Acts 9:32-35'),
(355, 12, 60, 28, 177, 'Joppa and Tabitha', 'Called from Lydda, Peter prays and raises Tabitha (Dorcas) and stays many days with Simon a tanner.', 38, 'Acts 9:36-43'),
(356, 12, 70, 29, 178, 'Caesarea and Cornelius', 'Taught by a vision at Joppa, Peter goes to the centurion Cornelius, preaches, and the Holy Ghost falls on the Gentiles.', 40, 'Acts 10:1-48'),
(357, 12, 80, 7, 368, 'Prison and Release in Jerusalem', 'Herod Agrippa I has Peter imprisoned; an angel frees him and he goes to the house of Mary, mother of John Mark.', 44, 'Acts 12:1-19'),
(358, 12, 90, 7, 52, 'Council in Jerusalem', 'Peter rises at the council and testifies that Gentiles are saved by grace, as Jews are.', 52, 'Acts 15:1-35'),
(359, 12, 100, 13, NULL, 'Antioch', 'Paul withstands Peter to the face at Antioch for drawing back from eating with Gentiles. Scripture ends Peters story here; tradition says he died at Rome under Nero (see Martyrdom of Peter and Paul, AD 67).', 52, 'Galatians 2:11-14');
